const AtlasHTMLElementBase = (globalThis.HTMLElement ?? class {}) as typeof HTMLElement;
const customElements = globalThis.customElements ?? ({ get: () => undefined, define: () => undefined } as unknown as CustomElementRegistry);
let atlasPublicMapEnvironmentCache: ReturnType<typeof projectAtlasPublicMapEnvironmentV1> | null = null;
const atlasPublicMapEnvironment = () => atlasPublicMapEnvironmentCache || (atlasPublicMapEnvironmentCache = projectAtlasPublicMapEnvironmentV1());

/** Escape a value before placing it in HTML assembled by administrative components. */
export function escapeAtlasDomValueV1(value: unknown = ""): string {
  return String(value).replace(/[&<>"']/g, character => ({
    "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;",
  }[character] || character));
}

/** Build the icon markup used by the compatibility MJS component adapters. */
export function renderAtlasIconMarkupV1(name: string, className = ""): string {
  return `<i data-lucide="${name}" class="${className}"></i>`;
}

/** Small shared card primitive used by the original Atlas workspace shell. */
export class AtlasGlassCardElementV1 extends AtlasHTMLElementBase {
  connectedCallback(): void {
    if (!this.classList.contains("glass-card")) this.classList.add("glass-card");
  }
}

/** Shared metric pill; attributes are view state and can be updated in place. */
export class AtlasStatPillElementV1 extends AtlasHTMLElementBase {
  static get observedAttributes(): string[] {
    return ["label", "value", "tone", "icon", "sub"];
  }

  connectedCallback(): void {
    this.render();
  }

  attributeChangedCallback(): void {
    this.render();
  }

  private render(): void {
    const label = this.getAttribute("label") || "";
    const value = this.getAttribute("value") || "";
    const tone = this.getAttribute("tone") || "teal";
    const icon = this.getAttribute("icon") || "activity";
    const sub = this.getAttribute("sub") || "";
    this.innerHTML = `<div class="stat-pill tone-${tone}"><span class="stat-icon">${renderAtlasIconMarkupV1(icon)}</span><span><small>${escapeAtlasDomValueV1(label)}</small><strong>${escapeAtlasDomValueV1(value)}</strong>${sub ? `<em>${escapeAtlasDomValueV1(sub)}</em>` : ""}</span></div>`;
    (globalThis as typeof globalThis & { lucide?: { createIcons?: () => void } }).lucide?.createIcons?.();
  }
}

/** Register shared presentational elements without replacing existing owners. */
export function registerAtlasPrimitiveElementsV1(
  customElementsRef: CustomElementRegistry = customElements,
): Readonly<{ GlassCard: typeof AtlasGlassCardElementV1; StatPill: typeof AtlasStatPillElementV1 }> {
  if (typeof customElementsRef?.get !== "function" || typeof customElementsRef?.define !== "function")
    throw new TypeError("Primitive element registration requires CustomElementRegistry.");
  if (!customElementsRef.get("glass-card")) customElementsRef.define("glass-card", AtlasGlassCardElementV1);
  if (!customElementsRef.get("stat-pill")) customElementsRef.define("stat-pill", AtlasStatPillElementV1);
  return Object.freeze({ GlassCard: AtlasGlassCardElementV1, StatPill: AtlasStatPillElementV1 });
}

type AtlasActionToastV1 = HTMLDivElement & { _timer?: ReturnType<typeof setTimeout> };

/** Show the shared administrative toast without coupling callers to a module-local DOM owner. */
export function notifyAtlasActionV1(message: unknown, tone = "info"): void {
  const documentRef = globalThis.document;
  const host = documentRef?.querySelector<HTMLElement>(".app-main");
  if (!host) return;
  let toast = host.querySelector<AtlasActionToastV1>(".action-toast");
  if (!toast) {
    toast = documentRef.createElement("div") as AtlasActionToastV1;
    toast.className = "action-toast";
    host.appendChild(toast);
  }
  toast.dataset.tone = tone;
  toast.textContent = String(message ?? "");
  toast.classList.add("show");
  globalThis.clearTimeout(toast._timer);
  toast._timer = globalThis.setTimeout(() => toast?.classList.remove("show"), 2800);
}

