/** Apply the full-inset viewport contract to the map and its rendering layers. */
export function applyAtlasMapSceneCoverLayout(scene: HTMLElement): void {
  scene.style.position = scene.style.position || "relative";
  scene.style.overflow = "hidden";
  scene.style.minWidth = "0";
  scene.style.minHeight = "0";
  const world = scene.querySelector<HTMLElement>(".scene-world");
  const canvas = scene.querySelector<HTMLCanvasElement>(".three-overlay");
  const host = scene.querySelector<HTMLElement>(".map-host");
  [world, host].forEach(node => {
    if (!node) return;
    node.style.position = "absolute";
    node.style.inset = "0";
    node.style.width = "100%";
    node.style.height = "100%";
    node.style.maxWidth = "none";
    node.style.maxHeight = "none";
  });
  if (canvas) {
    canvas.style.position = "absolute";
    canvas.style.inset = "0";
    canvas.style.width = "100%";
    canvas.style.height = "100%";
    canvas.style.maxWidth = "none";
    canvas.style.maxHeight = "none";
    canvas.style.objectFit = "cover";
  }
  scene.dataset.mapCoverLayoutV9 = "full-inset";
  scene.dataset.mapCoverPolicyV9 = "aerial-cover + pan-clamp + resize-lock";
}

