  highlightStatus: Record<string, AtlasMapFilterHighlight>;
  dashboardModeFiltersV1: Record<'tracking' | 'commercial' | 'social', AtlasMapFilterItem[]>;
  dashboardFiltersForModeV1: (modeValue?: unknown) => AtlasMapFilterItem[];
  dashboardFilterForModeV1: AtlasMapFilterLookupV1;
  mapFilterSelectionKeyV1: (state: Record<string, unknown>) => string | null;
  mapFilterSummaryMetricsV1: (key: unknown, state: Record<string, unknown>) => Array<[string, string, string]>;
  mapProgressSummaryMarkupV1: (state: Record<string, unknown>) => string;
  mapFilterSummaryMarkupV1: (key: unknown, state: Record<string, unknown>) => string;
