/** Bind the typed georeference catalog to the map component operations. */
export function createAtlasMapGeoreferenceBindingsV1(
  input: AtlasMapGeoreferenceBindingInputV1,
) {
  const { scene, projection } = input.configuration;
  const ports = input.ports;
  const rasterMask = scene.rasterMask;
  const aerial = scene.aerialReference;
  const pdfMasterplan = scene.pdfMasterplan;
  const aerialAsset = aerial.asset;
  const dwgUrl = input.runtimeRouteV1(scene.dwgGeoreferencePath, "v=dwg-georef-v1");
  const projectAdminReferenceUtmToUvV1 = (east: number, north: number): { u: number; v: number } | null => {
    const override = (globalThis as any).belavistaProjectAdminUtmToUv;
    const projected = typeof override === "function"
      ? override(east, north)
      : ports.projectPublicAdminUtmToUv(east, north);
    return projected && Number.isFinite(projected.u) && Number.isFinite(projected.v)
      ? { u: Number(projected.u), v: Number(projected.v) }
      : null;
  };

  return Object.freeze({
    DWG_GEOREFERENCE_URL: dwgUrl,
    PDF_LOT_TRACE_SATELLITE_ALIGNMENT_V1: projection.pdfLotTraceSatelliteAlignment,
    polygonCentroidV1: (polygon: unknown) => ports.publicMapPolygonCentroid(polygon),
    projectCanonicalLotTraceToMasterplanOverlayUvV1: (point: { x?: unknown; y?: unknown } | null | undefined, imageSize: readonly number[] = []) =>
      ports.projectPublicCanonicalLotTrace({ x: Number(point?.x), y: Number(point?.y) }, imageSize),
    ADMIN_REFERENCE_AERIAL_GEO_QUAD_UV_V1: { ...projection.aerialGeoQuadUv },
    ADMIN_MASTERPLAN_SATELLITE_FRAME_V1: { ...projection.masterplanSatelliteFrame },
    INVALID_MASTERPLAN_LOT_IDS_V1: new Set(projection.invalidMasterplanLotIds),
    MASTERPLAN_PDF_GEOMETRY_REPAIR_LOT_IDS_V1: new Set(projection.geometryRepairLotIds),
    MASTERPLAN_COMMON_AREA_SOURCE_IDS_V1: new Set(projection.commonAreaSourceIds),
    MASTERPLAN_COMMON_AREA_LABEL_V1: scene.commonAreaLabel,
    ADMIN_REFERENCE_AERIAL_GEO_WARP_VERSION_V1: scene.geoWarpVersion,
    ADMIN_REFERENCE_AERIAL_LOT_TRACE_URL_V1: scene.aerialLotTraceUrl,
    ADMIN_MASTERPLAN_LOT_POLYGONS_URL_V2: scene.masterplanLotPolygonsUrl,
    PDF_LOT_LABELS_URL_V1: scene.pdfLotLabelsUrl,
    PDF_LOT_GREEN_MAPPING_URL_V1: scene.pdfLotGreenMappingUrl,
    CANONICAL_LOT_TRACE_OVERLAY_ALIGNMENT_V1: projection.canonicalLotTraceOverlayAlignment,
    ADMIN_REFERENCE_AERIAL_ROAD_TRACE_URL_V1: scene.roadTraceUrl,
    ADMIN_REFERENCE_AERIAL_RASTER_MASK_MODEL_VERSION_V1: rasterMask.version,
    buildAdminReferenceAerialRasterMaskModelV1: ({ THREE, image, texture }: Pick<AtlasAdminAerialRasterMaskInputV1, "THREE" | "image" | "texture">) =>
      ports.buildAdminReferenceAerialRasterMaskModel({
        THREE,
        image,
        texture,
        enabled: rasterMask.enabled,
        sampleSize: { width: rasterMask.sampleSize.width, height: rasterMask.sampleSize.height },
        grid: { x: rasterMask.grid.x, y: rasterMask.grid.y },
        version: rasterMask.version,
        source: aerialAsset,
        pointInsideQuad: ports.pointInsideAdminReferenceAerialQuad,
        documentRef: (globalThis as any).document,
        consoleRef: (globalThis as any).console,
      }),
    loadAdminDwgGeoreferenceV1: () => ports.loadAdminDwgGeoreference(dwgUrl),
    appendAdminReferenceAerialCurbPathV1: ports.appendAdminReferenceAerialCurbPath,
    createAdminReferenceAerialBezierCurbGuidesV1: ports.createAdminReferenceAerialBezierCurbGuides,
    createAdminReferenceAerialRoadPlaneGeometryV1: ports.createAdminReferenceAerialRoadPlaneGeometry,
    createAdminReferenceAerialNativeRoadGeometryV1: ports.createAdminReferenceAerialNativeRoadGeometry,
    warpAdminGlbToFixedAerialV1: (warpInput: Pick<AtlasAdminFixedAerialGeoWarpInputV1, "THREE" | "source" | "georef" | "image" | "trace" | "roadTrace">) =>
      ports.warpAdminGlbToFixedAerial({
        ...warpInput,
        worldHeight: scene.worldHeight,
        verticalScale: scene.verticalScale,
        warpVersion: scene.geoWarpVersion,
        dwgUrl,
        projectUtmToUv: projectAdminReferenceUtmToUvV1,
        applyImageTrace: ports.applyAdminReferenceAerialImageTrace,
        applyResidualWarp: ports.applyAdminReferenceAerialResidualWarp,
      }),
    PDF_MASTERPLAN_MODEL_TEXTURE_VERSION: pdfMasterplan.modelTextureVersion,
    PDF_MODEL_TEXTURE_BRIGHTNESS: pdfMasterplan.modelTextureBrightness,
    ADMIN_REFERENCE_AERIAL_ASSET_V1: aerialAsset,
    ADMIN_AERIAL_ZOOM_TILE_ROOT_V1: aerial.zoomTileRoot,
    ADMIN_AERIAL_ZOOM_TILE_GRID_V1: { ...aerial.zoomTileGrid },
    ADMIN_AERIAL_ZOOM_TILE_PIXELS_V1: { ...aerial.zoomTilePixels },
    ADMIN_AERIAL_TILE_PREFETCH_RATIO_V2: aerial.tilePrefetchRatio,
    ADMIN_AERIAL_TILE_SWAP_RATIO_V2: aerial.tileSwapRatio,
    ADMIN_REFERENCE_AERIAL_SEMANTIC_COORDINATE_SYSTEM_V1: aerial.semanticCoordinateSystem,
    ADMIN_REFERENCE_AERIAL_VERSION_V1: aerial.version,
    ADMIN_SEMANTIC_3D_LAYER_VERSION_V1: aerial.semanticLayerVersion,
    ADMIN_REFERENCE_AERIAL_ENVIRONMENT_VERSION_V1: aerial.environmentVersion,
    ADMIN_REFERENCE_AERIAL_TERRAIN_SEGMENTS_X_V1: aerial.terrainSegments.x,
    ADMIN_REFERENCE_AERIAL_TERRAIN_SEGMENTS_Y_V1: aerial.terrainSegments.y,
    ADMIN_REFERENCE_AERIAL_SITE_FRAME_V2: { ...aerial.siteFrameV2 },
    ADMIN_REFERENCE_AERIAL_RELIEF_AMPLITUDE_V2: aerial.reliefAmplitudeV2,
    ADMIN_REFERENCE_AERIAL_SITE_FRAME_V1: { ...aerial.siteFrameV1 },
    ADMIN_REFERENCE_AERIAL_DISPLAY_SCALE_V1: aerial.displayScale,
    PDF_MASTERPLAN_TEXTURE_SHIFT_UP_V1: pdfMasterplan.textureShiftUp,
    PDF_MASTERPLAN_PAGE_SIZE_V1: { ...pdfMasterplan.pageSize },
    PDF_MASTERPLAN_SITE_FRAME_V1: { ...pdfMasterplan.siteFrame },
    PDF_MASTERPLAN_VEHICLE_ANCHORS_V1: pdfMasterplan.vehicleAnchors.map((anchor: Record<string, any>) => ({ ...anchor })),
  });
}

