/** Compose the map-owned filter rail and physical scene through typed ports. */
export async function installAtlasMapApplicationRegistrationV1(
  input: AtlasMapFilterRailInstallInput & {
    HTMLElementCtor?: typeof HTMLElement;
    REPASSE_PRICE_CATALOG?: AtlasMapLotPriceRowV1[];
    installMapFilterRail?: (dependencies: AtlasMapFilterRailInstallInput) => AtlasMapFilterCatalogV1;
    createMapSceneElement: AtlasMapSceneFactoryV1;
  },
): Promise<Readonly<AtlasMapFilterCatalogV1 & AtlasMapSceneElementBundleV1>> {
  const installFilterRail = input.installMapFilterRail || installAtlasMapFilterRail;
  const filterCatalog = installFilterRail({
    appStore: input.appStore,
    commands: input.commands,
    loadAgendaProgressDataV1: input.loadAgendaProgressDataV1,
    demoData: input.demoData,
    dashboardModes: input.dashboardModes,
    dashboardModeKeyV1: input.dashboardModeKeyV1,
    esc: input.esc,
    ico: input.ico,
    documentRef: input.documentRef,
    windowRef: input.windowRef,
    customElementsRef: input.customElementsRef,
  });
  const mapScene = await input.createMapSceneElement({
    HTMLElementCtor: input.HTMLElementCtor || AtlasHTMLElementBase,
    dashboardFilterForModeV1: filterCatalog.dashboardFilterForModeV1,
    dashboardModeKeyV1: input.dashboardModeKeyV1,
    REPASSE_PRICE_CATALOG: input.REPASSE_PRICE_CATALOG,
  });
  return Object.freeze({ ...filterCatalog, ...mapScene });
}

/** Create the complete sidebar; the MJS entry only supplies the store and host services. */
function emitAtlasShellCommandV1(target: EventTarget, command: AtlasShellCommandV1): void {
  target.dispatchEvent(new CustomEvent<AtlasShellCommandV1>(ATLAS_SHELL_COMMAND_EVENT_V1, {
    bubbles: true,
    composed: true,
    detail: command,
  }));
}

export function createAtlasSidebarElement(options: {
  appStore: {
    get: () => SidebarRenderState;
    set: (patch: Record<string, unknown>) => unknown;
    subscribe: (listener: () => void) => (() => void);
  };
  reportCatalog?: Array<{ id: string; family: string }>;
  navigationController: AtlasSidebarRouteControllerV1;
  getWorkerAssistant?: () => { setCollapsed?: (collapsed: boolean) => void } | null | undefined;
  notify?: (message: string, tone?: string) => void;
  esc?: (value: unknown) => string;
  ico?: (name: string) => string;
  document?: Document;
  window?: Window & { lucide?: { createIcons: () => void } };
}): CustomElementConstructor {
  const documentRef = options.document || globalThis.document;
  const windowRef = (options.window || globalThis.window) as Window & { lucide?: { createIcons: () => void } };
  return class AtlasSidebarElement extends AtlasHTMLElementBase {
    private unsubscribe: (() => void) | null = null;
    private navScrollTop = 0;
    private navScrollLeft = 0;
    private readonly chromeController = createAtlasSidebarChromeControllerV1({
      appStore: options.appStore,
      notify: options.notify,
    });
    constructor() {
      super();
    }

    connectedCallback(): void {
      const serviceRoot = this as unknown as AtlasServiceEventRoot;
      options.navigationController.connect(serviceRoot, { closeMobileNavigation: () => this.setMobileNavigationOpen(false) });
      this.chromeController.connect(serviceRoot);
      this.render();
      this.unsubscribe?.();
      this.unsubscribe = options.appStore.subscribe(() => {
        if (!(this as HTMLElement & { _dedicated?: boolean })._dedicated) this.render();
      });
    }

    disconnectedCallback(): void {
      options.navigationController.disconnect();
      this.chromeController.disconnect();
      this.unsubscribe?.();
      this.unsubscribe = null;
    }

    setMobileNavigationOpen(open: boolean): void {
      this.classList.toggle("mobile-open", open);
      documentRef?.querySelector("[data-sidebar-menu-toggle]")?.setAttribute("aria-expanded", String(open));
      documentRef?.querySelector("[data-sidebar-menu-toggle]")?.setAttribute("aria-label", open ? "Fechar menu" : "Abrir menu");
      documentRef?.querySelector("[data-sidebar-overlay]")?.setAttribute("aria-hidden", String(!open));
      const mobileTrigger = this.querySelector<HTMLElement>(".mobile-menu-trigger");
      mobileTrigger?.setAttribute("aria-expanded", String(open));
      mobileTrigger?.setAttribute("aria-label", open ? "Fechar navegação" : "Abrir navegação");
      const label = mobileTrigger?.querySelector("span");
      if (label) label.textContent = open ? "Fechar" : "Menu";
    }

    render(): void {
      const state = options.appStore.get();
      const navigation = projectSidebarNavigation({ state, modeValue: "tracking", reportCatalog: options.reportCatalog || [] });
      const navigationMarkup = renderSidebarNavigation({
        items: navigation.items,
        state,
        foremanSurface: navigation.foremanSurface,
        foremanExtensionViews: navigation.foremanExtensionViews,
        reportFamilies: navigation.reportFamilies,
        ico: options.ico,
        esc: options.esc,
      });
      this.dataset.role = navigation.normalizedRole;
      const previousNav = this.querySelector<HTMLElement>(".sidebar nav");
      this.navScrollTop = previousNav?.scrollTop ?? this.navScrollTop;
      this.navScrollLeft = previousNav?.scrollLeft ?? this.navScrollLeft;
      this.innerHTML = renderSidebarShell({
        actor: navigation.actor,
        adminMenuOpen: Boolean(state.adminMenu),
        navigationMarkup,
        esc: options.esc,
        ico: options.ico,
      });
      const nextNav = this.querySelector<HTMLElement>(".sidebar nav");
      if (nextNav) {
        nextNav.scrollTop = this.navScrollTop;
        nextNav.scrollLeft = this.navScrollLeft;
      }
      this.dataset.sidebarReady = "true";
      if (navigation.foremanSurface) this.querySelectorAll(".admin-menu button:not(:last-child)").forEach(button => button.remove());
      windowRef?.lucide?.createIcons();
    }
  };
}

export interface SidebarNavigationEventRoute {
  eventType: "click";
  selector: string;
  action: "open-messages" | "navigate";
  handler: (context: { target: HTMLElement }) => void;
}

/** Build the typed sidebar event policy; the shell event service owns dispatch. */
export function createSidebarNavigationEventRoutes(input: {
  closeMobileNavigation?: () => void;
  openMessages?: () => void;
  navigate?: (target: HTMLElement) => void;
} = {}): readonly SidebarNavigationEventRoute[] {
  const closeMobileNavigation = input.closeMobileNavigation || (() => {});
  const openMessages = input.openMessages || (() => {});
  const navigate = input.navigate || (() => {});
  return Object.freeze([
    Object.freeze({
      eventType: "click" as const,
      selector: '[data-sidebar-action="messages"]',
      action: "open-messages" as const,
      handler: () => { closeMobileNavigation(); openMessages(); },
    }),
    Object.freeze({
      eventType: "click" as const,
      selector: "[data-view]",
      action: "navigate" as const,
      handler: ({ target }: { target: HTMLElement }) => { closeMobileNavigation(); navigate(target); },
    }),
  ]);
}

export interface SidebarChromeEventRoute {
  eventType: "click";
  selector: string;
  action: "toggle-admin-menu" | "admin-menu-command";
  handler: (context: { target: HTMLElement }) => void;
}

/** Type the administrator-menu event policy while leaving store/session effects injectable. */
export function createSidebarChromeEventRoutes(input: {
  toggleAdminMenu?: () => void;
  runAdminMenuCommand?: (target: HTMLElement) => void;
} = {}): readonly SidebarChromeEventRoute[] {
  return Object.freeze([
    Object.freeze({
      eventType: "click" as const,
      selector: "#adminTrigger",
      action: "toggle-admin-menu" as const,
      handler: () => input.toggleAdminMenu?.(),
    }),
    Object.freeze({
      eventType: "click" as const,
      selector: ".admin-menu button",
      action: "admin-menu-command" as const,
      handler: ({ target }: { target: HTMLElement }) => input.runAdminMenuCommand?.(target),
    }),
  ]);
}

