interface AtlasPertWorkspaceViewLayer extends HTMLElement {
  bind(): void;
  pert(...args: unknown[]): unknown;
  actions(...args: unknown[]): unknown;
  raci(...args: unknown[]): unknown;
  raid(...args: unknown[]): unknown;
}

interface AtlasPertWorkspaceViewLayerConstructor {
  prototype: AtlasPertWorkspaceViewLayer;
}

export interface AtlasPertWorkspaceInput {
  ViewLayer: AtlasPertWorkspaceViewLayerConstructor;
  getSnapshot(): AtlasPertWorkspaceSnapshot;
  dispatch(command: AtlasPertCommand): void;
  esc(value: unknown): string;
  ico(name: string): string;
  notify(message: string, tone?: string): void;
  documentRef: Document;
  windowRef: Window;
}

/** Render and bind the PERT workspace; store transitions remain program commands. */
export function installAtlasPertWorkspace(input: AtlasPertWorkspaceInput): AtlasPertWorkspaceViewLayerConstructor {
  const { ViewLayer, getSnapshot, dispatch, esc, ico, notify, documentRef, windowRef } = input;
  const render = (): string => {
    const snapshot = getSnapshot();
    const nodes = snapshot.nodes;
    const selected = nodes.find((node) => node.id === snapshot.selectedNodeId) || nodes[0];
    if (!selected) return '<section class="stage-extension-page pert-page"><p>Nenhuma atividade no grafo PERT.</p></section>';
    const nodeById = new Map<string, typeof nodes[number]>(nodes.map((node): [string, typeof nodes[number]] => [node.id, node]));
    const edgeMarkup = (from: string, to: string, custom = false, label = ''): string => {
      const source = nodeById.get(from);
      const target = nodeById.get(to);
      if (!source || !target) return '';
      const x1 = source.x + 7;
      const y1 = source.y + 8;
      const x2 = target.x;
      const y2 = target.y + 8;
      const middle = (x1 + x2) / 2;
      return `<path${custom ? ' class="pert-custom-edge"' : ''} d="M ${x1} ${y1} C ${middle} ${y1}, ${middle} ${y2}, ${x2} ${y2}"/>${custom ? `<text class="pert-custom-label" x="${middle}" y="${(y1 + y2) / 2 - 1}">${esc(label || 'relação')}</text>` : `<circle cx="${x2}" cy="${y2}" r="0.7"/>`}`;
    };
    const states = { done: 'CONCLUÍDA', active: 'EM EXECUÇÃO', available: 'AÇÃO DISPONÍVEL', locked: 'BLOQUEADA' };
    const icons = { done: '✓', active: '●', available: '○', locked: '⌁' };
    const edges = snapshot.edges.map(([from, to]) => edgeMarkup(from, to)).join('')
      + snapshot.relations.map(({ from, to, label }) => edgeMarkup(from, to, true, label)).join('');
    const cards = nodes.map((node) => `<button type="button" class="pert-node state-${node.state} ${node.id === selected.id ? 'selected' : ''}" data-pert-node="${esc(node.id)}" style="--x:${node.x}%;--y:${node.y}%"><span class="pert-state-icon">${icons[node.state]}</span><span><small>${states[node.state]}</small><strong>${esc(node.label)}</strong><em>${node.progress}% · ${esc(node.owner)}</em></span></button>`).join('');
    const relations = snapshot.relations.length
      ? `<div class="pert-relation-editor-list">${snapshot.relations.map((relation, index) => `<button type="button" data-pert-relation-edit="${index}"><span>${esc(nodeById.get(relation.from)?.label || relation.from)} → ${esc(nodeById.get(relation.to)?.label || relation.to)}</span><b>${esc(relation.label || 'relação')}</b></button>`).join('')}</div>`
      : '<div class="pert-relation-editor-empty">Arraste o ponto ＋ de um card até outro para criar uma relação rotulada.</div>';
    return `<div class="stage-extension-page pert-page"><div class="extension-head"><div><span class="activity-kind">PERT · ${esc(snapshot.stageName)}</span><h1>Dependências vivas da etapa</h1><p>O grafo mostra o que já foi concluído, o que pode começar agora e quais atividades ainda dependem de liberações anteriores.</p></div><div class="extension-head-actions"><button class="ghost" data-view="stages">${ico('arrow-left')} Gantt da etapa</button><button class="primary" data-view="activities">${ico('sparkles')} Atividades</button></div></div><div class="pert-layout"><section class="pert-canvas" data-pert-interactive-bound="true"><div class="pert-canvas-head"><span>FLUXO OPERACIONAL</span><div class="pert-legend"><i class="done"></i> concluída <i class="active"></i> execução <i class="available"></i> disponível <i class="locked"></i> bloqueada</div></div><div class="pert-interaction-tools"><span>PERT EDITÁVEL</span><small>Arraste ＋ até outro card ou solte no canvas para criar um novo</small></div><div class="pert-relation-editor">${relations}</div><svg viewBox="0 0 100 80" preserveAspectRatio="none" aria-hidden="true">${edges}</svg>${cards}<form class="pert-link-form" data-pert-link-form hidden><header><b>Finalizar card e relação</b><button type="button" data-pert-link-cancel aria-label="Cancelar">×</button></header><label>Nome do card<input name="name" required maxlength="100" placeholder="Nova atividade"></label><label>Relação<input name="label" required maxlength="80" value="libera"></label><label>Responsável<input name="owner" maxlength="100" placeholder="Responsável"></label><footer><button type="submit">Criar card e conexão</button></footer></form></section><aside class="pert-inspector"><span class="activity-kind">NÓ SELECIONADO · ${selected.state.toUpperCase()}</span><h2>${esc(selected.label)}</h2><div class="pert-progress"><i style="width:${selected.progress}%"></i></div><div class="pert-properties"><div><small>RESPONSÁVEL</small><b>${esc(selected.owner)}</b></div><div><small>MATERIAIS / EVIDÊNCIAS</small><b>${esc(selected.material)}</b></div><div><small>CONTRATO / DOCUMENTO</small><b>${esc(selected.contract)}</b></div><div><small>ÚLTIMA ATUALIZAÇÃO</small><b>Hoje · ${new Date().toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' })}</b></div></div><div class="pert-inspector-actions"><button class="ghost" data-view="records">${ico('images')} Ver evidências</button><button class="ghost" data-view="activities">${ico('panel-right-open')} Abrir atividade</button>${selected.state !== 'done' ? `<button class="primary" data-pert-complete="${esc(selected.id)}">${ico('check-check')} Marcar concluída</button>` : '<span class="pert-complete-note">Próximas dependências foram reavaliadas.</span>'}</div></aside></div></div>`;
  };

  ViewLayer.prototype.pert = render;
  const previousBind = ViewLayer.prototype.bind;
  ViewLayer.prototype.bind = function (this: AtlasPertWorkspaceViewLayer): void {
    previousBind.call(this);
    const canvas = this.querySelector<HTMLElement>('.pert-canvas');
    if (!canvas || canvas.dataset.pertTypedBound === 'true') return;
    canvas.dataset.pertTypedBound = 'true';

    const form = canvas.querySelector<HTMLFormElement>('[data-pert-link-form]');
    const nameInput = form?.querySelector<HTMLInputElement>('[name="name"]');
    const labelInput = form?.querySelector<HTMLInputElement>('[name="label"]');
    const ownerInput = form?.querySelector<HTMLInputElement>('[name="owner"]');
    let pendingLink: { source: string; x: number; y: number } | null = null;
    form?.querySelector('[data-pert-link-cancel]')?.addEventListener('click', () => {
      pendingLink = null;
      form.hidden = true;
    });
    form?.addEventListener('submit', (event) => {
      event.preventDefault();
      if (!pendingLink || !nameInput || !labelInput) return;
      dispatch({
        type: 'create-node',
        from: pendingLink.source,
        name: nameInput.value.trim(),
        label: labelInput.value.trim(),
        owner: ownerInput?.value.trim() || '',
        x: pendingLink.x,
        y: pendingLink.y,
      });
      pendingLink = null;
      form.hidden = true;
    });

    const cardButtons = [...canvas.querySelectorAll<HTMLButtonElement>('[data-pert-node]')];
    cardButtons.forEach((node) => {
      const nodeId = node.dataset.pertNode || '';
      const handle = documentRef.createElement('button');
      handle.type = 'button';
      handle.className = 'pert-connect-handle';
      handle.textContent = '＋';
      handle.title = 'Arraste para conectar';
      handle.setAttribute('aria-label', `Criar dependência a partir de ${node.querySelector('strong')?.textContent || nodeId}`);
      handle.dataset.pertConnectFrom = nodeId;
      node.appendChild(handle);

      node.addEventListener('pointerdown', (event: PointerEvent) => {
        if (event.target === handle || event.button !== 0) return;
        event.preventDefault();
        const rect = canvas.getBoundingClientRect();
        const start = { x: event.clientX, y: event.clientY };
        const base = {
          x: Number.parseFloat(node.style.getPropertyValue('--x')) || 0,
          y: Number.parseFloat(node.style.getPropertyValue('--y')) || 0,
        };
        let moved = false;
        node.setPointerCapture?.(event.pointerId);
        node.classList.add('dragging');
        const move = (moveEvent: PointerEvent): void => {
          if (moveEvent.pointerId !== event.pointerId) return;
          const x = Math.max(2, Math.min(90, base.x + ((moveEvent.clientX - start.x) / rect.width) * 100));
          const y = Math.max(5, Math.min(76, base.y + ((moveEvent.clientY - start.y) / rect.height) * 100));
          node.style.setProperty('--x', `${x}%`);
          node.style.setProperty('--y', `${y}%`);
          moved = true;
        };
        const finish = (upEvent: PointerEvent): void => {
          if (upEvent.pointerId !== event.pointerId) return;
          node.classList.remove('dragging');
          node.releasePointerCapture?.(event.pointerId);
          node.removeEventListener('pointermove', move);
          node.removeEventListener('pointerup', finish);
          node.removeEventListener('pointercancel', finish);
          if (!moved) return;
          node.dataset.dragged = 'true';
          windowRef.setTimeout(() => { delete node.dataset.dragged; }, 0);
          dispatch({
            type: 'move',
            id: nodeId,
            x: Number.parseFloat(node.style.getPropertyValue('--x')) || base.x,
            y: Number.parseFloat(node.style.getPropertyValue('--y')) || base.y,
          });
        };
        node.addEventListener('pointermove', move);
        node.addEventListener('pointerup', finish);
        node.addEventListener('pointercancel', finish);
      });

      handle.addEventListener('pointerdown', (event: PointerEvent) => {
        if (event.button !== 0) return;
        event.preventDefault();
        event.stopPropagation();
        const source = nodeId;
        const svg = canvas.querySelector<SVGSVGElement>('svg');
        const preview = documentRef.createElementNS('http://www.w3.org/2000/svg', 'path');
        preview.classList.add('pert-pending-edge');
        svg?.appendChild(preview);
        const canvasPoint = (clientX: number, clientY: number): { x: number; y: number } => {
          const rect = canvas.getBoundingClientRect();
          return {
            x: Math.max(0, Math.min(100, ((clientX - rect.left) / Math.max(1, rect.width)) * 100)),
            y: Math.max(0, Math.min(100, ((clientY - rect.top - 52) / Math.max(1, rect.height)) * 100)),
          };
        };
        const svgPoint = (clientX: number, clientY: number): { x: number; y: number } => {
          const rect = canvas.getBoundingClientRect();
          return {
            x: Math.max(0, Math.min(100, ((clientX - rect.left) / Math.max(1, rect.width)) * 100)),
            y: Math.max(0, Math.min(80, ((clientY - rect.top) / Math.max(1, rect.height)) * 80)),
          };
        };
        const handleRect = handle.getBoundingClientRect();
        const start = svgPoint(handleRect.right, handleRect.top + handleRect.height / 2);
        const move = (moveEvent: PointerEvent): void => {
          if (moveEvent.pointerId !== event.pointerId || !preview) return;
          const point = svgPoint(moveEvent.clientX, moveEvent.clientY);
          preview.setAttribute('d', `M ${start.x} ${start.y} L ${point.x} ${point.y}`);
        };
        const finish = (upEvent: PointerEvent): void => {
          if (upEvent.pointerId !== event.pointerId) return;
          documentRef.removeEventListener('pointermove', move);
          documentRef.removeEventListener('pointerup', finish);
          documentRef.removeEventListener('pointercancel', finish);
          preview.remove();
          const target = documentRef.elementFromPoint(upEvent.clientX, upEvent.clientY)?.closest<HTMLElement>('[data-pert-node]');
          if (target && target !== node) {
            dispatch({ type: 'connect', from: source, to: target.dataset.pertNode || '', label: 'libera' });
            notify('Relação criada no PERT.', 'success');
            return;
          }
          const element = documentRef.elementFromPoint(upEvent.clientX, upEvent.clientY);
          if (!canvas.contains(element) || element?.closest('[data-pert-link-form]')) return;
          const point = canvasPoint(upEvent.clientX, upEvent.clientY);
          pendingLink = { source, x: point.x, y: point.y };
          form?.reset();
          if (form) form.hidden = false;
          nameInput?.focus();
        };
        documentRef.addEventListener('pointermove', move);
        documentRef.addEventListener('pointerup', finish);
        documentRef.addEventListener('pointercancel', finish);
      });
    });

    canvas.addEventListener('click', (event) => {
      const target = event.target instanceof Element ? event.target.closest<HTMLElement>('[data-pert-node]') : null;
      if (target?.dataset.dragged === 'true') return;
      if (target?.dataset.pertNode) dispatch({ type: 'select', id: target.dataset.pertNode });
      const complete = event.target instanceof Element ? event.target.closest<HTMLElement>('[data-pert-complete]') : null;
      if (complete?.dataset.pertComplete) dispatch({ type: 'complete', id: complete.dataset.pertComplete });
    });
    this.querySelector('[data-pert-complete]')?.addEventListener('click', (event) => {
      const id = (event.currentTarget as HTMLElement | null)?.dataset.pertComplete;
      if (id) dispatch({ type: 'complete', id });
    });
    canvas.querySelectorAll<HTMLButtonElement>('[data-pert-relation-edit]').forEach((button) => button.addEventListener('click', () => {
      const snapshot = getSnapshot();
      const index = Number(button.dataset.pertRelationEdit);
      const current = snapshot.relations[index];
      const label = windowRef.prompt('Novo rótulo da relação', current?.label || '');
      if (label?.trim()) dispatch({ type: 'edit-relation', index, label: label.trim() });
    }));
  };
  Object.defineProperty(ViewLayer.prototype, '__atlasPertWorkspaceTsOwnerV1', { configurable: true, value: true });
  return ViewLayer;
}

/** Rename the shared dashboard panorama when it is opened from Etapas. */
export function installAtlasStagePanoramaPageV1(
  ViewLayer: { prototype: HTMLElement & Record<string, any> },
): boolean {
  const panoramaBase = ViewLayer.prototype.assistant;
  ViewLayer.prototype.stagesPanoramaHome = function (...args: any[]): string {
    return String(panoramaBase?.apply(this, args) || '')
      .replace('DASHBOARD INICIAL · ALIANÇA PARK', 'ETAPAS E CRONOGRAMA · ALIANÇA PARK')
      .replace('<h1>Panorama operacional</h1>', '<h1>Etapas e cronograma</h1>')
      .replace('Registros rápidos e leitura de status, com o mapa aberto somente quando necessário.', 'Mapa, filtros e cronograma integrados para acompanhar cada frente de execução.');
  };
  ViewLayer.prototype.stagesCanvas = function (): string {
    return String(this.stagesPanoramaHome?.() || '');
  };
  Object.defineProperty(ViewLayer.prototype, '__atlasStagePanoramaTsOwnerV1', { configurable: true, value: true });
  return true;
}

export interface AtlasActionsWorkspaceInput {
  ViewLayer: AtlasPertWorkspaceViewLayerConstructor;
  getSnapshot(): AtlasOperationalActionSnapshot;
  dispatch(command: AtlasOperationalActionCommand): void;
  esc(value: unknown): string;
  ico(name: string): string;
  notify(message: string, tone?: string): void;
  windowRef: Window;
}

/** Render and bind the action-readiness matrix; program.ts owns projections and mutations. */
export function installAtlasActionsWorkspace(input: AtlasActionsWorkspaceInput): AtlasPertWorkspaceViewLayerConstructor {
  const { ViewLayer, getSnapshot, dispatch, esc, ico, notify, windowRef } = input;
  const render = (): string => {
    const snapshot = getSnapshot();
    const actions = snapshot.actions;
    const selected = actions.find((item) => item.id === snapshot.selectedActionId) || actions[0];
    if (!selected) return '<div class="stage-extension-page ai-actions-page"><p>Nenhuma ação operacional disponível.</p></div>';
    const points = actions.map((item) => `<button type="button" class="action-point ${item.id === selected.id ? 'selected' : ''} phase-${item.phase}" data-ai-action="${esc(item.id)}" style="left:${item.readiness}%;bottom:${item.impact}%" title="${esc(item.label)} · impacto ${item.impact} · prontidão ${item.readiness}"><span></span><b>${esc(item.label)}</b><small>${item.readiness}% pronto</small></button>`).join('');
    const highNow = actions.filter((item) => item.impact >= 75 && item.readiness >= 75).length;
    const phase = snapshot.phases[selected.phase] || snapshot.phases.at(-1) || 'Acompanhar';
    return `<div class="stage-extension-page ai-actions-page"><div class="extension-head"><div><span class="activity-kind">IA · AGENDA GERAL · ${esc(snapshot.stageName)}</span><h1>Ações por evolução e prontidão</h1><p>As ações são propagadas da agenda geral conforme avanço confirmado, dependências lógicas, materiais e descrição operacional de referência.</p></div><div class="extension-head-actions"><span class="ai-ready-count">${highNow} ações em “executar agora”</span></div></div><div class="action-workspace"><section class="action-matrix" data-action-matrix><div class="matrix-quadrant q-now"><b>EXECUTAR AGORA</b><small>alto impacto · alta prontidão</small></div><div class="matrix-quadrant q-prepare"><b>PREPARAR</b><small>alto impacto · baixa prontidão</small></div><div class="matrix-quadrant q-opportunity"><b>OPORTUNIDADES</b><small>prontas · menor impacto</small></div><div class="matrix-axis axis-y"><span>IMPACTO</span><b>alto</b><small>baixo</small></div><div class="matrix-axis axis-x"><span>PRONTIDÃO</span><small>preparar</small><b>pronto</b></div>${points}</section><aside class="action-inspector"><span class="activity-kind">${esc(selected.track).toUpperCase()} · ${esc(phase)}</span><h2>${esc(selected.label)}</h2><div class="action-score"><div><small>IMPACTO</small><b>${selected.impact}</b></div><div><small>PRONTIDÃO</small><b>${selected.readiness}%</b></div></div><dl><dt>Responsável</dt><dd>${esc(selected.owner)}</dd><dt>Próxima janela</dt><dd>${esc(selected.eta)}</dd><dt>Bloqueio atual</dt><dd>${esc(selected.blocker)}</dd><dt>Entidade ligada</dt><dd>${esc(selected.relation)}</dd><dt>Referência de execução</dt><dd>${esc(selected.referenceDescription || 'Descrição operacional da etapa')}</dd><dt>Requisitos materiais</dt><dd>${esc((selected.materialRequirements || []).join(' · ') || 'Sem falta material registrada')}</dd></dl><div class="action-inspector-buttons"><button class="primary" data-ai-advance="${esc(selected.id)}">${selected.phase >= 4 ? ico('check-circle') + ' Encerrada' : ico('arrow-right') + ' Adiantar atitude'}</button></div></aside></div></div>`;
  };

  ViewLayer.prototype.actions = render;
  const previousBind = ViewLayer.prototype.bind;
  ViewLayer.prototype.bind = function (this: AtlasPertWorkspaceViewLayer): void {
    previousBind.call(this);
    const snapshot = getSnapshot();
    if (snapshot.view !== 'actions' && !this.querySelector('[data-dashboard-action-workspace]')) return;
    const matrix = this.querySelector<HTMLElement>('[data-action-matrix]');
    this.querySelectorAll<HTMLButtonElement>('[data-ai-action]').forEach((point) => {
      point.addEventListener('click', () => {
        if (point.dataset.dragged === 'true') {
          delete point.dataset.dragged;
          return;
        }
        const id = point.dataset.aiAction;
        if (id) dispatch({ type: 'select', id });
      });
      point.addEventListener('pointerdown', (event: PointerEvent) => {
        if (event.button !== 0 || !matrix) return;
        event.preventDefault();
        event.stopPropagation();
        const id = point.dataset.aiAction || '';
        const current = getSnapshot().actions.find((item) => item.id === id);
        if (!current) return;
        const from = { impact: current.impact, readiness: current.readiness };
        let moved = false;
        point.setPointerCapture?.(event.pointerId);
        const move = (moveEvent: PointerEvent): void => {
          if (moveEvent.pointerId !== event.pointerId) return;
          const rect = matrix.getBoundingClientRect();
          const readiness = Math.max(4, Math.min(96, Math.round(((moveEvent.clientX - rect.left) / Math.max(1, rect.width)) * 100)));
          const impact = Math.max(4, Math.min(96, Math.round(((rect.bottom - moveEvent.clientY) / Math.max(1, rect.height)) * 100)));
          point.style.left = `${readiness}%`;
          point.style.bottom = `${impact}%`;
          point.dataset.nextReadiness = String(readiness);
          point.dataset.nextImpact = String(impact);
          moved = true;
        };
        const finish = (upEvent: PointerEvent): void => {
          if (upEvent.pointerId !== event.pointerId) return;
          point.releasePointerCapture?.(event.pointerId);
          windowRef.removeEventListener('pointermove', move);
          windowRef.removeEventListener('pointerup', finish);
          windowRef.removeEventListener('pointercancel', finish);
          if (!moved) return;
          point.dataset.dragged = 'true';
          dispatch({
            type: 'move',
            id,
            readiness: Number(point.dataset.nextReadiness),
            impact: Number(point.dataset.nextImpact),
          });
          notify('Impacto e prontidão recalculados para a ação.', 'success');
        };
        windowRef.addEventListener('pointermove', move);
        windowRef.addEventListener('pointerup', finish);
        windowRef.addEventListener('pointercancel', finish);
      });
    });
    this.querySelector('[data-ai-advance]')?.addEventListener('click', (event) => {
      const id = (event.currentTarget as HTMLElement | null)?.dataset.aiAdvance;
      if (!id) return;
      dispatch({ type: 'advance', id });
      notify('Ação avançou uma etapa.', 'success');
    });
  };
  return ViewLayer;
}

export interface AtlasRaciWorkspaceInput {
  ViewLayer: AtlasPertWorkspaceViewLayerConstructor;
  getSnapshot(): AtlasRaciWorkspaceSnapshot;
  dispatch(command: AtlasRaciCommand): AtlasRaciRole | void;
  esc(value: unknown): string;
  ico(name: string): string;
  notify(message: string, tone?: string): void;
}

/** Render the RACI role matrix and bind selection/cycling through typed commands. */
export function installAtlasRaciWorkspace(input: AtlasRaciWorkspaceInput): AtlasPertWorkspaceViewLayerConstructor {
  const { ViewLayer, getSnapshot, dispatch, esc, ico, notify } = input;
  const render = (): string => {
    const snapshot = getSnapshot();
    const selectedRoleLabel = snapshot.meaning[snapshot.selectedRole];
    const head = snapshot.actors.map((actor) => `<div class="raci-actor"><span class="avatar">${esc(actor.name[0] || '')}</span><b>${esc(actor.name)}</b><small>${esc(actor.role)}</small></div>`).join('');
    const rows = snapshot.tasks.map((task) => `<div class="raci-task"><span><b>${esc(task.label)}</b><small>${esc(snapshot.stageName)}</small></span></div>${snapshot.actors.map((actor) => {
      const value = snapshot.assignments[task.id]?.[actor.id] || '—';
      const key = `${task.id}:${actor.id}`;
      const meaning = snapshot.meaning[value];
      return `<button type="button" class="raci-cell role-${value.toLowerCase()} ${key === snapshot.selectedCell ? 'selected' : ''}" data-raci-cell="${esc(key)}" title="Clique para inspecionar · duplo clique para alternar R/A/C/I"><b>${value}</b><small>${value === '—' ? 'definir' : esc(meaning.split(' · ')[0])}</small></button>`;
    }).join('')}`).join('');
    return `<div class="stage-extension-page raci-page"><div class="extension-head"><div><span class="activity-kind">PESSOAS RESPONSÁVEIS · ${esc(snapshot.stageName)}</span><h1>RACI interativa da etapa</h1><p>Atividades nas linhas, pessoas e empresas nas colunas. A célula abre contrato, registros recentes, tarefas e o vínculo de responsabilidade.</p></div><div class="extension-head-actions"><button class="ghost" data-view="activities">${ico('sparkles')} Atividades</button><button class="ghost" data-view="agenda">${ico('calendar-days')} Agenda</button></div></div><div class="raci-layout"><section class="raci-table"><div class="raci-corner"><b>ATIVIDADE</b><small>R · A · C · I</small></div>${head}${rows}</section><aside class="raci-inspector"><span class="activity-kind">${snapshot.selectedRole === '—' ? 'SEM VÍNCULO' : esc(selectedRoleLabel)}</span><h2>${esc(snapshot.selectedActor.name)}</h2><p>${esc(snapshot.selectedTask.label)} · ${esc(snapshot.stageName)}</p><div class="raci-inspector-grid"><div><small>FUNÇÃO</small><b>${esc(snapshot.selectedActor.role)}</b></div><div><small>CONTRATO / VÍNCULO</small><b>${esc(snapshot.selectedActor.contract)}</b></div><div><small>REGISTRO RECENTE</small><b>${esc(snapshot.selectedTask.label)} · hoje 09:45</b></div><div><small>TAREFA RELACIONADA</small><b>Confirmar evidência e próximo responsável</b></div></div><div class="raci-role-legend"><span><b>R</b> executa</span><span><b>A</b> aprova</span><span><b>C</b> consultado</span><span><b>I</b> informado</span></div><div class="raci-actions"><button class="ghost" data-view="records">${ico('clipboard-pen-line')} Abrir registros</button><button class="primary" data-raci-cycle="${esc(snapshot.selectedCell)}">${ico('refresh-cw')} Alterar papel</button></div><small class="raci-hint">Duplo clique em qualquer célula também alterna R → A → C → I → sem vínculo.</small></aside></div></div>`;
  };
  ViewLayer.prototype.raci = render;
  const previousBind = ViewLayer.prototype.bind;
  ViewLayer.prototype.bind = function (this: AtlasPertWorkspaceViewLayer): void {
    previousBind.call(this);
    const bindCycle = (key: string): void => {
      const next = dispatch({ type: 'cycle', key });
      if (next) notify(`Papel RACI alterado para ${next}.`, 'success');
    };
    this.querySelectorAll<HTMLButtonElement>('[data-raci-cell]').forEach((cell) => {
      const key = cell.dataset.raciCell || '';
      cell.addEventListener('click', () => { if (key) dispatch({ type: 'select', key }); });
      cell.addEventListener('dblclick', (event) => { event.preventDefault(); if (key) bindCycle(key); });
    });
    this.querySelector('[data-raci-cycle]')?.addEventListener('click', (event) => {
      const key = (event.currentTarget as HTMLElement | null)?.dataset.raciCycle;
      if (key) bindCycle(key);
    });
  };
  return ViewLayer;
}

export interface AtlasRaidWorkspaceInput {
  ViewLayer: AtlasPertWorkspaceViewLayerConstructor;
  getSnapshot(): AtlasRaidWorkspaceSnapshot;
  dispatch(command: AtlasRaidCommand): void;
  esc(value: unknown): string;
  ico(name: string): string;
  notify(message: string, tone?: string): void;
  windowRef: Window;
}

/** Render RAID and bind drag/drop, link, and add operations through program commands. */
export function installAtlasRaidWorkspace(input: AtlasRaidWorkspaceInput): AtlasPertWorkspaceViewLayerConstructor {
  const { ViewLayer, getSnapshot, dispatch, esc, ico, notify, windowRef } = input;
  const render = (): string => {
    const snapshot = getSnapshot();
    const zones: Array<[AtlasRaidKind, string, string]> = [
      ['risk', 'Riscos', 'Probabilidade × impacto'],
      ['assumption', 'Premissas', 'Hipóteses que sustentam o plano'],
      ['issue', 'Problemas', 'Ocorrências que exigem ação'],
      ['dependency', 'Dependências', 'Condições antes do próximo passo'],
    ];
    const zoneMarkup = zones.map(([kind, label, description]) => `<section class="raid-zone zone-${kind}" data-raid-zone="${kind}"><header><span>${esc(label)}</span><small>${esc(description)}</small><b>${snapshot.items.filter((item) => item.kind === kind).length}</b></header><div class="raid-zone-list">${snapshot.items.filter((item) => item.kind === kind).map((item) => `<article class="raid-card level-${item.level} ${item.id === snapshot.selected.id ? 'selected' : ''}" draggable="true" data-raid-card="${esc(item.id)}"><div><span>${esc(item.level.toUpperCase())}</span><small>${esc(item.linked || 'Sem vínculo')}</small></div><b>${esc(item.title)}</b><p>${esc(item.detail)}</p></article>`).join('')}</div><button type="button" class="raid-add" data-raid-add="${kind}">＋ Adicionar</button></section>`).join('');
    return `<div class="stage-extension-page raid-page"><div class="extension-head"><div><span class="activity-kind">RAID · ${esc(snapshot.stageName)}</span><h1>Pendências e atenção operacional</h1><p>Riscos, premissas, problemas e dependências ficam no mesmo workspace e podem ser movidos entre zonas ou vinculados diretamente a uma atividade.</p></div><div class="extension-head-actions"><button class="ghost" data-view="pert">${ico('git-branch')} Dependências PERT</button><button class="primary" data-view="activities">${ico('sparkles')} Abrir atividades</button></div></div><div class="raid-workspace">${zoneMarkup}</div><div class="raid-bottom"><section class="raid-activity-targets"><div><span class="activity-kind">VINCULAR À ATIVIDADE</span><h2>Arraste uma pendência para uma entidade</h2></div><div>${snapshot.targets.map((target) => `<button type="button" data-raid-target="${esc(target)}">${ico('link-2')} ${esc(target)}</button>`).join('')}</div></section><aside class="raid-inspector"><span class="activity-kind">${esc(snapshot.selected.kind.toUpperCase())} · ${esc(snapshot.selected.level.toUpperCase())}</span><h2>${esc(snapshot.selected.title)}</h2><p>${esc(snapshot.selected.detail)}</p><dl><dt>Vínculo atual</dt><dd>${esc(snapshot.selected.linked || 'Sem vínculo')}</dd><dt>Etapa</dt><dd>${esc(snapshot.stageName)}</dd><dt>Origem</dt><dd>IA + registros + cronograma</dd></dl><button class="ghost" data-view="records">${ico('clipboard-pen-line')} Abrir evidências</button></aside></div></div>`;
  };

  ViewLayer.prototype.raid = render;
  const previousBind = ViewLayer.prototype.bind;
  ViewLayer.prototype.bind = function (this: AtlasPertWorkspaceViewLayer): void {
    previousBind.call(this);
    const snapshot = getSnapshot();
    let draggingId = '';
    this.querySelectorAll<HTMLElement>('[data-raid-card]').forEach((card) => {
      const id = card.dataset.raidCard || '';
      card.addEventListener('click', () => { if (id) dispatch({ type: 'select', id }); });
      card.addEventListener('dragstart', (event: DragEvent) => {
        draggingId = id;
        event.dataTransfer?.setData('text/plain', id);
        card.classList.add('dragging');
      });
      card.addEventListener('dragend', () => card.classList.remove('dragging'));
    });
    const draggedId = (event: DragEvent): string => event.dataTransfer?.getData('text/plain') || draggingId;
    this.querySelectorAll<HTMLElement>('[data-raid-zone]').forEach((zone) => {
      zone.addEventListener('dragover', (event) => { event.preventDefault(); zone.classList.add('drag-over'); });
      zone.addEventListener('dragleave', () => zone.classList.remove('drag-over'));
      zone.addEventListener('drop', (event: DragEvent) => {
        event.preventDefault();
        zone.classList.remove('drag-over');
        const id = draggedId(event);
        const kind = zone.dataset.raidZone as AtlasRaidKind | undefined;
        if (!id || !kind) return;
        dispatch({ type: 'move', id, kind });
        notify('Item RAID movido para a nova zona.', 'success');
      });
    });
    this.querySelectorAll<HTMLButtonElement>('[data-raid-target]').forEach((target) => {
      target.addEventListener('dragover', (event) => { event.preventDefault(); target.classList.add('drag-over'); });
      target.addEventListener('dragleave', () => target.classList.remove('drag-over'));
      target.addEventListener('drop', (event: DragEvent) => {
        event.preventDefault();
        target.classList.remove('drag-over');
        const id = draggedId(event);
        const linked = target.dataset.raidTarget;
        if (!id || !linked) return;
        dispatch({ type: 'link', id, target: linked });
        notify(`Pendência vinculada a ${linked}.`, 'success');
      });
    });
    this.querySelectorAll<HTMLButtonElement>('[data-raid-add]').forEach((button) => button.addEventListener('click', () => {
      const title = windowRef.prompt('Título da nova pendência:');
      if (!title?.trim()) return;
      const detail = windowRef.prompt('Descrição / condição observada:') || 'Sem descrição adicional.';
      const kind = button.dataset.raidAdd as AtlasRaidKind | undefined;
      if (!kind) return;
      dispatch({ type: 'add', kind, title: title.trim(), detail: detail.trim(), stageName: snapshot.stageName });
      notify('Nova pendência adicionada ao RAID.', 'success');
    }));
  };
  return ViewLayer;
}

export interface AtlasOperationalIntelligenceEventInput {
  ViewLayer: AtlasOperationalIntelligenceViewLayerConstructor;
  readState(): Record<string, unknown>;
  ico(name: string): string;
  notify(message: string, tone?: string): void;
}

/** Install typed actions, RACI, RAID and Gantt interactions on ViewLayer. */
export function installAtlasOperationalIntelligenceEvents(input: AtlasOperationalIntelligenceEventInput): AtlasOperationalIntelligenceViewLayerConstructor {
  const { ViewLayer, readState, ico, notify } = input;
  const previousBind = ViewLayer.prototype.bind;
  ViewLayer.prototype.bind = function (this: AtlasOperationalIntelligenceViewLayer): void {
    previousBind.call(this);
    this.bindOperationalIntelligence?.();
  };

  ViewLayer.prototype.bindOperationalIntelligence = function (this: AtlasOperationalIntelligenceViewLayer): void {
    const view = readState().view;
    if (view === "stages") {
      const pane = this.querySelector<HTMLElement>('.stage-plan-pane[data-stage-pane="cronograma"]');
      if (pane && !pane.dataset.ganttEnhanced) {
        pane.dataset.ganttEnhanced = "true";
        pane.style.setProperty("--gantt-day-width", "28px");
        pane.querySelector("header")?.insertAdjacentHTML(
          "afterend",
          `<div class="gantt-operational-tools"><span>${ico("milestone")} Gantt navegável + milestones</span><div><button type="button" data-gantt-zoom="-1">−</button><button type="button" data-gantt-today>Hoje</button><button type="button" data-gantt-zoom="1">＋</button></div></div>`,
        );
        const labels: Array<[string, string]> = [["31", "Medição"], ["58", "Liberação"], ["82", "Conclusão"]];
        pane.querySelectorAll<HTMLElement>(".planning-gantt-track").forEach((track, index) => {
          labels.forEach(([left, label]) => track.insertAdjacentHTML(
            "beforeend",
            `<span class="gantt-milestone" style="left:${left}%"><i></i>${index === 0 ? `<b>${label}</b>` : ""}</span>`,
          ));
        });
        pane.querySelectorAll<HTMLButtonElement>("[data-gantt-zoom]").forEach(button => button.addEventListener("click", () => {
          const current = Number.parseInt(pane.style.getPropertyValue("--gantt-day-width"), 10) || 28;
          const next = Math.max(20, Math.min(52, current + Number(button.dataset.ganttZoom) * 6));
          pane.style.setProperty("--gantt-day-width", `${next}px`);
          notify(`Escala do Gantt: ${next}px por dia.`);
        }));
        pane.querySelector("[data-gantt-today]")?.addEventListener("click", () => {
          pane.scrollTo({ left: Math.max(0, pane.scrollWidth * 0.28), behavior: "smooth" });
          notify("Cronograma centralizado na janela atual.");
        });
      }
    }
  };
  return ViewLayer;
}

interface AtlasCommercialWorkspaceViewLayer extends HTMLElement {}

interface AtlasCommercialWorkspaceViewLayerConstructor {
  prototype: AtlasCommercialWorkspaceViewLayer & { bindCommercialPagesV7?: () => void };
}

interface AtlasCommissionProfileExport {
  name: unknown;
  creci: unknown;
  sales: unknown;
  commission: unknown;
  conversion: unknown;
  lots: unknown[];
}

export interface AtlasCommercialWorkspaceEventInput {
  ViewLayer: AtlasCommercialWorkspaceViewLayerConstructor;
  readState(): Record<string, unknown>;
  onCommand(command: AtlasCommercialWorkspaceCommandV1): void;
  downloadCsv(fileName: string, columns: unknown[], rows: unknown[][]): void;
  commissionProfiles: AtlasCommissionProfileExport[];
  reportCatalog: ReportDefinition[];
  syncLiveSystemReportV1(state: Record<string, unknown>): void;
  windowRef?: Window & { lucide?: { createIcons(): void } };
}

export type AtlasCommercialWorkspaceCommandV1 =
  | { type: "open-broker"; profileId?: string }
  | { type: "open-finance-report"; reportId?: string }
  | { type: "select-report-period"; period?: string; label: string };

export type AtlasCommissionWorkspaceComponentCommandV1 =
  | { type: "commission-filter"; key: string; value: string }
  | { type: "commission-clear-filters" }
  | { type: "commission-exported" }
  | { type: "commission-new-entry" }
  | { type: "commission-cancel-entry" }
  | { type: "commission-edit-entry"; id: string }
  | { type: "commission-delete-entry"; id: string }
  | { type: "commission-open-deal"; id: string }
  | { type: "commission-save-entry"; values: Record<string, FormDataEntryValue> };

/** Install typed broker search/export and financial report interactions. */
export function installAtlasCommercialWorkspaceEvents(input: AtlasCommercialWorkspaceEventInput): AtlasCommercialWorkspaceViewLayerConstructor {
  const { ViewLayer, readState, onCommand, downloadCsv, commissionProfiles, reportCatalog, syncLiveSystemReportV1 } = input;
  const windowRef = input.windowRef ?? globalThis.window as Window & { lucide?: { createIcons(): void } };
  ViewLayer.prototype.bindCommercialPagesV7 = function (this: AtlasCommercialWorkspaceViewLayer): void {
    const root = this.querySelector<HTMLElement>(".v7-brokers-page,.v7-finance-page");
    if (!root || root.dataset.v7Bound) return;
    root.dataset.v7Bound = "1";
    if (root.matches(".v7-finance-page")) {
      root.querySelector("[data-v7-finance-export]")?.insertAdjacentHTML(
        "afterend",
        '<button type="button" class="toolbar-action" data-v7-finance-print>Imprimir</button>',
      );
      root.querySelector("[data-v7-finance-print]")?.addEventListener("click", () => windowRef?.print());
    }
    root.querySelector<HTMLInputElement>("[data-v7-broker-search]")?.addEventListener("input", event => {
      const query = (event.currentTarget as HTMLInputElement).value.toLowerCase();
      root.querySelectorAll<HTMLElement>("[data-v7-broker-row]").forEach(row => {
        row.hidden = !(row.dataset.search || "").includes(query);
      });
    });
    root.querySelectorAll<HTMLButtonElement>("[data-v7-open-broker]").forEach(button => button.addEventListener("click", () => onCommand({
      type: "open-broker",
      profileId: button.dataset.v7OpenBroker,
    })));
    root.querySelectorAll<HTMLButtonElement>("[data-v7-fin-report]").forEach(button => button.addEventListener("click", () => onCommand({
      type: "open-finance-report",
      reportId: button.dataset.v7FinReport,
    })));
    root.querySelectorAll<HTMLButtonElement>("[data-v7-period]").forEach(button => button.addEventListener("click", () => onCommand({
      type: "select-report-period",
      period: button.dataset.v7Period,
      label: button.textContent?.trim() || "",
    })));
    root.querySelector("[data-v7-brokers-export]")?.addEventListener("click", () => downloadCsv(
      "corretores.csv",
      ["Corretor", "CRECI", "Vendas", "Comissão", "Conversão", "Lotes"],
      commissionProfiles.map(profile => [profile.name, profile.creci, profile.sales, profile.commission, profile.conversion, profile.lots.join(" | ")]),
    ));
    root.querySelector("[data-v7-finance-export]")?.addEventListener("click", () => {
      const state = readState();
      syncLiveSystemReportV1(state);
      const report = reportCatalog.find(item => item.id === readState().reportType)
        || reportCatalog.find(item => item.family === "Financeiro");
      if (report) downloadCsv(`${report.id}.csv`, report.columns, report.rows);
    });
    windowRef?.lucide?.createIcons();
  };
  return ViewLayer;
}

interface AtlasFinanceAgentTraceStepV1 extends Record<string, unknown> {
  label?: string;
  title?: string;
  action?: string;
  detail?: string;
  message?: string;
  description?: string;
  at?: string;
  createdAt?: string;
  status?: string;
}

interface AtlasFinanceAgentEventV1 extends Record<string, unknown> {
  id?: string | number;
  date?: string;
  kind?: string;
  category?: string;
  stage?: string;
  stageName?: string;
  owner?: string;
  status?: string;
  description?: string;
  amountCents?: number;
  createdAt?: string;
  updatedAt?: string;
  at?: string;
  title?: string;
  label?: string;
  type?: string;
  eventType?: string;
  source?: string;
  message?: string;
  detail?: string;
  severity?: string;
  entity?: string;
  entityId?: string;
  steps?: AtlasFinanceAgentTraceStepV1[];
  actionSteps?: AtlasFinanceAgentTraceStepV1[];
  timeline?: AtlasFinanceAgentTraceStepV1[];
  trace?: AtlasFinanceAgentTraceStepV1[];
  expanded?: boolean;
  role?: string;
}

interface AtlasFinanceRecord extends AtlasFinanceAgentEventV1 {
  cash?: AtlasOperationalCashStateV1;
  stages?: AtlasOperationalReadinessStageV1[];
  operationalState?: AtlasOperationalReadinessStateV1 | null;
  operationalNotifications?: AtlasOperationalNotificationV1[];
  controlChangeLog?: AtlasFinanceAgentEventV1[];
  controlRealtime?: { events?: Record<string, AtlasFinanceAgentEventV1> };
  operationalGuidance?: AtlasOperationalGuidanceV1 | null;
  operationalAgenda?: AtlasStageAgendaCalendarEventV1[];
  focalStage?: AtlasOperationalGuidanceStageV1 | null;
  summary?: string;
  cashAction?: string;
  plannedStart?: string;
  plannedFinish?: string;
  adjustedRate?: number | null;
  blockedBy?: string[];
  coverage?: number;
  needCents?: number;
  allocatedCents?: number;
  balanceCents?: number;
  entriesCents?: number;
  exitsCents?: number;
  reserveCents?: number;
  allocatableCents?: number;
  calibrationVersion?: number;
}
const atlasFinanceRecord = (value: unknown): AtlasFinanceRecord => value && typeof value === "object" && !Array.isArray(value) ? value as AtlasFinanceRecord : {};
const atlasFinanceRecords = (value: unknown): AtlasFinanceRecord[] => Array.isArray(value) ? value.map(atlasFinanceRecord) : [];
const atlasFinanceText = (value: unknown, fallback = ""): string => String(value ?? fallback);
const atlasFinanceNumber = (value: unknown): number => Number(value) || 0;

interface AtlasFinanceViewLayer extends HTMLElement {
  bindCommercialPagesV7?(): void;
  finance(...args: unknown[]): string;
}

interface AtlasFinanceViewLayerConstructor {
  prototype: AtlasFinanceViewLayer;
}

export interface AtlasFinanceWorkspaceInput {
  readState(): AtlasApplicationStoreState;
  executionModel: AtlasExecutionModelSeed;
  esc(value: unknown): string;
  ico(name: string): string;
  formatBRL(value: number): string;
  queueMicrotaskFn(callback: () => void): void;
  DateCtor: DateConstructor;
}

export interface AtlasFinanceWorkspaceRenderers {
  cashRecordLauncherMarkupV1(returnView?: string): string;
  financeAgentAwarenessMarkupV1(state: AtlasApplicationStoreState): string;
  financeControlV8(this: AtlasFinanceViewLayer, ...args: unknown[]): string;
}

/** Build the typed finance ledger, cash controls and agent-awareness markup. */
export function createAtlasFinanceWorkspace(input: AtlasFinanceWorkspaceInput): AtlasFinanceWorkspaceRenderers {
  const { readState, executionModel, esc, ico, formatBRL, queueMicrotaskFn, DateCtor } = input;
  if (typeof readState !== "function") throw new TypeError("Finance workspace requires readState().");
  for (const [name, dependency] of Object.entries({ esc, ico, formatBRL, queueMicrotaskFn, DateCtor })) if (typeof dependency !== "function") throw new TypeError(`Finance workspace requires ${name}().`);
  if (!executionModel || typeof executionModel !== "object") throw new TypeError("Finance workspace requires the execution model.");

  const cashRecordLauncherMarkupV1 = (returnView = "finance"): string => {
    const actorValue = readState().currentActor;
    const actor = actorValue && typeof actorValue === "object" ? atlasFinanceRecord(actorValue) : { role: "owner", label: "Dono" };
    const role = atlasFinanceText(actor.role);
    const allowed = role === "owner" || role === "developer";
    return `<section class="cash-record-launcher" data-cash-record-launcher><div><span class="activity-kind">SAÍDAS DE CAIXA</span><h2>Registrar uma saída</h2><p>Entradas de lotes e repasses são registradas exclusivamente na página Repasses.</p></div>${allowed ? `<button type="button" class="toolbar-primary" data-cash-record-open data-return-view="${esc(returnView)}">${ico("plus")} Nova saída</button>` : `<span class="cash-record-permission">Somente o Dono pode registrar movimentações.</span>`}</section>`;
  };

  const agentAwarenessStepsV1 = (item: AtlasFinanceRecord): Array<{ label: string; detail: string; at: unknown; status: string }> => {
    const baseAt = item.createdAt || item.updatedAt || item.at || new DateCtor().toISOString();
    const supplied = [item.steps, item.actionSteps, item.timeline, item.trace].find(value => Array.isArray(value) && value.length > 0);
    if (supplied) return supplied.map((value, index) => {
      const step = atlasFinanceRecord(value);
      return {
        label: atlasFinanceText(step.label || step.title || step.action || `Passo ${index + 1}`),
        detail: atlasFinanceText(step.detail || step.message || step.description || "Etapa registrada pelo agente."),
        at: step.at || step.createdAt || baseAt,
        status: atlasFinanceText(step.status || "registrado"),
      };
    });
    const type = atlasFinanceText(item.type || item.eventType).toLowerCase();
    const subject = atlasFinanceText(item.entity || item.entityId || "contexto operacional");
    const labels: Array<[string, string]> = type.includes("cash")
      ? [["Evento financeiro recebido", "O motor identificou uma alteração relacionada ao caixa."], ["Saldo e cobertura recalculados", "As dependências e a capacidade de alocação foram comparadas."], ["Orientação encaminhada", "O alerta permanece disponível para decisão humana."]]
      : type.includes("material")
        ? [["Status de material recebido", "A entrada foi relacionada ao acompanhamento operacional."], ["Cobertura de suprimentos avaliada", "O agente comparou pendências e recebimentos da frente."], ["Ação sugerida registrada", "A equipe responsável deve confirmar a próxima providência."]]
        : type.includes("stage") || type.includes("activity")
          ? [["Evento da etapa recebido", "A alteração foi vinculada à frente correspondente."], ["Dependências verificadas", "O agente conferiu bloqueios, progresso e condições de execução."], ["Próximo passo preparado", "A recomendação aguarda confirmação ou novo registro."]]
          : [["Registro recebido", "O evento entrou na fila de ciência do agente."], ["Contexto relacionado", `A ação foi vinculada a ${subject}.`], ["Resultado aguardando confirmação", "Nenhuma alteração externa é aplicada sem uma ação autorizada."]];
    return labels.map(([label, detail], index) => ({
      label,
      detail: index === 0 && item.message ? String(item.message) : detail,
      at: baseAt,
      status: index === labels.length - 1 ? "aguardando" : "concluído",
    }));
  };

  const agentAwarenessEntriesV1 = (state: AtlasApplicationStoreState): AtlasFinanceRecord[] => {
    const notifications: AtlasFinanceRecord[] = atlasFinanceRecords(state.operationalNotifications).map(item => ({
      ...item,
      source: "Motor operacional",
      title: item.title || item.type || "Notificação do agente",
      message: item.message || "Evento recebido pelo agente.",
    }));
    const local: AtlasFinanceRecord[] = atlasFinanceRecords(state.controlChangeLog).map(item => ({
      id: `local-${item.id || item.at || item.label}`,
      type: "control.change",
      source: "Sessão local",
      title: item.label || "Alteração registrada",
      message: item.detail || "Alteração local capturada.",
      createdAt: item.at,
      entity: item.entity,
      entityId: item.entityId,
      steps: item.steps,
    }));
    const realtime: AtlasFinanceRecord[] = Object.values(atlasFinanceRecord(atlasFinanceRecord(state.controlRealtime).events)).map(value => {
      const item = atlasFinanceRecord(value);
      return {
        ...item,
        id: `rtdb-${item.id || item.createdAt || item.type}`,
        source: "RTDB",
        title: item.label || item.type || "Evento em tempo real",
        message: item.detail || item.message || "Evento recebido em tempo real.",
        createdAt: item.createdAt || item.updatedAt,
      };
    });
    return [...notifications, ...local, ...realtime]
      .filter(item => item.title || item.message)
      .sort((a, b) => atlasFinanceText(b.createdAt || b.updatedAt || b.at).localeCompare(atlasFinanceText(a.createdAt || a.updatedAt || a.at)))
      .slice(0, 10);
  };

  const agentAwarenessLogV1 = (item: AtlasFinanceRecord): string => {
    const steps = agentAwarenessStepsV1(item);
    const timestamp = item.createdAt || item.updatedAt || item.at;
    const date = timestamp ? new DateCtor(String(timestamp)) : null;
    const timeLabel = date && !Number.isNaN(date.getTime()) ? date.toLocaleString("pt-BR") : "agora";
    const severity = atlasFinanceText(item.severity || "info").toLowerCase();
    const logId = atlasFinanceText(item.id || `${item.type || "agent"}-${timestamp || "now"}`);
    return `<details class="finance-agent-log ${esc(severity)}" data-agent-log="${esc(logId)}"${item.expanded ? " open" : ""}><summary><span class="finance-agent-log-marker">${ico("chevron-right")}</span><span class="finance-agent-log-main"><time>${esc(timeLabel)}</time><b>${esc(item.title || "Registro do agente")}</b><small>${esc(item.message || "")}</small></span><span class="finance-agent-log-meta"><i>${esc(item.source || "Agente")}</i><b>${steps.length} passo${steps.length === 1 ? "" : "s"}</b></span></summary><div class="finance-agent-log-body"><div class="finance-agent-log-context"><span>${esc(String(item.type || "ação operacional"))}</span><small>${esc(item.entity ? `${item.entity}${item.entityId ? ` · ${item.entityId}` : ""}` : "Sem entidade informada")}</small></div><ol>${steps.map(step => {
      const stepDate = new DateCtor(String(step.at || timestamp || ""));
      const stepTime = !Number.isNaN(stepDate.getTime()) ? stepDate.toLocaleString("pt-BR") : timeLabel;
      return `<li><time>${esc(stepTime)}</time><div><b>${esc(step.label)}</b><small>${esc(step.detail)}</small></div><em class="${esc(step.status)}">${esc(step.status)}</em></li>`;
    }).join("")}</ol></div></details>`;
  };

  const financeAgentAwarenessMarkupV1 = (state: AtlasApplicationStoreState): string => {
    const logs = agentAwarenessEntriesV1(state).map((item, index) => agentAwarenessLogV1({ ...item, expanded: index === 0 }));
    return `<section class="finance-notification-list finance-agent-awareness" data-agent-awareness><header><div><span class="activity-kind">CIÊNCIA DO AGENTE</span><h2>Registros e passos da ação</h2><p>Abra cada ocorrência para acompanhar o horário, o contexto e a sequência observada pelo agente.</p></div><span class="finance-agent-awareness-count">${logs.length} registros · mais recente primeiro</span></header><div class="finance-agent-log-list">${logs.join("") || '<p class="finance-agent-empty">Nenhum registro para o perfil atual.</p>'}</div></section>`;
  };

  const financeControlV8 = function (this: AtlasFinanceViewLayer): string {
    const state = readState();
    const actor = atlasFinanceRecord(state.currentActor);
    const role = atlasFinanceText(actor.role || "owner");
    const summary = state.cashSummary || { balanceCents: 0, entriesCents: 0, exitsCents: 0 };
    const operational = state.operationalState;
    const cash = operational?.cash;
    const entries = state.cashFlowLocal || [];
    const notifications = state.operationalNotifications || [];
    const guidance = state.operationalGuidance;
    const agenda = (state.operationalAgenda || []).slice(0, 4);
    const stages = operational?.stages || [];
    queueMicrotaskFn(() => this.bindCommercialPagesV7?.());
    const focalStage = guidance?.focalStage;
    const guidanceMarkup = guidance ? `<section class="control-ledger"><header><div><span class="activity-kind">INFERÊNCIA OPERACIONAL CENTRAL</span><h2>${esc(focalStage?.name || "Frente prioritária")}</h2></div><small>${esc(guidance.summary)}</small></header><div class="finance-allocation-list"><article><span>01</span><div><b>Ação de caixa</b><small>${esc(guidance.cashAction || "Sem ação definida")}</small></div><div><small>Início previsto</small><b>${esc(focalStage?.plannedStart || "—")}</b></div><div><small>Fim previsto</small><b>${esc(focalStage?.plannedFinish || "—")}</b></div><em>${esc(String(focalStage?.adjustedRate ?? "—"))}</em></article>${agenda.map((item, index) => `<article><span>${String(index + 2).padStart(2, "0")}</span><div><b>${esc(item.title)}</b><small>${esc(item.stageName)} · ${esc(item.owner || "Responsável a definir")}</small></div><div><small>Início</small><b>${esc(item.plannedStart || "—")}</b></div><div><small>Status</small><b>${esc(item.status)}</b></div><em>${esc(item.category || "Agenda")}</em></article>`).join("")}</div></section>` : "";
    const cashEntry = role === "owner" || role === "developer"
      ? `<form class="cash-entry-control" data-v8-cash-entry><header><div><span class="activity-kind">NOVO LANÇAMENTO · AUTORIDADE DO DONO</span><h2>Movimentar fluxo de caixa</h2></div><small>Correções futuras devem usar estorno ou ajuste, preservando a trilha.</small></header><div><label>Tipo<select name="kind"><option value="entrada">Entrada</option><option value="saida">Saída</option></select></label><label>Data<input type="date" name="date" value="${new DateCtor().toISOString().slice(0, 10)}" required></label><label>Categoria<input name="category" placeholder="Vendas, obra, ajuste…" required></label><label>Etapa<select name="stage"><option>Geral</option>${executionModel.stages.map(item => `<option>${esc(item.name)}</option>`).join("")}</select></label><label>Valor (R$)<input name="amount" inputmode="decimal" placeholder="0,00" required></label><label class="wide">Origem / descrição<input name="description" placeholder="Identifique recebimento, pagamento, estorno ou ajuste" required></label></div><footer><span data-v8-cash-status>O agente recalculará todas as frentes após confirmar.</span><button type="submit">${ico("wallet-cards")} Registrar e recalcular</button></footer></form>`
      : `<div class="role-boundary-notice">${ico("lock-keyhole")} Somente o Dono altera o caixa. Seu perfil atual é ${esc(actor.label || role)}</div>`;
    const stageRows = stages.map((stage, index) => {
      const blockedBy = stage.blockedBy || [];
      const coverage = stage.coverage;
      return `<article><span>${String(index + 1).padStart(2, "0")}</span><div><b>${esc(stage.name)}</b><small>${blockedBy.length ? `Bloqueada por ${blockedBy.join(", ")}` : "Elegível conforme relações"}</small></div><div><small>Necessidade</small><b>${formatBRL(atlasFinanceNumber(stage.needCents) / 100)}</b></div><div><small>Alocado</small><b>${formatBRL(atlasFinanceNumber(stage.allocatedCents) / 100)}</b></div><em class="${coverage < 35 ? "critical" : ""}">${coverage}%</em></article>`;
    }).join("");
    const ledgerRows = entries.map(item => `<tr data-v8-finance-row data-search="${esc(JSON.stringify(item).toLowerCase())}"><td><b>${esc(item.date)}</b><small>${esc(item.id)}</small></td><td><span class="cash-kind ${esc(item.kind)}">${esc(item.kind)}</span></td><td>${esc(item.category)}</td><td>${esc(item.stage)}</td><td>${esc(item.description)}</td><td><b>${item.kind === "saida" ? "−" : "＋"} ${formatBRL(atlasFinanceNumber(item.amountCents) / 100)}</b></td></tr>`).join("");
    const notificationRows = notifications.slice(0, 6).map(item => `<article class="${esc(item.severity || "info")}"><b>${esc(item.title || "")}</b><p>${esc(item.message || "")}</p><small>${item.createdAt ? new DateCtor(item.createdAt).toLocaleString("pt-BR") : ""}</small></article>`).join("");
    return `<section class="control-page finance-control-page"><header class="control-page-head"><div><span class="activity-kind">GESTÃO FINANCEIRA · CONTROLE TOTAL</span><h1>Caixa e distribuição da obra</h1><p>Livro-razão, reserva operacional, alocação por dependência e alertas do agente.</p></div><div class="control-head-actions"><button type="button" data-view="reports">${ico("chart-no-axes-combined")} Relatórios gerenciais</button><button type="button" class="toolbar-primary" data-v7-finance-export>${ico("download")} Exportar dados</button></div></header><section class="finance-master-grid"><article class="finance-master-balance"><span>CAIXA MESTRE · DONO</span><strong>${formatBRL(atlasFinanceNumber(summary.balanceCents ?? cash?.balanceCents) / 100)}</strong><small>Entradas ${formatBRL(atlasFinanceNumber(summary.entriesCents) / 100)} · Saídas ${formatBRL(atlasFinanceNumber(summary.exitsCents) / 100)}</small></article><article><small>Reserva mínima</small><b>${formatBRL(atlasFinanceNumber(cash?.reserveCents) / 100)}</b><span>calibrada pelo Administrador</span></article><article><small>Disponível para alocação</small><b>${formatBRL(atlasFinanceNumber(cash?.allocatableCents) / 100)}</b><span>após reserva operacional</span></article><article><small>Notificações do perfil</small><b>${notifications.length}</b><span>eventos auditáveis</span></article></section>${guidanceMarkup}${cashEntry}<section class="finance-allocation-board"><header><div><span class="activity-kind">ALOCAÇÃO SEQUENCIAL · VERSÃO ${operational?.calibrationVersion || 1}</span><h2>Capacidade financeira por etapa</h2></div><button type="button" data-view="settings">Abrir calibrações</button></header><div class="finance-allocation-list">${stageRows || "<p>Aguardando o primeiro cálculo operacional.</p>"}</div></section><section class="control-ledger finance-ledger"><header><div><span class="activity-kind">LIVRO-RAZÃO</span><h2>Entradas e saídas registradas</h2></div><label>Filtrar lançamentos<input data-v8-finance-search placeholder="ID, etapa, categoria ou descrição"></label></header><div class="control-table-wrap"><table><thead><tr><th>Data / ID</th><th>Natureza</th><th>Categoria</th><th>Etapa</th><th>Descrição</th><th>Valor</th></tr></thead><tbody>${ledgerRows}</tbody></table></div></section><aside class="finance-notification-list"><span class="activity-kind">CIÊNCIA DO AGENTE</span>${notificationRows || "<p>Nenhuma notificação para o perfil atual.</p>"}</aside></section>`;
  };

  return { cashRecordLauncherMarkupV1, financeAgentAwarenessMarkupV1, financeControlV8 };
}

export interface AtlasFinancePageInstallInput {
  ViewLayer: AtlasFinanceViewLayerConstructor;
  workspace: AtlasFinanceWorkspaceRenderers;
  readState(): AtlasApplicationStoreState;
}

/** Compose the financial route from the finance component and auxiliary panels. */
export function installAtlasFinancePage(input: AtlasFinancePageInstallInput): AtlasFinanceViewLayerConstructor {
  const { ViewLayer, workspace, readState } = input;
  if (!ViewLayer?.prototype || typeof workspace.financeControlV8 !== "function" || typeof workspace.cashRecordLauncherMarkupV1 !== "function" || typeof workspace.financeAgentAwarenessMarkupV1 !== "function") throw new TypeError("Finance page requires a complete finance workspace.");
  ViewLayer.prototype.finance = function (this: AtlasFinanceViewLayer, ...args: unknown[]): string {
    const html = workspace.financeControlV8.apply(this, args);
    const withPrint = html.replace(/(<button type="button" class="toolbar-primary" data-v7-finance-export>[\s\S]*?<\/button>)/, match => `${match}<button type="button" class="toolbar-action" data-v7-finance-print>Imprimir</button>`);
    const withCashRecordLauncher = withPrint.replace(/<form class="cash-entry-control" data-v8-cash-entry>[\s\S]*?<\/form>|<div class="role-boundary-notice">[\s\S]*?<\/div>/, workspace.cashRecordLauncherMarkupV1("finance"));
    return withCashRecordLauncher.replace(/<aside class="finance-notification-list">[\s\S]*?<\/aside>/, workspace.financeAgentAwarenessMarkupV1(readState()));
  };
  return ViewLayer;
}

