/** Build attachment markup for the chat component. */
function renderAtlasWorkerContextChatAttachmentListMarkupV1(
  slot: HTMLElement | null,
  files: readonly AtlasWorkerContextChatAttachmentItemV1[],
): boolean {
  if (!slot) return false;
  const escape = escapeAtlasWorkerChatValueV1;
  slot.hidden = files.length === 0;
  slot.innerHTML = files.map((file, index) =>
    `<span><b>${escape(file.name)}</b><small>${escape(file.mimeType)}</small></span><button type="button" data-worker-chat-attachment-remove="${index}" aria-label="Remover ${escape(file.name)}">×</button>`
  ).join('');
  return true;
}

