export interface AtlasWorkerContextChatMountControllerV1 {
  root: HTMLElement | null;
  log: HTMLElement | null;
  input: HTMLTextAreaElement | null;
  status: HTMLElement | null;
  sessionStateOwnerV1: string;
  voiceController: unknown;
  getVoiceState(): { enabled: boolean; profile: string };
  render(): void;
  bind(): void;
  installRecordSavedEvent(): void;
  installObservation(): void;
}

/** Mount the chat shell and attach its view, event, record, and observation owners. */
export function mountAtlasWorkerContextChatV1(input: {
  documentRef: Document;
  controller: AtlasWorkerContextChatMountControllerV1;
  pathname: string;
  labelForPath(pathname: string): string;
  speakerProfiles: readonly { id: unknown; label: unknown }[];
  mobileDefaultCollapsed: boolean;
}): boolean {
  const documentRef = input?.documentRef;
  const controller = input?.controller;
  if (!documentRef?.body || !controller) return false;
  if (documentRef.querySelector('[data-worker-context-assistant]')) return true;
  const voice = controller.getVoiceState();
  const markup = renderAtlasWorkerContextChatShellV1({
    monitorLabel: input.labelForPath(input.pathname),
    voiceEnabled: voice.enabled,
    speakerProfile: voice.profile,
    speakerProfiles: input.speakerProfiles,
    mobileDefaultCollapsed: input.mobileDefaultCollapsed,
  });
  if (!markup) return false;

  documentRef.body.insertAdjacentHTML('beforeend', markup);
  const root = documentRef.querySelector<HTMLElement>('[data-worker-context-assistant]');
  if (!root) return false;
  controller.root = root;
  root.dataset.chatSessionStateOwnerV1 = controller.sessionStateOwnerV1 || 'mjs-fallback';
  root.dataset.chatShellRendererOwnerV1 = 'typescript';
  root.dataset.chatVoiceOwnerV1 = controller.voiceController ? 'typescript' : 'mjs-fallback';
  controller.log = documentRef.querySelector<HTMLElement>('[data-worker-chat-log]');
  controller.input = root.querySelector<HTMLTextAreaElement>('textarea');
  controller.status = root.querySelector<HTMLElement>('[data-worker-chat-status]');
  controller.render();
  controller.bind();
  controller.installRecordSavedEvent();
  controller.installObservation();
  return true;
}

export interface AtlasGlaucoShellBridgeHostV1 {
  documentRef: Document;
  windowRef: Window & typeof globalThis;
  customElementsRef?: CustomElementRegistry;
}

/** Install the optional legacy shell bridge and keep view selection on the existing sidebar route. */
export function installAtlasGlaucoShellBridgeComponentV1(input: AtlasGlaucoShellBridgeHostV1): boolean {
  const documentRef = input?.documentRef;
  const windowRef = input?.windowRef;
  if (!documentRef?.documentElement || !windowRef) return false;
  if (new URLSearchParams(windowRef.location.search).get('glauco_shell') !== '1') return false;
  if (documentRef.documentElement.dataset.glaucoShellBridgeOwnerV1 === 'typescript') return true;

  documentRef.documentElement.dataset.glaucoShell = '1';
  if (!documentRef.getElementById('glauco-shell-v50-style')) {
    const style = documentRef.createElement('style');
    style.id = 'glauco-shell-v50-style';
    style.textContent = `
      html[data-glauco-shell="1"] app-sidebar { display:none!important; }
      html[data-glauco-shell="1"] .app-shell,
      html[data-glauco-shell="1"] .app-shell.sidebar-collapsed { grid-template-columns:minmax(0,1fr)!important; }
      html[data-glauco-shell="1"] .app-main { grid-column:1!important; width:100%!important; min-width:0!important; }
      html[data-glauco-shell="1"] .mobile-menu-trigger { display:none!important; }
    `;
    documentRef.head.append(style);
  }

  let applying = false;
  let attempts = 0;
  let retryTimer: number | null = null;
  const requestedState = (): { view: string; reportFamily: string } => {
    const hash = new URLSearchParams(String(windowRef.location.hash || '').replace(/^#/, ''));
    return { view: hash.get('view') || 'map', reportFamily: hash.get('reportFamily') || '' };
  };
  const applyView = (): void => {
    if (applying) return;
    const requested = requestedState();
    const view = requested.view;
    let selector = `[data-view="${windowRef.CSS.escape(view)}"]`;
    if (view === 'reports' && requested.reportFamily)
      selector = `[data-view="reports"][data-report-family="${windowRef.CSS.escape(requested.reportFamily)}"]`;

    const target = documentRef.querySelector<HTMLElement>(selector);
    if (!target) {
      attempts += 1;
      if (attempts < 80) retryTimer = windowRef.setTimeout(applyView, 100);
      return;
    }
    attempts = 0;
    applying = true;
    try {
      target.click();
      windowRef.dispatchEvent(new windowRef.CustomEvent('glauco:legacy-view', { detail: { view } }));
    } finally {
      windowRef.queueMicrotask(() => { applying = false; });
    }
  };

  windowRef.addEventListener('hashchange', applyView);
  windowRef.addEventListener('DOMContentLoaded', applyView);
  (input.customElementsRef || windowRef.customElements).whenDefined('app-sidebar')
    .then(() => windowRef.setTimeout(applyView, 0))
    .catch(() => undefined);
  windowRef.setTimeout(applyView, 100);
  documentRef.documentElement.dataset.glaucoShellBridgeOwnerV1 = 'typescript';
  return true;
}

