/** Bind Worker chat DOM events to typed component transitions and program ports. */
export function installAtlasWorkerContextChatBindingsV1(input: {
  root: HTMLElement;
  controller: AtlasWorkerContextChatBindingControllerV1;
  programOwners: Readonly<Record<string, unknown>>;
  componentOwners: AtlasWorkerContextChatBindingComponentsV1;
  serviceKey: string;
  setStorage(key: string, value: string): void;
  native: boolean;
  capturePhoto?: () => Promise<File | null>;
  installSwipeSheet?: (input: { root: HTMLElement; setCollapsed(collapsed: boolean): void; native: boolean }) => void;
}): boolean {
  const root = input?.root;
  const components = input?.componentOwners;
  const controller = input?.controller;
  const installInteraction = components?.installAtlasWorkerContextChatInteractionEventsV1;
  const installComposer = components?.installAtlasWorkerContextChatComposerEventsV1;
  if (!root || !controller || typeof installInteraction !== 'function' || typeof installComposer !== 'function') return false;

  const programOwner = (name: string): boolean => typeof input.programOwners?.[name] === 'function';
  const componentOwner = (name: string): boolean => typeof components[name] === 'function';
  root.dataset.chatRecordReviewOwnerV1 = programOwner('applyAtlasWorkerContextChatRecordReviewFlowV1') ? 'typescript' : 'mjs-fallback';
  root.dataset.chatRecordDrawerOwnerV1 = componentOwner('openAtlasWorkerContextChatRecordDrawerV1') ? 'typescript' : 'mjs-fallback';
  root.dataset.chatPendingStateOwnerV1 = componentOwner('applyAtlasWorkerContextChatPendingStateV1') ? 'typescript' : 'mjs-fallback';
  root.dataset.chatTabStateOwnerV1 = componentOwner('applyAtlasWorkerContextChatTabV1') ? 'typescript' : 'mjs-fallback';
  root.dataset.chatMapContextOwnerV1 = componentOwner('applyAtlasWorkerContextChatMapContextV1') ? 'typescript' : 'mjs-fallback';
  root.dataset.chatAttachmentRendererOwnerV1 = componentOwner('renderAtlasWorkerContextChatAttachmentListV1') ? 'typescript' : 'mjs-fallback';
  root.dataset.chatComposerSubmissionOwnerV1 = programOwner('projectAtlasWorkerContextChatComposerSubmissionV1') ? 'typescript' : 'mjs-fallback';
  root.dataset.chatComposerSubmitBindingOwnerV1 = 'typescript';
  root.dataset.chatQuickActionOwnerV1 = componentOwner('runAtlasWorkerContextChatQuickActionV1') ? 'typescript' : 'mjs-fallback';
  root.dataset.chatIntentPlanOwnerV1 = programOwner('projectAtlasWorkerContextChatActionPlanV1') ? 'typescript' : 'legacy';
  root.dataset.chatCommandExecutorOwnerV1 = programOwner('executeAtlasWorkerContextChatCommandsV1') ? 'typescript' : 'legacy';
  root.dataset.chatFileReaderOwnerV1 = componentOwner('readAtlasWorkerContextChatFileV1') ? 'typescript' : 'unavailable';
  root.dataset.chatServiceRequestsOwnerV1 = programOwner('createAtlasWorkerContextChatServiceRequestV1') ? 'typescript' : 'legacy';
  root.dataset.chatVisualAllocationOwnerV1 = programOwner('projectAtlasWorkerContextChatVisualAllocationCallsV1') ? 'typescript' : 'mjs-recovery';
  root.dataset.chatStageInterpretationOwnerV1 = programOwner('resolveAtlasWorkerContextChatVisualStageV1') ? 'typescript' : 'mjs-fallback';
  root.dataset.chatRecordInterpretationOwnerV1 = programOwner('buildAtlasWorkerContextChatRecordInterpretationV1') ? 'typescript' : 'mjs-fallback';
  root.dataset.chatVisualClarificationOwnerV1 = programOwner('projectAtlasWorkerContextChatVisualClarificationV1') ? 'typescript' : 'mjs-fallback';
  root.dataset.chatInferenceRequestOwnerV1 = programOwner('requestAtlasWorkerContextChatReplyV1') ? 'typescript-program-ready' : 'legacy';

  input.installSwipeSheet?.({ root, setCollapsed: value => controller.setCollapsed(value), native: input.native });
  installInteraction(root, {
    discardRecord: () => controller.discardRecord(),
    applyRecord: () => controller.applyRecord(),
    minimize: () => controller.setCollapsed(!root.classList.contains('is-collapsed')),
    openCollapsedHead: () => controller.setCollapsed(false),
    toggleVoice: () => controller.toggleVoice(),
    selectSpeaker: profile => controller.selectSpeaker(profile),
    setStatus: message => {
      const status = root.querySelector<HTMLElement>('[data-worker-chat-status]');
      if (status) status.textContent = message;
    },
    previewSpeaker: () => controller.speak('Olá. Sou o assistente operacional do Aliança Park. Esta é uma prévia da voz selecionada.'),
    refreshServiceRequest: () => controller.refreshServiceRequest(),
    startEdit: messageId => controller.startEdit(messageId),
    speak: text => controller.speak(text),
    selectService: serviceId => {
      input.setStorage(input.serviceKey, serviceId);
      controller.refreshServiceRequest();
    },
  });
  root.dataset.chatInteractionEventsOwnerV1 = 'typescript';

  installComposer(root, {
    readFiles: (files, source) => files.forEach(file => controller.readImage(file, source)),
    capturePhoto: input.capturePhoto,
    readSubmission: () => controller.readComposerSubmission?.()
      || {
        text: controller.input?.value || '',
        editingId: controller.editingId,
        attachment: controller.attachment,
        files: controller.files,
      },
    clearSubmission: () => {
      if (controller.clearComposerSubmission) {
        controller.clearComposerSubmission();
        return;
      }
      controller.editingId = null;
      controller.attachment = null;
      controller.files = [];
      controller.renderAttachment();
    },
    submit: submission => controller.submit(submission.text, submission.editingId, submission.attachment, submission.files),
    isPending: () => controller.pending,
    removeAttachment: index => controller.removeAttachmentAt(index),
    selectTab: tab => controller.setTab(tab),
  });
  root.dataset.chatComposerEventsOwnerV1 = 'typescript';
  return true;
}

/** Render a chat snapshot through the active Web Element or the typed markup renderer. */
export function renderAtlasWorkerContextChatConversationV1(input: {
  root: HTMLElement | null;
  log: HTMLElement | null;
  conversation: AtlasWorkerContextChatLogInputV1;
}): HTMLElement | null {
  const root = input?.root;
  const log = input?.log;
  if (!log) return null;
  const componentHost = root as (HTMLElement & {
    renderConversation?: (conversation: AtlasWorkerContextChatLogInputV1) => boolean;
  }) | null;
  const renderConversation = componentHost?.renderConversation;
  if (typeof renderConversation === 'function' && renderConversation.call(root, input.conversation)) {
    if (root) root.dataset.chatLogRendererOwnerV1 = 'typescript-component';
    return root?.querySelector<HTMLElement>('[data-worker-chat-log]') || log;
  }
  const markup = renderAtlasWorkerContextChatLogV1(input.conversation);
  if (!markup) return null;
  log.innerHTML = markup;
  if (root) root.dataset.chatLogRendererOwnerV1 = 'typescript';
  log.scrollTop = log.scrollHeight;
  return log;
}

