export interface AtlasWorkerContextChatObservationHostV1 {
  eventTarget: EventTarget;
  documentRef: Pick<Document, 'body'> & { querySelector: Document['querySelector'] };
  storage?: Pick<Storage, 'getItem' | 'setItem'> | null;
  setTimeout: typeof globalThis.setTimeout;
  clearTimeout: typeof globalThis.clearTimeout;
  requestAnimationFrame: typeof globalThis.requestAnimationFrame;
  cancelAnimationFrame: typeof globalThis.cancelAnimationFrame;
  requestIdleCallback?: (callback: () => void, options?: { timeout?: number }) => number;
  MutationObserverCtor?: typeof MutationObserver;
}

export interface AtlasWorkerContextChatObservationPortsV1 {
  host: AtlasWorkerContextChatObservationHostV1;
  root: HTMLElement;
  route: string;
  routeStorageKey: string;
  pathname(): string;
  readContext(): Record<string, unknown>;
  labelForPath(pathname: string): string;
  projectEventMessage(kind: string, detail: unknown): string;
  projectContextMessages(previous: Record<string, unknown>, current: Record<string, unknown>): string[];
  voiceEnabled(): boolean;
  speak(message: string): void;
}

/** Own route announcements, context polling, transient hints, and monitor clock. */
export function installAtlasWorkerContextChatObservationV1(
  ports: AtlasWorkerContextChatObservationPortsV1,
): () => void {
  const { host, root } = ports;
  if (!host?.eventTarget || !host.documentRef?.body || !root)
    throw new TypeError('Worker chat observation requires an event target, document body, and root.');
  for (const [name, value] of Object.entries({
    setTimeout: host.setTimeout,
    clearTimeout: host.clearTimeout,
    requestAnimationFrame: host.requestAnimationFrame,
    cancelAnimationFrame: host.cancelAnimationFrame,
    pathname: ports.pathname,
    readContext: ports.readContext,
    labelForPath: ports.labelForPath,
    projectEventMessage: ports.projectEventMessage,
    projectContextMessages: ports.projectContextMessages,
    voiceEnabled: ports.voiceEnabled,
    speak: ports.speak,
  })) if (typeof value !== 'function') throw new TypeError(`Worker chat observation requires ${name}().`);

  root.dataset.chatObservationOwnerV1 = 'typescript';
  const Observer = host.MutationObserverCtor || globalThis.MutationObserver;
  let active = true;
  let lastSnapshot = JSON.stringify(ports.readContext());
  let pendingObservation = '';
  let contextTimer: ReturnType<typeof globalThis.setTimeout> | null = null;
  let fadeTimer: ReturnType<typeof globalThis.setTimeout> | null = null;
  let fadeHideTimer: ReturnType<typeof globalThis.setTimeout> | null = null;
  let monitorFrame = 0;

  const showContextualFade = (message: string): void => {
    const node = root.querySelector<HTMLElement>('[data-worker-context-fade]');
    if (!node) return;
    if (fadeTimer !== null) host.clearTimeout(fadeTimer);
    if (fadeHideTimer !== null) host.clearTimeout(fadeHideTimer);
    node.textContent = '';
    const label = host.documentRef.body.ownerDocument.createElement('span');
    label.textContent = 'Percepção contextual · IA';
    const text = host.documentRef.body.ownerDocument.createElement('p');
    text.textContent = String(message || '');
    node.append(label, text);
    node.hidden = false;
    node.classList.remove('is-visible');
    host.requestAnimationFrame(() => { if (active) node.classList.add('is-visible'); });
    fadeTimer = host.setTimeout(() => {
      node.classList.remove('is-visible');
      fadeHideTimer = host.setTimeout(() => {
        if (!node.classList.contains('is-visible')) node.hidden = true;
      }, 420);
    }, 4200);
  };

  const announce = (kind: string, detail: unknown): void => {
    const message = ports.projectEventMessage(kind, detail);
    const key = `${kind}:${message}`;
    if (pendingObservation === key) return;
    pendingObservation = key;
    showContextualFade(message);
    if (ports.voiceEnabled()) ports.speak(message);
  };

  const readSnapshot = (): Record<string, unknown> => {
    try {
      const value = JSON.parse(lastSnapshot || '{}');
      return value && typeof value === 'object' && !Array.isArray(value) ? value : {};
    } catch { return {}; }
  };

  const checkContext = (): void => {
    if (!active) return;
    const next = JSON.stringify(ports.readContext());
    if (next !== lastSnapshot) {
      const previous = readSnapshot();
      const current = JSON.parse(next) as Record<string, unknown>;
      lastSnapshot = next;
      for (const message of ports.projectContextMessages(previous, current)) announce('contexto', message);
    }
    contextTimer = host.setTimeout(scheduleContextCheck, 5000);
  };

  const scheduleContextCheck = (): void => {
    if (!active) return;
    if (host.requestIdleCallback) host.requestIdleCallback(checkContext, { timeout: 1200 });
    else contextTimer = host.setTimeout(checkContext, 0);
  };

  const eventTypes = [
    'belavista:test-case-completed',
    'belavista:test-controls-changed',
    'belavista:integrations-saved',
    'belavista:worker-cycle-completed',
    'belavista:worker-state-changed',
  ] as const;
  const eventListeners = new Map<string, EventListener>();
  for (const type of eventTypes) {
    const listener: EventListener = event => announce(type.replace('belavista:', ''), (event as CustomEvent).detail);
    eventListeners.set(type, listener);
    host.eventTarget.addEventListener(type, listener);
  }
  const onPopState: EventListener = () => announce('navegação', `Navegação observada: ${ports.labelForPath(ports.pathname())}.`);
  const onHashChange: EventListener = () => announce('navegação', 'A seção da superfície foi alterada; contexto mantido na conversa.');
  host.eventTarget.addEventListener('popstate', onPopState);
  host.eventTarget.addEventListener('hashchange', onHashChange);

  try {
    const previousRoute = host.storage?.getItem(ports.routeStorageKey) || null;
    host.storage?.setItem(ports.routeStorageKey, ports.route);
    if (previousRoute && previousRoute !== ports.route)
      showContextualFade(`Navegação observada: ${ports.labelForPath(ports.pathname())}. Vou acompanhar as entradas e saídas desta superfície.`);
  } catch { /* Storage may be unavailable in private or embedded contexts. */ }

  scheduleContextCheck();
  const observer = new Observer(() => {
    if (monitorFrame || !active) return;
    monitorFrame = host.requestAnimationFrame(() => {
      monitorFrame = 0;
      const monitor = root.querySelector<HTMLElement>('[data-worker-chat-monitor]');
      if (!monitor) return;
      const next = `Observando ${ports.labelForPath(ports.pathname())} · ${new Date().toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' })}`;
      if (monitor.textContent !== next) monitor.textContent = next;
    });
  });
  observer.observe(host.documentRef.body, { childList: true, subtree: true });

  return () => {
    if (!active) return;
    active = false;
    observer.disconnect();
    if (contextTimer !== null) host.clearTimeout(contextTimer);
    if (fadeTimer !== null) host.clearTimeout(fadeTimer);
    if (fadeHideTimer !== null) host.clearTimeout(fadeHideTimer);
    if (monitorFrame) host.cancelAnimationFrame(monitorFrame);
    for (const [type, listener] of eventListeners) host.eventTarget.removeEventListener(type, listener);
    host.eventTarget.removeEventListener('popstate', onPopState);
    host.eventTarget.removeEventListener('hashchange', onHashChange);
  };
}

