/** Own mobile route, chat, drawer, overlay, and permission state for the app shell. */
export function installAtlasMobileNavigation(root: HTMLElement, options: {
  appStore: AtlasTopbarStore;
  document?: Document;
}): () => void {
  const documentRef = options.document || globalThis.document;
  type Assistant = { setCollapsed?: (collapsed: boolean) => void; setTab?: (tab: string) => void };
  const assistant = (): Assistant | undefined => (globalThis as typeof globalThis & { belavistaWorkerAssistant?: Assistant }).belavistaWorkerAssistant;
  const setMenuOpen = (open: boolean): void => {
    const sidebar = root.querySelector<HTMLElement>("app-sidebar") as (HTMLElement & { setMobileNavigationOpen?: (open: boolean) => void }) | null;
    sidebar?.setMobileNavigationOpen?.(open);
    const trigger = root.querySelector<HTMLElement>("[data-sidebar-menu-toggle]");
    trigger?.setAttribute("aria-expanded", String(open));
    trigger?.setAttribute("aria-label", open ? "Fechar menu" : "Abrir menu");
  };
  const update = (state = options.appStore.get()): void => {
    root.querySelectorAll<HTMLButtonElement>("[data-mobile-view]").forEach(button => {
      const view = button.dataset.mobileView || "";
      button.hidden = !sidebarActorCanOpenView(state.currentActor || {}, view);
    });
    syncAtlasMobileNavigationSelectionV1(documentRef, String(state.view || ''));
  };
  const onClick = (event: Event): void => {
    const target = event.target;
    if (!(target instanceof Element)) return;
    const toggle = target.closest<HTMLElement>("[data-sidebar-menu-toggle]");
    if (toggle && root.contains(toggle)) {
      event.preventDefault();
      const sidebar = root.querySelector("app-sidebar");
      setMenuOpen(!sidebar?.classList.contains("mobile-open"));
      return;
    }
    if (target.closest("[data-sidebar-overlay]")) { setMenuOpen(false); return; }
    const mobile = target.closest<HTMLButtonElement>("[data-mobile-view]");
    if (mobile && root.contains(mobile)) {
      event.preventDefault(); assistant()?.setCollapsed?.(true);
      setMenuOpen(false);
      const shell = root.querySelector<HTMLElement>("#app.app"); if (shell) delete shell.dataset.mobileTab;
      documentRef.body.classList.remove("mobile-chat-tab-active");
      const chat = root.querySelector<HTMLButtonElement>("[data-mobile-chat-tab]"); chat?.setAttribute("aria-expanded", "false");
      emitAtlasShellCommandV1(root, {
        kind: "navigate",
        source: "mobile",
        view: mobile.dataset.mobileView || "map",
        label: mobile.textContent?.trim() || "",
        reportFamily: mobile.dataset.reportFamily || "",
      });
      update();
      return;
    }
    const chat = target.closest<HTMLButtonElement>("[data-mobile-chat-tab]");
    if (chat && root.contains(chat)) {
      event.preventDefault();
      const worker = assistant(), shell = root.querySelector<HTMLElement>("#app.app"), open = shell?.dataset.mobileTab === "chat";
      if (open) {
        worker?.setCollapsed?.(true); if (shell) delete shell.dataset.mobileTab;
        documentRef.body.classList.remove("mobile-chat-tab-active"); chat.setAttribute("aria-expanded", "false");
      } else if (worker) {
        worker.setTab?.("conversation"); worker.setCollapsed?.(false);
        if (shell) shell.dataset.mobileTab = "chat";
        documentRef.body.classList.add("mobile-chat-tab-active"); chat.setAttribute("aria-expanded", "true");
      }
      update();
    }
  };
  root.dataset.mobileNavigationTsOwner = "true";
  root.addEventListener("click", onClick);
  const unsubscribe = options.appStore.subscribe(update);
  update();
  return () => {
    root.removeEventListener("click", onClick);
    unsubscribe();
    delete root.dataset.mobileNavigationTsOwner;
  };
}

