const stageHomeEscape = (value: unknown = ""): string => String(value).replace(/[&<>"']/g, char => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[char] || char));
const stageHomePercent = (value: unknown): number => Math.max(0, Math.min(100, Number(value) || 0));
const stageHomeTone = (value: unknown): "done" | "warning" | "active" => /concl|feito|final|valid|aprov/i.test(String(value || ""))
  ? "done"
  : /pend|atras|risco|bloq|alto/i.test(String(value || "")) ? "warning" : "active";
const stageHomeActionPhase = (value: unknown): string => ["Identificar", "Preparar", "Liberar", "Executar", "Verificar"][Number(value) || 0] || "Preparar";

