/** Render the Dashboard's stage controls from the program's projected catalog. */
export function renderAtlasDashboardStageControlV1(
  rows: readonly AtlasDashboardStageControlRowV1[],
  esc: (value: unknown) => string,
  ico: (name: string) => string,
): string {
  const cards = rows.map((stage, index) =>
    `<article class="stage-persistent-timeline-card stage-persistent-timeline-control-card" tabindex="0" role="button" data-dashboard-stage-control-open="${esc(stage.key)}" data-dashboard-stage-control-id="${esc(stage.stageId)}"><span>${String(index + 1).padStart(2, "0")}</span><div><small>${esc(stage.period)} · ${esc(stage.status)}</small><b>${esc(stage.name)}</b><i><em style="width:${stage.progress}%"></em></i></div><strong>${stage.progress}%</strong><button type="button" class="stage-persistent-timeline-edit" data-dashboard-stage-control-edit="${esc(stage.key)}" data-dashboard-stage-control-id="${esc(stage.stageId)}" aria-label="Editar ${esc(stage.name)}">${ico("pencil")}</button></article>`,
  ).join("");
  return `<section class="stage-persistent-timeline dashboard-stage-control" data-dashboard-stage-control><header><div><span class="activity-kind">CONTROLE DE ETAPAS · WORKER</span><b>Etapas e atividades da obra</b><small>Role horizontalmente para navegar. Abra uma frente ou edite diretamente pelo ícone.</small></div><span class="stage-persistent-timeline-count">${rows.length} frentes</span></header><div class="stage-persistent-timeline-track">${cards}<button type="button" class="stage-persistent-timeline-add" data-dashboard-stage-control-new aria-label="Adicionar etapa">${ico("plus")}<span>Adicionar<br>etapa</span></button></div></section>`;
}

/** Install Dashboard stage markup and publish navigation commands to the program. */
export function installAtlasDashboardStageControlElementV1(
  dependencies: AtlasDashboardStageControlDependenciesV1,
): void {
  const { ViewLayer, rows, esc, ico, CustomEventCtor, createIcons } = dependencies;
  const prototype = ViewLayer.prototype;
  const baseAssistant = prototype.assistant;
  prototype.assistant = function (this: HTMLElement, ...args: any[]): string {
    const html = typeof baseAssistant === "function" ? String(baseAssistant.apply(this, args) || "") : "";
    if (html.includes("data-dashboard-stage-control")) return html;
    return html.replace(
      '<section class="dashboard-stage-timeline"',
      `${renderAtlasDashboardStageControlV1(rows(), esc, ico)}<section class="dashboard-stage-timeline"`,
    );
  };

  const baseBind = prototype.bind;
  prototype.bind = function (this: HTMLElement, ...args: any[]): unknown {
    const result = typeof baseBind === "function" ? baseBind.apply(this, args) : undefined;
    const control = this.querySelector<HTMLElement>("[data-dashboard-stage-control]");
    if (!control || control.dataset.bound === "true") return result;
    control.dataset.bound = "true";
    const publish = (detail: { key: string; mode: string; stageId: string }): void => {
      control.dispatchEvent(new CustomEventCtor("atlas:dashboard-stage-control-command", {
        bubbles: true,
        composed: true,
        detail,
      }));
    };
    control.dispatchEvent(new CustomEventCtor("atlas:dashboard-stage-control-connected", { bubbles: true, composed: true }));
    control.addEventListener("click", event => {
      const target = event.target as Element | null;
      const create = target?.closest<HTMLElement>("[data-dashboard-stage-control-new]");
      if (create) {
        event.preventDefault();
        publish({ key: "new", mode: "new", stageId: "" });
        return;
      }
      const edit = target?.closest<HTMLElement>("[data-dashboard-stage-control-edit]");
      if (edit) {
        event.preventDefault();
        event.stopPropagation();
        publish({ key: edit.dataset.dashboardStageControlEdit || "", mode: "edit", stageId: edit.dataset.dashboardStageControlId || "" });
        return;
      }
      const card = target?.closest<HTMLElement>("[data-dashboard-stage-control-open]");
      if (card) {
        event.preventDefault();
        publish({ key: card.dataset.dashboardStageControlOpen || "", mode: "edit", stageId: card.dataset.dashboardStageControlId || "" });
      }
    });
    control.addEventListener("keydown", event => {
      const target = event.target as Element | null;
      const card = target?.closest<HTMLElement>("[data-dashboard-stage-control-open]");
      if ((event.key === "Enter" || event.key === " ") && card) {
        event.preventDefault();
        publish({ key: card.dataset.dashboardStageControlOpen || "", mode: "edit", stageId: card.dataset.dashboardStageControlId || "" });
      }
    });
    createIcons?.();
    return result;
  };
}

/** Render the live stage/calendar/record snapshot supplied by the operational program. */
export function renderAtlasStageHomePage(model: AtlasStageHomeModel = {}): string {
  const stages = Array.isArray(model.stages) ? model.stages : [];
  const records = Array.isArray(model.records) ? model.records : [];
  const calendar = Array.isArray(model.calendar) ? model.calendar : [];
  const eventCards = Array.isArray(model.calendarEvents) ? model.calendarEvents : [];
  const weekStart = calendar[0]?.iso || "";
  const dayLabels = calendar.map(day => `<span class="stage-home-canvas-day ${day.today ? "today" : ""}"><b>${stageHomeEscape(day.weekday)}</b><strong>${stageHomeEscape(day.date)}</strong></span>`).join("");
  const recordCards = records.slice().reverse().slice(0, 6).map(record => `<button type="button" class="stage-home-record-card tone-${stageHomeTone(record.status)}" data-stage-home-record="${stageHomeEscape(record.id || "")}">
    <header><span>${stageHomeEscape(record.id || "REGISTRO")}</span><b>${stageHomeEscape(record.status || "Pendente")}</b></header>
    <h3>${stageHomeEscape(record.atividade || record.activity || "Atividade operacional")}</h3>
    <p>${stageHomeEscape(record.detalhes || "Sem apontamento descritivo.")}</p>
    <footer><span>${stageHomeEscape(record.etapa || record.stage || "Etapa não informada")}</span><small>${stageHomeEscape(record.data || "Sem data")} · ${stageHomeEscape(record.responsavel || "Responsável a definir")}</small></footer>
  </button>`).join("");
  const stageRows = stages.map(stage => {
    const scheduled = eventCards.filter(event => String(event.stageKey) === String(stage.key));
    const cards = scheduled.map((event, index) => {
      const dayIndex = calendar.findIndex(day => day.iso === event.date);
      if (dayIndex < 0) return "";
      const width = Math.max(1, Math.min(7 - dayIndex, Number(event.spanDays) || 1));
      return `<button type="button" class="stage-home-canvas-event tone-${stageHomeTone(event.status)}" data-stage-home-calendar-event="${stageHomeEscape(event.id)}" data-stage-home-calendar-date="${stageHomeEscape(event.date)}" title="${stageHomeEscape(event.title)} · ${stageHomeEscape(event.start || "")}" style="left:calc(${dayIndex} * 100% / 7 + 4px);width:calc(${width} * 100% / 7 - 8px);top:${8 + index * 47}px"><b>${stageHomeEscape(event.start || "—")} · ${stageHomeEscape(event.title || "Atividade")}</b><small>${stageHomeEscape(event.owner || stage.owner)} · ${stageHomeEscape(event.status || "Planejado")}</small></button>`;
    }).join("");
    return `<div class="stage-home-canvas-row"><button type="button" class="stage-home-canvas-stage" data-stage-home-stage="${stageHomeEscape(stage.key)}"><b>${stageHomeEscape(stage.name)}</b><small>${stageHomePercent(stage.progress)}% · ${stageHomeEscape(stage.owner)}</small></button><div class="stage-home-canvas-track" style="min-height:${Math.max(58, scheduled.length * 47 + 12)}px">${cards || '<span class="stage-home-canvas-empty">Sem atividade agendada nesta semana</span>'}</div></div>`;
  }).join("");
  return `<section class="stage-home-page-v1" data-stage-home-page>
    <section class="stage-home-section stage-home-calendar-canvas" data-stage-home-section="calendar" data-stage-home-calendar-week="${stageHomeEscape(weekStart)}"><header><div><span class="activity-kind">GANTT · ETAPAS E ATIVIDADES</span><h2>Etapas na linha do tempo</h2><p>Agenda operacional por dia e etapa. Abra um compromisso para ajustar dia, horário ou detalhes.</p></div><div class="stage-home-calendar-controls"><button type="button" data-stage-home-calendar-shift="-1" aria-label="Semana anterior">‹</button><b>${stageHomeEscape(model.calendarLabel || "")}</b><button type="button" data-stage-home-calendar-shift="1" aria-label="Próxima semana">›</button></div></header><div class="stage-home-canvas-scroll"><div class="stage-home-canvas-grid"><div class="stage-home-canvas-axis"><span>ETAPAS</span><div>${dayLabels}</div></div>${stageRows || '<p class="stage-home-empty">Nenhuma etapa cadastrada.</p>'}</div></div><footer class="stage-home-section-footer"><span>${eventCards.length} compromisso(s) na semana · clique em um card para abrir na Agenda</span><small>Fuso · America/Bahia</small></footer></section>
    <section class="stage-home-section stage-home-records" data-stage-home-section="records"><header><div><span class="activity-kind">REGISTROS DA ETAPA</span><h2>Entradas, materiais e serviços</h2><p>Consulte registros e itens adicionados pelo assistente, associados à etapa selecionada.</p></div><div class="stage-home-head-actions"><span class="stage-home-section-meta"><b>${records.length}</b><span>registros<br>preservados</span></span></div></header><div class="stage-home-record-grid">${recordCards || '<p class="stage-home-empty">Nenhum registro cadastrado. O primeiro apontamento pode ser criado aqui.</p>'}</div><div class="stage-home-record-resources-slot" data-stage-home-record-resources-slot>${model.recordResources || ""}</div></section>
  </section>`;
}

