/** Own Dashboard markup, persisted CSV exports and focused-stage interactions. */
export function installAtlasDashboardHomePageV1(input: AtlasDashboardHomePageDependenciesV1): Readonly<{
  render(): string;
  bind(layer: HTMLElement): void;
}> {
  const documentRef = input.documentRef || globalThis.document;
  const windowRef = input.windowRef || globalThis.window;
  const BlobCtor = input.BlobCtor || globalThis.Blob;
  const URLCtor = input.URLCtor || globalThis.URL;
  const esc = (value: unknown): string => input.esc(value);
  const ico = (name: string): string => input.ico(name);
  const stages = (): AtlasDashboardHomeRowV1[] => input.executionModel.stages || [];
  const demoStages = (): AtlasDashboardHomeRowV1[] => input.demoData.activities || [];
  const widget = (title: string, eyebrow: string, body: string, view: string, meta: string): string =>
    `<article class="dashboard-carbon-widget"><header><div><span>${eyebrow}</span><h2>${title}</h2></div><button type="button" data-view="${view}" aria-label="Abrir ${title}">${ico('arrow-up-right')}</button></header><p>${body}</p><footer><small>${meta}</small><button type="button" data-view="${view}">Abrir contexto</button></footer></article>`;
  const render = (): string => {
    const state = input.readState(), cash = state.cashSummary || {}, activityStages = demoStages(), notifications = state.operationalNotifications || [], records = state.records || [];
    const cashBalance = Number(cash.balanceCents || 0) / 100;
    const active = activityStages.filter(item => Number(item.progress) > 0 && Number(item.progress) < 100).length;
    const completed = activityStages.filter(item => Number(item.progress) >= 100).length;
    const timelineStages = stages().map((stage, index) => {
      const live = activityStages.find(item => String(item.name).toLocaleLowerCase('pt-BR') === String(stage.name).toLocaleLowerCase('pt-BR')) || {};
      const progress = Math.max(0, Math.min(100, Number(live.progress) || 0));
      return { stage, live, progress, status: progress >= 100 ? 'Concluída' : progress > 0 ? 'Em andamento' : 'Planejada', period: live.week || `Fase ${String(index + 1).padStart(2, '0')}` };
    });
    const timeline = timelineStages.map(({ stage, live, progress, status, period }, index) =>
      `<article class="dashboard-stage-timeline-card" tabindex="0" role="button" data-dashboard-stage-card="${esc(stage.key)}" data-stage-state="${progress >= 100 ? 'done' : progress > 0 ? 'active' : 'planned'}"><span class="dashboard-stage-timeline-index">${String(index + 1).padStart(2, '0')}</span><header><small>${esc(period)}</small><em>${esc(status)}</em></header><h3>${esc(stage.name)}</h3><p>${esc(live.owner || 'Responsável a definir')}</p><div class="dashboard-stage-timeline-progress"><i><b style="width:${progress}%"></b></i><strong>${progress}%</strong></div><footer><span>${stage.dependsOn?.length ? `Após ${esc(stage.dependsOn[stage.dependsOn.length - 1])}` : 'Início do encadeamento'}</span><button type="button" class="dashboard-stage-worker-button" data-dashboard-worker="${esc(stage.key)}">Editar worker ${ico('pencil')}</button></footer></article>`
    ).join('');
    const focusKey = String(state.dashboardStageFocus || ''), focus = timelineStages.find(item => String(item.stage.key) === focusKey), focusTab = String(state.dashboardStageFocusTab || 'overview');
    const focusContent = focus ? ({
      overview: `<div class="dashboard-stage-focus-grid"><div><small>DESCRIÇÃO DA EXECUÇÃO</small><p>${esc(focus.stage.description || input.stageV9DirectiveText(focus.stage, input.stageV9ProfileFor(focus.stage)))}</p></div><div><small>RESPONSÁVEL DO WORKER</small><b>${esc(focus.live.owner || 'Responsável a definir')}</b><span>${esc(focus.period)} · ${focus.progress}% executado</span></div><div><small>PRÓXIMO GATILHO</small><b>${esc(focus.stage.dependsOn?.length ? 'Concluir dependências e liberar a frente' : 'Confirmar a frente inicial')}</b><span>Validação humana antes da propagação</span></div></div>`,
      agenda: `<div class="dashboard-stage-focus-copy"><small>AGENDA DA ETAPA</small><h3>Compromissos e afazeres do worker</h3><p>Abra a agenda dedicada para editar horários, responsáveis e alertas desta frente.</p><button type="button" class="dashboard-focus-action" data-dashboard-focus-view="agenda">Abrir agenda da etapa ${ico('arrow-up-right')}</button></div>`,
      records: `<div class="dashboard-stage-focus-copy"><small>REGISTROS DA ETAPA</small><h3>Medições e evidências vinculadas</h3><p>Os registros confirmados alimentam o avanço, as evidências e a próxima decisão operacional.</p><button type="button" class="dashboard-focus-action" data-dashboard-focus-view="records">Abrir registros da etapa ${ico('arrow-up-right')}</button></div>`,
      worker: `<div class="dashboard-stage-focus-copy"><small>EDITOR DO WORKER</small><h3>Propriedades da execução</h3><p>Edite atividades, gatilhos, materiais e instruções diretamente na página do worker.</p><button type="button" class="dashboard-focus-action" data-dashboard-worker="${esc(focus.stage.key)}">Editar worker desta etapa ${ico('arrow-up-right')}</button></div>`,
    } as Record<string, string>)[focusTab] || '' : '';
    const focusMarkup = focus ? `<section class="dashboard-stage-focus" aria-live="polite"><header class="dashboard-stage-focus-bar"><div><span class="activity-kind">ETAPA EM FOCO · ${esc(String(focus.stage.key || '').toUpperCase())}</span><h3>${esc(focus.stage.name)}</h3><p>${esc(focus.live.owner || 'Responsável a definir')} · ${esc(focus.status)} · ${focus.progress}%</p></div><div class="dashboard-stage-focus-actions"><button type="button" class="dashboard-focus-worker" data-dashboard-worker="${esc(focus.stage.key)}">${ico('pencil')} Editar worker</button><button type="button" class="dashboard-focus-close" data-dashboard-focus-close aria-label="Fechar etapa em foco">×</button></div></header><nav class="dashboard-stage-focus-tabs" aria-label="Conteúdo da etapa em foco">${[['overview', 'Resumo'], ['agenda', 'Agenda'], ['records', 'Registros'], ['worker', 'Worker']].map(([key, label]) => `<button type="button" class="${focusTab === key ? 'active' : ''}" data-dashboard-stage-tab="${key}">${label}</button>`).join('')}</nav><div class="dashboard-stage-focus-content">${focusContent}</div></section>` : '';
    return `<section class="dashboard-home dashboard-carbon-home"><header class="dashboard-carbon-head"><div><span class="activity-kind">DASHBOARD INICIAL · ALIANÇA PARK</span><h1>Panorama operacional</h1><p>Registros rápidos e leitura de status, com o mapa aberto somente quando necessário.</p></div><div class="dashboard-top-action-row"><button type="button" class="carbon-top-button" data-view="map">${ico('map')} Mapa</button><button type="button" class="carbon-top-button" data-view="reports">${ico('file-chart-column')} Relatórios</button><button type="button" class="carbon-top-button primary" data-view="records" data-records-open-new="true">${ico('plus')} Novo registro</button></div></header><section class="dashboard-carbon-kpis"><article class="dashboard-cash-kpi"><small>CAIXA MESTRE · DONO</small><b>${input.formatBRL(cashBalance)}</b><span>Base para a distribuição das etapas</span></article><article><small>Frentes ativas</small><b>${active}</b><span>${completed} concluídas</span></article><article><small>Notificações</small><b>${notifications.length}</b><span>Ciência do agente</span></article><article><small>Registros no histórico</small><b>${records.length}</b><span>Somente consulta no Diário</span></article></section><section class="dashboard-quick-reports" aria-labelledby="dashboard-quick-reports-title"><header><div><span class="activity-kind">EXPORTAÇÕES · DADOS PERSISTIDOS</span><h2 id="dashboard-quick-reports-title">Relatórios rápidos</h2><p>Gere CSV no momento da solicitação, lendo os registros reais do servidor.</p></div></header><div class="dashboard-quick-report-actions"><article><div><strong>Registros de campo</strong><p>Data, etapa, atividade, responsável, estado e detalhes do diário operacional.</p></div><button type="button" data-dashboard-quick-report="records">${ico('download')} Gerar CSV</button></article><article><div><strong>Agenda por estado</strong><p>Compromissos persistidos, ordenados por estado, data e horário.</p></div><button type="button" data-dashboard-quick-report="agenda">${ico('download')} Gerar CSV</button></article></div><p class="dashboard-quick-report-feedback" data-dashboard-quick-report-feedback role="status" aria-live="polite"></p></section><section class="dashboard-operational-map-card" aria-labelledby="dashboard-operational-map-title"><header><div><span class="activity-kind">MAPA OPERACIONAL · MESMA SUPERFÍCIE DE LEADS</span><h2 id="dashboard-operational-map-title">Progresso físico por etapa</h2><p>Use os filtros para destacar no mapa as áreas de execução, equipes, cronograma, leads, materiais, riscos e progresso.</p></div><button type="button" class="dashboard-map-open-button" data-view="map">Abrir mapa completo ${ico('arrow-up-right')}</button></header><div class="dashboard-operational-map-frame"><map-scene compact interactive data-base-map data-dashboard-operational-map="true" class="dashboard-operational-map" data-stage="Execução do Aliança Park" data-overlay="drenagem" aria-label="Mapa operacional 3D com progresso por etapa"></map-scene><map-filter-rail></map-filter-rail></div></section><section class="dashboard-stage-timeline" aria-labelledby="dashboard-stage-timeline-title"><header><div><span class="activity-kind">CRONOGRAMA · ETAPAS DA OBRA</span><h2 id="dashboard-stage-timeline-title">Linha do tempo de execução</h2><p>Cards em cascata horizontal. Clique em uma etapa para manter seu cabeçalho fixo e alternar o conteúdo operacional.</p></div><div class="dashboard-stage-timeline-summary"><b>${timelineStages.length}</b><span>etapas<br>relacionais</span></div></header><div class="dashboard-stage-timeline-track">${timeline || '<p>Nenhuma etapa cadastrada.</p>'}</div>${focusMarkup}<footer class="dashboard-stage-timeline-legend"><span><i class="planned"></i> Planejada</span><span><i class="active"></i> Em andamento</span><span><i class="done"></i> Concluída</span><button type="button" data-view="stages">Abrir cronograma completo ${ico('arrow-up-right')}</button></footer></section><nav class="carbon-widget-bar dashboard-initial-widget-bar" aria-label="Interfaces operacionais">${[['stages', 'workflow', 'Etapas'], ['records', 'clipboard-pen-line', 'Registros'], ['leads', 'users-round', 'Leads'], ['brokers', 'users-round', 'Corretores'], ['finance', 'wallet-cards', 'Financeiro'], ['reports', 'file-chart-column', 'Relatórios'], ['settings', 'settings', 'Ajustes']].map(([view, icon, label]) => `<button type="button" data-view="${view}">${ico(icon)}<span>${label}</span></button>`).join('')}</nav><section class="dashboard-carbon-widget-grid">${widget('Próxima frente', 'PRIORIDADE PELO CAIXA', 'A etapa elegível é recalculada pelas dependências, cobertura financeira e materiais registrados.', 'stages', `${active} frentes em acompanhamento`)}${widget('Registros rápidos', 'APONTAMENTOS DE CAMPO', 'Abra a interface para registrar produção, unidade de medida, evidências e responsável.', 'records', `${records.length} registro(s) preservado(s)`)}${widget('Atendimento de leads', 'COMERCIAL', 'Consulte reservas, conversas, documentos e o vínculo de cada cliente ao lote.', 'leads', `${(state.publicLeads || []).length} leads recebidos`)}${widget('Comissões', 'CARTEIRAS', 'Navegue por cards de corretores e aplique a regra na página dedicada.', 'brokers', 'Mensal · anual · acumulado')}</section></section>`;
  };
  const downloadQuickReport = async (kind: AtlasDashboardQuickReportKindV1, button: HTMLButtonElement, feedback: HTMLElement | null): Promise<void> => {
    button.disabled = true; button.dataset.originalLabel = button.textContent?.trim() || ''; button.textContent = 'Lendo dados persistidos…';
    if (feedback) feedback.textContent = 'Consultando o banco da aplicação…';
    try {
      const report = await input.loadQuickReport(kind);
      if (!report.rowCount) { if (feedback) feedback.textContent = 'A fonte persistida não contém registros para exportar.'; return; }
      const url = URLCtor.createObjectURL(new BlobCtor([report.csv], { type: 'text/csv;charset=utf-8' }));
      const anchor = documentRef.createElement('a'); anchor.href = url; anchor.download = report.filename; anchor.hidden = true; documentRef.body.append(anchor); anchor.click(); anchor.remove();
      windowRef.setTimeout(() => URLCtor.revokeObjectURL(url), 0);
      if (feedback) feedback.textContent = `Relatório gerado com ${report.rowCount} registro(s) lido(s) do servidor.`;
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error);
      if (feedback) feedback.textContent = `Relatório não gerado: ${message}`;
      input.notify?.(`Falha ao gerar relatório: ${message}`, 'error');
    } finally { button.disabled = false; button.textContent = button.dataset.originalLabel || 'Gerar CSV'; delete button.dataset.originalLabel; }
  };
  const bind = (layer: HTMLElement): void => {
    const reportSection = layer.querySelector<HTMLElement>('.dashboard-quick-reports');
    if (reportSection && reportSection.dataset.dashboardReportsBound !== 'true') {
      reportSection.dataset.dashboardReportsBound = 'true';
      const feedback = reportSection.querySelector<HTMLElement>('[data-dashboard-quick-report-feedback]');
      reportSection.querySelectorAll<HTMLButtonElement>('[data-dashboard-quick-report]').forEach(button => button.addEventListener('click', () => {
        const kind = button.dataset.dashboardQuickReport;
        if (kind === 'records' || kind === 'agenda') void downloadQuickReport(kind, button, feedback);
      }));
    }
    const timeline = layer.querySelector<HTMLElement>('.dashboard-stage-timeline');
    if (!timeline || timeline.dataset.dashboardStageFocusBound === 'true') return;
    timeline.dataset.dashboardStageFocusBound = 'true';
    timeline.querySelectorAll<HTMLElement>('[data-dashboard-stage-card]').forEach(card => {
      const select = (): void => {
        const stageKey = card.dataset.dashboardStageCard || '';
        input.onCommand({ type: 'select-stage', stageKey, stageName: card.querySelector('h3')?.textContent || stageKey });
      };
      card.addEventListener('click', event => { const target = event.target; if (target instanceof Element && target.closest('[data-dashboard-worker]')) return; select(); });
      card.addEventListener('keydown', event => { const target = event.target; if ((event.key === 'Enter' || event.key === ' ') && !(target instanceof Element && target.closest('button'))) { event.preventDefault(); select(); } });
    });
    timeline.querySelectorAll<HTMLButtonElement>('[data-dashboard-worker]').forEach(button => button.addEventListener('click', event => { event.preventDefault(); event.stopPropagation(); input.onCommand({ type: 'open-worker', stageKey: button.dataset.dashboardWorker || '' }); }));
    timeline.querySelectorAll<HTMLButtonElement>('[data-dashboard-stage-tab]').forEach(tab => tab.addEventListener('click', () => input.onCommand({ type: 'select-focus-tab', tab: tab.dataset.dashboardStageTab || '', label: tab.textContent?.trim() || '' })));
    timeline.querySelector<HTMLElement>('[data-dashboard-focus-close]')?.addEventListener('click', () => input.onCommand({ type: 'close-focus' }));
    timeline.querySelectorAll<HTMLButtonElement>('[data-dashboard-focus-view]').forEach(button => button.addEventListener('click', () => {
      input.onCommand({
        type: 'open-focus-view',
        view: button.dataset.dashboardFocusView || '',
        fallbackStageKey: timeline.querySelector<HTMLElement>('[data-dashboard-stage-card]')?.dataset.dashboardStageCard || '',
      });
    }));
    (windowRef as Window & { lucide?: { createIcons(): void } }).lucide?.createIcons();
  };
  input.ViewLayer.prototype.assistant = render;
  return Object.freeze({ render, bind });
}

/** Keep Dashboard map-context actions outside the map filter rail. */
export function installAtlasDashboardHomeContextV1(
  ViewLayer: { prototype: AtlasStageChromeViewLayerV1 },
  input: {
    readState(): Record<string, unknown>;
    onCommand(command: Extract<AtlasDashboardHomeCommandV1, { type: 'open-map-context' }>): void;
    dashboardFilters: Array<[string, string, string]>;
    documentRef?: Document;
  },
): void {
  const documentRef = input.documentRef || globalThis.document;
  const renderBase = ViewLayer.prototype.render;
  ViewLayer.prototype.render = function (...args: any[]): any {
    const result = renderBase?.apply(this, args), home = this.querySelector<HTMLElement>('.dashboard-carbon-home'), head = home?.querySelector<HTMLElement>('.dashboard-carbon-head'), timeline = home?.querySelector<HTMLElement>('.dashboard-stage-timeline');
    if (home && head && timeline) head.after(timeline);
    return result;
  };
  const bindBase = ViewLayer.prototype.bind;
  ViewLayer.prototype.bind = function (...args: any[]): any {
    const result = bindBase?.apply(this, args);
    this.querySelectorAll<HTMLButtonElement>('[data-map-widget-context]').forEach(button => {
      if (button.dataset.mapWidgetContextBound === 'true' || button.closest('map-filter-rail')) return;
      button.dataset.mapWidgetContextBound = 'true';
      button.addEventListener('click', event => {
        event.preventDefault(); event.stopImmediatePropagation();
        const source = button.closest<HTMLElement>('[data-map-summary-widget],[data-highlight-status]'), state = input.readState(), key = source?.dataset.mapSummaryKey || source?.dataset.highlightStatus || String(state.mapFilter || 'execution'), filter = input.dashboardFilters.find(item => item[0] === key) || input.dashboardFilters[0], nextView = button.dataset.mapWidgetContext || 'map';
        input.onCommand({ type: 'open-map-context', key, view: nextView, label: filter?.[1] || 'camada' });
      });
    });
    return result;
  };
}

/** Keep the TypeScript Dashboard bindings in the existing ViewLayer chain. */
export function installAtlasDashboardHomeEventsV1(
  ViewLayer: { prototype: AtlasStageChromeViewLayerV1 },
  bindDashboard: (layer: HTMLElement) => void,
): void {
  const baseBind = ViewLayer.prototype.bind;
  ViewLayer.prototype.bind = function (...args: any[]): any {
    const result = baseBind?.apply(this, args);
    bindDashboard(this);
    return result;
  };
}

export interface AtlasStageDedicatedPageDependenciesV1 {
  readState(): Record<string, any>;
  executionModel: { stages: Array<Record<string, any>> };
  stageV9ByState(state: Record<string, any>): Record<string, any> | undefined;
  stageV9LiveFor(stage: Record<string, any>): Record<string, any>;
  stageV9ProfileFor(stage: Record<string, any>): Record<string, any>;
  stageV9MaterialsFor(stage: Record<string, any>): Array<Record<string, any>>;
  stageV9FlowPackets(stage: Record<string, any>): Array<Record<string, any>>;
  stageV9BudgetFor(stage: Record<string, any>, state?: Record<string, any>): number;
  stageOf(record: Record<string, any>): string;
  stageV9StatusFor(live: Record<string, any>): string;
  stageV9ProductionFor(stage: Record<string, any>): string;
  stageV9DirectiveText(stage: Record<string, any>, profile: Record<string, any>): string;
  formatBRL(value: unknown): string;
  esc(value: unknown): string;
  ico(name: string): string;
}

export function renderAtlasStageEscListV1(items: unknown, esc: (value: unknown) => string, empty = 'Não configurado'): string {
  return Array.isArray(items) && items.length
    ? items.map(item => `<li>${esc(item)}</li>`).join('')
    : `<li>${empty}</li>`;
}

/** Render the existing stage detail page from typed stage projections. */
export function installAtlasStageDedicatedPageBaseV1(
  ViewLayer: { prototype: HTMLElement & Record<string, unknown> },
  dependencies: AtlasStageDedicatedPageDependenciesV1,
): void {
  const { readState, executionModel, stageV9ByState, stageV9LiveFor, stageV9ProfileFor, stageV9MaterialsFor, stageV9FlowPackets, stageV9BudgetFor, stageOf, stageV9StatusFor, stageV9ProductionFor, stageV9DirectiveText, formatBRL, esc, ico } = dependencies;
  const listItems = (items: unknown, empty = 'Não configurado'): string => renderAtlasStageEscListV1(items, esc, empty);
  ViewLayer.prototype.activityDedicatedPage = function (): string {
    const state = readState();
    const stage = stageV9ByState(state) || executionModel.stages[0];
    if (!stage) return '<section class="stage-v9-dedicated-page"><p>Nenhuma etapa disponível.</p></section>';
    const live = stageV9LiveFor(stage), profile = stageV9ProfileFor(stage), materials = stageV9MaterialsFor(stage), packets = stageV9FlowPackets(stage), budget = stageV9BudgetFor(stage, state);
    const deps = (Array.isArray(stage.dependsOn) ? stage.dependsOn : []).map((key: unknown) => executionModel.stages.find(item => item.key === key)?.name || key);
    const targets = profile.notificationTargets && typeof profile.notificationTargets === 'object' ? profile.notificationTargets : {};
    const flow = packets.map((packet, index) => `<button type="button" class="stage-v9-activity-card" data-activity-v9="${esc(`${stage.key}:${packet.key}`)}"><header><span>${String(index + 1).padStart(2, '0')} · ${esc(String(packet.unit || '').toUpperCase())}</span><em>${index === 0 ? 'Pronto' : index === 1 && Number(live.progress) > 0 ? 'Em execução' : index === 2 ? 'Aguardando validação' : 'Bloqueado por completude'}</em></header><h3>${esc(packet.label)}</h3><p>${esc(packet.detail)}</p><div><small>Gatilho</small><b>${esc(packet.trigger)}</b></div><footer>Em sequência ${index < packets.length - 1 ? ico('arrow-right') : '· liberação'}</footer></button>`).join('');
    const recordRows = (Array.isArray(state.records) ? state.records : []).filter((record: AtlasStageActivityRecordV1) =>
      stage.name === stageOf(record) || String(record.atividade || '').toLowerCase().includes(String(stage.name || '').toLowerCase().split(' ')[0]),
    ).slice(-8).reverse();
    const diary = recordRows.length ? recordRows.map((record: AtlasStageActivityRecordV1) => `<tr><td><b>${esc(record.data || '—')}</b><small>${esc(record.hora || '')}</small></td><td>${esc(record.atividade || stage.name)}</td><td>${esc(record.responsavel || 'A definir')}</td><td>${esc(record.detalhes || 'Sem apontamento')}</td><td><span>${esc(record.status || 'Pendente')}</span></td><td>${record.comprovante || record.evidencias ? 'Anexado' : '—'}</td></tr>`).join('') : '<tr><td colspan="6" class="stage-v9-empty-diary">Nenhum apontamento desta etapa no histórico. O primeiro registro confirmado aparecerá aqui.</td></tr>';
    const production = stage.production && typeof stage.production === 'object' ? stage.production : {};
    const materialsMarkup = materials.map(item => `<div><b>${esc(item.name)}</b><span>${item.quantity == null ? 'Quantidade a medir' : `${esc(item.quantity)} ${esc(item.unit || 'un.')}`}</span><small>${esc(item.status || 'Planejado')} · ${esc(item.scope || 'Requisito da etapa')}</small></div>`).join('');
    return `<section class="stage-v9-dedicated-page" data-stage-key="${esc(String(stage.key || ""))}"><header class="stage-v9-dedicated-head"><button type="button" class="stage-v9-back" data-view="stages">${ico('arrow-left')} Todas as etapas</button><div><span class="activity-kind">ETAPA DEDICADA · ${esc(String(stage.key || '').toUpperCase())}</span><h1>${esc(stage.name)}</h1><p>${esc(live.week || 'Cronograma operacional')} · ${esc(live.owner || 'Responsável a definir')} · unidade ${esc(production.unit || 'produção')}</p></div><aside><small>AVANÇO REGISTRADO</small><b>${Number(live.progress) || 0}%</b><span>${esc(stageV9StatusFor(live))}</span></aside></header><section class="stage-v9-status-lines"><div><small>STATUS DA RELAÇÃO</small><b>${deps.length ? `Aguardando ${deps.join(', ')}` : 'Liberada para início'}</b></div><div><small>CAIXA / ORÇAMENTO</small><b>${formatBRL(budget)}</b><span>peso ${Number(stage.cashWeight || 0) * 100}% no caixa</span></div><div><small>PRODUÇÃO</small><b>${esc(stageV9ProductionFor(stage))}</b><span>medida validada no diário</span></div><div><small>NOTIFICAÇÕES</small><b>${Object.values(targets).flat().length || 0} destinos</b><span>eventos auditáveis</span></div></section><section class="stage-v9-flow-section"><header><div><span class="activity-kind">FLUXOGRAMA ATUAL DE EXECUÇÃO</span><h2>Atividades e linhagens de requisito</h2><p>Clique em qualquer card para abrir o cabeçalho estrutural da atividade e seu diário de obra.</p></div><span class="stage-v9-flow-note">${Array.isArray(stage.dependsOn) && stage.dependsOn.length ? `↳ depende de ${stage.dependsOn.join(' · ')}` : '↳ início do encadeamento'}</span></header><div class="stage-v9-flow">${flow}</div></section><section class="stage-v9-detail-grid"><article class="stage-v9-detail-card"><span class="activity-kind">DIRETRIZ ATIVA</span><h2>O que dispara esta etapa</h2><p>${esc(stageV9DirectiveText(stage, profile))}</p><h3>Requisitos de evidência</h3><ul>${listItems(profile.evidenceFocus)}</ul><h3>Pedidos e materiais</h3><ul>${listItems(profile.procurementFocus || materials.map(item => item.name))}</ul></article><article class="stage-v9-detail-card"><span class="activity-kind">MATERIAIS PRINCIPAIS</span><h2>Composição da frente</h2><div class="stage-v9-material-list">${materialsMarkup}</div></article></section><section class="stage-v9-diary"><header><div><span class="activity-kind">DIÁRIO DE OBRA · HISTÓRICO DA ETAPA</span><h2>Registros, medições e comprovantes</h2></div><button type="button" data-view="records">Abrir histórico completo ${ico('arrow-up-right')}</button></header><div class="stage-v9-diary-table-wrap"><table class="stage-v9-diary-table"><thead><tr><th>Data / hora</th><th>Atividade</th><th>Responsável</th><th>Apontamento</th><th>Status</th><th>Comprovante</th></tr></thead><tbody>${diary}</tbody></table></div></section></section>`;
  };
}

