  attachments(record: AtlasStageHomeRecordResourceRowV1): Array<{ label: unknown; url: unknown; meta: unknown }>;
  properties(record: AtlasStageHomeRecordResourceRowV1): Array<{ label: unknown; value: unknown }>;
  statusLabel(record: AtlasStageHomeRecordResourceRowV1): unknown;
  progress(stage: AtlasStageHomeRecordResourceStageV1, state: Record<string, any>): number;
  materialRows(state: Record<string, any>): AtlasStageHomeRecordResourceRowV1[];
  serviceRows(state: Record<string, any>): AtlasStageHomeRecordResourceRowV1[];
  stageContext(): { model?: AtlasStageHomeRecordResourceStageV1 } | null | undefined;
