export interface AtlasDashboardControlTableRowsV1 {
  finance: Array<{ date: string; kind: string; link: string; amountCents: number; description: string }>;
  materials: Array<{ stageName: string; activityName: string; name: string; scope: string; receivedQuantity: number; plannedQuantity: number; unit: string; status: string }>;
  sales: Array<{ id: string; lot: string; client: string; broker: string; receiptCount: number; commissionLabel: string }>;
  notices: Array<{ label: string; statusLabel: string }>;
}


export function projectAtlasDashboardControlTableRowsV1(
  snapshot: Pick<DashboardSnapshot, 'cashEntries' | 'materials' | 'repasses' | 'notifications'>,
): AtlasDashboardControlTableRowsV1 {
  return {
    finance: snapshot.cashEntries.slice(0, 8).map(row => ({
      date: String(row.date || row.createdAt || '—'),
      kind: String(row.kind || ''),
      link: String(row.stage || row.category || 'Caixa'),
      amountCents: Number(row.amountCents) || 0,
      description: String(row.description || ''),
    })),
    materials: snapshot.materials.map(row => ({
      stageName: String(row.stageName || 'Sem etapa'),
      activityName: String(row.activityName || '—'),
      name: String(row.name || ''),
      scope: String(row.scope || ''),
      receivedQuantity: row.receivedQuantity,
      plannedQuantity: row.plannedQuantity,
      unit: String(row.unit || ''),
      status: String(row.status || ''),
    })),
    sales: snapshot.repasses.sales.map(sale => ({
      id: String(sale.id || ''),
      lot: String(sale.lot || ''),
      client: String(sale.client || ''),
      broker: String(sale.broker || ''),
      receiptCount: sale.receipts.length,
      commissionLabel: sale.brokerRule?.active ? `${sale.brokerRule.commissionPercent}%` : 'Regra pendente',
    })),
    notices: snapshot.notifications.slice(0, 8).map(item => ({
      label: String(item.title || item.message || 'Notificação'),
      statusLabel: String(item.status || (item.read ? 'Lida' : 'Não lida')),
    })),
  };
}


export interface AtlasDashboardLotStatusChartItemV1 extends AtlasDashboardLotStatusSummary {
  color: string;
  sharePercent: number;
  startPercent: number;
  endPercent: number;
}

export interface AtlasDashboardLotChartBlockV1 extends AtlasDashboardLotBlockSummary {
  barPercent: number;
  averageTicket: number;
}

export interface AtlasDashboardLotAnalysisPresentationV1 {
  statusTotal: number;
  statuses: AtlasDashboardLotStatusChartItemV1[];
  topValueBlocks: AtlasDashboardLotChartBlockV1[];
  blocks: AtlasDashboardLotChartBlockV1[];
}

/** Project dashboard chart geometry and per-block metrics without rendering markup. */
export function projectAtlasDashboardLotAnalysisPresentationV1(
  data: AtlasDashboardLotAnalysis,
  statusColors: readonly string[],
): AtlasDashboardLotAnalysisPresentationV1 {
  const statusTotal = data.statuses.reduce((sum, item) => sum + item.count, 0);
  let cursor = 0;
  const palette = statusColors.length ? statusColors : ["#3478d4"];
  const statuses = data.statuses.filter(item => item.count > 0).map((item, index) => {
    const sharePercent = statusTotal ? item.count / statusTotal * 100 : 0;
    const startPercent = cursor;
    cursor += sharePercent;
    return {
      ...item,
      color: palette[index % palette.length],
      sharePercent,
      startPercent,
      endPercent: cursor,
    };
  });
  const maxBlockValue = Math.max(1, ...data.topValueBlocks.map(item => item.value));
  const projectBlock = (item: AtlasDashboardLotBlockSummary): AtlasDashboardLotChartBlockV1 => ({
    ...item,
    barPercent: Math.max(2, Math.round(item.value / maxBlockValue * 100)),
    averageTicket: item.value / Math.max(1, item.lots),
  });
  return {
    statusTotal,
    statuses,
    topValueBlocks: data.topValueBlocks.map(projectBlock),
    blocks: data.blocks.map(projectBlock),
  };
}


export interface AtlasDashboardStageProgressRowV1 {
  stage: OperationalStage;
  progress: number;
  state: "done" | "active" | "planned";
  statusLabel: string;
}

export interface AtlasDashboardOperationalOverviewV1 {
  activeStageCount: number;
  completedStageCount: number;
  totalStageCount: number;
  stages: AtlasDashboardStageProgressRowV1[];
}

/** Normalize the dashboard's stage KPIs and progress rows from the same persisted catalog. */
export function projectAtlasDashboardOperationalOverviewV1(
  stages: OperationalStage[],
): AtlasDashboardOperationalOverviewV1 {
  const rows = [...stages].sort((left, right) => Number(left.id) - Number(right.id)).map(stage => {
    const sourceProgress = Number(stage.progress);
    const progress = Math.max(0, Math.min(100, sourceProgress || 0));
    return {
      stage,
      progress,
      state: progress >= 100 ? "done" as const : progress > 0 ? "active" as const : "planned" as const,
      statusLabel: sourceProgress >= 100 ? "Concluída" : sourceProgress > 0 ? "Em andamento" : stage.status || "Planejada",
    };
  });
  return {
    activeStageCount: stages.filter(stage => Number(stage.progress) > 0 && Number(stage.progress) < 100).length,
    completedStageCount: stages.filter(stage => Number(stage.progress) >= 100).length,
    totalStageCount: stages.length,
    stages: rows,
  };
}

export interface DashboardAgendaDay {
  iso: string;
  date: string;
  weekday: string;
  isToday: boolean;
  isSelected: boolean;
  eventCount: number;
}

export interface DashboardAgendaWeek {
  selectedDate: string;
  selectedDayLabel: string;
  weekLabel: string;
  days: DashboardAgendaDay[];
  selectedEvents: OperationalAgendaEvent[];
  materialsByEvent: Record<string, string[]>;
  eventCount: number;
}

/** Resolve dashboard agenda navigation against local calendar dates. */
export function projectAtlasDashboardAgendaNavigationDateV1(
  selectedDate: unknown,
  action: 'today' | 'week-shift',
  weekDelta = 0,
  now = new Date(),
): string {
  const dateKey = (date: Date): string => `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}-${String(date.getDate()).padStart(2, '0')}`;
  if (action === 'today') return dateKey(now);
  const value = String(selectedDate || '');
  const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(value);
  const candidate = match
    ? new Date(Number(match[1]), Number(match[2]) - 1, Number(match[3]), 12)
    : new Date(now.getFullYear(), now.getMonth(), now.getDate(), 12);
  const selected = Number.isFinite(candidate.getTime()) && dateKey(candidate) === value
    ? candidate
    : new Date(now.getFullYear(), now.getMonth(), now.getDate(), 12);
  selected.setDate(selected.getDate() + Math.trunc(Number(weekDelta) || 0) * 7);
  return dateKey(selected);
}

/** Project the selected dashboard agenda week without changing stored events. */
export function projectDashboardAgendaWeek(
  events: OperationalAgendaEvent[],
  selectedDate = "",
  now = new Date(),
  materials: OperationalMaterial[] = [],
): DashboardAgendaWeek {
  const dateKey = (date: Date): string => `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, "0")}-${String(date.getDate()).padStart(2, "0")}`;
  const parseDate = (value: string): Date | null => {
    const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(value);
    if (!match) return null;
    const date = new Date(Number(match[1]), Number(match[2]) - 1, Number(match[3]), 12);
    return Number.isFinite(date.getTime()) && dateKey(date) === value ? date : null;
  };
  const todayKey = dateKey(now);
  const selected = parseDate(selectedDate) || new Date(now.getFullYear(), now.getMonth(), now.getDate(), 12);
  const selectedKey = dateKey(selected);
  const start = new Date(selected);
  start.setDate(start.getDate() - ((start.getDay() + 6) % 7));
  const weekDates = Array.from({ length: 7 }, (_, index) => {
    const date = new Date(start);
    date.setDate(start.getDate() + index);
    return date;
  });
  const ordered = [...events].filter(event => parseDate(String(event.date || "")))
    .sort((a, b) => `${a.date}T${a.start || "00:00"}`.localeCompare(`${b.date}T${b.start || "00:00"}`));
  const days = weekDates.map(date => {
    const iso = dateKey(date);
    return {
      iso,
      date: String(date.getDate()),
      weekday: date.toLocaleDateString("pt-BR", { weekday: "short" }).replace(".", ""),
      isToday: iso === todayKey,
      isSelected: iso === selectedKey,
      eventCount: ordered.filter(event => event.date === iso).length,
    };
  });
  const weekEnd = weekDates[6];
  const startLabel = start.toLocaleDateString("pt-BR", { day: "2-digit", month: "short" });
  const endLabel = weekEnd.toLocaleDateString("pt-BR", { day: "2-digit", month: "short", year: "numeric" });
  const selectedEvents = ordered.filter(event => event.date === selectedKey);
  const materialNames = new Map(materials.map(material => [material.id, material.name]));
  const materialsByEvent = Object.fromEntries(selectedEvents.map(event => [
    event.id,
    event.materialIds.map(id => materialNames.get(id)).filter((name): name is string => Boolean(name)),
  ]));
  return {
    selectedDate: selectedKey,
    selectedDayLabel: selected.toLocaleDateString("pt-BR", { weekday: "long", day: "numeric", month: "long", year: "numeric" }),
    weekLabel: `${startLabel} — ${endLabel}`,
    days,
    selectedEvents,
    materialsByEvent,
    eventCount: ordered.filter(event => event.date >= dateKey(weekDates[0]) && event.date <= dateKey(weekEnd)).length,
  };
}

export interface AtlasDashboardCashMonthV1 {
  key: string;
  label: string;
  entriesCents: number;
  exitsCents: number;
}

/** Aggregate the persisted cash ledger into six local calendar months for the dashboard chart. */
export function projectAtlasDashboardCashTrendV1(
  entries: readonly CashFlowRecord[],
  now = new Date(),
  monthCount = 6,
): AtlasDashboardCashMonthV1[] {
  const count = Math.max(1, Math.min(12, Math.trunc(Number(monthCount) || 6)));
  const months: AtlasDashboardCashMonthV1[] = [];
  const cursor = new Date(now.getFullYear(), now.getMonth(), 1, 12);
  for (let offset = count - 1; offset >= 0; offset -= 1) {
    const date = new Date(cursor.getFullYear(), cursor.getMonth() - offset, 1, 12);
    const key = `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}`;
    months.push({
      key,
      label: new Intl.DateTimeFormat('pt-BR', { month: 'short' }).format(date).replace('.', ''),
      entriesCents: 0,
      exitsCents: 0,
    });
  }
  const byMonth = new Map(months.map(month => [month.key, month]));
  for (const entry of entries) {
    const rawDate = String(entry.date || entry.createdAt || '').slice(0, 10);
    const match = /^(\d{4})-(\d{2})-\d{2}$/.exec(rawDate);
    if (!match) continue;
    const month = byMonth.get(`${match[1]}-${match[2]}`);
    if (!month) continue;
    const amount = Math.max(0, Math.trunc(Number(entry.amountCents) || 0));
    if (entry.kind === 'entrada') month.entriesCents += amount;
    else if (entry.kind === 'saida') month.exitsCents += amount;
  }
  return months;
}

export interface AtlasDashboardCashChartMonthV1 extends AtlasDashboardCashMonthV1 {
  entriesHeightPercent: number;
  exitsHeightPercent: number;
}

export interface AtlasDashboardCashChartV1 {
  months: AtlasDashboardCashChartMonthV1[];
  peakCents: number;
  hasActivity: boolean;
}

/** Scale the six-month ledger trend into display-ready bar heights. */
export function projectAtlasDashboardCashChartV1(
  entries: readonly CashFlowRecord[],
  now = new Date(),
): AtlasDashboardCashChartV1 {
  const trend = projectAtlasDashboardCashTrendV1(entries, now);
  const peakCents = Math.max(0, ...trend.flatMap(month => [month.entriesCents, month.exitsCents]));
  const height = (value: number): number => value > 0 && peakCents > 0
    ? Math.max(4, Math.round(value / peakCents * 100))
    : 0;
  return {
    peakCents,
    hasActivity: peakCents > 0,
    months: trend.map(month => ({
      ...month,
      entriesHeightPercent: height(month.entriesCents),
      exitsHeightPercent: height(month.exitsCents),
    })),
  };
}

export interface AtlasDashboardMaterialCoverageV1 {
  id: string;
  name: string;
  unit: string;
  planned: number;
  received: number;
  used: number;
  receivedPercent: number | null;
  stageName: string;
  activityName: string;
  status: string;
}

/** Project inventory quantities as comparable per-item receipt coverage without changing source records. */
export function projectAtlasDashboardMaterialCoverageV1(
  materials: readonly OperationalMaterial[],
): AtlasDashboardMaterialCoverageV1[] {
  return materials.map(material => {
    const planned = Math.max(0, Number(material.plannedQuantity) || 0);
    const received = Math.max(0, Number(material.receivedQuantity) || 0);
    return {
      id: String(material.id || ''),
      name: String(material.name || 'Material sem nome'),
      unit: String(material.unit || ''),
      planned,
      received,
      used: Math.max(0, Number(material.usedQuantity) || 0),
      receivedPercent: planned > 0 ? Math.max(0, Math.min(100, received / planned * 100)) : null,
      stageName: String(material.stageName || 'Sem etapa'),
      activityName: String(material.activityName || 'Sem atividade'),
      status: String(material.status || 'Sem status'),
    };
  }).sort((left, right) => {
    const leftCoverage = left.receivedPercent ?? 101;
    const rightCoverage = right.receivedPercent ?? 101;
    return leftCoverage - rightCoverage || left.name.localeCompare(right.name, 'pt-BR');
  });
}

/** Compose the dashboard's typed data projections for one render pass. */
export function projectAtlasDashboardPageV1(input: {
  snapshot: DashboardSnapshot;
  agendaSelectedDate: string;
  recordStageId: string;
  statusColors: readonly string[];
  now?: Date;
}) {
  const { snapshot } = input;
  const now = input.now || new Date();
  const selectedRecordStage = snapshot.stages.find(stage => String(stage.id) === input.recordStageId) || snapshot.stages[0];
  return {
    operationalOverview: projectAtlasDashboardOperationalOverviewV1(snapshot.stages),
    controlTableRows: projectAtlasDashboardControlTableRowsV1(snapshot),
    lotAnalysisPresentation: projectAtlasDashboardLotAnalysisPresentationV1(snapshot.lotAnalysis, input.statusColors),
    agendaWeek: projectDashboardAgendaWeek(snapshot.agendaEvents, input.agendaSelectedDate, now, snapshot.materials),
    cashChart: projectAtlasDashboardCashChartV1(snapshot.cashEntries, now),
    materialCoverage: projectAtlasDashboardMaterialCoverageV1(snapshot.materials),
    recordForm: {
      selectedStage: selectedRecordStage,
      stageOptions: snapshot.stages.map(stage => ({ stage, selected: stage.id === selectedRecordStage?.id })),
      activityOptions: selectedRecordStage?.activities || [],
      date: now.toISOString().slice(0, 10),
    },
  };
}

