type DashboardState = DashboardSnapshot & {
  loading: boolean; error: string | null; feedback: string; recordFormOpen: boolean; recordSaving: boolean;
  recordStageId: string; recordError: string; agendaSelectedDate: string;
  aiGenerationStatus: 'idle' | 'loading' | 'ready' | 'error';
  aiGenerationKind: AtlasDashboardGenerationKindV1 | null;
  aiGeneration: AtlasDashboardAiGenerationV1 | null;
  aiGenerationError: string;
};

/** Dashboard web element; transient focus state and markup live here, service orchestration lives in program(). */
export class AtlasDashboard extends AtlasHTMLElementBase {
  private snapshot: DashboardState;
  private readonly state: { next(setter: StateSetter<DashboardState>, render?: boolean): DashboardState };
  private commercialInterestCount: number | null = null;
  private commercialInterestState: DashboardSnapshot["commercialInterestState"] = "loading";
  constructor() {
    super();
    const todayKey = projectAtlasDashboardAgendaNavigationDateV1("", "today");
    const initial: DashboardState = { cashBalanceCents: 0, cashEntries: [], stages: [], records: [], notifications: [], agendaEvents: [], materials: [], repasses: { sales: [], entries: [], brokerRules: [], reasons: [], stages: [] }, commercialInterestCount: null, commercialInterestState: "loading", lotAnalysis: { lotCount: 0, totalArea: 0, totalValue: 0, committedCount: 0, statuses: [], blocks: [], topValueBlocks: [] }, loading: true, error: null, feedback: "", recordFormOpen: false, recordSaving: false, recordStageId: "", recordError: "", agendaSelectedDate: todayKey, aiGenerationStatus: "idle", aiGenerationKind: null, aiGeneration: null, aiGenerationError: "" };
    function* state(value: DashboardState): Generator<DashboardState, never, StateSetter<DashboardState>> { while (true) value = (yield value)(value); }
    const iterator = state(initial); iterator.next(); this.snapshot = initial;
    this.state = { next: (setter, render = true) => { this.snapshot = iterator.next(setter).value; if (render) this.render(); return this.snapshot; } };
  }
  private esc(value: unknown): string { return String(value ?? "").replace(/[&<>"']/g, char => ({ "&":"&amp;", "<":"&lt;", ">":"&gt;", '"':"&quot;", "'":"&#39;" }[char] || char)); }
  private renderLotAnalysis(data: AtlasDashboardLotAnalysis, interestedRecords: number | null, interestState: DashboardSnapshot["commercialInterestState"], projection: ReturnType<typeof projectAtlasDashboardPageV1>["lotAnalysisPresentation"]): string {
    const esc = (value: unknown) => this.esc(value),
      money = new Intl.NumberFormat("pt-BR", { style: "currency", currency: "BRL" }),
      number = new Intl.NumberFormat("pt-BR", { maximumFractionDigits: 2 }),
      statusTotal = projection.statusTotal,
      statusSegments = projection.statuses.map(item => `${item.color} ${item.startPercent.toFixed(2)}% ${item.endPercent.toFixed(2)}%`),
      statusLegend = projection.statuses.map(item => {
        return `<div class="atlas-lot-status-item"><span class="atlas-lot-status-label"><i style="background:${item.color}"></i><span>${esc(item.label)}</span></span><small>${Math.round(item.sharePercent)}%</small><strong>${item.count}</strong></div>`;
      }).join(""),
      topBlocks = projection.topValueBlocks.map(item => {
        return `<div class="atlas-lot-analysis-row"><span>Quadra ${esc(item.quadra)}</span><div class="atlas-lot-analysis-track" role="img" aria-label="Quadra ${esc(item.quadra)}: ${esc(money.format(item.value))}"><i style="width:${item.barPercent}%"></i></div><strong>${esc(money.format(item.value))}</strong></div>`;
      }).join(""),
      rows = projection.blocks.map(item => `<tr><td>${esc(item.quadra)}</td><td>${item.lots}</td><td>${item.available}</td><td>${item.committed}</td><td>${esc(number.format(item.area))} m²</td><td>${esc(money.format(item.value))}</td><td>${esc(money.format(item.averageTicket))}</td></tr>`).join("");
    const interestValue = (interestState === "loaded" || interestState === "demo") && interestedRecords !== null ? interestedRecords : "—";
    const interestCaption = interestState === "demo" ? "leads ilustrativos locais" : interestState === "loaded" ? "leads e reservas persistidos" : interestState === "unavailable" ? "CRM indisponível nesta sessão" : "consultando o serviço de CRM";
    const statusChart = statusTotal
      ? `<div class="atlas-lot-status-layout"><div class="atlas-lot-status-donut" role="img" aria-label="Distribuição de status entre ${statusTotal} lotes" style="background:conic-gradient(${statusSegments.join(",")})"><span><strong>${statusTotal}</strong><small>lotes</small></span></div><div class="atlas-lot-status-legend">${statusLegend}</div></div>`
      : `<p class="atlas-lot-analysis-empty">A tabela de preços não retornou lotes. Os gráficos serão preenchidos quando a fonte oficial estiver disponível.</p>`;
    const valueChart = topBlocks || `<p class="atlas-lot-analysis-empty">Sem valores por quadra para representar.</p>`;
    const table = rows
      ? `<details class="atlas-lot-analysis-table"><summary>Composição por quadra · ${data.blocks.length} quadras</summary><div class="atlas-table-scroll"><table><thead><tr><th>Quadra</th><th>Lotes</th><th>Disponíveis</th><th>Ocupados / negociação</th><th>Área total</th><th>Valor de tabela</th><th>Ticket médio</th></tr></thead><tbody>${rows}</tbody></table></div></details>`
      : "";
    return `${dashboardLotAnalysisStyles}<section class="atlas-lot-analysis" data-dashboard-lot-analysis aria-labelledby="atlas-lot-analysis-title"><header><div><span class="atlas-eyebrow">02 · ANÁLISE DE LOTES</span><h2 id="atlas-lot-analysis-title">Quadro de lotes, ocupação e valor</h2><p>Disponibilidade e concentração de valor da tabela oficial, com reservas persistidas.</p></div><button type="button" data-atlas-dashboard-view="brokers-board">Abrir tabela de lotes</button></header><div class="atlas-lot-analysis-metrics"><article><small>Lotes tabelados</small><strong>${data.lotCount}</strong><span>unidades com preço</span></article><article><small>Valor de tabela</small><strong>${esc(money.format(data.totalValue))}</strong><span>${esc(number.format(data.totalArea))} m² de área</span></article><article><small>Interesses comerciais</small><strong data-dashboard-interest-count>${interestValue}</strong><span data-dashboard-interest-caption>${interestCaption}</span></article><article><small>Ocupados / negociação</small><strong>${data.committedCount}</strong><span>status comerciais controlados</span></article></div><div class="atlas-lot-analysis-charts"><section class="atlas-lot-analysis-card"><h3>Ocupação por status</h3>${statusChart}</section><section class="atlas-lot-analysis-card"><h3>Valor total por quadra</h3><div class="atlas-lot-analysis-rows">${valueChart}</div></section></div>${table}</section>`;
  }
  setData(data: DashboardSnapshot): void {
    this.commercialInterestCount = data.commercialInterestCount;
    this.commercialInterestState = data.commercialInterestState;
    this.state.next(previous => ({ ...previous, ...data, recordStageId: previous.recordStageId || String(data.stages[0]?.id || ""), loading: false, error: null }));
  }
  setCommercialInterestSummary(count: number | null, state: DashboardSnapshot["commercialInterestState"]): void {
    this.commercialInterestCount = count;
    this.commercialInterestState = state;
    const countNode = this.querySelector<HTMLElement>("[data-dashboard-interest-count]");
    const captionNode = this.querySelector<HTMLElement>("[data-dashboard-interest-caption]");
    if (countNode) countNode.textContent = (state === "loaded" || state === "demo") && count !== null ? String(count) : "—";
    if (captionNode) captionNode.textContent = state === "demo"
      ? "leads ilustrativos locais"
      : state === "loaded" ? "leads e reservas persistidos"
        : state === "unavailable" ? "CRM indisponível nesta sessão" : "consultando o serviço de CRM";
  }
  setError(message: string): void { this.state.next(previous => ({ ...previous, loading: false, error: message })); }
  setFeedback(message: string): void {
    this.state.next(previous => ({ ...previous, feedback: message }), false);
    const feedback = this.querySelector<HTMLElement>("[data-dashboard-feedback]");
    if (feedback) feedback.textContent = message;
  }
  setAiGenerationLoading(kind: AtlasDashboardGenerationKindV1): void {
    this.state.next(previous => ({ ...previous, aiGenerationStatus: 'loading', aiGenerationKind: kind, aiGeneration: null, aiGenerationError: '' }));
  }
  setAiGenerationResult(result: AtlasDashboardAiGenerationV1): void {
    this.state.next(previous => ({ ...previous, aiGenerationStatus: 'ready', aiGenerationKind: result.kind, aiGeneration: result, aiGenerationError: '' }));
  }
  setAiGenerationError(message: string): void {
    this.state.next(previous => ({ ...previous, aiGenerationStatus: 'error', aiGeneration: null, aiGenerationError: message }));
  }
  setRecordSaving(recordSaving: boolean): void { this.state.next(previous => ({ ...previous, recordSaving, recordError: "" })); }
  setRecordResult(message: string, error = ""): void { this.state.next(previous => ({ ...previous, recordSaving: false, recordFormOpen: false, recordError: error, feedback: message })); }
  private navigate(view: string, extra: Record<string, unknown> = {}): void { this.dispatchEvent(new CustomEvent("atlas:navigate", { bubbles: true, detail: { view, ...extra } })); }
  private renderAgendaMarkup(agendaWeek: ReturnType<typeof projectAtlasDashboardPageV1>["agendaWeek"]): string {
    const s = this.snapshot, esc = (value: unknown) => this.esc(value);
    const agendaDaysMarkup = agendaWeek.days.map(day => `<button type="button" data-atlas-dashboard-agenda-select-day="${day.iso}" aria-pressed="${day.isSelected}" aria-current="${day.isToday ? "date" : "false"}"><span>${esc(day.weekday)}</span><strong>${esc(day.date)}</strong><small>${day.eventCount}</small></button>`).join("");
    const agendaEventsMarkup = agendaWeek.selectedEvents.map(event => {
      const materials = agendaWeek.materialsByEvent[event.id] || [];
      return `<button type="button" class="atlas-agenda-card" style="width:100%;text-align:left" data-atlas-dashboard-agenda-open="${esc(event.id)}" data-agenda-date="${esc(event.date)}"><div class="atlas-agenda-date"><strong>${esc(event.start||"Horário a definir")}</strong><span>${esc(event.owner||"Equipe a definir")}</span></div><div class="atlas-agenda-details"><h3>${esc(event.title||event.activityName||"Compromisso")}</h3><p>${esc(event.stageName||"Etapa não informada")} · ${esc(event.activityName||"Atividade não informada")}</p><small>${esc(event.status||"Planejado")}${materials.length?` · Materiais: ${esc(materials.join(", "))}`:""}</small></div></button>`;
    }).join("");
    const agendaMarkup = `<style>.atlas-dashboard .atlas-dashboard-agenda{display:grid;gap:12px}.atlas-dashboard .atlas-dashboard-agenda-nav{display:flex;align-items:center;justify-content:space-between;gap:8px;flex-wrap:wrap}.atlas-dashboard .atlas-dashboard-agenda-nav>div{display:flex;gap:7px}.atlas-dashboard .atlas-dashboard-agenda-nav strong{color:#3a4961;font-size:12px}.atlas-dashboard .atlas-dashboard-agenda-days{display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:7px}.atlas-dashboard .atlas-dashboard-agenda-days button{display:grid;min-width:0;gap:4px;justify-items:center;padding:8px 3px}.atlas-dashboard .atlas-dashboard-agenda-days button[aria-pressed=true]{border-color:#246be0;background:#eef4ff;color:#1d4f9d}.atlas-dashboard .atlas-dashboard-agenda-days button[aria-current=date]{box-shadow:inset 0 -2px #246be0}.atlas-dashboard .atlas-dashboard-agenda-days small{color:#718096;font-size:10px}.atlas-dashboard .atlas-dashboard-agenda-selected{display:flex;justify-content:space-between;align-items:baseline;gap:8px;flex-wrap:wrap}.atlas-dashboard .atlas-dashboard-agenda-selected strong{text-transform:capitalize;color:#34445e}.atlas-dashboard .atlas-dashboard-agenda-selected span{color:#718096;font-size:11px}@media(max-width:540px){.atlas-dashboard .atlas-dashboard-agenda-days{gap:3px}.atlas-dashboard .atlas-dashboard-agenda-days button{padding:7px 2px;font-size:11px}}</style><div class="atlas-dashboard-agenda"><div class="atlas-dashboard-agenda-nav"><div><button type="button" data-atlas-dashboard-agenda-week-shift="-1" aria-label="Semana anterior">‹</button><button type="button" data-atlas-dashboard-agenda-today>Hoje</button><button type="button" data-atlas-dashboard-agenda-week-shift="1" aria-label="Próxima semana">›</button></div><strong>${esc(agendaWeek.weekLabel)}</strong></div><nav class="atlas-dashboard-agenda-days" aria-label="Dias da semana">${agendaDaysMarkup}</nav><div class="atlas-dashboard-agenda-selected"><strong>${esc(agendaWeek.selectedDayLabel)}</strong><span>${agendaWeek.selectedEvents.length} compromisso(s) · ${agendaWeek.eventCount} na semana</span></div>${agendaEventsMarkup || `<p class="atlas-muted">${s.loading ? "Carregando compromissos…" : "Nenhum compromisso neste dia."}</p>`}</div>`;
    return agendaMarkup;
  }
  private renderAiGenerationPanel(): string {
    const s = this.snapshot, esc = (value: unknown) => this.esc(value);
    const loading = s.aiGenerationStatus === 'loading';
    const buttons: Array<[AtlasDashboardGenerationKindV1, string]> = [
      ['agenda', 'Gerar agenda'],
      ['materials', 'Gerar lista de compra de materiais'],
      ['complete', 'Gerar plano completo'],
    ];
    const actions = buttons.map(([kind, label]) => `<button type="button" data-atlas-dashboard-generate="${kind}" data-kind="${kind}" ${loading ? 'disabled' : ''}>${loading && s.aiGenerationKind === kind ? 'Gerando…' : label}</button>`).join('');
    let output = '';
    const result = s.aiGeneration;
    if (s.aiGenerationStatus === 'loading') {
      output = '<p class="atlas-ai-generation-status" role="status" aria-live="polite">Cloudflare Workers AI está analisando etapas, atividades, dependências e materiais cadastrados…</p>';
    } else if (s.aiGenerationStatus === 'error') {
      output = `<p class="atlas-ai-generation-status" role="alert">${esc(s.aiGenerationError)}</p>`;
    } else if (result) {
      const fmtQuantity = (value: unknown, unit: unknown) => value === null || value === undefined || value === ''
        ? 'A definir'
        : `${new Intl.NumberFormat('pt-BR', { maximumFractionDigits: 3 }).format(Number(value) || 0)}${unit ? ` ${esc(unit)}` : ''}`;
      const dateLabel = (value: unknown) => {
        const raw = String(value || '');
        if (!/^\d{4}-\d{2}-\d{2}$/.test(raw)) return 'Data a definir';
        return new Intl.DateTimeFormat('pt-BR', { dateStyle: 'medium', timeZone: 'UTC' }).format(new Date(`${raw}T12:00:00Z`));
      };
      const scheduleMarkup = result.schedule.length
        ? `<div class="atlas-ai-output-list">${result.schedule.map(item => `<article class="atlas-ai-output-row"><strong>${esc(item.activityName || item.activityId || 'Atividade')}</strong><span>${esc(item.stageName || 'Etapa')} · ${esc(dateLabel(item.proposedStartDate))}${item.proposedEndDate ? ` até ${esc(dateLabel(item.proposedEndDate))}` : ''}</span><small>${esc(item.rationale || 'Sequência sugerida pela análise das dependências.')}</small></article>`).join('')}</div>`
        : '<p class="atlas-ai-output-empty">A IA não indicou atividade executável para agendar com os dados atuais.</p>';
      const materialMarkup = result.materials.length
        ? `<div class="atlas-table-scroll"><table><thead><tr><th>Material</th><th>Etapas</th><th>Necessário</th><th>Saldo registrado</th><th>Pedidos abertos</th><th>Sugestão de compra</th></tr></thead><tbody>${result.materials.map(item => `<tr><td><strong>${esc(item.name || 'Material')}</strong><small>${esc(item.unit || '')} · ${esc(item.source || 'catálogo')}</small>${item.rationale ? `<small>${esc(item.rationale)}</small>` : ''}</td><td>${esc(Array.isArray(item.stageNames) ? item.stageNames.join(', ') : '')}</td><td>${fmtQuantity(item.plannedQuantity, item.unit)}</td><td>${fmtQuantity(item.stockQuantity, item.unit)}</td><td>${fmtQuantity(item.orderedQuantity, item.unit)}</td><td><strong>${fmtQuantity(item.suggestedPurchaseQuantity, item.unit)}</strong></td></tr>`).join('')}</tbody></table></div>`
        : '<p class="atlas-ai-output-empty">O modelo das atividades não contém materiais quantificados para esta geração.</p>';
      const blockerMarkup = result.blocked.length
        ? `<ul class="atlas-ai-blockers">${result.blocked.map(item => `<li><strong>${esc(item.activityName || item.activityId || 'Atividade')}</strong><span>${esc(item.reason || 'Revisar pré-condições da atividade.')}</span></li>`).join('')}</ul>`
        : '';
      const showSchedule = result.kind !== 'materials';
      const showMaterials = result.kind !== 'agenda';
      const generatedAt = new Date(result.generatedAt);
      const generatedLabel = Number.isFinite(generatedAt.getTime()) ? new Intl.DateTimeFormat('pt-BR', { dateStyle: 'short', timeStyle: 'short' }).format(generatedAt) : '';
      output = `<div class="atlas-ai-generation-result"><header><div><strong>${esc(result.summary)}</strong><p>${esc(result.source)}</p></div><small>Cloudflare Workers AI · ${esc(result.inference.model)}${generatedLabel ? ` · ${esc(generatedLabel)}` : ''}</small></header>${showSchedule ? `<section class="atlas-ai-output"><h3>Agenda sugerida · ${result.schedule.length} atividade(s)</h3>${scheduleMarkup}</section>` : ''}${showMaterials ? `<section class="atlas-ai-output"><h3>Lista de compra sugerida · ${result.materials.length} item(ns)</h3>${materialMarkup}</section>` : ''}${result.kind !== 'materials' && blockerMarkup ? `<section class="atlas-ai-output"><h3>Pendências para revisão</h3>${blockerMarkup}</section>` : ''}<p class="atlas-ai-generation-note">Prévia para revisão humana. Nenhum compromisso ou pedido foi gravado.</p></div>`;
    }
    const status = s.demoMode
      ? 'Demonstração sem login: a IA recebe só o catálogo ilustrativo. O resultado é temporário e desaparece ao sair.'
      : 'As gerações usam o modelo de etapas e atividades e aparecem aqui para revisão.';
    return `<section class="atlas-panel atlas-ai-generation" aria-labelledby="atlas-ai-generation-title"><header><div><span class="atlas-eyebrow">PLANEJAMENTO · CLOUDFLARE WORKERS AI</span><h2 id="atlas-ai-generation-title">Gerações operacionais</h2><p class="atlas-muted">Prepare agenda e necessidades de compra a partir das etapas, atividades, dependências e materiais cadastrados.</p></div></header><div class="atlas-ai-actions" role="group" aria-label="Gerar conteúdo operacional">${actions}</div><p class="atlas-ai-generation-status">${status}</p>${output}</section>`;
  }
  private updateAgendaDate(date: string): void {
    this.state.next(previous => ({ ...previous, agendaSelectedDate: date }), false);
    const agenda = this.querySelector<HTMLElement>(".atlas-agenda-list");
    if (agenda) {
      const snapshot = this.snapshot;
      const projection = projectAtlasDashboardPageV1({
        snapshot,
        agendaSelectedDate: date,
        recordStageId: snapshot.recordStageId,
        statusColors: ["#3478d4", "#d69e18", "#8c58cc", "#21875c", "#55a96b", "#42a5a3", "#c94754"],
      });
      agenda.innerHTML = this.renderAgendaMarkup(projection.agendaWeek);
    }
  }
  private render(): void {
    const s = this.snapshot, esc = (value: unknown) => this.esc(value);
    const pageProjection = projectAtlasDashboardPageV1({ snapshot: s, agendaSelectedDate: s.agendaSelectedDate, recordStageId: s.recordStageId, statusColors: ["#3478d4", "#d69e18", "#8c58cc", "#21875c", "#55a96b", "#42a5a3", "#c94754"] });
    const operationalOverview = pageProjection.operationalOverview;
    const active = operationalOverview.activeStageCount, done = operationalOverview.completedStageCount;
    const money = new Intl.NumberFormat("pt-BR", { style: "currency", currency: "BRL" }).format(s.cashBalanceCents / 100);
    const agendaMarkup = this.renderAgendaMarkup(pageProjection.agendaWeek);
    const reportActions = s.demoMode ? `<p class="atlas-muted">Exportações ficam disponíveis após autenticar no serviço operacional.</p>` : dashboardPresentation.reportActions.map(({kind,title,description})=>`<article><div><strong>${title}</strong><p>${description}</p></div><button type="button" data-report="${kind}">Gerar CSV</button></article>`).join("");
    const headerActions = s.demoMode ? `<span class="atlas-demo-badge">Demonstração local · conteúdo ilustrativo</span>` : `<div class="atlas-actions"><button type="button" data-refresh>Atualizar</button><button type="button" data-atlas-dashboard-view="map">Mapa</button><button type="button" class="atlas-primary" data-new-record>Novo registro</button></div>`;
    const widgets = dashboardPresentation.widgets.map(({view,label,icon})=>`<button type="button" class="atlas-widget" data-atlas-dashboard-view="${view}"><span aria-hidden="true">${icon}</span>${label} →</button>`).join("");
    this.innerHTML = `${dashboardStyles}${dashboardAgendaStyles}${dashboardAiGenerationStyles}<style>.atlas-dashboard .atlas-demo-badge{display:inline-flex;align-items:center;min-height:38px;padding:8px 12px;border:1px solid #b7d2f7;border-radius:10px;background:#eef5ff;color:#235a9e;font-size:12px;font-weight:700}</style><section class="atlas-dashboard atlas-dashboard-home"><header class="atlas-dashboard-head"><div><span class="atlas-eyebrow">DASHBOARD · ALIANÇA PARK</span><h1>Panorama operacional</h1><p>${s.demoMode ? "Exemplos locais para conhecer a aplicação; não representam gravações persistidas." : "Resumo atualizado das fontes persistidas da aplicação."}</p></div>${headerActions}</header>${s.error?`<p role="alert">${esc(s.error)}</p>`:""}${s.loading?`<p>Carregando panorama do banco operacional…</p>`:""}<section class="atlas-kpis"><article class="atlas-kpi"><small>SALDO DE CAIXA</small><strong>${s.loading?"—":money}</strong><span>${s.demoMode ? "Saldo ilustrativo do caixa" : "Resumo retornado pelo serviço de caixa"}</span></article><article class="atlas-kpi"><small>ETAPAS ATIVAS</small><strong>${s.loading?"—":active}</strong><span>${done} concluídas · ${operationalOverview.totalStageCount} cadastradas</span></article><article class="atlas-kpi"><small>NOTIFICAÇÕES</small><strong>${s.loading?"—":s.notifications.length}</strong><span>${s.demoMode ? "Alertas de exemplo" : "Itens do serviço operacional"}</span></article><article class="atlas-kpi"><small>REGISTROS DE CAMPO</small><strong>${s.loading?"—":s.records.length}</strong><span>${s.demoMode ? "Apontamentos de exemplo" : "Histórico persistido"}</span></article></section>${this.renderAiGenerationPanel()}${this.renderLotAnalysis(s.lotAnalysis, this.commercialInterestCount, this.commercialInterestState, pageProjection.lotAnalysisPresentation)}<section class="atlas-panel"><header><div><span class="atlas-eyebrow">AGENDA · SEMANA</span><h2>Compromissos da obra</h2><p class="atlas-muted">Escolha um dia para consultar atividades, responsáveis e materiais.</p></div><button type="button" data-atlas-dashboard-view="agenda">Abrir agenda completa</button></header><div class="atlas-agenda-list">${agendaMarkup||`<p class="atlas-muted">${s.loading?"Carregando compromissos…":"Nenhum compromisso pendente nos próximos sete dias."}</p>`}</div></section><section class="atlas-panel"><header><div><span class="atlas-eyebrow">${s.demoMode ? "DEMONSTRAÇÃO LOCAL" : "EXPORTAÇÕES · BANCO OPERACIONAL"}</span><h2>Relatórios rápidos</h2><p class="atlas-muted">${s.demoMode ? "Os exemplos não são enviados ao servidor." : "Os arquivos são gerados a partir de leituras atualizadas do servidor."}</p></div></header><div class="atlas-report-actions">${reportActions}</div><p class="atlas-feedback" data-dashboard-feedback role="status" aria-live="polite">${esc(s.feedback)}</p></section><section class="atlas-panel atlas-dashboard-map-overview-panel"><header><div><span class="atlas-eyebrow">MAPA OPERACIONAL</span><h2>Progresso físico por etapa</h2><p class="atlas-muted">Mapa compartilhado com a navegação operacional.</p></div><button type="button" data-atlas-dashboard-view="map">Abrir mapa completo</button></header><div class="atlas-dashboard-map"><map-scene compact interactive data-base-map data-dashboard-operational-map="true" class="dashboard-operational-map" data-stage="Execução do Aliança Park" data-overlay="drenagem" aria-label="Mapa operacional 3D"></map-scene><map-filter-rail></map-filter-rail></div></section><nav class="atlas-widgets" aria-label="Interfaces operacionais">${widgets}</nav></section>`;
    const moneyCell = (cents: number) => new Intl.NumberFormat("pt-BR", { style: "currency", currency: "BRL" }).format((Number(cents) || 0) / 100);
    const tableRows = pageProjection.controlTableRows;
    const financeRows = tableRows.finance.map(row => `<tr><td>${esc(row.date)}</td><td>${esc(row.kind)}</td><td>${esc(row.link)}</td><td>${moneyCell(row.amountCents)}</td><td>${esc(row.description)}</td></tr>`).join("");
    const materialRows = tableRows.materials.map(row => `<tr><td>${esc(row.stageName)}</td><td>${esc(row.activityName)}</td><td><strong>${esc(row.name)}</strong><small>${esc(row.scope)}</small></td><td>${esc(row.receivedQuantity)} / ${esc(row.plannedQuantity)} ${esc(row.unit)}</td><td>${esc(row.status)}</td></tr>`).join("");
    const stageRows = operationalOverview.stages.map(({ stage, progress, state, statusLabel }) => `<article class="atlas-stage-progress-row" data-state="${state}"><div class="atlas-stage-progress-heading"><strong>${esc(stage.name)}</strong><span>${progress}%</span></div><div class="atlas-stage-progress-track" role="progressbar" aria-label="Progresso de ${esc(stage.name)}" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${progress}"><i style="width:${progress}%"></i></div><small>${esc(stage.owner || "Responsável a definir")} · ${esc(statusLabel)}</small></article>`).join("");
    const saleRows = tableRows.sales.map(sale => `<tr><td>${esc(sale.id)}</td><td>${esc(sale.lot)}</td><td>${esc(sale.client)}</td><td>${esc(sale.broker)}</td><td>${sale.receiptCount}</td><td>${esc(sale.commissionLabel)}</td></tr>`).join("");
    const notices = tableRows.notices.map(item => `<li><strong>${esc(item.label)}</strong><span>${esc(item.statusLabel)}</span></li>`).join("");
    const controlSectionsMarkup = `<div class="atlas-control-sections"><section class="atlas-panel atlas-panel-cash"><header><div><span class="atlas-eyebrow">01 · CAIXA</span><h2>Movimentações recentes</h2><p class="atlas-muted">Leitura do livro-caixa persistido.</p></div><button type="button" data-atlas-dashboard-view="cash-record">Registrar saída</button></header><div class="atlas-table-scroll"><table><thead><tr><th>Data</th><th>Tipo</th><th>Vínculo</th><th>Valor</th><th>Descrição</th></tr></thead><tbody>${financeRows || `<tr class="atlas-empty-row"><td colspan="5">Nenhuma movimentação retornada pelo serviço.</td></tr>`}</tbody></table></div></section><section class="atlas-panel atlas-panel-materials"><header><div><span class="atlas-eyebrow">02 · NOTAS</span><h2>Notas por atividade</h2><p class="atlas-muted">Itens, quantidades e estados vinculados às atividades operacionais.</p></div><button type="button" data-atlas-dashboard-view="materials">Abrir notas</button></header><div class="atlas-table-scroll"><table><thead><tr><th>Etapa</th><th>Atividade</th><th>Nota / uso</th><th>Recebido / previsto</th><th>Estado</th></tr></thead><tbody>${materialRows || `<tr class="atlas-empty-row"><td colspan="5">Nenhuma nota retornada pelo serviço.</td></tr>`}</tbody></table></div></section><section class="atlas-panel atlas-panel-execution"><header><div><span class="atlas-eyebrow">03 · EXECUÇÃO</span><h2>Etapas e progresso</h2><p class="atlas-muted">Situação composta a partir do catálogo operacional persistido.</p></div><button type="button" data-atlas-dashboard-view="agenda">Abrir agenda</button></header><div class="atlas-stage-progress-list">${stageRows || `<p class="atlas-section-empty">Nenhuma etapa retornada pelo serviço.</p>`}</div></section><section class="atlas-panel atlas-panel-sales"><header><div><span class="atlas-eyebrow">04 · VENDAS E REPASSES</span><h2>Perfis de lote relacionados</h2><p class="atlas-muted">Vendas e regras financeiras atuais; configuração detalhada em Repasses.</p></div><button type="button" data-atlas-dashboard-view="repasses">Abrir repasses</button></header><div class="atlas-table-scroll"><table><thead><tr><th>Venda</th><th>Lote</th><th>Cliente</th><th>Corretor</th><th>Entradas</th><th>Comissão</th></tr></thead><tbody>${saleRows || `<tr class="atlas-empty-row"><td colspan="6">Nenhuma venda retornada pelo serviço.</td></tr>`}</tbody></table></div></section><section class="atlas-panel atlas-panel-notices"><header><div><span class="atlas-eyebrow">05 · AVISOS OPERACIONAIS</span><h2>Notificações recentes</h2></div></header><ul class="atlas-notices">${notices || `<li class="atlas-section-empty">Nenhuma notificação retornada pelo serviço.</li>`}</ul></section></div>`;
    this.querySelector("[data-dashboard-lot-analysis]")?.insertAdjacentHTML("afterend", `<style>.atlas-dashboard .atlas-control-sections{display:grid;grid-template-columns:repeat(12,minmax(0,1fr));gap:16px;align-items:start}.atlas-dashboard .atlas-control-sections>.atlas-panel{min-width:0;margin:0;padding:20px;border-radius:16px}.atlas-dashboard .atlas-control-sections>.atlas-panel-cash{grid-column:span 6}.atlas-dashboard .atlas-control-sections>.atlas-panel-materials{grid-column:span 6}.atlas-dashboard .atlas-control-sections>.atlas-panel-execution{grid-column:1/-1}.atlas-dashboard .atlas-control-sections>.atlas-panel-notices{grid-column:span 5}.atlas-dashboard .atlas-control-sections>.atlas-panel-sales{grid-column:span 7}.atlas-dashboard .atlas-table-scroll{max-width:100%;overflow:auto;border:1px solid #e8ecf2;border-radius:10px}.atlas-dashboard table{width:100%;border-collapse:collapse;font-size:12px}.atlas-dashboard th,.atlas-dashboard td{padding:10px;border-bottom:1px solid #e8ecf2;text-align:left;vertical-align:top}.atlas-dashboard tr:last-child td{border-bottom:0}.atlas-dashboard th{color:#708096;font-size:10px;text-transform:uppercase;white-space:nowrap}.atlas-dashboard td small{display:block;color:#758197;margin-top:3px}.atlas-dashboard .atlas-empty-row td,.atlas-dashboard .atlas-section-empty{padding:16px;color:#778399;font-size:12px;line-height:1.5}.atlas-dashboard .atlas-stage-progress-list{display:grid;grid-template-columns:repeat(auto-fit,minmax(190px,1fr));gap:10px}.atlas-dashboard .atlas-stage-progress-row{display:grid;align-content:start;gap:10px;min-width:0;padding:13px;border:1px solid #e5eaf1;border-radius:12px;background:#fafbfd}.atlas-dashboard .atlas-stage-progress-heading{display:flex;align-items:flex-start;justify-content:space-between;gap:8px;color:#29364b;font-size:12px}.atlas-dashboard .atlas-stage-progress-heading strong{font-weight:650}.atlas-dashboard .atlas-stage-progress-heading span{flex:none;color:#536782;font-variant-numeric:tabular-nums}.atlas-dashboard .atlas-stage-progress-track{height:7px;overflow:hidden;border-radius:99px;background:#e7edf5}.atlas-dashboard .atlas-stage-progress-track i{display:block;height:100%;border-radius:inherit;background:#3478db}.atlas-dashboard .atlas-stage-progress-row[data-state=done] .atlas-stage-progress-track i{background:#33996e}.atlas-dashboard .atlas-stage-progress-row small{color:#758197;font-size:10px}.atlas-dashboard .atlas-notices{display:grid;gap:4px;margin:0;padding:0;list-style:none}.atlas-dashboard .atlas-notices li{display:flex;justify-content:space-between;gap:12px;padding:12px;border-bottom:1px solid #e8ecf2;color:#29364b;font-size:12px}.atlas-dashboard .atlas-notices span{flex:none;color:#758197;font-size:11px}@media(max-width:1120px){.atlas-dashboard .atlas-control-sections>.atlas-panel{grid-column:1/-1}}@media(max-width:640px){.atlas-dashboard .atlas-control-sections>.atlas-panel{padding:14px}.atlas-dashboard .atlas-control-sections>.atlas-panel>header{display:grid}}</style>${controlSectionsMarkup}`);
    this.insertAdjacentHTML("beforeend", dashboardControlStyles);
    if (s.demoMode) this.querySelector<HTMLButtonElement>('[data-atlas-dashboard-view="cash-record"]')?.remove();
    const controlGrid = this.querySelector<HTMLElement>(".atlas-control-sections");
    const agendaPanel = [...this.querySelectorAll<HTMLElement>(".atlas-panel")].find(panel => panel.querySelector("h2")?.textContent?.trim() === "Compromissos da obra");
    agendaPanel?.classList.add("atlas-panel-agenda");
    if (controlGrid) {
      [".atlas-panel-execution", ".atlas-panel-agenda", ".atlas-panel-cash", ".atlas-panel-materials", ".atlas-panel-sales", ".atlas-panel-notices"]
        .forEach(selector => { const panel = this.querySelector<HTMLElement>(selector); if (panel) controlGrid.append(panel); });
    }

    const cashPanel = this.querySelector<HTMLElement>(".atlas-panel-cash");
    const cashTable = cashPanel?.querySelector<HTMLElement>(".atlas-table-scroll");
    if (cashPanel && cashTable) {
      const heading = cashPanel.querySelector("h2");
      const caption = cashPanel.querySelector(".atlas-muted");
      if (heading) heading.textContent = "Entradas e saídas";
      if (caption) caption.textContent = "Fluxo mensal do livro-caixa nos últimos seis meses.";
      const cashChart = pageProjection.cashChart;
      const months = cashChart.months;
      const hasCashActivity = cashChart.hasActivity;
      let chart: HTMLElement;
      if (hasCashActivity) {
        const figure = document.createElement("figure");
        figure.className = "atlas-cash-chart";
        figure.setAttribute("role", "img");
        figure.setAttribute("aria-label", "Entradas e saídas mensais do caixa nos últimos seis meses");
        for (const month of months) {
          const column = document.createElement("div");
          column.className = "atlas-cash-month";
          const bars = document.createElement("div");
          bars.className = "atlas-cash-bars";
          for (const [kind, value, height] of [["entry", month.entriesCents, month.entriesHeightPercent], ["exit", month.exitsCents, month.exitsHeightPercent]] as const) {
            const bar = document.createElement("i");
            bar.dataset.kind = kind;
            bar.style.height = `${height}%`;
            bar.title = `${kind === "entry" ? "Entradas" : "Saídas"}: ${moneyCell(value)}`;
            bars.append(bar);
          }
          const label = document.createElement("small");
          label.textContent = month.label;
          column.append(bars, label);
          figure.append(column);
        }
        chart = figure;
      } else {
        chart = document.createElement("p");
        chart.className = "atlas-chart-empty";
        chart.textContent = s.loading ? "Carregando movimentações…" : "Sem entradas ou saídas nos últimos seis meses.";
      }
      const legend = document.createElement("div");
      legend.className = "atlas-cash-legend";
      for (const [kind, label] of [["entry", "Entradas"], ["exit", "Saídas"]] as const) {
        const item = document.createElement("span"), swatch = document.createElement("i");
        swatch.dataset.kind = kind;
        item.append(swatch, document.createTextNode(label));
        legend.append(item);
      }
      const ledger = document.createElement("details");
      const ledgerSummary = document.createElement("summary");
      ledgerSummary.textContent = `Movimentações recentes · ${s.cashEntries.length}`;
      ledger.append(ledgerSummary, cashTable.cloneNode(true));
      cashTable.replaceWith(chart, ...(hasCashActivity ? [legend] : []), ledger);
    }

    const materialPanel = this.querySelector<HTMLElement>(".atlas-panel-materials");
    const materialTable = materialPanel?.querySelector<HTMLElement>(".atlas-table-scroll");
    if (materialPanel && materialTable) {
      const quantity = new Intl.NumberFormat("pt-BR", { maximumFractionDigits: 2 });
      const coverage = pageProjection.materialCoverage;
      const list = document.createElement("div");
      list.className = "atlas-material-list";
      for (const item of coverage.slice(0, 5)) {
        const row = document.createElement("article");
        row.className = "atlas-material-row";
        if (item.receivedPercent !== null && item.receivedPercent >= 100) row.dataset.state = "complete";
        const title = document.createElement("div"), name = document.createElement("strong"), value = document.createElement("span");
        title.className = "atlas-material-heading";
        name.textContent = item.name;
        value.textContent = item.receivedPercent === null ? "Sem previsão" : `${Math.round(item.receivedPercent)}% recebido`;
        title.append(name, value);
        row.append(title);
        if (item.receivedPercent !== null) {
          const track = document.createElement("div"), fill = document.createElement("i");
          track.className = "atlas-material-track";
          track.setAttribute("role", "progressbar");
          track.setAttribute("aria-label", `Recebimento de ${item.name}`);
          track.setAttribute("aria-valuemin", "0");
          track.setAttribute("aria-valuemax", "100");
          track.setAttribute("aria-valuenow", String(Math.round(item.receivedPercent)));
          fill.style.width = `${item.receivedPercent}%`;
          track.append(fill);
          row.append(track);
        }
        const details = document.createElement("small");
        details.textContent = item.receivedPercent === null
          ? `${quantity.format(item.received)} ${item.unit} recebidos · ${item.stageName} · ${item.activityName}`
          : `${quantity.format(item.received)} de ${quantity.format(item.planned)} ${item.unit} · ${item.stageName} · ${item.activityName}`;
        row.append(details);
        list.append(row);
      }
      if (!coverage.length) {
        const empty = document.createElement("p");
        empty.className = "atlas-chart-empty";
        empty.textContent = s.loading ? "Carregando materiais…" : "Nenhuma nota vinculada a uma atividade.";
        list.append(empty);
      } else if (coverage.length > 5) {
        const remainder = document.createElement("p");
        remainder.className = "atlas-muted";
        remainder.textContent = `Exibindo 5 de ${coverage.length} itens. Abra Materiais para ver o inventário completo.`;
        list.append(remainder);
      }
      const inventory = document.createElement("details");
      const inventorySummary = document.createElement("summary");
      inventorySummary.textContent = `Inventário completo · ${s.materials.length}`;
      inventory.append(inventorySummary, materialTable.cloneNode(true));
      materialTable.replaceWith(list, inventory);
    }

    if (s.recordFormOpen) {
      const recordForm = pageProjection.recordForm;
      const stageOptions = recordForm.stageOptions.map(({ stage, selected }) => `<option value="${stage.id}" ${selected ? "selected" : ""}>${esc(stage.name)}</option>`).join("");
      const activityOptions = recordForm.activityOptions.map(activity => `<option value="${esc(activity.id)}">${esc(activity.name)}</option>`).join("");
      this.querySelector(".atlas-kpis")?.insertAdjacentHTML("afterend", `<style>.atlas-dashboard .atlas-record-fields{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.atlas-dashboard .atlas-record-fields label{display:grid;gap:6px;color:#59667a;font-size:12px}.atlas-dashboard .atlas-record-fields input,.atlas-dashboard .atlas-record-fields select,.atlas-dashboard .atlas-record-fields textarea{width:100%;min-height:40px;padding:9px 11px;border:1px solid #d7deea;border-radius:9px;background:#fff;color:#18243e;font:inherit}.atlas-dashboard .atlas-record-fields textarea{min-height:86px}.atlas-dashboard .atlas-record-fields .wide{grid-column:1/-1}.atlas-dashboard [data-record-capture] form footer{display:flex;justify-content:flex-end;gap:8px;margin-top:12px}.atlas-dashboard .atlas-record-fields [role=alert]{grid-column:1/-1}@media(max-width:640px){.atlas-dashboard .atlas-record-fields{grid-template-columns:1fr}.atlas-dashboard .atlas-record-fields .wide{grid-column:auto}}</style><section class="atlas-panel" data-record-capture><header><div><span class="atlas-eyebrow">DIÁRIO OPERACIONAL</span><h2>Novo registro</h2><p class="atlas-muted">O apontamento será enviado ao serviço persistente do diário.</p></div><button type="button" data-record-cancel>Cancelar</button></header><form data-record-form><div class="atlas-record-fields"><label>Etapa<select name="stageId" data-record-stage required>${stageOptions}</select></label><label>Atividade<select name="activityId" required>${activityOptions}</select></label><label>Data<input name="date" type="date" required value="${recordForm.date}"></label><label>Hora<input name="time" type="time" required value="08:30"></label><label>Responsável<input name="responsible" placeholder="Encarregado ou equipe"></label><label class="wide">Resumo / medição<textarea name="detail" required placeholder="Descreva a execução, medição ou ocorrência"></textarea></label><label class="wide">Foto ou comprovante (opcional)<input name="evidence" type="file" accept="image/jpeg,image/png,image/webp,application/pdf" capture="environment"><small>Até 6 MB; o anexo será vinculado ao registro.</small></label><label>Status<select name="status"><option>Pendente</option><option>Concluído</option></select></label>${s.recordError ? `<p role="alert">${esc(s.recordError)}</p>` : ""}</div><footer><button type="button" data-record-cancel>Cancelar</button><button type="submit" class="atlas-primary" ${s.recordSaving ? "disabled" : ""}>${s.recordSaving ? "Salvando…" : "Salvar registro"}</button></footer></form></section>`);
      this.querySelector<HTMLElement>("[data-record-capture]")?.scrollIntoView({ behavior: "smooth", block: "start" });
    }
  }
  connectedCallback(): void {
    this.render();
    this.addEventListener("click", event => { const target=event.target;if(!(target instanceof Element))return;const button=target.closest<HTMLElement>("button");if(!button)return;
      if(button.hasAttribute("data-refresh")){this.dispatchEvent(new CustomEvent("atlas:dashboard-refresh",{bubbles:true,detail:{element:this}}));return;}
      if(button.hasAttribute("data-new-record")){this.state.next(s=>({...s,recordFormOpen:true,recordStageId:s.recordStageId||String(s.stages[0]?.id||""),recordError:""}));return;}
      if(button.hasAttribute("data-record-cancel")){this.state.next(s=>({...s,recordFormOpen:false,recordError:""}));return;}
      if(button.dataset.atlasDashboardAgendaSelectDay){this.updateAgendaDate(button.dataset.atlasDashboardAgendaSelectDay);return;}
      if(button.dataset.atlasDashboardAgendaWeekShift){const selected=projectAtlasDashboardAgendaNavigationDateV1(this.snapshot.agendaSelectedDate,"week-shift",Number(button.dataset.atlasDashboardAgendaWeekShift));this.updateAgendaDate(selected);return;}
      if(button.hasAttribute("data-atlas-dashboard-agenda-today")){this.updateAgendaDate(projectAtlasDashboardAgendaNavigationDateV1(this.snapshot.agendaSelectedDate,"today"));return;}
      if(button.dataset.atlasDashboardAgendaOpen){this.navigate("agenda",{agendaDate:button.dataset.agendaDate||this.snapshot.agendaSelectedDate,agendaEventId:button.dataset.atlasDashboardAgendaOpen});return;}
      if(button.dataset.atlasDashboardView){this.navigate(button.dataset.atlasDashboardView);return;}
      if(button.dataset.atlasDashboardGenerate){
        const kind=button.dataset.atlasDashboardGenerate;
        if(kind==='agenda'||kind==='materials'||kind==='complete')this.dispatchEvent(new CustomEvent('atlas:dashboard-generate',{bubbles:true,detail:{element:this,kind}}));
        return;
      }
      if(button.dataset.report){this.dispatchEvent(new CustomEvent("atlas:dashboard-report",{bubbles:true,detail:{element:this,kind:button.dataset.report,button}}));}
    });
    this.addEventListener("change",event=>{const target=event.target;if(target instanceof HTMLSelectElement&&target.matches("[data-record-stage]"))this.state.next(s=>({...s,recordStageId:target.value,recordError:""}));});
    this.addEventListener("submit",event=>{const form=event.target;if(!(form instanceof HTMLFormElement)||!form.matches("[data-record-form]"))return;event.preventDefault();void this.submitRecord(form);});
    this.dispatchEvent(new CustomEvent("atlas:dashboard-connected",{bubbles:true,detail:{element:this}}));
  }
  setRecordError(message: string): void {
    this.state.next(previous => ({ ...previous, recordSaving: false, recordError: message }));
  }
  private async submitRecord(form: HTMLFormElement): Promise<void> {
    const data = new FormData(form), file = data.get("evidence");
    const draft: AtlasDashboardRecordDraftV1 = {
      stageId: String(data.get("stageId") || ""),
      activityId: String(data.get("activityId") || ""),
      date: String(data.get("date") || ""),
      time: String(data.get("time") || ""),
      responsible: String(data.get("responsible") || ""),
      detail: String(data.get("detail") || ""),
      status: String(data.get("status") || "Pendente"),
      evidenceSizeBytes: file instanceof File ? file.size : 0,
    };
    let evidenceUri = "";
    try {
      if (file instanceof File && file.size) {
        evidenceUri = await new Promise<string>((resolve, reject) => {
          const reader = new FileReader();
          reader.onload = () => resolve(String(reader.result || ""));
          reader.onerror = () => reject(new Error("Não foi possível ler o comprovante."));
          reader.readAsDataURL(file);
        });
      }
    } catch (error: unknown) {
      this.setRecordError(error instanceof Error ? error.message : String(error));
      return;
    }
    this.state.next(previous => ({ ...previous, recordSaving: true, recordError: "" }));
    this.dispatchEvent(new CustomEvent<AtlasDashboardRecordCreateCommandDetailV1>("atlas:dashboard-record-create", {
      bubbles: true,
      detail: { element: this, draft, evidenceUri },
    }));
  }
}
if (!customElements.get("atlas-dashboard")) customElements.define("atlas-dashboard", AtlasDashboard);

export interface AtlasDashboardRecordCreateCommandDetailV1 {
  element: AtlasDashboard;
  draft: AtlasDashboardRecordDraftV1;
  evidenceUri: string;
}

export interface AtlasOperationalRecordSubmissionV1 extends Record<string, unknown> {
  obra?: string;
  etapa?: string;
  stageId?: number | string | null;
  stageKey?: string;
  activityId?: number | string | null;
  atividade?: string;
  activity?: string;
  activityName?: string;
  data?: string;
  date?: string;
  hora?: string;
  time?: string;
  responsavel?: string;
  status?: string;
  detalhes?: string;
  detail?: string;
  progresso?: number | string;
  progress?: number | string;
  progressPercent?: number | string;
  evidenceUri?: string | null;
  mapArea?: string | null;
  properties?: Array<{
    id?: string;
    key?: string;
    label?: string;
    type?: string;
    value?: unknown;
    source?: string;
    confidence?: number;
  }> | Record<string, unknown>;
}

export interface AtlasOperationalRecordCreateCommandDetailV1<TElement extends HTMLElement = HTMLElement> {
  element: TElement;
  payload: AtlasOperationalRecordSubmissionV1;
}

export interface AtlasLegacyOperationalRecordSaveCommandV1 {
  element: HTMLElement;
  editingId: string | null;
  values: Record<string, FormDataEntryValue>;
  nature: string;
  contextFields: Array<{ label: string; value: string }>;
  attachments: File[];
}

export interface AtlasLegacyOperationalRecordDeleteCommandV1 {
  element: HTMLElement;
  id: string;
}

export interface AtlasLegacyRecordEditorComponentInputV1 {
  root: HTMLElement;
  onCommand(command: AtlasLegacyRecordEditorComponentCommandV1): void;
}

export type AtlasLegacyRecordEditorComponentCommandV1 =
  | { kind: 'open-new'; element: HTMLElement }
  | { kind: 'edit'; element: HTMLElement; id: string }
  | { kind: 'delete'; element: HTMLElement; id: string }
  | { kind: 'cancel'; element: HTMLElement }
  | {
      kind: 'save';
      element: HTMLElement;
      values: Record<string, FormDataEntryValue>;
      nature: string;
      contextFields: Array<{ label: string; value: string }>;
      attachments: File[];
    };

export function renderAtlasLegacyRecordsPageV1(state: Record<string, any>): string {
  const records = Array.isArray(state.records) ? state.records : [];
  const editing = records.find((record: any) => record.id === state.editingRecord);
  const editorOpen = Boolean(state.editingRecord);
  const rows = records.map((record: any) =>
    `<article class="record-card"><div><span class="record-id">${record.id}</span><strong>${record.atividade}</strong><small>${record.data} · ${record.hora} · ${record.responsavel}</small></div><span class="record-status">${record.status}</span><div class="record-actions"><button data-record-edit="${record.id}">Editar</button><button data-record-delete="${record.id}">Excluir</button></div></article>`,
  ).join('');
  const mobilePreview = records.slice(0, 3).map((record: any) =>
    `<div><small>${record.data} · ${record.hora}</small><strong>${record.atividade}</strong><span>${record.status}</span></div>`,
  ).join('');
  return `<div class="records-page"><div class="records-map-wash"></div><div class="records-shell"><div class="records-head"><div><span class="activity-kind">REGISTROS OPERACIONAIS</span><h1>Registros</h1><p>Obra → atividade → evidência → responsável → confirmação.</p></div><button class="records-new">＋ Novo registro</button></div><div class="records-layout"><section class="records-list"><div class="records-list-head"><b>${records.length} registros</b><small>SQLite local · entidades relacionais</small></div>${rows || '<div class="empty-records">Nenhum registro cadastrado.</div>'}</section><aside class="records-form-wrap ${editorOpen ? 'open' : ''}"><form class="record-form"><h2>${editing ? 'Editar registro' : 'Adicionar registro'}</h2><label>Obra<select name="obra"><option>Aliança Park</option><option>Aliança Park</option></select></label><label>Atividade<select name="atividade"><option>Drenagem Pluvial</option><option>Pavimentação</option><option>Rede de Água</option><option>Rede Elétrica</option></select></label><div class="form-pair"><label>Data<input name="data" type="date" value="${editing?.data || new Date().toISOString().slice(0, 10)}"></label><label>Hora<input name="hora" type="time" value="${editing?.hora || '08:30'}"></label></div><label>Responsável<input name="responsavel" value="${editing?.responsavel || ''}" placeholder="Nome do envolvido"></label><label>Detalhes<textarea name="detalhes" placeholder="Descreva a evidência, medição ou ocorrência">${editing?.detalhes || ''}</textarea></label><label>Status<select name="status"><option ${editing?.status === 'Pendente' ? 'selected' : ''}>Pendente</option><option ${editing?.status === 'Concluído' ? 'selected' : ''}>Concluído</option></select></label><button class="record-confirm">${editing ? 'Salvar alterações' : 'Confirmar registro'}</button>${editing ? '<button type="button" class="record-cancel">Cancelar</button>' : ''}</form></aside></div><div class="phone-preview"><div class="phone-frame"><div class="phone-notch"></div><div class="phone-screen"><b>Registros</b>${mobilePreview}</div></div><small>Prévia da interface mobile</small></div></div></div>`;
}

export function installAtlasLegacyRecordEditorComponentV1(input: AtlasLegacyRecordEditorComponentInputV1): void {
  const { root, onCommand } = input;
  root.querySelector('.records-new')?.addEventListener('click', () => onCommand({ kind: 'open-new', element: root }));
  root.querySelectorAll<HTMLElement>('[data-record-edit]').forEach(button =>
    button.addEventListener('click', () => onCommand({ kind: 'edit', element: root, id: String(button.dataset.recordEdit || '') })),
  );
  root.querySelectorAll<HTMLElement>('[data-record-delete]').forEach(button =>
    button.addEventListener('click', () => onCommand({ kind: 'delete', element: root, id: String(button.dataset.recordDelete || '') })),
  );
  root.querySelector('.record-cancel')?.addEventListener('click', () => onCommand({ kind: 'cancel', element: root }));
  root.querySelector<HTMLFormElement>('.record-form')?.addEventListener('submit', event => {
    event.preventDefault();
    const form = event.currentTarget as HTMLFormElement;
    const formData = new FormData(form);
    const attachments = formData.getAll('attachments').filter((item): item is File => item instanceof File && item.size > 0);
    formData.delete('attachments');
    const values = Object.fromEntries(formData.entries());
    const contextFields = [...form.querySelectorAll<HTMLElement>('[data-record-context-field]')]
      .map(input => ({
        label: String(input.dataset.recordContextLabel || ''),
        value: String((input as HTMLInputElement).value || '').trim(),
      }))
      .filter(field => field.label && field.value);
    onCommand({
      kind: 'save',
      element: root,
      values,
      nature: String(form.dataset.recordNature || 'execução'),
      contextFields,
      attachments,
    });
  });
}

