export function installAtlasLegacyLeadComponentV1(root: HTMLElement): void {
  if (root.dataset.atlasLegacyLeadComponentBound === 'true') return;
  root.dataset.atlasLegacyLeadComponentBound = 'true';
  const emit = (command: AtlasLegacyLeadCommandV1): void => {
    root.dispatchEvent(new CustomEvent<AtlasLegacyLeadCommandV1>('atlas:legacy-lead-command', {
      bubbles: true,
      detail: command,
    }));
  };
  root.addEventListener('click', event => {
    const target = event.target instanceof Element ? event.target : null;
    if (!target) return;
    const lead = target.closest<HTMLElement>('[data-lead]');
    if (lead && root.contains(lead)) {
      emit({ kind: 'select', element: root, index: Number(lead.dataset.lead) });
    }
    const messageButton = target.closest<HTMLElement>('[data-lead-message]');
    if (messageButton && root.contains(messageButton)) {
      const detail = messageButton.closest('.lead-ops-detail');
      emit({
        kind: 'prepare-whatsapp',
        element: root,
        name: detail?.querySelector('h2')?.textContent?.trim() || 'interessado',
        lot: detail?.querySelector('.lead-lot-focus b')?.textContent?.trim() || 'lote selecionado',
      });
    }
    const reserveButton = target.closest<HTMLElement>('[data-lead-reserve]');
    if (reserveButton && root.contains(reserveButton)) {
      emit({ kind: 'prepare-reservation', element: root, index: Number(reserveButton.dataset.leadReserve) });
    }
  });
  root.addEventListener('input', event => {
    const target = event.target instanceof HTMLInputElement ? event.target : null;
    if (!target || !target.matches('[data-lead-search]')) return;
    const query = target.value.trim().toLowerCase();
    root.querySelectorAll<HTMLElement>('.lead-client-row').forEach(row => {
      row.hidden = Boolean(query && !row.textContent?.toLowerCase().includes(query));
    });
  });
}

