export function installAtlasLegacyCanvasRelationComponentV1(root: HTMLElement): void {
  root.querySelectorAll<HTMLElement>('.canvas-node').forEach(node => {
    node.addEventListener('dragstart', event => {
      event.dataTransfer!.setData('text/plain', String(node.dataset.node || ''));
      node.classList.add('dragging');
    });
    node.addEventListener('dragend', () => node.classList.remove('dragging'));
  });
  const zone = root.querySelector<HTMLElement>('.canvas-relate');
  if (!zone) return;
  zone.addEventListener('dragover', event => {
    event.preventDefault();
    zone.classList.add('drop-ready');
  });
  zone.addEventListener('dragleave', () => zone.classList.remove('drop-ready'));
  zone.addEventListener('drop', event => {
    event.preventDefault();
    const node = event.dataTransfer!.getData('text/plain');
    zone.classList.remove('drop-ready');
    zone.querySelector('strong')!.textContent = `Relacionamento: ${node} → orçamento mensal`;
    root.dispatchEvent(new CustomEvent<AtlasLegacyCanvasRelationCommandV1>('atlas:legacy-canvas-relation-command', {
      bubbles: true,
      detail: { element: root, node },
    }));
  });
}

export function installAtlasLegacyStageCanvasComponentV1(root: HTMLElement, windowRef: Window): void {
  const emit = (detail: AtlasLegacyStageCanvasCommandV1): void => {
    root.dispatchEvent(new CustomEvent<AtlasLegacyStageCanvasCommandV1>('atlas:legacy-stage-canvas-command', {
      bubbles: true,
      detail,
    }));
  };
  root.querySelectorAll<HTMLElement>('.stage-card[draggable="true"]').forEach(card => {
    card.addEventListener('dragstart', event => {
      event.dataTransfer!.setData('text/stage', String(card.dataset.stage));
      card.classList.add('dragging');
    });
    card.addEventListener('dragend', () => card.classList.remove('dragging'));
    card.addEventListener('pointerdown', event => {
      if (event.button !== 0 || (event.target as Element).closest('button,input,textarea')) return;
      const canvas = card.closest<HTMLElement>('.stage-canvas');
      if (!canvas) return;
      const initial = { x: card.offsetLeft, y: card.offsetTop };
      const origin = { x: event.clientX, y: event.clientY };
      card.classList.add('pointer-dragging');
      const move = (pointer: PointerEvent): void => {
        card.style.left = `${Math.max(12, initial.x + pointer.clientX - origin.x)}px`;
        card.style.top = `${Math.max(42, initial.y + pointer.clientY - origin.y)}px`;
      };
      const up = (): void => {
        card.classList.remove('pointer-dragging');
        windowRef.removeEventListener('pointermove', move);
        windowRef.removeEventListener('pointerup', up);
        const relation = canvas.querySelector<HTMLElement>('.relation-label');
        if (relation) relation.textContent = `Posições relacionadas: ${card.dataset.stage} → próxima atividade`;
        emit({ kind: 'stage-position', element: root, stage: String(card.dataset.stage) });
      };
      windowRef.addEventListener('pointermove', move);
      windowRef.addEventListener('pointerup', up);
    });
  });
  root.querySelectorAll<HTMLElement>('.stage-activity-card').forEach(card => {
    card.addEventListener('pointerdown', event => {
      if (event.button !== 0 || (event.target as Element).closest('.activity-connect')) return;
      event.preventDefault();
      card.setPointerCapture?.(event.pointerId);
      const initial = { x: card.offsetLeft, y: card.offsetTop };
      const origin = { x: event.clientX, y: event.clientY };
      let moved = false;
      card.classList.add('dragging');
      const move = (pointer: PointerEvent): void => {
        if (Math.abs(pointer.clientX - origin.x) > 3 || Math.abs(pointer.clientY - origin.y) > 3) moved = true;
        card.style.left = `${Math.max(10, initial.x + pointer.clientX - origin.x)}px`;
        card.style.top = `${Math.max(45, initial.y + pointer.clientY - origin.y)}px`;
      };
      const up = (): void => {
        card.classList.remove('dragging');
        card.releasePointerCapture?.(event.pointerId);
        card.removeEventListener('pointermove', move);
        card.removeEventListener('pointerup', up);
        if (moved) {
          card.dataset.dragged = 'true';
          setTimeout(() => delete card.dataset.dragged, 0);
          emit({ kind: 'activity-position', element: root, activity: String(card.dataset.activityDetail) });
        }
      };
      card.addEventListener('pointermove', move);
      card.addEventListener('pointerup', up);
    });
  });
  const stageCanvas = root.querySelector<HTMLElement>('.stage-canvas');
  if (!stageCanvas) return;
  stageCanvas.addEventListener('dragover', event => {
    event.preventDefault();
    stageCanvas.classList.add('drop-ready');
  });
  stageCanvas.addEventListener('dragleave', () => stageCanvas.classList.remove('drop-ready'));
  stageCanvas.addEventListener('drop', event => {
    event.preventDefault();
    const stage = event.dataTransfer!.getData('text/stage');
    stageCanvas.classList.remove('drop-ready');
    const label = stageCanvas.querySelector<HTMLElement>('.relation-label');
    if (label) label.textContent = `Dependência relacionada: ${stage} → próxima etapa`;
    emit({ kind: 'stage-drop', element: root, stage });
  });
}

export function installAtlasLegacyGenericActionsComponentV1(root: HTMLElement): void {
  const skipped = '[data-report-row-toggle],[data-agenda-day],[data-agenda-new],[data-agenda-item-menu],[data-agenda-whatsapp],[data-agenda-alert],[data-activity-category-filter],[data-activity-open],[data-activity-v9],[data-activity-new],[data-activity-detail-tab],[data-activity-new-record],[data-activity-record-close],[data-front-stage-tab],[data-control-context-add-material],[data-progress-period],[data-progress-new],[data-progress-send],[data-progress-cancel],[data-record-paint],[data-record-mobile-select],[data-record-camera],[data-record-image-next],[data-record-image-back],[data-record-image-remove],[data-records-drill-root],[data-records-drill-stage],[data-records-drill-stage-back],[data-records-drill-activity],[data-record-new-activity],[data-record-drill-paint],[data-record-drill-fit],[data-record-drill-clear],[data-records-stage-fit],[data-map-pdf],[data-map-print-start],[data-map-print-close],[data-audit-clear],[data-audit-export],[data-lead-reservation-start],[data-reservation-start],[data-reservation-close],[data-reservation-analyze],[data-copy-pix],[data-commission-directory-page],[data-ai-step-prev],[data-ai-step-next],[data-ai-step-select],.control-remove-context-material,.reservation-submit,.records-new,.record-confirm,.record-cancel,.journal-open,.personnel-primary-button-v5372';
  root.querySelectorAll<HTMLElement>(`button:not([data-view]):not([data-cmd]):not([data-lead]):not([data-lead-message]):not([data-lead-reserve]):not([id])`).forEach(button =>
    button.addEventListener('click', () => {
      if (button.matches(skipped) || button.closest('.activity-journal-form')) return;
      if (button.closest('.reports-toolbar,.report-footer')) return;
      const label = button.textContent?.trim().replace(/\s+/g, ' ') || '';
      if (!label) return;
      const emit = (detail: AtlasLegacyGenericActionCommandV1): void => {
        root.dispatchEvent(new CustomEvent<AtlasLegacyGenericActionCommandV1>('atlas:legacy-generic-action-command', {
          bubbles: true,
          detail,
        }));
      };
      if (button.classList.contains('stage-tab')) {
        root.querySelectorAll('.stage-tab').forEach(tab => tab.classList.remove('active'));
        button.classList.add('active');
        emit({ kind: 'stage-tab', element: root, label });
        return;
      }
      if (button.classList.contains('public-submit')) {
        const values = [...root.querySelectorAll<HTMLInputElement>('.public-fields input')].map(input => input.value.trim());
        emit({ kind: 'public-lead-submit', element: root, complete: !values.some(value => !value) });
        return;
      }
      if (label.includes('relatório')) {
        emit({ kind: 'report-export', element: root });
        return;
      }
      if (label.includes('recomend')) {
        emit({ kind: 'recommendations', element: root });
        return;
      }
      emit({ kind: 'action', element: root, label });
    }),
  );
}

