export interface AtlasDashboardComponentControllerV1 {
  ViewLayer: { prototype: HTMLElement & Record<string, unknown> };
  host: Document;
  onConnected(element: AtlasDashboard): void;
  onRefresh(element: AtlasDashboard): void;
  onGenerate(event: CustomEvent<{ element: AtlasDashboard; kind: AtlasDashboardGenerationKindV1 }>): void;
  onReport(event: CustomEvent<{ element: AtlasDashboard; kind: string }>): void;
  onRecordCreate(event: CustomEvent<AtlasDashboardRecordCreateCommandDetailV1>): void;
  onQuickRecord(event: CustomEvent<AtlasDashboardQuickRecordSubmitDetailV1>): void;
  onNavigate(element: AtlasDashboard, navigation: AtlasDashboardComponentNavigationV1): void;
}

const atlasDashboardComponentBindingsV1 = new WeakMap<Document, AbortController>();

/** Keep Dashboard rendering and its page-level event controller under the same component owner. */
export function installAtlasDashboardComponentControllerV1(
  input: AtlasDashboardComponentControllerV1,
): void {
  atlasDashboardComponentBindingsV1.get(input.host)?.abort();
  const AbortControllerCtor = input.host.defaultView?.AbortController || AbortController;
  const bindings = new AbortControllerCtor();
  atlasDashboardComponentBindingsV1.set(input.host, bindings);
  input.ViewLayer.prototype.control = () => '<atlas-dashboard></atlas-dashboard>';
  const options = { signal: bindings.signal };
  const getElement = (event: Event): AtlasDashboard | null => {
    const element = (event as CustomEvent<{ element?: AtlasDashboard }>).detail?.element;
    return element instanceof AtlasDashboard ? element : null;
  };
  input.host.addEventListener('atlas:dashboard-connected', event => {
    const element = getElement(event);
    if (element) input.onConnected(element);
  }, options);
  input.host.addEventListener('atlas:dashboard-refresh', event => {
    const element = getElement(event);
    if (element) input.onRefresh(element);
  }, options);
  input.host.addEventListener('atlas:dashboard-generate', event => {
    if (getElement(event)) input.onGenerate(event as CustomEvent<{ element: AtlasDashboard; kind: AtlasDashboardGenerationKindV1 }>);
  }, options);
  input.host.addEventListener('atlas:dashboard-report', event => {
    if (getElement(event)) input.onReport(event as CustomEvent<{ element: AtlasDashboard; kind: string }>);
  }, options);
  input.host.addEventListener('atlas:dashboard-record-create', event => {
    if (getElement(event)) input.onRecordCreate(event as CustomEvent<AtlasDashboardRecordCreateCommandDetailV1>);
  }, options);
  input.host.addEventListener('atlas:dashboard-quick-record-submit', event => {
    input.onQuickRecord(event as CustomEvent<AtlasDashboardQuickRecordSubmitDetailV1>);
  }, options);
  input.host.addEventListener('atlas:navigate', event => {
    const element = getElement(event);
    if (!element || event.target !== element) return;
    const navigation = (event as CustomEvent<AtlasDashboardComponentNavigationV1>).detail;
    if (navigation) input.onNavigate(element, navigation);
  }, options);
}

