type BrokersState = {
  data: RepasseOperations | null;
  reports: RepasseReport[];
  profileRecords: BrokerProfile[];
  commissionReport: AtlasBrokerCommissionReportV1 | null;
  profileAttachments: AtlasBrokerProfileAttachmentV1[];
  query: string;
  selectedBroker: string;
  editingProfile: boolean;
  savingProfile: boolean;
  status: "loading" | "ready" | "error";
  error: string | null;
  message: string | null;
};
type BrokersSetter = (previous: BrokersState) => BrokersState;

export interface AtlasCommissionNegotiationViewsV1 {
  commissionNegotiationDealsV1(state?: AtlasCommissionNegotiationStateV1): AtlasCommissionNegotiationDealV1[];
  commissionNegotiationProfileV1(id?: string): AtlasCommissionProfileCatalogEntry | undefined;
  commissionNegotiationTransactionsV1(deal: AtlasCommissionNegotiationDealV1, profile?: AtlasCommissionProfileCatalogEntry): AtlasCommissionNegotiationTransactionV1[];
  commissionNegotiationDateV1(value: unknown): string;
  commissionNegotiationsMarkupV1(state: AtlasCommissionNegotiationStateV1): string;
  commissionAttachmentListV1(attachments?: Partial<Record<AtlasCommissionAttachmentKindV1, AtlasCommissionAttachmentV1[]>>): string;
  commissionDealMarkupV1(): string;
  commissionFileToDataUrlV1(file: File): Promise<string>;
  bindCommissionNegotiationEventsV1(root: ParentNode): void;
}
export interface AtlasCommissionNegotiationViewsInputV1 {
  readState(): AtlasCommissionNegotiationStateV1;
  onAction(action: AtlasCommissionNegotiationPageActionV1): void;
  commissionDeals: AtlasCommissionNegotiationDealV1[];
  commissionProfiles: AtlasCommissionProfileCatalogEntry[];
  esc: (value: unknown) => string;
  ico: (name: string) => string;
  formatBRL: (value: unknown) => string;
  brlToNumber: (value: unknown) => number;
  contractStatusClassV1: (status: unknown) => string;
  FileReader: typeof FileReader;
  Date?: DateConstructor;
  FormData: typeof FormData;
  windowRef: Pick<Window, 'print'>;
}

/** Typed markup and interaction adapters for the commercial negotiation flow. */
export function createAtlasCommissionNegotiationViewsV1({
  readState,
  onAction,
  commissionDeals,
  commissionProfiles,
  esc,
  ico,
  formatBRL,
  brlToNumber,
  contractStatusClassV1,
  FileReader: BrowserFileReader,
  Date: BrowserDate = Date,
  FormData: BrowserFormData,
  windowRef,
}: AtlasCommissionNegotiationViewsInputV1 = {} as AtlasCommissionNegotiationViewsInputV1): AtlasCommissionNegotiationViewsV1 {
  if (typeof readState !== "function" || typeof onAction !== "function")
    throw new TypeError("Commission views require readState() and onAction().");
  if (!Array.isArray(commissionDeals) || !Array.isArray(commissionProfiles))
    throw new TypeError("Commission views require the commercial catalog.");
  for (const [name, value] of Object.entries({ esc, ico, formatBRL, brlToNumber, contractStatusClassV1 }))
    if (typeof value !== "function")
      throw new TypeError(`Commission views require ${name}().`);
  if (typeof BrowserFileReader !== "function")
    throw new TypeError("Commission views require the browser FileReader service.");
  if (typeof BrowserFormData !== "function" || typeof windowRef?.print !== "function")
    throw new TypeError("Commission views require form and print browser services.");

  const commissionNegotiationDealsV1 = (state: AtlasCommissionNegotiationStateV1 = readState()): AtlasCommissionNegotiationDealV1[] => {
    return projectAtlasCommissionNegotiationDealsV1({ state, canonicalDeals: commissionDeals });
  };

  const emptyCommissionProfile: AtlasCommissionProfileCatalogEntry = {
    id: "",
    name: "Corretor não definido",
    initials: "—",
    role: "Corretor",
    creci: "",
    avatar: "#697386",
    sales: 0,
    commission: "",
    conversion: "",
    lots: [],
    phone: "",
    emails: [],
  };
  const commissionNegotiationProfileV1 = (id?: string): AtlasCommissionProfileCatalogEntry =>
    commissionProfiles.find((item) => item.id === id) || commissionProfiles[0] || emptyCommissionProfile;

  const commissionNegotiationTransactionsV1 = (deal: AtlasCommissionNegotiationDealV1, profile?: AtlasCommissionProfileCatalogEntry): AtlasCommissionNegotiationTransactionV1[] => {
    return projectAtlasCommissionNegotiationTransactionsV1(deal, profile);
  };

  const commissionNegotiationDateV1 = (value: unknown): string => {
    const text = String(value || "");
    return text || "Data não informada";
  };

  const commissionNegotiationsMarkupV1 = (state: AtlasCommissionNegotiationStateV1): string => {
    const ledger = projectAtlasCommissionNegotiationLedgerV1({ state, canonicalDeals: commissionDeals, brlToNumber });
    const { deals, filters, shown, statusOptions } = ledger;
    const list = shown
        .map((deal) => {
          const profile = commissionNegotiationProfileV1(deal.profile),
            transactions = commissionNegotiationTransactionsV1(deal, profile);
          return `<article class="commission-negotiation-row" data-commission-record="${esc(deal.id)}"><header class="commission-negotiation-row-head"><div class="commission-negotiation-broker"><span class="commission-avatar" style="background:${esc(profile.avatar)}">${esc(profile.initials)}</span><span><b>${esc(profile.name)}</b><small>${esc(profile.role)} · ${esc(profile.creci)}</small></span></div><div class="commission-negotiation-identity"><span>${esc(deal.id || "NEGOCIAÇÃO")}</span><h2>${esc(deal.client || "Cliente não informado")}</h2><small>${esc(deal.lot || "Lote a definir")} · ${esc(deal.quadra || "Quadra não informada")}</small></div><span class="deal-status ${contractStatusClassV1(deal.status || deal.stage)}">${esc(deal.status || deal.stage || "Em acompanhamento")}</span></header><div class="commission-negotiation-facts"><div><small>VALOR DO LOTE</small><b>${esc(deal.value || "—")}</b><span>${esc(deal.payment || "Condição a definir")}</span></div><div><small>COMISSÃO</small><b>${esc(deal.commission || "—")}</b><span>${esc(deal.rate || "Taxa cadastrada")}</span></div><div><small>ETAPA</small><b>${esc(deal.stage || "Em acompanhamento")}</b><span>${commissionNegotiationDateV1(deal.date)}</span></div><div><small>FINALIDADE</small><b>${esc(deal.purpose || "Não informada")}</b><span>${esc(deal.cpf || "Documento não informado")}</span></div></div><section class="commission-negotiation-transactions"><div class="commission-negotiation-transactions-head"><span>ÚLTIMAS TRANSAÇÕES DA NEGOCIAÇÃO</span><small>${transactions.length} registros sumarizados</small></div><ol>${transactions.map((transaction) => `<li><span><b>${esc(transaction.label || transaction.type || "Transação")}</b><small>${esc(transaction.detail || transaction.description || "")}</small></span><span><b>${esc(transaction.value || transaction.amount || "—")}</b><small>${esc(transaction.at || transaction.date || deal.date || "")}</small></span><em>${esc(transaction.status || "Registrada")}</em></li>`).join("")}</ol></section><footer class="commission-negotiation-row-footer"><span>Última atualização: ${commissionNegotiationDateV1(deal.date)} · vínculo lote → cliente → corretor</span><button type="button" class="toolbar-primary" data-commission-record-open="${esc(deal.id)}">Abrir negociação ${ico("arrow-up-right")}</button></footer></article>`;
        })
        .join("");
    return `<section class="commission-negotiations-page"><header class="commission-negotiations-head"><div><span class="activity-kind">OPERAÇÃO COMERCIAL · COMISSÕES</span><h1>Negociações e comissões</h1><p>Uma linha por negociação, com o corretor, o lote, o cliente, os valores e as últimas transações registradas.</p></div><div class="commission-negotiations-head-actions"><button type="button" class="toolbar-action" data-view="brokers-board">${ico("users-round")} Corretores</button><button type="button" class="toolbar-primary" data-commission-new>${ico("plus")} Nova negociação</button></div></header><section class="commission-negotiation-kpis"><article><small>NEGOCIAÇÕES</small><b>${shown.length}</b><span>${deals.length} no histórico</span></article><article><small>VALOR EM NEGOCIAÇÃO</small><b>${formatBRL(ledger.valueTotal)}</b><span>lotes e reservas acompanhados</span></article><article><small>COMISSÃO PREVISTA</small><b>${formatBRL(ledger.commissionTotal)}</b><span>conforme a carteira visível</span></article><article><small>EM ANDAMENTO</small><b>${ledger.activeCount}</b><span>precisam de próxima ação</span></article></section><div class="commission-negotiation-toolbar"><label>Buscar negociação<input type="search" data-commission-negotiation-filter="query" value="${esc(filters.query)}" placeholder="Cliente, lote ou contrato"></label><label>Status<select data-commission-negotiation-filter="status"><option value="all">Todos os status</option>${statusOptions.map((status) => `<option value="${esc(status)}" ${filters.status === status ? "selected" : ""}>${esc(status)}</option>`).join("")}</select></label><label>Corretor<select data-commission-negotiation-filter="profile"><option value="all">Todos os corretores</option>${commissionProfiles.map((profile) => `<option value="${esc(profile.id)}" ${filters.profile === profile.id ? "selected" : ""}>${esc(profile.name)}</option>`).join("")}</select></label><button type="button" class="toolbar-action" data-commission-negotiation-clear>${ico("filter-x")} Limpar</button></div><section class="commission-negotiation-list" aria-label="Negociações comerciais"><header><div><span class="activity-kind">01 · REGISTROS DE NEGOCIAÇÃO</span><h2>Comissões por negociação</h2><p>Selecione uma linha para abrir o formulário completo, o contrato e os anexos do cliente.</p></div><span>${shown.length} registros</span></header>${list || '<p class="empty-data">Nenhuma negociação corresponde aos filtros atuais.</p>'}</section></section>`;
  };

  const commissionAttachmentListV1 = (
    attachments: Partial<Record<AtlasCommissionAttachmentKindV1, AtlasCommissionAttachmentV1[]>> = {},
  ): string => {
    const groups: Array<[string, AtlasCommissionAttachmentV1[]]> = [
      ["Contrato", attachments.contract || []],
      ["Cliente", attachments.client || []],
    ];
    return groups
      .flatMap(([label, items]) => items.map((item) => ({ ...item, label })))
      .map(
        (item) =>
          `<li><span>${ico("paperclip")}<b>${esc(item.name)}</b><small>${esc(item.label)} · ${esc(item.type || "arquivo")} · ${Math.max(1, Math.round(Number(item.size || 0) / 1024))} KB</small></span><time>${item.at ? new BrowserDate(item.at).toLocaleString("pt-BR") : "agora"}</time></li>`,
      )
      .join("");
  };

  const commissionDealMarkupV1 = function (): string {
    const state = readState(),
      deal = commissionNegotiationDealsV1(state).find(
        (item) => item.id === state.selectedCommissionNegotiation,
      );
    if (!deal)
      return `<section class="commission-deal-page commission-deal-empty"><h1>Negociação não encontrada</h1><button type="button" data-view="brokers">Voltar para comissões</button></section>`;
    const profile = commissionNegotiationProfileV1(deal.profile),
      attachments = state.commissionDealAttachments?.[deal.id] || {};
    return `<section class="commission-deal-page"><header class="commission-deal-head"><div><button type="button" class="commission-back" data-commission-deal-back>${ico("arrow-left")} Voltar para comissões</button><span class="activity-kind">NEGOCIAÇÃO · ${esc(deal.id)}</span><h1>${esc(deal.client || "Cliente")}</h1><p>${esc(deal.lot || "Lote a definir")} · ${esc(deal.quadra || "Quadra não informada")} · corretor ${esc(profile.name)}</p></div><div><span class="deal-status ${contractStatusClassV1(deal.status)}">${esc(deal.status || "Em acompanhamento")}</span><button type="button" class="toolbar-action" data-commission-deal-print>${ico("printer")} Imprimir / PDF</button></div></header><form class="commission-deal-form" data-commission-deal-form><section class="commission-deal-form-section"><header><span>01</span><div><h2>Dados da negociação</h2><p>Edite os dados que alimentam a comissão, o contrato e o acompanhamento do cliente.</p></div></header><div class="commission-deal-fields"><label>Corretor<select name="profile">${commissionProfiles.map((item) => `<option value="${esc(item.id)}" ${item.id === deal.profile ? "selected" : ""}>${esc(item.name)} · ${esc(item.creci)}</option>`).join("")}</select></label><label>Cliente<input name="client" required value="${esc(deal.client || "")}"></label><label>CPF / CNPJ<input name="cpf" value="${esc(deal.cpf || "")}"></label><label>Lote<input name="lot" required value="${esc(deal.lot || "")}"></label><label>Quadra / identificação<input name="quadra" value="${esc(deal.quadra || "")}"></label><label>Valor do lote<input name="value" required value="${esc(deal.value || "")}"></label><label>Taxa de comissão<input name="rate" value="${esc(deal.rate || "")}"></label><label>Status<select name="status">${["Reserva", "Em análise", "Proposta", "Assinado", "Compra confirmada"].map((status) => `<option ${status === deal.status ? "selected" : ""}>${esc(status)}</option>`).join("")}</select></label><label>Etapa<input name="stage" value="${esc(deal.stage || "")}"></label><label>Finalidade<input name="purpose" value="${esc(deal.purpose || "")}"></label><label class="wide">Condição de pagamento<textarea name="payment" rows="3">${esc(deal.payment || "")}</textarea></label><label class="wide">Observações do cliente<textarea name="notes" rows="4">${esc(deal.notes || "")}</textarea></label></div></section><section class="commission-deal-form-section commission-deal-attachments"><header><span>02</span><div><h2>Documentos e anexos</h2><p>Separe o contrato da documentação enviada pelo cliente. Os nomes e o vínculo ficam registrados na negociação.</p></div></header><div class="commission-deal-upload-grid"><label class="commission-deal-upload"><span>${ico("file-signature")}<b>Contrato da negociação</b><small>PDF ou imagem · um arquivo principal</small></span><input type="file" name="contractAttachment" data-commission-contract-attachment accept="application/pdf,image/*"></label><label class="commission-deal-upload"><span>${ico("files")}<b>Anexos do cliente</b><small>Documento, comprovante ou identificação · vários arquivos</small></span><input type="file" name="clientAttachments" data-commission-client-attachments multiple accept="application/pdf,image/*"></label></div><ul class="commission-deal-attachment-list" data-commission-attachment-list>${commissionAttachmentListV1(attachments) || '<li class="empty-data">Nenhum anexo registrado ainda.</li>'}</ul><p class="commission-deal-attachment-note">A seleção atual será vinculada ao contrato ${esc(deal.id)} ao salvar.</p></section><aside class="commission-deal-transaction-summary"><header><div><span class="activity-kind">03 · HISTÓRICO RESUMIDO</span><h2>Últimas transações</h2></div><span>${commissionNegotiationTransactionsV1(deal, profile).length} registros</span></header><ol>${commissionNegotiationTransactionsV1(
      deal,
      profile,
    )
      .map(
        (item) =>
          `<li><span><b>${esc(item.label || "Transação")}</b><small>${esc(item.detail || "")}</small></span><strong>${esc(item.value || "—")}</strong><time>${esc(item.at || item.date || deal.date || "")}</time></li>`,
      )
      .join(
        "",
      )}</ol></aside><footer class="commission-deal-form-footer"><span data-commission-deal-status>Os anexos permanecem associados à negociação após salvar.</span><button type="submit" class="toolbar-primary">${ico("save")} Salvar negociação</button></footer></form></section>`;
  };

  const commissionFileToDataUrlV1 = (file: File): Promise<string> =>
    new Promise<string>((resolve, reject) => {
      const reader = new BrowserFileReader();
      reader.onload = () => resolve(String(reader.result || ""));
      reader.onerror = () =>
        reject(reader.error || new Error("Falha ao ler anexo."));
      reader.readAsDataURL(file);
    });

  const negotiationBindingsV1 = new WeakSet<object>();
  const pendingNegotiationFilesV1 = new WeakMap<HTMLFormElement, {
    metadata: Record<AtlasCommissionAttachmentKindV1, AtlasCommissionAttachmentV1[]>;
    files: Record<AtlasCommissionAttachmentKindV1, File[]>;
  }>();
  const bindCommissionNegotiationEventsV1 = (root: ParentNode): void => {
    const eventRoot = root as ParentNode & EventTarget;
    if (typeof eventRoot.addEventListener !== "function" || negotiationBindingsV1.has(eventRoot)) return;
    negotiationBindingsV1.add(eventRoot);
    const contains = (element: Element): boolean =>
      !(root instanceof Element) || root.contains(element);
    const pendingFor = (form: HTMLFormElement) => {
      let pending = pendingNegotiationFilesV1.get(form);
      if (!pending) {
        pending = { metadata: { contract: [], client: [] }, files: { contract: [], client: [] } };
        pendingNegotiationFilesV1.set(form, pending);
      }
      return pending;
    };
    const applyFilter = (control: HTMLInputElement | HTMLSelectElement): void => {
      const filterKey = control.dataset.commissionNegotiationFilter;
      if (filterKey !== "query" && filterKey !== "status" && filterKey !== "profile") return;
      onAction({ kind: "set-filter", key: filterKey, value: control.value });
    };

    eventRoot.addEventListener("change", event => {
      const target = event.target;
      if (!(target instanceof HTMLInputElement || target instanceof HTMLSelectElement) || !contains(target)) return;
      if (target.closest(".commission-negotiations-page") && target.matches("[data-commission-negotiation-filter]")) applyFilter(target);
      const form = target.closest<HTMLFormElement>("[data-commission-deal-form]");
      if (!form || !contains(form)) return;
      const kind: AtlasCommissionAttachmentKindV1 | null =
        target.matches("[data-commission-contract-attachment]") ? "contract" :
        target.matches("[data-commission-client-attachments]") ? "client" : null;
      if (!kind || !(target instanceof HTMLInputElement)) return;
      const pending = pendingFor(form), files = Array.from(target.files || []);
      pending.files[kind] = files;
      pending.metadata[kind] = files.map(file => ({
        name: file.name, size: file.size, type: file.type || "arquivo", at: new BrowserDate().toISOString(),
      }));
      const selectedId = readState().selectedCommissionNegotiation;
      const existing = selectedId ? readState().commissionDealAttachments?.[selectedId] || {} : {};
      const list = form.querySelector<HTMLElement>("[data-commission-attachment-list]");
      if (list) list.innerHTML = commissionAttachmentListV1({
        contract: [...(existing.contract || []), ...pending.metadata.contract],
        client: [...(existing.client || []), ...pending.metadata.client],
      }) || '<li class="empty-data">Nenhum anexo registrado ainda.</li>';
    });

    eventRoot.addEventListener("keydown", event => {
      const keyboard = event as KeyboardEvent, target = event.target;
      if (keyboard.key !== "Enter" || !(target instanceof HTMLInputElement) ||
          !target.closest(".commission-negotiations-page") ||
          !target.matches('[data-commission-negotiation-filter="query"]') || !contains(target)) return;
      keyboard.preventDefault();
      applyFilter(target);
    });

    eventRoot.addEventListener("click", event => {
      const target = event.target;
      if (!(target instanceof Element) || !contains(target)) return;
      const negotiationPage = target.closest(".commission-negotiations-page");
      if (negotiationPage && target.closest("[data-commission-negotiation-clear]")) {
        onAction({ kind: "clear-filters" });
        return;
      }
      if (negotiationPage && target.closest('[data-view="brokers-board"]')) {
        onAction({ kind: "open-brokers" });
        return;
      }
      const openRecord = negotiationPage
        ? target.closest<HTMLElement>("[data-commission-record-open]") : null;
      if (openRecord) {
        const id = openRecord.dataset.commissionRecordOpen;
        onAction({ kind: "open-record", id });
        return;
      }
      if (negotiationPage && target.closest("[data-commission-new]")) {
        onAction({ kind: "create-record" });
        return;
      }
      const dealPage = target.closest(".commission-deal-page");
      if (dealPage && target.closest("[data-commission-deal-back]")) {
        onAction({ kind: "return-to-ledger" });
        return;
      }
      if (dealPage && target.closest("[data-commission-deal-print]")) windowRef.print();
    });

    eventRoot.addEventListener("submit", event => {
      const form = event.target;
      if (!(form instanceof HTMLFormElement) || !form.matches("[data-commission-deal-form]") || !contains(form)) return;
      event.preventDefault();
      const id = readState().selectedCommissionNegotiation;
      if (!id) return;
      const submit = form.querySelector<HTMLButtonElement>('button[type="submit"]');
      if (submit) submit.disabled = true;
      const data: Record<string, string> = {};
      for (const [name, value] of new BrowserFormData(form).entries())
        if (typeof value === "string") data[name] = value;
      const pending = pendingFor(form);
      const files: AtlasCommissionNegotiationSaveCommandV1["files"] = [];
      let attachmentReadFailed = false;
      void (async () => {
        try {
          for (const kind of ["contract", "client"] as const)
            for (const file of pending.files[kind])
              files.push({ kind, fileName: file.name, dataUrl: await commissionFileToDataUrlV1(file) });
        } catch {
          attachmentReadFailed = true;
        }
        form.dispatchEvent(new CustomEvent<AtlasCommissionNegotiationSaveCommandV1>(
          "atlas:commission-negotiation-save-v1",
          { bubbles: true, composed: true, detail: {
            id, fields: data, attachments: pending.metadata, files, attachmentReadFailed,
          } },
        ));
      })();
    });
  };

  return Object.freeze({
    commissionNegotiationDealsV1,
    commissionNegotiationProfileV1,
    commissionNegotiationTransactionsV1,
    commissionNegotiationDateV1,
    commissionNegotiationsMarkupV1,
    commissionAttachmentListV1,
    commissionDealMarkupV1,
    commissionFileToDataUrlV1,
    bindCommissionNegotiationEventsV1,
  });
}

/** Install negotiation rendering and its delegated UI controller beside the view model. */
export function installAtlasCommissionNegotiationComponentControllerV1(
  ViewLayer: { prototype: HTMLElement & Record<string, unknown> },
  views: AtlasCommissionNegotiationViewsV1,
): void {
  const prototype = ViewLayer.prototype;
  prototype["commission-deal"] = views.commissionDealMarkupV1;
  const baseBind = prototype.bind as ((this: HTMLElement, ...args: unknown[]) => unknown) | undefined;
  prototype.bind = function (this: HTMLElement, ...args: unknown[]): unknown {
    const result = baseBind?.apply(this, args);
    views.bindCommissionNegotiationEventsV1(this);
    return result;
  };
}

interface AtlasCommissionPageRendererLayerV1 extends HTMLElement {
  brokers(...args: unknown[]): unknown;
  commissions(...args: unknown[]): unknown;
}

/** Install the typed commission markup as the final renderer for both legacy view IDs. */
export function installAtlasCommissionPageRenderersV1(
  ViewLayer: { prototype: AtlasCommissionPageRendererLayerV1 },
  input: {
    readState(): AtlasCommissionNegotiationStateV1;
    commissionNegotiationsMarkupV1(state: AtlasCommissionNegotiationStateV1): string;
  },
): void {
  if (typeof input?.readState !== "function" || typeof input.commissionNegotiationsMarkupV1 !== "function")
    throw new TypeError("Commission page renderers require a state reader and markup projection.");
  ViewLayer.prototype.brokers = function (): string {
    return input.commissionNegotiationsMarkupV1(input.readState());
  };
  ViewLayer.prototype.commissions = function (): string {
    return input.commissionNegotiationsMarkupV1(input.readState());
  };
}

export interface AtlasBrokerControlPageDependenciesV1 {
  readState(): Record<string, unknown>;
  commissionDeals: AtlasCommissionDealV1[];
  commissionProfiles: AtlasCommissionProfileCatalogEntry[];
  brokerReasonsV9(state: Record<string, unknown>): AtlasBrokerCommissionReasonV1[];
  brlToNumber(value: unknown): number;
  formatBRL(value: unknown): string;
  esc(value: unknown): string;
  ico(name: string): string;
  queueMicrotaskFn?: (callback: VoidFunction) => void;
}

type AtlasBrokerControlViewLayer = HTMLElement & { bindCommercialPagesV7?: () => void };

const renderAtlasBrokerReasonEditorV1 = (
  rows: Array<{ reason: AtlasBrokerCommissionReasonV1; initialSharePercent: number }>,
  esc: (value: unknown) => string,
  ico: (name: string) => string,
): string => `<section class="broker-rule-editor" aria-label="Editor de regras de repasse"><header><div><span class="activity-kind">REGRAS EDITÁVEIS · ADMINISTRADOR</span><h2>Razões de comissão e divisão</h2><p>Edite a participação da razão. A divisão declarada permanece: mensais 70% Warley / 30% contraparte; sinal e intermediária 50% / 50%.</p></div><span class="broker-rule-audit">Aplicação controlada</span></header><div class="broker-rule-grid">${rows.map(({ reason, initialSharePercent }) => `<form data-v8-reason-form="${esc(reason.id)}"><div class="broker-rule-form-head"><b>${esc(reason.label)}</b><span>${esc(reason.payment)}</span></div><label>Nome da razão<input name="label" value="${esc(reason.label)}"></label><label>Participação na composição (%)<input name="sharePercent" type="number" min="0" max="100" step="0.1" value="${initialSharePercent}"></label><label>Warley (%)<input value="${reason.warley}" readonly></label><label>Contraparte (%)<input value="${reason.partner}" readonly></label><label class="wide">Descrição<input name="description" value="${esc(reason.description || "")}" placeholder="Quando esta razão libera o repasse"></label><button type="submit">${ico("save")} Salvar razão</button></form>`).join("")}</div></section>`;

/** Render the broker portfolio and commission ledger; the program owns all commands and persistence. */
export function createAtlasBrokerControlPageV1(input: AtlasBrokerControlPageDependenciesV1): (this: AtlasBrokerControlViewLayer) => string {
  const { readState, commissionDeals, commissionProfiles, brokerReasonsV9, brlToNumber, formatBRL, esc, ico } = input;
  const queueMicrotaskFn = input.queueMicrotaskFn || globalThis.queueMicrotask?.bind(globalThis);
  if (typeof readState !== "function") throw new TypeError("Broker control page requires readState().");
  if (!Array.isArray(commissionDeals) || !Array.isArray(commissionProfiles)) throw new TypeError("Broker control page requires commission deals and profiles.");
  for (const [name, value] of Object.entries({ brokerReasonsV9, brlToNumber, formatBRL, esc, ico }))
    if (typeof value !== "function") throw new TypeError(`Broker control page requires ${name}().`);
  if (typeof queueMicrotaskFn !== "function") throw new TypeError("Broker control page requires queueMicrotask().");

  return function brokersControlV8(this: AtlasBrokerControlViewLayer): string {
    const state = readState();
    const projection = projectAtlasBrokerControlPageV1({
      state, commissionDeals, commissionProfiles, reasons: brokerReasonsV9(state), brlToNumber,
    });
    const { period, periodLabels, reasons, reasonLabels } = projection;
    const ruleEditor = renderAtlasBrokerReasonEditorV1(projection.reasonEditorRows, esc, ico);
    queueMicrotaskFn(() => this.bindCommercialPagesV7?.());
    return `<section class="control-page broker-control-page"><header class="control-page-head"><div><span class="activity-kind">CENTRAL COMERCIAL · CONTROLE TOTAL</span><h1>Corretores e repasses</h1><p>Carteiras, contratos, razões de comissão, competências e arquivos gerados.</p></div><div class="control-head-actions"><button type="button" data-view="commissions">${ico("settings-2")} Regras de repasse</button><button type="button" class="toolbar-primary" data-v8-broker-reports>${ico("file-down")} PDF / Excel</button></div></header><nav class="control-period-tabs" aria-label="Período dos repasses">${Object.entries(periodLabels).map(([id, label]) => `<button type="button" class="${period === id ? "active" : ""}" data-v7-period="${id}">${label}</button>`).join("")}</nav><section class="control-rule-strip"><div><small>RAZÕES ATIVAS</small><b>${reasons.length}</b></div>${reasons.map(item => `<span><b>${esc(reasonLabels[item.id] || item.label)}</b><small>${Number(item.sharePercent || 0).toLocaleString("pt-BR")}% da composição · ${item.warley}/${item.partner}</small></span>`).join("")}<button type="button" data-broker-rule-focus>Editar regras</button></section>${ruleEditor}<div class="broker-control-grid">${projection.profileCards.map(({ profile: person, stats }) => {
      return `<article class="broker-control-card"><header><span class="commission-avatar">${person.initials}</span><span><em>${stats.pending ? "EM ACOMPANHAMENTO" : "REGULAR"}</em><h2>${esc(person.name)}</h2><small>${esc(person.creci)} · ${esc(person.role)}</small></span></header><div class="broker-card-metrics"><span><small>Carteira</small><b>${stats.rows.length}</b></span><span><small>Vendas</small><b>${formatBRL(stats.sales)}</b></span><span><small>Comissão</small><b>${formatBRL(stats.commission)}</b></span><span><small>Pendências</small><b>${stats.pending}</b></span></div><div class="broker-card-lots">${person.lots.map(lot => `<i>${esc(lot)}</i>`).join("")}</div><footer><a href="https://wa.me/${esc(person.phone)}" target="_blank" rel="noopener">${ico("message-circle")} Contato</a><button type="button" data-v7-open-broker="${person.id}">Abrir página dedicada ${ico("arrow-right")}</button></footer></article>`;
    }).join("")}</div><section class="control-ledger"><header><div><span class="activity-kind">TABELAÇÃO COMPLETA · ${periodLabels[period].toUpperCase()}</span><h2>Negócios, comissão e situação de repasse</h2></div><label>Buscar operação<input data-v8-broker-ledger-search placeholder="Contrato, corretor, cliente ou lote"></label></header><div class="control-table-wrap"><table><thead><tr><th>Contrato</th><th>Corretor</th><th>Cliente / lote</th><th>Venda</th><th>Comissão</th><th>Razão</th><th>Situação</th><th></th></tr></thead><tbody>${projection.ledgerRows.map(({ deal, profile: person, reason, searchValue }) => {
      return `<tr data-v8-broker-ledger-row data-search="${esc(searchValue)}"><td><b>${esc(deal.id)}</b><small>${esc(deal.date || "Sem competência")}</small></td><td>${esc(person?.name || "A definir")}</td><td><b>${esc(deal.client)}</b><small>${esc(deal.lot)} · ${esc(deal.quadra || "")}</small></td><td>${esc(deal.value)}</td><td><b>${esc(deal.commission)}</b><small>${esc(deal.rate)}</small></td><td>${esc(reason?.label || "Sinal")}</td><td><span class="control-status">${esc(deal.stage || deal.status)}</span></td><td><button type="button" data-commission-open="${esc(deal.id)}">Abrir</button></td></tr>`;
    }).join("")}</tbody></table></div></section><section class="broker-report-files" data-v8-broker-files><span>ARQUIVOS GERADOS</span><p>Carregando relatórios mensais e acumulados…</p></section></section>`;
  };
}

export class AtlasBrokers extends AtlasHTMLElementBase {
  private readonly state: AtomicState<BrokersState>;
  private snapshot: BrokersState;
  constructor() {
    super();
    const initial: BrokersState = {
      data: null,
      reports: [],
      profileRecords: [],
      commissionReport: null,
      profileAttachments: [],
      query: "",
      selectedBroker: "",
      editingProfile: false,
      savingProfile: false,
      status: "loading",
      error: null,
      message: null,
    };
    function* state(
      value: BrokersState,
    ): Generator<BrokersState, never, BrokersSetter> {
      while (true) value = (yield value)(value);
    }
    this.snapshot = initial;
    const iterator = state(initial);
    iterator.next();
    this.state = { next: setter => { this.snapshot = iterator.next(setter).value; this.render(); return this.snapshot; } };
  }
  private escape(value: unknown): string {
    return String(value ?? "").replace(
      /[&<>"']/g,
      (char) =>
        ({
          "&": "&amp;",
          "<": "&lt;",
          ">": "&gt;",
          '"': "&quot;",
          "'": "&#39;",
        })[char] || char,
    );
  }
  private money(value: number): string {
    return new Intl.NumberFormat("pt-BR", {
      style: "currency",
      currency: "BRL",
    }).format((Number(value) || 0) / 100);
  }
  setData(data: RepasseOperations, reports: RepasseReport[], profileRecords: BrokerProfile[]): void {
    this.state.next((previous) => ({
      ...previous,
      data,
      reports,
      profileRecords,
      status: "ready",
      error: null,
      savingProfile: false,
      editingProfile: false,
      selectedBroker:
        previous.selectedBroker || this.dataset.selectedBroker || "",
    }));
  }
  setLoading(): void {
    this.state.next((previous) => ({
      ...previous,
      status: "loading",
      error: null,
    }));
  }
  setError(message: string): void {
    this.state.next((previous) => ({
      ...previous,
      status: "error",
      error: message,
    }));
  }
  setMessage(message: string | null): void {
    this.state.next((previous) => ({ ...previous, message }));
  }
  setCommissionSnapshot(
    state: AtlasBrokerCommissionReportStateV1,
    attachmentsByProfile: Record<string, AtlasBrokerProfileAttachmentV1[]>,
  ): void {
    const selected = resolveAtlasBrokerDirectoryProfileV1(this.profiles(), this.snapshot.selectedBroker);
    const report = selected ? projectAtlasBrokerCommissionReportV1(selected.name, state) : null;
    this.state.next(previous => ({
      ...previous,
      commissionReport: report,
      profileAttachments: report ? attachmentsByProfile[report.profile.id] || [] : [],
    }));
  }
  setProfileSaveState(saving: boolean, message: string | null = null): void {
    this.state.next((previous) => ({ ...previous, savingProfile: saving, error: message, message: null }));
  }
  snapshotData(): RepasseOperations | null {
    return this.snapshot.data;
  }
  profiles(): AtlasBrokerDirectoryProfileV1[] {
    return projectAtlasBrokerDirectoryProfilesV1(
      this.snapshot.data,
      this.snapshot.reports,
      this.snapshot.profileRecords,
    );
  }
  private render(): void {
    const state = this.snapshot;
    const projection = projectAtlasBrokerDirectoryPageV1({
      data: state.data,
      reports: state.reports,
      profileRecords: state.profileRecords,
      query: state.query,
      selectedBrokerId: state.selectedBroker,
    });
    const { profiles, selectedProfile: selected, visibleProfiles: visible } = projection;
    if (state.status === "loading" && !state.data) {
      this.innerHTML = `<section class="atlas-brokers-page">${brokerDirectoryStyles}<h1>Perfis de corretores</h1><p>Carregando vendas e repasses persistidos…</p></section>`;
      return;
    }
    if (state.status === "error" && !state.data) {
      this.innerHTML = `<section class="atlas-brokers-page">${brokerDirectoryStyles}<h1>Perfis de corretores</h1><p class="atlas-status" role="alert">${this.escape(state.error || "Não foi possível carregar os perfis.")}</p><button data-brokers-refresh>Atualizar</button></section>`;
      return;
    }
    const status = `${profiles.length} perfis associados a vendas persistidas · cadastros profissionais mantidos no banco operacional.`;
    this.innerHTML = `<section class="atlas-brokers-page">${brokerDirectoryStyles}<header><div><span class="atlas-eyebrow">CADASTRO COMERCIAL · PERFIS</span><h1>${selected ? "Perfil do corretor" : "Perfis de corretores"}</h1><p>${selected ? "Vendas, lotes, recebimentos e documentos associados a este nome nos registros comerciais." : "Perfis derivados dos nomes de corretor registrados nas vendas; dados cadastrais ausentes permanecem explicitamente sem informação."}</p></div><div class="atlas-page-actions">${selected ? "<button data-broker-back>Voltar aos perfis</button>" : ""}<button data-brokers-export${!profiles.length ? " disabled" : ""}>Exportar perfis</button><button data-brokers-refresh>Atualizar</button></div></header><p class="atlas-status" role="status" aria-live="polite">${this.escape(state.message || status)}${state.error ? ` <span role="alert">${this.escape(state.error)}</span>` : ""}</p>${
      selected
        ? this.detail(selected, projection.selectedSales)
        : `<div class="atlas-toolbar"><label>Buscar perfil<input type="search" data-broker-search value="${this.escape(state.query)}" placeholder="Nome do corretor ou lote"></label><span class="atlas-muted">${visible.length} de ${profiles.length} perfis</span></div><div class="atlas-broker-grid">${
            visible
              .map(
                (profile) =>
                  `<article class="atlas-card"><header class="atlas-profile-head"><span class="atlas-avatar" aria-hidden="true">${this.escape(
                    profile.name
                      .split(/\s+/)
                      .map((part) => part[0])
                      .slice(0, 2)
                      .join("")
                      .toUpperCase(),
                  )}</span><div><h2>${this.escape(profile.name)}</h2><p>${this.escape(profile.record?.creci || "CRECI não registrado")}</p></div></header><div class="atlas-profile-metrics"><span>Vendas<b>${profile.sales.length}</b></span><span>Valor registrado<b>${this.money(profile.valueCents)}</b></span><span>Recebido<b>${this.money(profile.receivedCents)}</b></span></div><p class="atlas-muted">Lotes: ${this.escape(profile.lots.join(" · ") || "Não informados")} · ${this.escape(profile.record?.phone || "contato não registrado")}</p><footer><button data-broker-open="${this.escape(profile.id)}">Abrir perfil</button></footer></article>`,
              )
              .join("") ||
            '<p class="atlas-card">Nenhum corretor associado às vendas persistidas.</p>'
          }</div>`
    }</section>`;
  }
  private detail(
    profile: ReturnType<AtlasBrokers["profiles"]>[number],
    selectedSales: ReturnType<typeof projectAtlasBrokerDirectoryPageV1>["selectedSales"],
  ): string {
    const sales = selectedSales
      .map(({ sale, receivedCents }) => {
        const files = sale.files || [];
        return `<tr><td><b>${this.escape(sale.id)}</b><small>${this.escape(sale.createdAt || "Data não informada")}</small></td><td>${this.escape(sale.lot || "Lote não informado")}<small>${this.escape(sale.tablePrice?.quadra || "Quadra não informada")}</small></td><td>${this.escape(sale.client || "Cliente não informado")}</td><td>${this.money(Number(sale.valueCents) || 0)}</td><td>${this.money(receivedCents)}</td><td>${this.escape(sale.status || "Status não informado")}</td><td>${files.map((file) => `<button class="atlas-file" data-broker-file="${this.escape(file.fileUrl)}" data-broker-file-name="${this.escape(file.fileName)}">${this.escape(file.fileName)}</button>`).join("") || "Nenhum"}</td></tr>`;
      })
      .join("");
    return `<section class="atlas-detail"><div class="atlas-card"><header class="atlas-profile-head"><span class="atlas-avatar" aria-hidden="true">${this.escape(
      profile.name
        .split(/\s+/)
        .map((part) => part[0])
        .slice(0, 2)
        .join("")
        .toUpperCase(),
    )}</span><div><span class="atlas-eyebrow">PERFIL COMERCIAL · DADOS PERSISTIDOS</span><h2>${this.escape(profile.name)}</h2><p>${this.escape(profile.record?.creci || "CRECI não registrado")}</p></div></header><div class="atlas-detail-summary"><article><small>Vendas vinculadas</small><b>${profile.sales.length}</b></article><article><small>Valor registrado</small><b>${this.money(profile.valueCents)}</b></article><article><small>Entradas recebidas</small><b>${this.money(profile.receivedCents)}</b></article><article><small>Lotes</small><b>${profile.lots.length}</b></article></div><p>Lotes: ${this.escape(profile.lots.join(" · ") || "Não informados")}</p></div>${this.profileEditor(profile)}${this.commissionReportMarkup()}<section class="atlas-card"><header><div><span class="atlas-eyebrow">CARTEIRA · REGISTROS COMERCIAIS</span><h2>Vendas e documentos</h2></div><span class="atlas-muted">${profile.sales.length} registros persistidos</span></header><div class="atlas-table-wrap"><table><thead><tr><th>Venda / data</th><th>Lote / quadra</th><th>Cliente</th><th>Valor registrado</th><th>Entradas</th><th>Situação</th><th>Documentos</th></tr></thead><tbody>${sales || '<tr><td colspan="7">Nenhuma venda associada.</td></tr>'}</tbody></table></div></section></section>`;
  }
  private commissionMoney(value: number): string {
    return new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(Number(value) || 0);
  }
  private commissionReportMarkup(): string {
    const report = this.snapshot.commissionReport;
    if (!report)
      return `<section class='atlas-card'><header><div><span class='atlas-eyebrow'>COMISSÕES</span><h2>Relatório de comissões</h2></div></header><p class='atlas-muted'>Nenhuma carteira do catálogo comercial corresponde a este corretor.</p></section>`;
    const rows = report.rows.map(row =>
      `<tr><td><b>${this.escape(row.id)}</b><small>${this.escape(row.date || 'Sem data')}</small></td><td>${this.escape(row.lot || 'Lote a definir')}<small>${this.escape(row.client || 'Cliente não informado')}</small></td><td>${this.escape(row.reason.label)}<small>${this.escape(row.reason.payment)}</small></td><td>${this.commissionMoney(row.numberValue)}</td><td>${this.commissionMoney(row.numberCommission)}</td><td>${this.commissionMoney(row.warley)}</td><td>${this.commissionMoney(row.partner)}</td><td>${this.escape(row.status || row.stage || '—')}</td></tr>`
    ).join('');
    const attachments = this.snapshot.profileAttachments.map((item, index) =>
      `<li><a href='${this.escape(item.dataUrl)}' download='${this.escape(item.name)}'>${this.escape(item.name)}</a><button type='button' data-broker-profile-attachment-remove='${index}' aria-label='Remover ${this.escape(item.name)}'>×</button></li>`
    ).join('');
    return `<section class='atlas-card atlas-broker-commission-report'><header><div><span class='atlas-eyebrow'>CARTEIRA · COMISSÕES</span><h2>Negócios e rateio</h2><p>Registros associados a ${this.escape(report.profile.name)} e totalizados por competência.</p></div><div class='atlas-page-actions'><button type='button' data-broker-apply-rules>Aplicar regras</button><button type='button' data-broker-profile-print>Imprimir / PDF</button></div></header>
      <div class='atlas-toolbar atlas-broker-report-period'><fieldset><legend>Competência</legend><label><input type='radio' name='brokerPrintMode' value='monthly' data-broker-print-mode ${report.mode === 'monthly' ? 'checked' : ''}> Mensal</label><label><input type='radio' name='brokerPrintMode' value='annual' data-broker-print-mode ${report.mode === 'annual' ? 'checked' : ''}> Anual</label></fieldset><label>Mês<input type='month' data-broker-print-month value='${this.escape(report.month)}' ${report.mode === 'annual' ? 'disabled' : ''}></label><label>Ano<input type='number' min='2000' max='2100' data-broker-print-year value='${this.escape(report.year)}' ${report.mode === 'monthly' ? 'disabled' : ''}></label><span class='atlas-muted'>${report.rows.length} lançamento(s) · ${this.escape(report.periodLabel)}</span></div>
      <div class='atlas-detail-summary'><article><small>Valor da carteira</small><b>${this.commissionMoney(report.totals.value)}</b></article><article><small>Comissão</small><b>${this.commissionMoney(report.totals.commission)}</b></article><article><small>Warley</small><b>${this.commissionMoney(report.totals.warley)}</b></article><article><small>Contraparte</small><b>${this.commissionMoney(report.totals.partner)}</b></article></div>
      <div class='atlas-table-wrap'><table><thead><tr><th>Contrato / data</th><th>Lote / cliente</th><th>Razão</th><th>Venda</th><th>Comissão</th><th>Warley</th><th>Contraparte</th><th>Situação</th></tr></thead><tbody>${rows || '<tr><td colspan=8>Nenhuma comissão nesta competência.</td></tr>'}</tbody><tfoot><tr><th colspan=3>Total · ${this.escape(report.periodLabel)}</th><th>${this.commissionMoney(report.totals.value)}</th><th>${this.commissionMoney(report.totals.commission)}</th><th>${this.commissionMoney(report.totals.warley)}</th><th>${this.commissionMoney(report.totals.partner)}</th><th>${report.rows.length} negócio(s)</th></tr></tfoot></table></div>
      <div class='atlas-broker-profile-attachments'><header><div><span class='atlas-eyebrow'>ANEXOS DO PERFIL</span><h2>Documentos profissionais</h2></div><span class='atlas-muted'>${this.snapshot.profileAttachments.length} arquivo(s)</span></header><ul>${attachments || '<li class=atlas-muted>Nenhum anexo de perfil.</li>'}</ul><label>Adicionar PDF ou imagem<input type='file' data-broker-profile-attachment multiple accept='application/pdf,image/jpeg,image/png,image/webp'></label><small class='atlas-muted'>Limite total de 2 MB · PDF, JPG, PNG ou WebP.</small></div></section>`;
  }

  private profileEditor(profile: ReturnType<AtlasBrokers["profiles"]>[number]): string {
    const record=profile.record, state=this.snapshot;
    if(!state.editingProfile)return `<section class="atlas-card"><header><div><span class="atlas-eyebrow">CADASTRO PROFISSIONAL</span><h2>Contato e identificação</h2></div><button type="button" data-broker-profile-edit>Editar cadastro</button></header><div class="atlas-detail-summary"><article><small>CRECI</small><b>${this.escape(record?.creci||"Não registrado")}</b></article><article><small>Telefone</small><b>${this.escape(record?.phone||"Não registrado")}</b></article><article><small>E-mail</small><b>${this.escape(record?.email||"Não registrado")}</b></article><article><small>Atualizado</small><b>${this.escape(record?.updatedAt||"Sem cadastro")}</b></article></div>${record?.notes?`<p>${this.escape(record.notes)}</p>`:""}${record?'<footer><button type="button" data-broker-profile-delete>Excluir cadastro profissional</button></footer>':""}</section>`;
    return `<form class="atlas-card" data-broker-profile-form><header><div><span class="atlas-eyebrow">CADASTRO PROFISSIONAL</span><h2>${record?"Editar cadastro":"Cadastrar contato profissional"}</h2></div></header><div class="atlas-profile-metrics"><label>CRECI<input name="creci" maxlength="80" value="${this.escape(record?.creci||"")}"></label><label>Telefone<input name="phone" maxlength="40" autocomplete="tel" value="${this.escape(record?.phone||"")}"></label><label>E-mail<input name="email" type="email" maxlength="254" autocomplete="email" value="${this.escape(record?.email||"")}"></label></div><label>Observações<textarea name="notes" maxlength="4000">${this.escape(record?.notes||"")}</textarea></label><footer><button type="button" data-broker-profile-cancel>Cancelar</button><button class="atlas-primary" type="submit"${state.savingProfile?" disabled":""}>${state.savingProfile?"Salvando…":"Salvar cadastro"}</button></footer>${state.error?`<p role="alert">${this.escape(state.error)}</p>`:""}</form>`;
  }
  connectedCallback(): void {
    this.addEventListener("input", (event) => {
      const target = event.target;
      if (
        target instanceof HTMLInputElement &&
        target.matches("[data-broker-search]")
      ) {
        const cursor = target.selectionStart;
        this.state.next((previous) => ({ ...previous, query: target.value }));
        const replacement = this.querySelector<HTMLInputElement>(
          "[data-broker-search]",
        );
        replacement?.focus();
        if (cursor !== null) replacement?.setSelectionRange(cursor, cursor);
      }
    });
    this.addEventListener("click", (event) => {
      const target = event.target;
      if (!(target instanceof Element)) return;
      if (target.closest('[data-broker-profile-print]')) {
        this.dispatchEvent(new CustomEvent<AtlasBrokerProfilePrintCommandV1>('atlas:broker-profile-print', { bubbles: true, detail: { element: this } }));
        return;
      }
      if (target.closest('[data-broker-apply-rules]')) {
        this.dispatchEvent(new CustomEvent<AtlasBrokerApplyRulesCommandV1>('atlas:broker-apply-rules', { bubbles: true, detail: { element: this } }));
        return;
      }
      const attachmentRemove = target.closest<HTMLElement>('[data-broker-profile-attachment-remove]');
      if (attachmentRemove) {
        this.dispatchEvent(new CustomEvent<AtlasBrokerProfileAttachmentRemoveCommandV1>('atlas:broker-profile-attachment-remove', { bubbles: true, detail: { element: this, profileId: this.snapshot.commissionReport?.profile.id || '', index: Number(attachmentRemove.dataset.brokerProfileAttachmentRemove) } }));
        return;
      }
      if (target.closest("[data-brokers-refresh]")) {
        this.dispatchEvent(
          new CustomEvent<AtlasBrokerExportCommandV1>("atlas:brokers-refresh", {
            bubbles: true,
            detail: { element: this },
          }),
        );
        return;
      }
      const open = target.closest<HTMLElement>("[data-broker-open]");
      if (open) {
        this.dispatchEvent(
          new CustomEvent<AtlasBrokerNavigationCommandV1>("atlas:navigate", {
            bubbles: true,
            detail: { view: "broker-detail", id: open.dataset.brokerOpen },
          }),
        );
        return;
      }
      if (target.closest("[data-broker-back]")) {
        this.dispatchEvent(
          new CustomEvent<AtlasBrokerNavigationCommandV1>("atlas:navigate", {
            bubbles: true,
            detail: { view: "brokers" },
          }),
        );
        return;
      }
      if (target.closest("[data-brokers-export]")) {
        this.dispatchEvent(
          new CustomEvent<AtlasBrokerExportCommandV1>("atlas:brokers-export", {
            bubbles: true,
            detail: { element: this },
          }),
        );
        return;
      }
      if (target.closest("[data-broker-profile-edit]")) {
        this.state.next(previous=>({...previous,editingProfile:true,error:null}));
        return;
      }
      if (target.closest("[data-broker-profile-cancel]")) {
        this.state.next(previous=>({...previous,editingProfile:false,error:null}));
        return;
      }
      if (target.closest("[data-broker-profile-delete]")) {
        const selected=resolveAtlasBrokerDirectoryProfileV1(this.profiles(),this.snapshot.selectedBroker);
        if(selected&&window.confirm(`Excluir o cadastro profissional de ${selected.name}? As vendas não serão alteradas.`))
          this.dispatchEvent(new CustomEvent<AtlasBrokerProfileDeleteCommandV1>("atlas:broker-profile-delete",{bubbles:true,detail:{element:this,name:selected.name}}));
        return;
      }
      const file = target.closest<HTMLElement>("[data-broker-file]");
      if (file)
        this.dispatchEvent(
          new CustomEvent<AtlasBrokerFileOpenCommandV1>("atlas:brokers-file", {
            bubbles: true,
            detail: {
              element: this,
              fileUrl: file.dataset.brokerFile,
              fileName: file.dataset.brokerFileName,
            },
          }),
        );
    });
    this.addEventListener('change', event => {
      const target = event.target;
      if (!(target instanceof HTMLInputElement)) return;
      if (target.matches('[data-broker-print-mode]')) {
        this.dispatchEvent(new CustomEvent<AtlasBrokerPrintPeriodChangeCommandV1>('atlas:broker-print-period-change', { bubbles: true, detail: { element: this, brokerPrintMode: target.value } }));
        return;
      }
      if (target.matches('[data-broker-print-month]')) {
        this.dispatchEvent(new CustomEvent<AtlasBrokerPrintPeriodChangeCommandV1>('atlas:broker-print-period-change', { bubbles: true, detail: { element: this, brokerPrintMonth: target.value } }));
        return;
      }
      if (target.matches('[data-broker-print-year]')) {
        this.dispatchEvent(new CustomEvent<AtlasBrokerPrintPeriodChangeCommandV1>('atlas:broker-print-period-change', { bubbles: true, detail: { element: this, brokerPrintYear: target.value } }));
        return;
      }
      if (target.matches('[data-broker-profile-attachment]')) {
        this.dispatchEvent(new CustomEvent<AtlasBrokerProfileAttachmentsAddCommandV1>('atlas:broker-profile-attachments-add', { bubbles: true, detail: { element: this, profileId: this.snapshot.commissionReport?.profile.id || '', files: Array.from(target.files || []) } }));
        target.value = '';
      }
    });
    this.addEventListener("submit",event=>{
      const form=event.target;
      if(!(form instanceof HTMLFormElement)||!form.matches("[data-broker-profile-form]"))return;
      event.preventDefault();
      const data=new FormData(form);
      const draft=createAtlasBrokerProfileSaveDraftV1({
        profiles:this.profiles(),
        selectedBrokerId:this.snapshot.selectedBroker,
        saving:this.snapshot.savingProfile,
        fields:{creci:data.get("creci"),phone:data.get("phone"),email:data.get("email"),notes:data.get("notes")},
      });
      if(!draft)return;
      this.setProfileSaveState(true);
      this.dispatchEvent(new CustomEvent<AtlasBrokerProfileSaveCommandV1>("atlas:broker-profile-save",{bubbles:true,detail:{element:this,...draft}}));
    });
    this.render();
    this.dispatchEvent(
      new CustomEvent("atlas:brokers-connected", {
        bubbles: true,
        detail: { element: this },
      }),
    );
  }
}
if (!customElements.get("atlas-brokers"))
  customElements.define("atlas-brokers", AtlasBrokers);

