/** Complete, typed lot catalog and commercial control workflow for the active sidebar route. */
export class AtlasLotBoard extends AtlasHTMLElementBase {
  private snapshot: AtlasLotBoardState;
  private readonly state: AtomicState<AtlasLotBoardState>;
  private onClick = (event: Event): void => { this.handleClick(event); };
  private onInput = (event: Event): void => { this.handleInput(event); };
  private onChange = (event: Event): void => { this.handleChange(event); };
  private onSubmit = (event: Event): void => { this.handleSubmit(event); };
  private onKeydown = (event: Event): void => { this.handleKeydown(event as KeyboardEvent); };
  private onMapMarkerSelected = (event: Event): void => {
    const detail = (event as CustomEvent<{ lotId?: string; label?: string }>).detail;
    if (!detail) return;
    const lotId = String(detail.lotId || detail.label || "");
    event.stopPropagation();
    this.emit("atlas:lot-board-map-marker", { lotId, label: String(detail.label || lotId) });
  };
  constructor() {
    super();
    const initial: AtlasLotBoardState = { rows: [], balanceLoadState: "loading", balanceError: "", sellers: [], search: "", quadra: "", status: "", payment: "", seller: "", selectedKey: "", activeLotKey: "", draftStatus: "Disponível", draftSellerId: "", draftNote: "", modalOpen: false, flowPage: 0, pickerQuadra: "", pickerPage: 0, markerLotNumber: 0, mapOpen: false, message: "Carregando catálogo de lotes…" };
    function* state(value: AtlasLotBoardState): Generator<AtlasLotBoardState, never, AtlasLotBoardSetter> { while (true) value = (yield value)(value); }
    const iterator = state(initial); iterator.next(); this.snapshot = initial;
    this.state = { next: setter => { this.snapshot = iterator.next(setter).value; this.render(); return this.snapshot; } };
  }
  private esc(value: unknown): string { return String(value ?? "").replace(/[&<>"']/g, char => ({ "&":"&amp;", "<":"&lt;", ">":"&gt;", '"':"&quot;", "'":"&#39;" }[char] || char)); }
  private money(value: number): string { return new Intl.NumberFormat("pt-BR", { style: "currency", currency: "BRL" }).format(Number(value) || 0); }
  private area(value: number): string { return `${new Intl.NumberFormat("pt-BR", { maximumFractionDigits: 2 }).format(Number(value) || 0)} m²`; }
  private emit(name: string, detail: Record<string, unknown> = {}): void { this.dispatchEvent(new CustomEvent(name, { bubbles: true, detail: { element: this, ...detail } })); }
  setData(rows: AtlasLotBoardRow[], sellers: AtlasLotBoardSeller[], balanceLoadState: AtlasLotBoardState['balanceLoadState'] = 'ready', balanceError = ''): void { this.state.next(previous => ({ ...previous, rows, sellers, balanceLoadState, balanceError, message: balanceLoadState === 'error' ? `Saldos indisponíveis: ${balanceError}` : balanceLoadState === 'loading' ? `${rows.length} lotes no catálogo · carregando entradas vinculadas às vendas…` : `${rows.length} lotes no catálogo · preços e entradas persistidos carregados.` })); }
  setMessage(message: string): void { this.state.next(previous => ({ ...previous, message })); }
  openControl(lotKey: string, flowPage: 0 | 1 | 2 = 1, markerLotNumber = 0): void {
    const row = this.pageProjection({ ...this.snapshot, activeLotKey: lotKey }).activeRow;
    this.state.next(previous => ({ ...previous, selectedKey: lotKey || previous.selectedKey, activeLotKey: row?.label || "", draftStatus: (row?.status as AtlasLotCommercialStatus) || "Disponível", draftSellerId: row?.sellerId || "", draftNote: row?.note || "", markerLotNumber, pickerQuadra: "", pickerPage: 0, flowPage, modalOpen: true }));
    if (flowPage === 0) this.querySelector<HTMLSelectElement>("[data-lot-picker-quadra]")?.focus();
    else this.querySelector<HTMLSelectElement>("[name=lotBoardStatus]")?.focus();
  }
  openPickerForMarker(rawLotId: string): void {
    const matched = rawLotId.match(/\d+/g);
    const number = Number(matched?.at(-1) || 0);
    if (!number) return;
    const matches = this.pageProjection({ ...this.snapshot, markerLotNumber: number }).markerMatches;
    if (matches.length === 1) { this.openControl(matches[0].label, 1); return; }
    this.state.next(previous => ({ ...previous, activeLotKey: "", markerLotNumber: number, pickerQuadra: "", pickerPage: 0, modalOpen: true, flowPage: 0, message: `Marcador Lote ${String(number).padStart(3, "0")} · selecione a quadra.` }));
    this.querySelector<HTMLSelectElement>("[data-lot-picker-quadra]")?.focus();
  }
  closeControl(): void { this.state.next(previous => ({ ...previous, modalOpen: false, markerLotNumber: 0 })); }
  private pageProjection(state: AtlasLotBoardState = this.snapshot): AtlasLotBoardPageProjectionV1 {
    return projectAtlasLotBoardPageV1({
      rows: state.rows,
      search: state.search,
      quadra: state.quadra,
      status: state.status,
      payment: state.payment,
      seller: state.seller,
      selectedKey: state.selectedKey,
      activeLotKey: state.activeLotKey,
      pickerQuadra: state.pickerQuadra,
      pickerPage: state.pickerPage,
      markerLotNumber: state.markerLotNumber,
    });
  }
  private renderRows(projection = this.pageProjection()): string {
    const rows = projection.filteredRows;
    const financialLabel = (row: AtlasLotBoardRow) => this.snapshot.balanceLoadState === 'loading' ? 'Carregando…' : this.snapshot.balanceLoadState === 'error' ? 'Indisponível' : row.balanceStatus;
    const financialAmount = (cents: number | null, hasSale: boolean) => this.snapshot.balanceLoadState === 'loading' ? 'Carregando…' : this.snapshot.balanceLoadState === 'error' ? 'Indisponível' : hasSale && cents !== null ? this.money(cents / 100) : '—';
    return `<div class="atlas-lot-table-wrap"><table><thead><tr><th>Lote</th><th>Quadra</th><th>Área</th><th>Preço de tabela</th><th>Preço contratado</th><th>Entradas recebidas</th><th>Saldo restante</th><th>Situação do saldo</th><th>Status</th><th>Pagamento</th><th>Ações</th></tr></thead><tbody>${rows.map(row => { const hasSale = row.contractPriceCents !== null; return `<tr class="${row.label === this.snapshot.selectedKey ? "is-selected" : ""}" data-lot-row="${this.esc(row.label)}"><td><b>${this.esc(row.lot)}</b></td><td>${this.esc(row.quadra)}</td><td>${this.area(row.area)}</td><td><b>${this.money(row.price)}</b></td><td>${financialAmount(row.contractPriceCents, hasSale)}</td><td>${financialAmount(hasSale ? row.receivedCents : null, hasSale)}</td><td>${financialAmount(row.remainingCents, hasSale)}</td><td><span class="lot-payment-pill">${this.esc(financialLabel(row))}</span></td><td><span class="lot-status-pill">${this.esc(row.status)}</span></td><td><span class="lot-payment-pill">${this.esc(row.paymentStatus)}</span></td><td><button type="button" data-lot-detail-open="${this.esc(row.label)}">Abrir ficha</button> <button type="button" data-lot-select="${this.esc(row.label)}">Abrir controle</button></td></tr>`; }).join("") || `<tr><td colspan="11" class="atlas-lot-empty">Nenhum lote corresponde aos filtros.</td></tr>`}</tbody></table></div><footer class="atlas-lot-feedback" data-lot-count>${rows.length} de ${this.snapshot.rows.length} lotes · saldo = preço contratado − entradas vinculadas à venda; lote sem venda não tem saldo calculado.</footer>`;
  }
  private renderPicker(): string {
    const state = this.snapshot;
    const projection = this.pageProjection(), matches = projection.pickerMatches;
    const pages = projection.pickerPages, page = projection.pickerPage, items = projection.pickerRows;
    return `<section data-lot-flow-panel="0" ${state.flowPage === 0 ? "" : "hidden"}><header><div><span class="atlas-eyebrow">01 · SELECIONAR LOTE</span><b>Fluxo de controle</b></div><small>${state.activeLotKey ? `Selecionado: ${this.esc(state.activeLotKey)}` : "Nenhum lote selecionado"}</small></header><div class="atlas-lot-form-grid"><label>Quadra<select data-lot-picker-quadra><option value="">Todas</option>${projection.quadrants.map(name => `<option value="${this.esc(name)}" ${name === state.pickerQuadra ? "selected" : ""}>${this.esc(name)}</option>`).join("")}</select></label><label class="wide">Lotes da página<div class="atlas-lot-picker-list" role="listbox">${items.map(row => `<button type="button" class="atlas-lot-picker-option" role="option" aria-selected="${row.label === state.activeLotKey}" data-lot-picker-option="${this.esc(row.label)}"><span><b>${this.esc(row.label)}</b><small>${this.esc(row.quadra)} · ${this.area(row.area)} · ${this.money(row.price)}</small></span><strong>Selecionar</strong></button>`).join("") || `<p class="atlas-lot-empty">Nenhum lote encontrado para este filtro.</p>`}</div></label></div><footer><button type="button" data-lot-page-prev ${page === 0 ? "disabled" : ""}>← Anterior</button><span>${matches.length} lote(s) · página ${page + 1} de ${pages}</span><button type="button" data-lot-page-next ${page >= pages - 1 ? "disabled" : ""}>Próxima →</button></footer></section>`;
  }
  private renderModal(): string {
    const state = this.snapshot, active = this.pageProjection().activeRow;
    return `<div class="atlas-lot-modal" ${state.modalOpen ? "" : "hidden"}><div class="atlas-lot-modal-backdrop" data-lot-modal-close></div><section class="atlas-lot-modal-dialog" role="dialog" aria-modal="true" aria-labelledby="atlas-lot-modal-title"><header><div><span class="atlas-eyebrow">CONTROLE DO LOTE</span><h2 id="atlas-lot-modal-title">Controle comercial</h2><p>${active ? `${this.esc(active.label)} · ${this.money(active.price)}` : state.markerLotNumber ? `Marcador Lote ${String(state.markerLotNumber).padStart(3, "0")} · selecione a quadra` : "Selecione um lote"}</p></div><button type="button" data-lot-modal-close aria-label="Fechar">×</button></header><nav class="atlas-lot-flow" aria-label="Etapas do controle">${["1. Lote", "2. Comercial", "3. Entrada"].map((label, index) => `<button type="button" data-lot-flow-step="${index}" aria-current="${state.flowPage === index ? "step" : "false"}" ${index > 0 && !active ? "disabled" : ""}>${label}</button>`).join("")}</nav><form data-lot-status-form><input type="hidden" name="lotKey" value="${this.esc(state.activeLotKey)}">${this.renderPicker()}<section data-lot-flow-panel="1" ${state.flowPage === 1 ? "" : "hidden"}><span class="atlas-eyebrow">02 · COMERCIAL</span><div class="atlas-lot-form-grid"><label>Status do lote<select name="lotBoardStatus">${atlasLotStatuses.map(status => `<option ${status === state.draftStatus ? "selected" : ""}>${status}</option>`).join("")}</select></label><label>Vendedor<select name="lotBoardSeller"><option value="">Selecionar vendedor</option>${state.sellers.map(seller => `<option value="${this.esc(seller.id)}" ${seller.id === state.draftSellerId ? "selected" : ""}>${this.esc(seller.name)}</option>`).join("")}</select></label><label class="wide">Observação<textarea name="lotBoardNote" rows="3" placeholder="Observação sobre o controle comercial do lote">${this.esc(state.draftNote)}</textarea></label></div></section><section data-lot-flow-panel="2" ${state.flowPage === 2 ? "" : "hidden"}><span class="atlas-eyebrow">03 · ENTRADAS E REPASSES</span><p>Valores recebidos, plano de pagamento, juros e comissões são mantidos no fluxo financeiro do lote.</p><button type="button" class="atlas-primary" data-lot-open-repasses>◫ Abrir Repasses para este lote</button></section><footer><button type="button" data-lot-flow-back ${state.flowPage === 0 ? "hidden" : ""}>Voltar</button><button type="button" data-lot-flow-next ${state.flowPage >= 2 ? "hidden" : ""} ${!active ? "disabled" : ""}>Avançar</button><button type="submit" class="atlas-primary" ${state.flowPage !== 2 ? "hidden" : ""}>Salvar controle comercial</button></footer></form></section></div>`;
  }
  private render(): void {
    const state = this.snapshot, projection = this.pageProjection(), rows = projection.filteredRows;
    const totalValue = projection.totalValue, controlled = projection.controlledCount;
    const selected = projection.selectedRow, quadrants = projection.quadrants;
    this.innerHTML = `<section class="atlas-lot-board">${atlasLotBoardStyles}${atlasLotBoardResponsiveStylesV1}<header class="atlas-lot-head"><div><span class="atlas-eyebrow">LOTES · TABELA E CONTROLE</span><h1>Lotes</h1><p>Consulte valores, situação comercial, pagamentos e encaminhamento para Repasses.</p></div><div class="atlas-lot-head-actions"><button type="button" data-lot-print>Imprimir tabela</button><button type="button" data-lot-export ${rows.length ? "" : "disabled"}>Exportar Excel</button></div></header><div class="atlas-lot-kpis"><div class="atlas-lot-kpi"><span>LOTES NO CATÁLOGO</span><b>${state.rows.length}</b><small>Unidades de preço importadas</small></div><div class="atlas-lot-kpi"><span>VALOR DE TABELA</span><b>${this.money(totalValue)}</b><small>Base catalogada</small></div><div class="atlas-lot-kpi"><span>CONTROLES COMERCIAIS</span><b>${controlled}</b><small>Lotes com status, vendedor ou observação</small></div><div class="atlas-lot-kpi"><span>RESULTADOS</span><b data-lot-visible-count>${rows.length}</b><small>Correspondem aos filtros atuais</small></div></div><section class="lot-price-catalog-card" data-lot-price-catalog><div class="lot-catalog-print-header"><div class="lot-catalog-print-brand"><img src="./assets/public/alianca-park-logo-full-letter-cutouts-v555.png" alt="Aliança Park Loteamento"></div><div class="lot-catalog-print-heading"><span>RELATÓRIO OPERACIONAL · LOTES</span><h1>Valores por lote</h1><p>Tabela de referência para acompanhamento comercial.</p><span>Emitido em ${new Date().toLocaleString("pt-BR")}</span></div></div><header class="atlas-lot-card-head"><div><span class="atlas-eyebrow">01 · TABELA DE LOTES</span><h2>Valores por lote</h2><p>Referências importadas da tabela de preços do empreendimento.</p></div><div class="atlas-lot-crud"><button type="button" class="atlas-primary" data-lot-control-new>Novo controle</button><button type="button" data-lot-control-edit ${selected ? "" : "disabled"}>Editar selecionado</button><button type="button" class="atlas-danger" data-lot-control-delete ${selected && selected.hasControl ? "" : "disabled"}>Excluir controle</button></div></header><details class="lot-catalog-map-drawer" data-lot-map-drawer ${state.mapOpen ? "open" : ""}><summary><span>⌖ Mapa de lotes</span><small>Abra e clique em um marcador para iniciar o controle</small></summary><div class="lot-catalog-map-window"><map-scene compact interactive data-public-static-only="true" data-admin-public-map data-lot-catalog-map data-stage="Controle comercial" data-overlay="urbanizacao" aria-label="Mapa retrátil dos lotes para controle comercial"></map-scene></div></details><div class="atlas-lot-tools"><div class="atlas-lot-filter-head"><div><strong>Filtrar lotes</strong><small>Combine busca, quadra e situação comercial.</small></div><span data-lot-filter-summary>${rows.length} de ${state.rows.length} lotes</span></div><div class="atlas-lot-tool-row"><label class="atlas-lot-search">Buscar lote ou quadra<input type="search" data-lot-search placeholder="Ex.: QA 12" value="${this.esc(state.search)}"></label><label>Quadra<select data-lot-filter="quadra"><option value="">Todas</option>${quadrants.map(name => `<option value="${this.esc(name)}" ${name === state.quadra ? "selected" : ""}>${this.esc(name)}</option>`).join("")}</select></label><label>Status<select data-lot-filter="status"><option value="">Todos</option>${atlasLotStatuses.map(status => `<option ${status === state.status ? "selected" : ""}>${status}</option>`).join("")}</select></label><label>Pagamento<select data-lot-filter="payment"><option value="">Todos</option>${atlasLotPayments.map(status => `<option ${status === state.payment ? "selected" : ""}>${status}</option>`).join("")}</select></label><label>Vendedor<select data-lot-filter="seller"><option value="">Todos</option>${projection.sellerNames.map(name => `<option ${name === state.seller ? "selected" : ""}>${this.esc(name)}</option>`).join("")}</select></label><button type="button" data-lot-filter-clear>Limpar filtros</button></div></div><div data-lot-table class="atlas-lot-table-region">${this.renderRows(projection)}</div><footer class="lot-catalog-print-footer"><span>Aliança Park · Lotes</span><span>Documento de apoio operacional · tabela de repasse</span></footer></section><p class="atlas-lot-note" role="status" aria-live="polite">${this.esc(state.message)}</p>${this.renderModal()}</section>`;
    const drawer = this.querySelector<HTMLDetailsElement>("[data-lot-map-drawer]");
    drawer?.addEventListener("toggle", () => { this.snapshot.mapOpen = drawer.open; if (drawer.open) this.initializeMap(); });
    if (drawer?.open) this.initializeMap();
  }
  private initializeMap(): void {
    const drawer = this.querySelector<HTMLDetailsElement>("[data-lot-map-drawer]");
    const map = drawer?.querySelector<HTMLElement & { bindStaticSatelliteMapGesturesV1?: () => void; installAdminMasterplanOverlayV1?: () => void; installSatelliteLotPlanOverlayV1?: (options: { markers: boolean; outlines: boolean }) => Promise<void>; fitStaticSatelliteMasterplanV1?: () => void }>("[data-lot-catalog-map]");
    requestAnimationFrame(() => {
      map?.bindStaticSatelliteMapGesturesV1?.(); map?.installAdminMasterplanOverlayV1?.();
      void map?.installSatelliteLotPlanOverlayV1?.({ markers: true, outlines: false }).then(() => requestAnimationFrame(() => requestAnimationFrame(() => map?.fitStaticSatelliteMasterplanV1?.())));
    });
  }
  private updateRowsOnly(): void {
    const projection = this.pageProjection();
    const target = this.querySelector<HTMLElement>("[data-lot-table]");
    if (target) target.innerHTML = this.renderRows(projection);
    const count = this.querySelector<HTMLElement>("[data-lot-visible-count]");
    if (count) count.textContent = String(projection.filteredRows.length);
    const exportButton = this.querySelector<HTMLButtonElement>("[data-lot-export]");
    if (exportButton) exportButton.disabled = !projection.filteredRows.length;
    const summary = this.querySelector<HTMLElement>("[data-lot-filter-summary]");
    if (summary) summary.textContent = `${projection.filteredRows.length} de ${this.snapshot.rows.length} lotes`;
    const footer = this.querySelector<HTMLElement>("[data-lot-count]");
    if (footer) footer.textContent = `${projection.filteredRows.length} de ${this.snapshot.rows.length} lotes · selecione uma linha para abrir a ficha completa.`;
  }
  private handleInput(event: Event): void {
    const target = event.target;
    if (!(target instanceof HTMLInputElement) || !target.matches("[data-lot-search]")) return;
    this.snapshot.search = target.value; this.updateRowsOnly();
  }
  private handleChange(event: Event): void {
    const target = event.target;
    if (!(target instanceof HTMLSelectElement)) return;
    if (target.matches("[data-lot-filter]")) {
      const key = target.dataset.lotFilter;
      if (key === "quadra") this.snapshot.quadra = target.value;
      if (key === "status") this.snapshot.status = isAtlasLotCommercialStatus(target.value) ? target.value : "";
      if (key === "payment") this.snapshot.payment = isAtlasLotPaymentStatus(target.value) ? target.value : "";
      if (key === "seller") this.snapshot.seller = target.value;
      this.updateRowsOnly();
    }
    if (target.matches("[data-lot-picker-quadra]")) this.state.next(previous => ({ ...previous, pickerQuadra: target.value, pickerPage: 0 }));
    if (target.matches("[name=lotBoardStatus]")) this.snapshot.draftStatus = target.value as AtlasLotCommercialStatus;
    if (target.matches("[name=lotBoardSeller]")) this.snapshot.draftSellerId = target.value;
  }
  private handleClick(event: Event): void {
    const origin = event.target;
    if (!(origin instanceof Element)) return;
    const close = origin.closest("[data-lot-modal-close]");
    if (close) { this.closeControl(); return; }
    const openDetail = origin.closest<HTMLElement>("[data-lot-detail-open]");
    if (openDetail) { event.stopPropagation(); const lotKey = String(openDetail.dataset.lotDetailOpen || ""); if (lotKey) this.emit("atlas:lot-board-navigate", { view: "lot-detail", lotKey }); return; }
    const selectLot = origin.closest<HTMLElement>("[data-lot-select]");
    if (selectLot) { event.stopPropagation(); this.openControl(String(selectLot.dataset.lotSelect || ""), 1); return; }
    const pickerOption = origin.closest<HTMLElement>("[data-lot-picker-option]");
    if (pickerOption) { this.openControl(String(pickerOption.dataset.lotPickerOption || ""), 1); return; }
    const row = origin.closest<HTMLElement>("[data-lot-row]");
    if (row && !origin.closest("button")) { this.snapshot.selectedKey = String(row.dataset.lotRow || ""); this.emit("atlas:lot-board-navigate", { view: "lot-detail", lotKey: this.snapshot.selectedKey }); return; }
    if (origin.closest("[data-lot-control-new]")) { const visible = this.pageProjection().filteredRows, first = visible[0], selected = visible.find(item => item.label === this.snapshot.selectedKey); this.openControl(selected?.label || first?.label || "", 0); return; }
    if (origin.closest("[data-lot-control-edit]")) { if (this.snapshot.selectedKey) this.openControl(this.snapshot.selectedKey, 1); return; }
    if (origin.closest("[data-lot-control-delete]")) { if (this.snapshot.selectedKey) this.emit("atlas:lot-board-delete", { lotKey: this.snapshot.selectedKey }); return; }
    if (origin.closest("[data-lot-modal-close]")) { this.closeControl(); return; }
    const step = origin.closest<HTMLElement>("[data-lot-flow-step]");
    if (step && this.snapshot.activeLotKey) { const next = Number(step.dataset.lotFlowStep); if (next >= 0 && next <= 2) this.state.next(previous => ({ ...previous, flowPage: next as 0 | 1 | 2 })); return; }
    if (origin.closest("[data-lot-flow-back]")) { this.state.next(previous => ({ ...previous, flowPage: Math.max(0, previous.flowPage - 1) as 0 | 1 | 2 })); return; }
    if (origin.closest("[data-lot-flow-next]")) { this.state.next(previous => ({ ...previous, flowPage: Math.min(2, previous.flowPage + 1) as 0 | 1 | 2 })); return; }
    if (origin.closest("[data-lot-page-prev]")) { this.state.next(previous => ({ ...previous, pickerPage: Math.max(0, previous.pickerPage - 1) })); return; }
    if (origin.closest("[data-lot-page-next]")) { this.state.next(previous => ({ ...previous, pickerPage: previous.pickerPage + 1 })); return; }
    if (origin.closest("[data-lot-filter-clear]")) { this.state.next(previous => ({ ...previous, search: "", quadra: "", status: "", payment: "", seller: "" })); return; }
    if (origin.closest("[data-lot-open-repasses]")) { this.emit("atlas:lot-board-navigate", { view: "repasses", lotKey: this.snapshot.activeLotKey }); this.closeControl(); return; }
    if (origin.closest("[data-lot-export]")) { this.emit("atlas:lot-board-export", { lotKeys: this.pageProjection().filteredRows.map(item => item.label) }); return; }
    if (origin.closest("[data-lot-print]")) { this.emit("atlas:lot-board-print"); return; }
  }
  private handleSubmit(event: Event): void {
    const form = event.target;
    if (!(form instanceof HTMLFormElement) || !form.matches("[data-lot-status-form]")) return;
    event.preventDefault();
    if (!this.snapshot.activeLotKey || this.snapshot.flowPage !== 2) return;
    const data = new FormData(form);
    this.snapshot.draftStatus = String(data.get("lotBoardStatus") || "Disponível") as AtlasLotCommercialStatus;
    this.snapshot.draftSellerId = String(data.get("lotBoardSeller") || "");
    this.snapshot.draftNote = String(data.get("lotBoardNote") || "");
    this.emit("atlas:lot-board-status-save", { lotKey: this.snapshot.activeLotKey, status: this.snapshot.draftStatus, sellerId: this.snapshot.draftSellerId, note: this.snapshot.draftNote });
  }
  private handleKeydown(event: KeyboardEvent): void { if (event.key === "Escape" && this.snapshot.modalOpen) { event.preventDefault(); this.closeControl(); } }
  connectedCallback(): void {
    this.addEventListener("click", this.onClick); this.addEventListener("input", this.onInput); this.addEventListener("change", this.onChange); this.addEventListener("submit", this.onSubmit); this.addEventListener("keydown", this.onKeydown); this.addEventListener("belavista:lot-marker-selected", this.onMapMarkerSelected);
    this.render(); this.emit("atlas:lot-board-connected");
  }
  disconnectedCallback(): void { this.removeEventListener("click", this.onClick); this.removeEventListener("input", this.onInput); this.removeEventListener("change", this.onChange); this.removeEventListener("submit", this.onSubmit); this.removeEventListener("keydown", this.onKeydown); this.removeEventListener("belavista:lot-marker-selected", this.onMapMarkerSelected); }
}
if (!customElements.get("atlas-lot-board")) customElements.define("atlas-lot-board", AtlasLotBoard);

export interface AtlasLotBoardComponentControllerInputV1 {
  ViewLayer: { prototype: HTMLElement & Record<string, unknown> };
  readStatuses(): Record<string, AtlasLotStatus | undefined>;
  loadBalances(): Promise<AtlasLotBoardReceivableV1[]>;
  onCommand(command: AtlasLotBoardComponentCommandV1): void;
  prepareAssistantLotStatusPrompt(label: string): void;
  host: Document;
  globalRef?: typeof globalThis;
}

export type AtlasLotBoardComponentCommandV1 =
  | { type: "save-status"; lotKey: string; status: AtlasLotCommercialStatus; sellerId: string; note: string }
  | { type: "delete-status"; lotKey: string }
  | { type: "navigate"; view: "lot-detail" | "repasses"; lotKey: string };

/** Render the spreadsheet opened by the Lotes component from its filtered projection. */
export function renderAtlasLotBoardExportV1(rows: readonly AtlasLotBoardRow[], generatedAt = new Date()): string {
  const esc = (value: unknown) => String(value ?? "").replace(/[&<>"']/g, char => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[char] || char));
  const money = (value: number) => new Intl.NumberFormat("pt-BR", { style: "currency", currency: "BRL" }).format(Number(value) || 0);
  const body = rows.map(row => `<tr><td>${esc(row.label)}</td><td>${esc(row.quadra)}</td><td>${esc(row.area)} m²</td><td>${esc(money(row.price))}</td><td>${row.contractPriceCents === null ? '—' : esc(money(row.contractPriceCents / 100))}</td><td>${row.contractPriceCents === null ? '—' : esc(money(row.receivedCents / 100))}</td><td>${row.remainingCents === null ? '—' : esc(money(row.remainingCents / 100))}</td><td>${esc(row.balanceStatus)}</td><td>${esc(row.status)}</td><td>${esc(row.paymentStatus)}</td><td>${esc(row.sellerName)}</td><td>${esc(row.note)}</td></tr>`).join("");
  return `<!doctype html><html><head><meta charset="utf-8"><style>body{font:12px Arial;color:#202638}h1{font-size:20px}table{width:100%;border-collapse:collapse}th,td{padding:8px;border:1px solid #aeb8c5;text-align:left}th{background:#edf2f8}</style></head><body><h1>Aliança Park · Tabela de lotes</h1><p>Preço de tabela e contratado, entradas, saldo restante e status · ${esc(generatedAt.toLocaleString("pt-BR"))}</p><table><thead><tr><th>Lote</th><th>Quadra</th><th>Área</th><th>Preço de tabela</th><th>Preço contratado</th><th>Entradas recebidas</th><th>Saldo restante</th><th>Situação do saldo</th><th>Status</th><th>Pagamento</th><th>Vendedor</th><th>Observação</th></tr></thead><tbody>${body}</tbody></table></body></html>`;
}

const atlasLotBoardControllerBindingsV1 = new WeakMap<Document, AbortController>();

/** Keep Lotes route control, local mutations and export presentation with its rendering component. */
export function installAtlasLotBoardComponentControllerV1(input: AtlasLotBoardComponentControllerInputV1): void {
  atlasLotBoardControllerBindingsV1.get(input.host)?.abort();
  const AbortControllerCtor = input.host.defaultView?.AbortController || AbortController;
  const bindings = new AbortControllerCtor();
  atlasLotBoardControllerBindingsV1.set(input.host, bindings);
  const options = { signal: bindings.signal };
  const globalRef = input.globalRef || globalThis;
  let element: AtlasLotBoard | null = null;
  let receivables: AtlasLotBoardReceivableV1[] = [];
  let balanceLoadState: AtlasLotBoardState['balanceLoadState'] = 'loading';
  let balanceError = '';
  let balanceRequest = 0;
  const sellers = projectAtlasLotBoardSellers();
  const currentStatuses = (): Record<string, AtlasLotStatus | undefined> => input.readStatuses();
  const sync = (): void => { element?.setData(projectAtlasLotBoardRows(currentStatuses(), undefined, receivables), sellers, balanceLoadState, balanceError); };
  const refreshBalances = async (): Promise<void> => {
    const request = ++balanceRequest;
    balanceLoadState = 'loading';
    balanceError = '';
    sync();
    try {
      const result = await input.loadBalances();
      if (request !== balanceRequest) return;
      receivables = result;
      balanceLoadState = 'ready';
    } catch (error) {
      if (request !== balanceRequest) return;
      balanceLoadState = 'error';
      balanceError = error instanceof Error ? error.message : String(error || 'Serviço financeiro indisponível.');
    }
    sync();
  };
  input.ViewLayer.prototype["brokers-board"] = () => '<atlas-lot-board></atlas-lot-board>';
  input.host.addEventListener("atlas:lot-board-connected", event => {
    const candidate = (event as CustomEvent<{ element?: AtlasLotBoard }>).detail?.element;
    if (!(candidate instanceof AtlasLotBoard)) return;
    element = candidate;
    sync();
    void refreshBalances();
  }, options);
  input.host.addEventListener("atlas:lot-board-status-save", event => {
    const detail = (event as CustomEvent<{ element?: AtlasLotBoard; lotKey?: string; status?: string; sellerId?: string; note?: string }>).detail;
    if (!detail || detail.element !== element) return;
    const allowed: AtlasLotCommercialStatus[] = ["Disponível", "Reservado", "Em negociação", "Vendido", "Repasse programado", "Quitado", "Bloqueado"];
    if (!detail.lotKey || !allowed.includes(detail.status as AtlasLotCommercialStatus)) return;
    input.onCommand({ type: "save-status", lotKey: detail.lotKey, status: detail.status as AtlasLotCommercialStatus, sellerId: String(detail.sellerId || ""), note: String(detail.note || "") });
    sync();
    element.closeControl();
    element.setMessage(`Controle do lote ${detail.lotKey} salvo no estado local.`);
  }, options);
  input.host.addEventListener("atlas:lot-board-delete", event => {
    const detail = (event as CustomEvent<{ element?: AtlasLotBoard; lotKey?: string }>).detail;
    if (!detail || detail.element !== element || !detail.lotKey) return;
    if (typeof globalRef.confirm === "function" && !globalRef.confirm(`Excluir o controle de ${detail.lotKey}? O lote e seu preço permanecerão na tabela.`)) return;
    input.onCommand({ type: "delete-status", lotKey: detail.lotKey });
    sync();
    element.setMessage(`Controle do lote ${detail.lotKey} removido; preço de referência preservado.`);
  }, options);
  input.host.addEventListener("atlas:lot-board-navigate", event => {
    const detail = (event as CustomEvent<{ element?: AtlasLotBoard; view?: string; lotKey?: string }>).detail;
    if (!detail || detail.element !== element) return;
    if (detail.view === "lot-detail" && detail.lotKey) {
      input.onCommand({ type: "navigate", view: "lot-detail", lotKey: detail.lotKey });
      return;
    }
    if (detail.view === "repasses" && detail.lotKey)
      input.onCommand({ type: "navigate", view: "repasses", lotKey: detail.lotKey });
  }, options);
  input.host.addEventListener("atlas:lot-board-map-marker", event => {
    const detail = (event as CustomEvent<{ element?: AtlasLotBoard; lotId?: string; label?: string }>).detail;
    if (!detail || detail.element !== element) return;
    element.openPickerForMarker(String(detail.lotId || ""));
    input.prepareAssistantLotStatusPrompt(String(detail.label || detail.lotId || ""));
  }, options);
  input.host.addEventListener("atlas:lot-board-export", event => {
    const detail = (event as CustomEvent<{ element?: AtlasLotBoard; lotKeys?: string[] }>).detail;
    if (!detail || detail.element !== element) return;
    if (balanceLoadState !== 'ready') {
      element.setMessage(balanceLoadState === 'loading' ? 'Aguarde o carregamento das entradas antes de exportar os saldos.' : `Exportação financeira indisponível: ${balanceError}`);
      return;
    }
    const selected = new Set(detail.lotKeys || []);
    const rows = projectAtlasLotBoardRows(currentStatuses(), undefined, receivables).filter(row => selected.has(row.label));
    if (!rows.length) return;
    const urlApi = input.host.defaultView?.URL || URL;
    const objectUrl = urlApi.createObjectURL(new Blob([renderAtlasLotBoardExportV1(rows)], { type: "application/vnd.ms-excel;charset=utf-8" }));
    const link = input.host.createElement("a");
    link.href = objectUrl;
    link.download = "alianca-park-tabela-lotes.xls";
    input.host.body.append(link);
    link.click();
    link.remove();
    globalRef.setTimeout(() => urlApi.revokeObjectURL(objectUrl), 1000);
    element.setMessage(`${rows.length} lote(s) exportados em planilha.`);
  }, options);
  input.host.addEventListener("atlas:lot-board-print", event => {
    const detail = (event as CustomEvent<{ element?: AtlasLotBoard }>).detail;
    if (!detail || detail.element !== element) return;
    const cleanup = () => input.host.body.classList.remove("lot-catalog-print-mode");
    input.host.body.classList.add("lot-catalog-print-mode");
    globalRef.addEventListener?.("afterprint", cleanup, { once: true });
    globalRef.print?.();
  }, options);
}

export interface AtlasLotDetailPageInputV1 {
  state: AtlasLotDetailStateV1;
  priceCatalog: RepassePriceCatalogEntry[];
  commissionProfiles: AtlasCommissionProfileCatalogEntry[];
  esc(value: unknown): string;
  formatBRL(value: unknown): string;
  ico(name: string): string;
}

/** Render the selected lot's existing status, payment, plans, documents, cash, map and history. */
export function renderAtlasLotDetailPageV1(input: AtlasLotDetailPageInputV1): string {
  const { state, esc, formatBRL, ico } = input;
  const projection: AtlasLotDetailPageProjectionV1 = projectAtlasLotDetailPageV1({ ...input, state });
  const { lotKey, lot, lotStatus, plans, documents, history, partners, sellerId, payment, paymentTotal, derivedHistory, cashEntries, totalCashCents, canRegisterCash } = projection;
  if (!lot) return `<section class="lot-detail-page"><p class="empty-data">Nenhum lote disponível na tabela de preços.</p></section>`;
  const cashMarkup = `<div class="lot-cash-summary"><div><small>RECEBIDO NO CAIXA</small><strong>${formatBRL(totalCashCents / 100)}</strong><span>${cashEntries.length} lançamento(s) vinculado(s)</span></div>${canRegisterCash ? `<button type="button" class="atlas-dark-button" data-lot-cash-entry="${esc(lotKey)}">${ico("plus")} Registrar em Repasses</button>` : ""}</div><ol class="lot-cash-entry-list">${cashEntries.map(entry => `<li><div><b>${esc(entry.category || "Entrada de caixa")}</b><small>${esc(entry.date || "Sem data")} · ${esc(entry.description || "Sem descrição")}</small></div><strong>${formatBRL(Number(entry.amountCents || 0) / 100)}</strong></li>`).join("") || '<li class="empty-data">Nenhuma entrada de caixa vinculada a este lote.</li>'}</ol>`;
  const statusOptions = ["Disponível", "Reservado", "Em negociação", "Vendido", "Repasse programado", "Quitado", "Bloqueado"];
  const paymentOptions = ["Pendente", "Parcial", "Pago", "Cancelado"];
  const documentKinds = [...new Set(["Contrato de compra e venda", "Documento do cliente", "Comprovante de pagamento", "Planta / memorial", "Outro", ...documents.map(document => String(document.kind || "").trim()).filter(Boolean)])];
  const selected = (value: unknown, current: unknown): string => String(value) === String(current) ? " selected" : "";
  const detailDate = (value: unknown): string => {
    if (!value) return "Sem data";
    const date = new Date(String(value));
    return Number.isNaN(date.getTime()) ? String(value) : date.toLocaleString("pt-BR", { dateStyle: "short", timeStyle: "short" });
  };
  const requestedReturnView = String(state.lotDetailReturnView || "");
  const returnView = ["lot-development", "brokers-board", "map"].includes(requestedReturnView) ? requestedReturnView : "brokers-board";
  const returnLabel = returnView === "lot-development" ? "Lotes" : returnView === "map" ? "Mapa" : "Tabela de lotes";
  return `<section class="lot-detail-page" data-lot-detail-page data-lot-key="${esc(lotKey)}">
    <header class="lot-detail-head">
      <div><button type="button" class="lot-detail-back" data-atlas-view="${esc(returnView)}" aria-label="Voltar para ${esc(returnLabel)}">${ico("arrow-left")} Voltar para ${esc(returnLabel)}</button><span class="activity-kind">FICHA COMERCIAL · ${esc(lot.quadra)}</span><h1>Lote ${esc(lot.lot)}</h1><p>${esc(lotKey)} · ${esc(lot.area)} m² · valor de tabela <b>${formatBRL(lot.price)}</b></p></div>
      <div class="lot-detail-head-state"><span class="lot-status-pill">${esc(lotStatus.status || "Disponível")}</span><span class="lot-payment-pill">${esc(payment.status || "Pendente")}</span><button type="button" class="toolbar-action" data-lot-detail-print>${ico("printer")} PDF</button><button type="button" class="toolbar-action" data-lot-detail-excel>${ico("download")} Excel</button></div>
    </header>
    <div class="lot-detail-layout">
      <form class="lot-detail-form" data-lot-detail-form>
        <input type="hidden" name="lotKey" value="${esc(lotKey)}">
        <section class="lot-detail-section"><header><span>01</span><div><h2>Propriedades do lote</h2><p>Dados oficiais do catálogo e vínculos comerciais desta unidade.</p></div></header><div class="lot-detail-fields">
          <label>Lote<input value="${esc(lotKey)}" disabled aria-label="Identificação oficial do lote"></label><label>Quadra<input value="${esc(lot.quadra)}" disabled></label><label>Área (m²)<input value="${esc(lot.area)}" disabled></label><label>Valor de tabela<input value="${formatBRL(lot.price)}" disabled></label>
          <label>Situação comercial<select name="status">${statusOptions.map(value => `<option${selected(value, lotStatus.status || "Disponível")}>${esc(value)}</option>`).join("")}</select></label>
          <label>Corretor responsável<select name="sellerId"><option value="">Não definido</option>${partners.map(person => `<option value="${esc(person.id)}"${selected(person.id, sellerId)}>${esc(person.name)}</option>`).join("")}</select></label>
          <label>Sócio do repasse<select name="repassePartnerId"><option value="">Não definido</option>${partners.map(person => `<option value="${esc(person.id)}"${selected(person.id, lotStatus.repasse?.partnerId || "")}>${esc(person.name)}</option>`).join("")}</select></label>
          <label>Cliente<input name="client" value="${esc(lotStatus.client || "")}" placeholder="Nome do cliente"></label>
          <label class="wide">Observações<textarea name="note" rows="4" placeholder="Condições, contato, pendências e observações">${esc(lotStatus.note || "")}</textarea></label>
        </div><footer><span data-lot-detail-form-feedback>Alterações são gravadas no controle comercial deste lote.</span><button type="submit" class="toolbar-primary">${ico("save")} Salvar detalhes</button></footer></section>
      </form>
      <aside class="lot-detail-side">
        <section class="lot-detail-section" data-lot-payment-details><header><span>02</span><div><h2>Pagamento e entrada</h2><p>Controle do sinal informado. Entradas confirmadas ficam registradas no caixa.</p></div></header><form class="lot-detail-inline-form lot-detail-payment-form" data-lot-payment-form><input type="hidden" name="lotKey" value="${esc(lotKey)}"><label>Situação<select name="paymentStatus">${paymentOptions.map(value => `<option${selected(value, payment.status || "Pendente")}>${esc(value)}</option>`).join("")}</select></label><label>Valor do sinal / entrada (R$)<input name="paymentAmount" type="number" min="0" step="0.01" value="${esc(payment.amount ?? "")}" placeholder="0,00"></label><label>Data prevista ou recebida<input name="paymentDate" type="date" value="${esc(payment.date || "")}"></label><footer><span>Para lançar o recebimento no caixa, use Repasses.</span><button type="submit" class="toolbar-primary">${ico("save")} Salvar pagamento</button></footer></form></section>
        <section class="lot-detail-section" data-lot-payment-plans><header><span>03</span><div><h2>Parcelamento</h2><p>${plans.length} parcela(s) · ${formatBRL(paymentTotal)} programado(s)</p></div></header><ol class="lot-detail-plan-list">${plans.map(plan => `<li data-lot-plan-id="${esc(plan.id)}"><div><b>${esc(plan.description || "Parcela")}</b><small>${esc(plan.dueDate || "Sem vencimento")} · ${esc(plan.status || "Pendente")}</small></div><strong>${formatBRL(plan.amount || 0)}</strong><span><button type="button" data-lot-plan-edit="${esc(plan.id)}">Editar</button><button type="button" data-lot-plan-delete="${esc(plan.id)}">Excluir</button></span></li>`).join("") || '<li class="empty-data">Nenhuma parcela programada.</li>'}</ol><form class="lot-detail-inline-form" data-lot-plan-form><input type="hidden" name="id"><label>Descrição<input name="description" required placeholder="Ex.: Parcela 01"></label><label>Vencimento<input name="dueDate" type="date"></label><label>Valor (R$)<input name="amount" required type="number" min="0.01" step="0.01"></label><label>Situação<select name="status">${paymentOptions.map(value => `<option>${esc(value)}</option>`).join("")}</select></label><footer><button type="reset" data-lot-plan-cancel hidden>Cancelar edição</button><button type="submit">Adicionar parcela</button></footer></form></section>
        <section class="lot-detail-section lot-detail-cash" data-lot-cash-entries><header><span>04</span><div><h2>Entradas registradas</h2><p>Recebimentos efetivamente lançados em Repasses e vinculados a este lote.</p></div></header>${cashMarkup}</section>
        <section class="lot-detail-section" data-lot-documents><header><span>05</span><div><h2>Contrato e documentos</h2><p>Anexe o contrato de compra e venda e mantenha os demais arquivos ligados ao lote.</p></div></header><ul class="lot-detail-document-list">${documents.map(document => `<li data-lot-document-id="${esc(document.id)}"><span>${ico("file-text")}</span><div><b>${esc(document.title || "Documento sem título")}</b><small>${esc(document.kind || "Documento")} · ${esc(document.note || "Sem observação")}</small>${document.fileName ? `<small>Arquivo: ${esc(document.fileName)}</small>` : ""}${document.url ? `<a href="${esc(document.url)}" target="_blank" rel="noreferrer">Abrir no GitHub</a>` : ""}</div><span><button type="button" data-lot-document-edit="${esc(document.id)}">Editar</button><button type="button" data-lot-document-delete="${esc(document.id)}">Excluir</button></span></li>`).join("") || '<li class="empty-data">Nenhum anexo associado.</li>'}</ul><form class="lot-detail-inline-form" data-lot-document-form><input type="hidden" name="id"><label>Título<input name="title" required placeholder="Ex.: Contrato do lote ${esc(lotKey)}"></label><label>Tipo de documento<select name="kind">${documentKinds.map(value => `<option value="${esc(value)}"${selected(value, "Contrato de compra e venda")}>${esc(value)}</option>`).join("")}</select></label><label class="wide">Anexo do contrato (PDF ou imagem)<input name="file" type="file" accept="application/pdf,image/jpeg,image/png,image/webp" required></label><label class="wide">Observação<input name="note" placeholder="Descrição do contrato ou documento"></label><footer><span class="lot-detail-upload-status" data-lot-document-upload-status>PDF ou imagem de até 6 MB. O arquivo será associado a este lote.</span><button type="reset" data-lot-document-cancel hidden>Cancelar edição</button><button type="submit">Enviar e associar</button></footer></form></section>
      </aside>
      <section class="lot-detail-section lot-detail-history" data-lot-history><header><span>06</span><div><h2>Histórico do lote</h2><p>Alterações do controle, entradas e registros associados.</p></div></header><ol>${derivedHistory.map(item => `<li><time>${esc(detailDate(item.at))}</time><div><b>${esc(item.type)}</b><small>${esc(item.detail || "Sem detalhes")}</small></div></li>`).join("") || '<li class="empty-data">Nenhum evento registrado para este lote.</li>'}</ol></section>
    </div>
    <details class="lot-detail-map-drawer"><summary><span>${ico("map")} Mapa e localização do lote</span><small>Abra o mapa para conferir o lote destacado.</small></summary><div class="lot-detail-map-window"><map-scene compact interactive data-public-static-only data-admin-public-map data-lot-detail-map data-lot-detail-number="${esc(lot.lot)}" data-stage="Lote ${esc(lotKey)}" data-overlay="urbanizacao" aria-label="Mapa do lote ${esc(lotKey)}"></map-scene></div></details>
  </section>`;
}

/** Preserve the branded HTML workbook export used by the old lot detail. */
export function downloadAtlasBrandedLotExcelV1(
  input: { lots?: Array<RepassePriceCatalogEntry & Record<string, unknown>>; title?: string; subtitle?: string; filename?: string },
  host: typeof globalThis = globalThis,
): void {
  const esc = (value: unknown): string => String(value ?? "").replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/\"/g, "&quot;");
  const money = (value: unknown): string => Number(value || 0).toLocaleString("pt-BR", { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  const rows = Array.isArray(input.lots) ? input.lots : [];
  const gross = rows.reduce((total, item) => total + Number(item.price || 0), 0);
  const occupied = rows.filter(item => !["", "Disponível"].includes(String(item.status || "Disponível"))).length;
  const now = new host.Date().toLocaleString("pt-BR");
  const html = `<!DOCTYPE html><html xmlns:o="urn:schemas-microsoft-com:office:office" xmlns:x="urn:schemas-microsoft-com:office:excel"><head><meta charset="utf-8"><meta name="ProgId" content="Excel.Sheet"><style>table{border-collapse:collapse;font-family:Arial,sans-serif}td{border:1px solid #C6CFD8;padding:7px;color:#17212B;font-size:10pt}.brand{background:#09233B;color:#FFF;font-size:18pt;font-weight:bold;height:34px}.kicker{background:#09233B;color:#9FC8FF;font-size:9pt;font-weight:bold}.title{background:#EEF5FB;color:#09233B;font-size:16pt;font-weight:bold}.subtitle{background:#EEF5FB;color:#516170;font-size:10pt}.label{background:#DCEAF5;color:#315D87;font-size:8pt;font-weight:bold}.metric{background:#F7FAFC;color:#09233B;font-size:13pt;font-weight:bold}.head{background:#09233B;color:#FFF;font-size:9pt;font-weight:bold;text-align:center}.money{mso-number-format:'\"R$\" #,##0.00';text-align:right}.number{text-align:right}.status{background:#E8F5EC;color:#176B3A;font-weight:bold}.footer{background:#F2F4F8;color:#5A6875;font-size:8pt}</style></head><body><table><colgroup><col width="16"><col width="13"><col width="13"><col width="15"><col width="18"><col width="18"><col width="24"><col width="30"></colgroup><tr><td class="brand" colspan="8">ALIANÇA PARK · LOTES</td></tr><tr><td class="kicker" colspan="8">RELATÓRIO COMERCIAL · EXPORTAÇÃO EXCEL</td></tr><tr><td class="title" colspan="8">${esc(input.title || "Tabela de lotes")}</td></tr><tr><td class="subtitle" colspan="8">${esc(input.subtitle || "Valores, status e pagamentos")} · Emitido em ${esc(now)}</td></tr><tr><td class="label" colspan="2">LOTES LISTADOS</td><td class="label" colspan="2">VALOR DE TABELA</td><td class="label" colspan="2">COM CONTROLE</td><td class="label" colspan="2">EMITIDO POR</td></tr><tr><td class="metric" colspan="2">${rows.length}</td><td class="metric money" colspan="2">${money(gross)}</td><td class="metric" colspan="2">${occupied}</td><td class="metric" colspan="2">Aliança Park</td></tr><tr><td class="head">LOTE</td><td class="head">QUADRA</td><td class="head">ÁREA (m²)</td><td class="head">VALOR À VISTA</td><td class="head">STATUS</td><td class="head">PAGAMENTO</td><td class="head">VENDEDOR</td><td class="head">CLIENTE / OBSERVAÇÃO</td></tr>${rows.map(item => `<tr><td>${esc(item.label || item.lot)}</td><td>${esc(item.quadra)}</td><td class="number">${esc(item.area)}</td><td class="money">${money(item.price)}</td><td class="status">${esc(item.status || "Disponível")}</td><td>${esc(item.paymentStatus || "Pendente")}</td><td>${esc(item.sellerName || "—")}</td><td>${esc(item.client || item.note || "—")}</td></tr>`).join("")}<tr><td class="footer" colspan="8">Documento timbrado para apoio comercial e conferência de valores · Aliança Park Loteamento</td></tr></table></body></html>`;
  const blob = new host.Blob(["\ufeff", html], { type: "application/vnd.ms-excel;charset=utf-8" });
  const url = host.URL.createObjectURL(blob);
  const link = host.document.createElement("a");
  link.href = url; link.download = `${input.filename || "alianca-park-lotes"}-${new host.Date().toISOString().slice(0, 10)}.xls`; link.click();
  host.setTimeout(() => host.URL.revokeObjectURL(url), 1000);
}

export type AtlasLotDetailCommandV1 =
  | { type: "cash-entry"; lotKey: string }
  | { type: "status-save"; lotKey: string; fields: Record<string, string> }
  | { type: "payment-plan-save"; lotKey: string; fields: Record<string, string> }
  | { type: "payment-plan-delete"; lotKey: string; planId: string }
  | { type: "document-save"; lotKey: string; fields: Record<string, string>; file: File | null }
  | { type: "document-delete"; lotKey: string; documentId: string }
  | { type: "map-marker-select"; lotKey: string; targetLotKey?: string; lotId?: string; label?: string };

export interface AtlasLotDetailCommandResultV1 {
  ok: boolean;
  message?: string;
}

export interface AtlasLotDetailComponentControllerInputV1 {
  ViewLayer: { prototype: HTMLElement & Record<string, unknown> };
  getState(): AtlasLotDetailStateV1;
  priceCatalog: RepassePriceCatalogEntry[];
  commissionProfiles: AtlasCommissionProfileCatalogEntry[];
  esc(value: unknown): string;
  formatBRL(value: unknown): string;
  ico(name: string): string;
  execute(command: AtlasLotDetailCommandV1): AtlasLotDetailCommandResultV1 | Promise<AtlasLotDetailCommandResultV1>;
  exportLot(lotKey: string): void;
  host?: typeof globalThis;
}

/** Keep the lot-detail renderer and its delegated DOM controller on the component side. */
export function installAtlasLotDetailComponentControllerV1(input: AtlasLotDetailComponentControllerInputV1): void {
  const host = input.host || globalThis;
  const prototype = input.ViewLayer.prototype;
  const layer = prototype as HTMLElement & Record<string, any>;
  const baseBind = layer.bind as ((this: HTMLElement, ...args: unknown[]) => unknown) | undefined;
  const boundLayers = new WeakSet<HTMLElement>();
  const configuredMaps = new WeakSet<HTMLElement>();
  const configuredDetails = new WeakSet<HTMLDetailsElement>();
  const formControl = (form: HTMLFormElement, name: string): HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement | null =>
    form.elements.namedItem(name) as HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement | null;
  const formFields = (form: HTMLFormElement): Record<string, string> => {
    const values = Object.fromEntries(new host.FormData(form));
    return Object.fromEntries(Object.entries(values).map(([key, value]) => [key, String(value ?? "")]));
  };
  const pageFor = (target: EventTarget | null): HTMLElement | null => {
    const element = target instanceof host.Element ? target : null;
    return element?.closest<HTMLElement>("[data-lot-detail-page]") || null;
  };
  const execute = async (command: AtlasLotDetailCommandV1): Promise<AtlasLotDetailCommandResultV1> => {
    try {
      return await input.execute(command);
    } catch (error) {
      return { ok: false, message: error instanceof Error ? error.message : "Não foi possível concluir a ação." };
    }
  };
  const focusPlan = (view: HTMLElement, planId: string): void => {
    const state = input.getState();
    const lotKey = String(view.querySelector<HTMLElement>("[data-lot-detail-page]")?.dataset.lotKey || "");
    const plan = (state.lotPaymentPlans?.[lotKey] || []).find(item => item.id === planId);
    const form = view.querySelector<HTMLFormElement>("[data-lot-plan-form]");
    if (!plan || !form) return;
    for (const [key, value] of Object.entries(plan)) {
      const field = formControl(form, key);
      if (field) field.value = String(value ?? "");
    }
    const cancel = form.querySelector<HTMLButtonElement>("[data-lot-plan-cancel]");
    if (cancel) cancel.hidden = false;
    const submit = form.querySelector<HTMLButtonElement>('[type="submit"]');
    if (submit) submit.textContent = "Salvar parcela";
    form.scrollIntoView({ block: "center", behavior: "smooth" });
  };
  const resetPlan = (form: HTMLFormElement): void => {
    form.reset();
    const id = formControl(form, "id");
    if (id) id.value = "";
    const cancel = form.querySelector<HTMLButtonElement>("[data-lot-plan-cancel]");
    if (cancel) cancel.hidden = true;
    const submit = form.querySelector<HTMLButtonElement>('[type="submit"]');
    if (submit) submit.textContent = "Adicionar parcela";
  };
  const focusDocument = (view: HTMLElement, documentId: string): void => {
    const lotKey = String(view.querySelector<HTMLElement>("[data-lot-detail-page]")?.dataset.lotKey || "");
    const document = (input.getState().lotDocuments?.[lotKey] || []).find(item => item.id === documentId);
    const form = view.querySelector<HTMLFormElement>("[data-lot-document-form]");
    if (!document || !form) return;
    for (const [key, value] of Object.entries(document)) {
      const field = formControl(form, key);
      if (field) field.value = String(value ?? "");
    }
    const file = formControl(form, "file");
    if (file instanceof host.HTMLInputElement) file.required = false;
    const cancel = form.querySelector<HTMLButtonElement>("[data-lot-document-cancel]");
    if (cancel) cancel.hidden = false;
    const status = form.querySelector<HTMLElement>("[data-lot-document-upload-status]");
    if (status) status.textContent = "Selecione outro arquivo somente para substituí-lo no repositório.";
    const submit = form.querySelector<HTMLButtonElement>('[type="submit"]');
    if (submit) submit.textContent = "Salvar documento";
    form.scrollIntoView({ block: "center", behavior: "smooth" });
  };
  const resetDocument = (form: HTMLFormElement): void => {
    form.reset();
    const id = formControl(form, "id");
    if (id) id.value = "";
    const file = formControl(form, "file");
    if (file instanceof host.HTMLInputElement) file.required = true;
    const cancel = form.querySelector<HTMLButtonElement>("[data-lot-document-cancel]");
    if (cancel) cancel.hidden = true;
    const status = form.querySelector<HTMLElement>("[data-lot-document-upload-status]");
    if (status) status.textContent = "PDF ou imagem de até 6 MB.";
    const submit = form.querySelector<HTMLButtonElement>('[type="submit"]');
    if (submit) submit.textContent = "Enviar e associar";
  };

  layer["lot-detail"] = function (this: HTMLElement): string {
    return renderAtlasLotDetailPageV1({
      state: input.getState(), priceCatalog: input.priceCatalog,
      commissionProfiles: input.commissionProfiles, esc: input.esc,
      formatBRL: input.formatBRL, ico: input.ico,
    });
  };
  layer.bind = function (this: HTMLElement, ...args: unknown[]): unknown {
    const result = baseBind?.apply(this, args);
    const root = this.querySelector<HTMLElement>("[data-lot-detail-page]");
    if (!root) return result;

    if (!boundLayers.has(this)) {
      boundLayers.add(this);
      this.addEventListener("click", event => {
        const origin = event.target instanceof host.Element ? event.target : null;
        if (!origin) return;
        const page = pageFor(origin);
        if (!page) return;
        const lotKey = String(page.dataset.lotKey || "");
        const button = origin.closest<HTMLButtonElement>("button");
        if (!button) return;
        if (button.matches("[data-lot-cash-entry]")) {
          void execute({ type: "cash-entry", lotKey });
        } else if (button.matches("[data-lot-detail-print]")) {
          const documentRef = host.document;
          const cleanPrint = (): void => documentRef.body.classList.remove("lot-detail-print-mode");
          documentRef.body.classList.add("lot-detail-print-mode");
          host.window.addEventListener("afterprint", cleanPrint, { once: true });
          host.window.print();
        } else if (button.matches("[data-lot-detail-excel]")) {
          input.exportLot(lotKey);
        } else if (button.matches("[data-lot-plan-edit]")) {
          focusPlan(this, button.dataset.lotPlanEdit || "");
        } else if (button.matches("[data-lot-plan-delete]")) {
          const planId = String(button.dataset.lotPlanDelete || "");
          const plan = (input.getState().lotPaymentPlans?.[lotKey] || []).find(item => item.id === planId);
          if (plan && host.confirm(`Excluir a parcela “${plan.description}”?`)) void execute({ type: "payment-plan-delete", lotKey, planId });
        } else if (button.matches("[data-lot-plan-cancel]")) {
          const form = button.closest<HTMLFormElement>("[data-lot-plan-form]");
          if (form) resetPlan(form);
        } else if (button.matches("[data-lot-document-edit]")) {
          focusDocument(this, button.dataset.lotDocumentEdit || "");
        } else if (button.matches("[data-lot-document-delete]")) {
          const documentId = String(button.dataset.lotDocumentDelete || "");
          const document = (input.getState().lotDocuments?.[lotKey] || []).find(item => item.id === documentId);
          if (document && host.confirm(`Excluir o documento “${document.title}”?`)) void execute({ type: "document-delete", lotKey, documentId });
        } else if (button.matches("[data-lot-document-cancel]")) {
          const form = button.closest<HTMLFormElement>("[data-lot-document-form]");
          if (form) resetDocument(form);
        }
      });
      this.addEventListener("submit", event => {
        const form = event.target instanceof host.HTMLFormElement ? event.target : null;
        const page = pageFor(form);
        if (!form || !page) return;
        const lotKey = String(page.dataset.lotKey || "");
        if (form.matches("[data-lot-detail-form]")) {
          event.preventDefault();
          void execute({ type: "status-save", lotKey, fields: formFields(form) });
        } else if (form.matches("[data-lot-payment-form]")) {
          event.preventDefault();
          void execute({ type: "status-save", lotKey, fields: formFields(form) });
        } else if (form.matches("[data-lot-plan-form]")) {
          event.preventDefault();
          const fields = formFields(form);
          if (!(Number(fields.amount.replace(",", ".")) > 0)) return;
          void execute({ type: "payment-plan-save", lotKey, fields });
        } else if (form.matches("[data-lot-document-form]")) {
          event.preventDefault();
          const fields = formFields(form);
          const fileControl = formControl(form, "file");
          const file = fileControl instanceof host.HTMLInputElement ? fileControl.files?.[0] || null : null;
          const existing = (input.getState().lotDocuments?.[lotKey] || []).find(item => item.id === fields.id);
          const status = form.querySelector<HTMLElement>("[data-lot-document-upload-status]");
          if (!file && !existing) {
            if (status) status.textContent = "Selecione um PDF ou uma imagem para enviar.";
            return;
          }
          const submit = form.querySelector<HTMLButtonElement>('[type="submit"]');
          if (submit) submit.disabled = true;
          if (status) status.textContent = file ? `Enviando ${file.name} ao repositório…` : "Mantendo arquivo já enviado.";
          void execute({ type: "document-save", lotKey, fields, file }).then(result => {
            const currentForm = this.querySelector<HTMLFormElement>("[data-lot-document-form]");
            if (result.ok && currentForm) {
              resetDocument(currentForm);
              const currentStatus = currentForm.querySelector<HTMLElement>("[data-lot-document-upload-status]");
              if (currentStatus) currentStatus.textContent = result.message || "Arquivo salvo no repositório GitHub e vinculado ao lote.";
            } else if (!result.ok) {
              const currentStatus = this.querySelector<HTMLElement>("[data-lot-document-upload-status]");
              if (currentStatus) currentStatus.textContent = result.message || "Não foi possível enviar o arquivo.";
            }
          }).finally(() => {
            const currentSubmit = this.querySelector<HTMLButtonElement>("[data-lot-document-form] [type=submit]");
            if (currentSubmit) currentSubmit.disabled = false;
          });
        }
      });
      this.addEventListener("belavista:lot-marker-selected", event => {
        const map = event.target instanceof host.Element ? event.target.closest<HTMLElement>("[data-lot-detail-map]") : null;
        const page = pageFor(map);
        if (!map || !page) return;
        const detail = (event as CustomEvent<{ lotId?: string; label?: string }>).detail;
        const currentLotKey = String(page.dataset.lotKey || "");
        const currentLot = input.priceCatalog.find(item => String(item.label) === currentLotKey);
        const lotNumber = Number(String(detail?.lotId || "").match(/\d+/g)?.at(-1));
        const selectedLot = input.priceCatalog.find(item => item.quadra === currentLot?.quadra && Number(item.lot) === lotNumber)
          || input.priceCatalog.find(item => Number(item.lot) === lotNumber);
        void execute({ type: "map-marker-select", lotKey: currentLotKey, targetLotKey: selectedLot?.label, lotId: detail?.lotId, label: detail?.label });
      });
    }

    const map = root.querySelector<HTMLElement & {
      installAdminMasterplanOverlayV1?: () => void;
      installSatelliteLotPlanOverlayV1?: (options: { markers: boolean; outlines: boolean }) => void;
    }>("[data-lot-detail-map]");
    if (map && !configuredMaps.has(map)) {
      configuredMaps.add(map);
      const lotKey = String(root.dataset.lotKey || "");
      const lot = input.priceCatalog.find(item => String(item.label) === lotKey);
      const installLotMap = (): void => {
        map.installAdminMasterplanOverlayV1?.();
        map.installSatelliteLotPlanOverlayV1?.({ markers: true, outlines: false });
      };
      host.requestAnimationFrame(installLotMap);
      const details = map.closest("details");
      if (details && !configuredDetails.has(details)) {
        configuredDetails.add(details);
        details.addEventListener("toggle", () => { if (details.open) host.requestAnimationFrame(installLotMap); });
      }
      const selectMarker = (): boolean => {
        const marker = Array.from(map.querySelectorAll<HTMLElement>(".satellite-lot-plan-marker"))
          .find(node => Number(String(node.dataset.lot || "").match(/\d+/g)?.at(-1)) === Number(lot?.lot));
        if (!marker) return false;
        map.querySelectorAll<HTMLElement>(".satellite-lot-plan-marker.is-selected").forEach(node => node.classList.remove("is-selected"));
        marker.classList.add("is-selected");
        map.dataset.selectedLot = marker.dataset.lot || lotKey;
        return true;
      };
      if (!selectMarker()) {
        const observer = new host.MutationObserver(() => {
          if (!map.isConnected) { observer.disconnect(); return; }
          if (selectMarker()) observer.disconnect();
        });
        observer.observe(map, { childList: true, subtree: true });
      }
    }
    return result;
  };
}

type MaterialsState = {
  materials: OperationalMaterial[];
  stages: OperationalStage[];
  stageAiPreviews: Record<string, AtlasMaterialsStageAiPreviewV1>;
  columns: MaterialCustomColumn[];
  agenda: OperationalAgendaEvent[];
  documents: ProjectDocument[];
  query: string;
  page: number;
  pageTab: "canvas" | "list";
  activeStage: number | "inventory";
  statusFilter: string;
  hiddenColumns: string[];
  isNative: boolean;
  editing: OperationalMaterial | null | false;
  transition: OperationalMaterial | null;
  transitionHistory: AtlasMaterialTransitionRecordV1[];
  transitionAttachments: AtlasMaterialTransitionAttachmentV1[];
  status: "loading" | "ready" | "error";
  error: string | null;
  saving: boolean;
};
type MaterialsSetter = (previous: MaterialsState) => MaterialsState;
const atlasMaterialHiddenColumnsStorageKey = "atlas.materials.hidden-columns.v1";
function readAtlasMaterialHiddenColumns(): string[] {
  try {
    const value = JSON.parse(globalThis.localStorage?.getItem(atlasMaterialHiddenColumnsStorageKey) || "[]");
    return Array.isArray(value) ? value.map(String) : [];
  } catch { return []; }
}
function writeAtlasMaterialHiddenColumns(columns: readonly string[]): void {
  try { globalThis.localStorage?.setItem(atlasMaterialHiddenColumnsStorageKey, JSON.stringify([...new Set(columns.map(String))])); } catch { /* storage can be disabled */ }
}
