/** Catálogo persistido; estados e controles transitórios pertencem ao Web Element. */
export class AtlasMaterials extends AtlasHTMLElementBase {
  private readonly state: AtomicState<MaterialsState>;
  private snapshot: MaterialsState;
  constructor() {
    super();
    const initial: MaterialsState = { materials: [], stages: [], stageAiPreviews: {}, columns: [], agenda: [], documents: [], query: "", page: 1, pageTab: "canvas", activeStage: "inventory", statusFilter: "all", hiddenColumns: readAtlasMaterialHiddenColumns(), isNative: false, editing: false, transition: null, transitionHistory: [], transitionAttachments: [], status: "loading", error: null, saving: false };
    function* state(value: MaterialsState): Generator<MaterialsState, never, MaterialsSetter> { while (true) value = (yield value)(value); }
    this.snapshot = initial; const iterator=state(initial); iterator.next(); this.state={next:setter=>{this.snapshot=iterator.next(setter).value;this.renderSafely();return this.snapshot;}};
  }
  private renderSafely():void{try{this.render();}catch(error: any){console.error("Falha ao renderizar materiais Atlas",error);this.textContent=`Falha ao renderizar Materiais: ${error instanceof Error?error.message:String(error)}`;}}
  private escape(value: unknown): string { return String(value ?? "").replace(/[&<>"']/g, char => ({ "&":"&amp;", "<":"&lt;", ">":"&gt;", '"':"&quot;", "'":"&#39;" }[char] || char)); }
  setData(materials: OperationalMaterial[], stages: OperationalStage[], columns: MaterialCustomColumn[] = [], agenda: OperationalAgendaEvent[] = [], documents: ProjectDocument[] = [], stageAiPreviews: Record<string, AtlasMaterialsStageAiPreviewV1> = {}, isNative = false): void { this.state.next(s => ({...s, materials, stages, stageAiPreviews, columns, agenda, documents, isNative, status:"ready", error:null, saving:false})); }
  getProjectDocument(id:string):ProjectDocument|undefined{return this.snapshot.documents.find(item=>item.id===id);}
  getMaterial(id:string):OperationalMaterial|undefined{return this.snapshot.materials.find(item=>item.id===id);}
  private stageAiPreviewMarkup(stage:OperationalStage):string{
    const preview=this.snapshot.stageAiPreviews[String(stage.id)]||this.snapshot.stageAiPreviews[String(stage.key||stage.name)];
    const entries=preview?.entries||[];
    return `<section class="atlas-stage-ai-preview" aria-label="Prévia de aplicação dos materiais"><div class="atlas-stage-ai-preview-head"><span>PRÉVIA IA · APLICAÇÃO DOS MATERIAIS</span><small>${this.escape(preview?.source||"contexto operacional")}</small></div><div class="atlas-stage-ai-preview-flow">${entries.length?entries.map(entry=>`<article class="atlas-stage-ai-preview-item"><span>${this.escape(entry.phase)}</span><div>${entry.connected?`<button type="button" data-edit="${this.escape(entry.id)}">${this.escape(entry.name)}</button>`:`<b>${this.escape(entry.name)}</b>`}<p>${this.escape(entry.application)}</p><small>${this.escape(entry.quantity)} · ${this.escape(entry.timing)}</small></div><em>${this.escape(entry.status)}</em>${entry.connected?`<button type="button" class="atlas-stage-ai-unlink" data-unlink="${this.escape(entry.id)}" aria-label="Remover ${this.escape(entry.name)} desta etapa" title="Remover vínculo com esta etapa">Remover vínculo</button>`:""}</article>`).join(""):`<div class="atlas-stage-ai-preview-empty"><b>Aguardando materiais</b><p>Adicione ou vincule um material para projetar sua aplicação nesta frente.</p></div>`}</div><small class="atlas-stage-ai-preview-note">Prévia operacional. Agenda e compreensão da etapa orientam a aplicação; confirme quantidades e datas antes da execução.</small></section>`;
  }
  isDraftMaterial(id:string):boolean{return !this.snapshot.materials.some(item=>item.id===id);}
  closeTransition():void{this.state.next(s=>({...s,transition:null,transitionHistory:[],transitionAttachments:[],saving:false,error:null}));}
  setError(message: string): void { this.state.next(s => ({...s,status:"error",error:message,saving:false})); }
  setTransitionHistory(id: string, transitions: AtlasMaterialTransitionRecordV1[], attachments: AtlasMaterialTransitionAttachmentV1[]): void { if(this.snapshot.transition?.id===id)this.state.next(s=>({...s,transitionHistory:transitions,transitionAttachments:attachments})); }
  private drawLinks(): void {
    const board=this.querySelector<HTMLElement>("[data-canvas]"),svg=this.querySelector<SVGElement>("[data-links]");
    if(!board||!svg)return;
    const frame=board.getBoundingClientRect(),width=board.scrollWidth,height=board.scrollHeight;svg.setAttribute("viewBox",`0 0 ${width} ${height}`);svg.setAttribute("width",String(width));svg.setAttribute("height",String(height));
    const paths=[...board.querySelectorAll<HTMLElement>("[data-material-link-card][data-stage-id]")].flatMap(card=>{
      const stage=board.querySelector<HTMLElement>(`[data-stage-drop="${CSS.escape(card.dataset.stageId||"")}"]`);if(!stage)return[];
      const a=card.getBoundingClientRect(),b=stage.getBoundingClientRect(),x1=a.right-frame.left,y1=a.top+a.height/2-frame.top,x2=b.left-frame.left,y2=b.top+b.height/2-frame.top,bend=Math.max(36,(x2-x1)*.4);
      return [`<path d="M ${x1} ${y1} C ${x1+bend} ${y1}, ${x2-bend} ${y2}, ${x2} ${y2}"></path>`];
    });svg.innerHTML=paths.join("");
  }
  private render(): void {
    const s=this.snapshot;
    const projection=projectAtlasMaterialsPageV1({materials:s.materials,stages:s.stages,columns:s.columns,agenda:s.agenda,documents:s.documents,query:s.query,page:s.page,activeStage:s.activeStage,statusFilter:s.statusFilter,hiddenColumns:s.hiddenColumns,editing:s.editing,transition:s.transition,transitionHistory:s.transitionHistory,transitionAttachments:s.transitionAttachments,presentation:materialsPresentation});
    const {rows,pages,page,selected,formOpen,baseColumns,shownColumns,tableRows,stageOptions,stageAllocations,canvasMaterials,history:historyRows,transitionStage,statusOptions}=projection;
    const customColumns=s.columns;
    const input=(name:string,label:string,value:unknown,type="text",required=false)=>`<label>${label}<input name="${name}" type="${type}" value="${this.escape(value)}"${required?" required":""}></label>`;
    const stageCanvas=stageAllocations.map(({stage,allocatedCount,agenda,agendaPreview})=>{
      return `<article class="atlas-canvas-stage" data-stage-drop="${stage.id}" data-stage-label="${this.escape(stage.name)}"><span class="atlas-eyebrow">ETAPA · ${this.escape(stage.id)}</span><h3>${this.escape(stage.name)}</h3><small>${allocatedCount} notas persistidas · ${agenda.length} eventos de agenda</small><section class="atlas-material-stage-context"><b>Agenda e registros relacionados</b>${agendaPreview.length?agendaPreview.map(event=>`<p>${this.escape(event.date)} · ${this.escape(event.title)} <small>${this.escape(event.status)}</small></p>`).join(""):`<p class="atlas-muted">Não há eventos de agenda relacionados registrados.</p>`}</section>${this.stageAiPreviewMarkup(stage)}<button type="button" data-add-stage="${stage.id}">＋ Adicionar nota à etapa</button></article>`;
    }).join("");
    const canvasMaterialsMarkup=canvasMaterials.map(({material:item,documents,statusLabel,stageLabel})=>{return `<article class="atlas-link-card${item.stageId?" atlas-linked":""}" data-material-link-card="${this.escape(item.id)}" data-stage-id="${item.stageId||""}" draggable="true"><div><span class="atlas-eyebrow">NOTA · ${this.escape(item.id)}</span><b>${this.escape(item.name)}</b><small>${item.plannedQuantity} ${this.escape(item.unit)} · ${this.escape(statusLabel)} · ${this.escape(stageLabel)}</small>${documents.length?`<div class="atlas-material-documents"><small>DOCUMENTOS VINCULADOS</small>${documents.map(document=>`<button type="button" data-material-document-open="${this.escape(document.id)}">${this.escape(document.title||document.fileName||"Documento")}${document.fileName?` · ${this.escape(document.fileName)}`:""}</button>`).join("")}</div>`:""}</div><div class="atlas-actions">${item.stageId?`<button type="button" data-unlink="${this.escape(item.id)}">Remover vínculo</button>`:""}<button type="button" data-transition="${this.escape(item.id)}">Registrar estado</button><button type="button" data-edit="${this.escape(item.id)}">Editar</button></div></article>`;}).join("")||`<p class="atlas-empty">Nenhuma nota persistida corresponde aos filtros.</p>`;
    const history=historyRows.map(({record,beforeQuantity,beforeUnit,afterQuantity,afterUnit,afterDescription,documents})=>`<article><b>${this.escape(record.id)} · ${this.escape(record.data)} ${this.escape(record.hora||"")}</b><p>${this.escape(beforeQuantity||"—")} ${this.escape(beforeUnit)} → ${this.escape(afterQuantity)} ${this.escape(afterUnit)}</p><p>${this.escape(afterDescription)}</p>${documents.map(file=>`<button type="button" data-material-file="${this.escape(file.fileUrl)}" data-material-file-name="${this.escape(file.fileName)}">${this.escape(file.title||"Comprovante")} · ${this.escape(file.fileName)}</button>`).join("")||`<small>Sem comprovantes anexados.</small>`}</article>`).join("");
    const transition=s.transition;
    const stageFormOptions=stageOptions.map(({stage,selected:isSelected})=>`<option value="${stage.id}" ${isSelected?"selected":""}>${this.escape(stage.name)}</option>`).join("");
    const fieldValues=selected;
    const form= formOpen?`<form class="atlas-material-form" data-form><div class="atlas-material-toolbar"><div><span class="atlas-eyebrow">CADASTRO OPERACIONAL</span><h2>${fieldValues?"Editar nota":"Nova nota"}</h2></div><button type="button" data-cancel>Cancelar</button></div><div class="atlas-fields">${input("name","Item",fieldValues?.name||"","text",true)}<label>Etapa<select name="stageId"><option value="">Sem etapa</option>${stageFormOptions}</select></label>${input("activityName","Atividade",fieldValues?.activityName||"")}${input("unit","Unidade",fieldValues?.unit||"un.")}${input("plannedQuantity","Quantidade prevista",fieldValues?.plannedQuantity||0,"number")}${input("receivedQuantity","Quantidade recebida",fieldValues?.receivedQuantity||0,"number")}${input("usedQuantity","Quantidade utilizada",fieldValues?.usedQuantity||0,"number")}<label>Situação<select name="status">${["Planejado","Em andamento","Adequado","Atenção","Crítico","Concluído"].map(value=>`<option ${fieldValues?.status===value?"selected":""}>${value}</option>`).join("")}</select></label><label class="atlas-wide">Descrição e uso<textarea name="scope">${this.escape(fieldValues?.scope||"")}</textarea></label>${customColumns.map(column=>input(`property:${column.id}`,column.label,fieldValues?.properties?.[column.id]||"")).join("")}</div>${s.error?`<p role="alert">${this.escape(s.error)}</p>`:""}<button class="atlas-primary" type="submit" ${s.saving?"disabled":""}>${s.saving?"Salvando…":fieldValues?"Salvar alterações":"Cadastrar nota"}</button></form>`:"";
    const listRows=tableRows.map(({item,cells})=>`<tr>${cells.map(({key,value})=>`<td><button type="button" data-sheet-cell="${this.escape(item.id)}" data-sheet-field="${this.escape(key)}" aria-selected="false">${this.escape(value)}</button></td>`).join("")}<td><div class="atlas-actions"><button type="button" data-transition="${this.escape(item.id)}">Registrar estado</button><button type="button" data-edit="${this.escape(item.id)}">Editar</button><button type="button" data-delete="${this.escape(item.id)}">Excluir</button></div></td></tr>`).join("");
    const table=`<div class="atlas-material-card"><div class="atlas-stage-heading"><h2>Notas cadastradas</h2><p>${rows.length} itens · página ${page} de ${pages}</p></div>${s.isNative?`<div class="atlas-sheet-controls">${baseColumns.map(([id,label])=>`<label><input type="checkbox" data-column-toggle="${this.escape(id)}" ${s.hiddenColumns.includes(id)?"":"checked"}> ${this.escape(label)}</label>`).join("")}<form data-column-form><input name="label" aria-label="Nova propriedade" placeholder="Nova propriedade"><button type="submit">Adicionar coluna</button></form>${customColumns.map(column=>`<button type="button" data-column-delete="${this.escape(column.id)}">Remover ${this.escape(column.label)}</button>`).join("")}</div>`:`<p class="atlas-muted" style="padding:12px">Colunas e propriedades configuradas em Configurações.</p>`}<div class="atlas-table-scroll"><table><thead><tr>${shownColumns.map(([,label])=>`<th>${this.escape(label)}</th>`).join("")}<th>Ações</th></tr></thead><tbody>${listRows||`<tr><td class="atlas-empty" colspan="${shownColumns.length+1}">Nenhuma nota corresponde aos filtros.</td></tr>`}</tbody></table></div><footer><button type="button" data-page="${Math.max(1,page-1)}" ${page<=1?"disabled":""}>Anterior</button><span>${page} / ${pages}</span><button type="button" data-page="${Math.min(pages,page+1)}" ${page>=pages?"disabled":""}>Próxima</button></footer></div>`;
    const transitionDialog=transition?`<dialog class="atlas-transition" open><div><header><div><span class="atlas-eyebrow">REGISTRO DE MOVIMENTAÇÃO</span><h2>${this.escape(transition.name||"Novo material")}</h2><p>${this.escape(transitionStage?.name||"Material sem etapa")}</p></div><button type="button" data-transition-close>Fechar</button></header><form data-transition-form><div class="atlas-fields">${input("name","Material",transition.name,"text",true)}${input("materialNumber","Número do material",transition.id,"text",true)}<label>Etapa<select name="stageId" required>${stageFormOptions}</select></label>${input("activityName","Atividade",transition.activityName)}${input("quantity","Quantidade",transition.receivedQuantity,"number",true)}${input("unit","Unidade",transition.unit)}${input("status","Situação",transition.status)}${input("documentNumber","Número do documento","")}<label class="atlas-wide">Descrição da movimentação<textarea name="description" required></textarea></label><label class="atlas-wide">Descrição do comprovante<textarea name="documentDescription"></textarea></label><label class="atlas-wide">Comprovantes<input name="documents" type="file" multiple accept="application/pdf,image/jpeg,image/png,image/webp"></label></div>${s.error?`<p role="alert">${this.escape(s.error)}</p>`:""}<button class="atlas-primary" type="submit" ${s.saving?"disabled":""}>${s.saving?"Salvando…":"Registrar movimentação"}</button></form><section class="atlas-transition-history"><h3>Histórico persistido</h3>${history||"<p class=atlas-muted>Carregando histórico…</p>"}</section></div></dialog>`:"";
    this.innerHTML=`${materialsStyles}${materialsAiPreviewStyles}<section class="atlas-materials"><header><div><span class="atlas-eyebrow">OPERAÇÃO · NOTAS</span><h1>Notas</h1><p>Notas operacionais, itens vinculados às etapas e histórico persistido.</p></div><div class="atlas-actions"><button type="button" data-refresh>Atualizar</button><button type="button" class="atlas-primary" data-new>Nova nota</button></div></header>${s.error&&!formOpen?`<p role="alert">${this.escape(s.error)}</p>`:""}${s.status==="loading"?`<p>Carregando notas do banco operacional…</p>`:""}<nav class="atlas-stage-tabs" aria-label="Notas por etapa"><button type="button" data-stage="inventory" aria-selected="${s.activeStage==="inventory"}">Todos <small>${s.materials.length}</small></button>${stageAllocations.map(({stage,selected,allocatedCount})=>`<button type="button" data-stage="${stage.id}" aria-selected="${selected}">${this.escape(stage.name)} <small>${allocatedCount}</small></button>`).join("")}</nav><div class="atlas-material-toolbar"><label>Buscar nota<input data-search type="search" value="${this.escape(s.query)}" placeholder="Nome, atividade, etapa ou descrição"></label><label>Situação<select data-status-filter><option value="all">Todas as situações</option>${statusOptions.map(({value,label,selected})=>`<option value="${this.escape(value)}" ${selected?"selected":""}>${this.escape(label)}</option>`).join("")}</select></label><nav class="atlas-view-tabs"><button type="button" data-view-tab="canvas" aria-pressed="${s.pageTab==="canvas"}">Alocação por etapa</button><button type="button" data-view-tab="list" aria-pressed="${s.pageTab==="list"}">Lista e cadastro</button></nav></div>${form}${s.pageTab==="canvas"?`<div class="atlas-material-card"><div class="atlas-stage-heading"><h2>Distribuição das notas por etapa</h2><p>Arraste uma nota até uma etapa para persistir sua alocação.</p></div><div class="atlas-canvas" data-canvas><svg class="atlas-canvas-links" data-links aria-hidden="true"></svg><div class="atlas-canvas-column">${stageCanvas||`<p class="atlas-empty">Não há etapas operacionais cadastradas.</p>`}</div><div class="atlas-canvas-column">${canvasMaterialsMarkup}</div></div></div>`:table}${transitionDialog}</section>`;
    queueMicrotask(()=>this.drawLinks());
  }
  connectedCallback(): void {
    this.addEventListener("input",event=>{const t=event.target;if(t instanceof HTMLInputElement&&t.matches("[data-search]")){const cursor=t.selectionStart;this.state.next(s=>({...s,query:t.value,page:1}));const next=this.querySelector<HTMLInputElement>("[data-search]");next?.focus();if(cursor!==null)next?.setSelectionRange(cursor,cursor);}});
    this.addEventListener("click",event=>{const t=event.target;if(!(t instanceof Element))return;
      if(t.closest("[data-refresh]")){this.dispatchEvent(new CustomEvent("atlas:materials-refresh",{bubbles:true,detail:{element:this}}));return;}
      if(t.closest("[data-new]")){this.state.next(s=>({...s,editing:null,error:null,pageTab:"list",activeStage:"inventory"}));return;}
      if(t.closest("[data-cancel]")){this.state.next(s=>({...s,editing:false,error:null}));return;}
      if(t.closest("[data-transition-close]")){this.state.next(s=>({...s,transition:null,transitionHistory:[],transitionAttachments:[],error:null}));return;}
      const viewTab=t.closest<HTMLElement>("[data-view-tab]");if(viewTab){this.state.next(s=>({...s,pageTab:viewTab.dataset.viewTab as "canvas"|"list"}));return;}
      const status=t.closest<HTMLSelectElement>("[data-status-filter]");if(status)return;
      const tab=t.closest<HTMLElement>("[data-stage]");if(tab){this.state.next(s=>({...s,activeStage:tab.dataset.stage==="inventory"?"inventory":Number(tab.dataset.stage),editing:false,page:1}));return;}
      const pageButton=t.closest<HTMLElement>("[data-page]");if(pageButton){this.state.next(s=>({...s,page:Math.max(1,Number(pageButton.dataset.page)||1)}));return;}
      const newStage=t.closest<HTMLElement>("[data-add-stage]");if(newStage){const stageId=Number(newStage.dataset.addStage),stage=this.snapshot.stages.find(item=>item.id===stageId);if(stage)this.openTransition({id:`MAT-${crypto.randomUUID()}`,name:"",unit:"un.",plannedQuantity:0,receivedQuantity:0,usedQuantity:0,status:"Dimensionar",stageId,stageName:stage.name,activityName:"",scope:"",updatedAt:"",properties:{}},true);return;}
      const unlink=t.closest<HTMLElement>("[data-unlink]");if(unlink){const material=this.snapshot.materials.find(item=>item.id===unlink.dataset.unlink);if(material&&confirm(`Remover ${material.name} da etapa ${material.stageName}?`))this.dispatchEvent(new CustomEvent<AtlasMaterialAllocationCommandV1>("atlas:material-allocate",{bubbles:true,detail:{element:this,id:material.id,stageId:null}}));return;}
      const allocateStage=t.closest<HTMLElement>("[data-stage-drop]");if(allocateStage){const dragging=this.dataset.dragMaterial;if(dragging){delete this.dataset.dragMaterial;this.dispatchEvent(new CustomEvent<AtlasMaterialAllocationCommandV1>("atlas:material-allocate",{bubbles:true,detail:{element:this,id:dragging,stageId:Number(allocateStage.dataset.stageDrop)}}));return;}}
      const materialFile=t.closest<HTMLElement>("[data-material-file]");if(materialFile){this.dispatchEvent(new CustomEvent<AtlasMaterialFileOpenCommandV1>("atlas:material-file",{bubbles:true,detail:{element:this,fileUrl:materialFile.dataset.materialFile||"",fileName:materialFile.dataset.materialFileName||"comprovante"}}));return;}
      const projectDocument=t.closest<HTMLElement>("[data-material-document-open]");if(projectDocument){this.dispatchEvent(new CustomEvent<AtlasProjectDocumentOpenCommandV1<AtlasMaterials>>("atlas:document-open",{bubbles:true,detail:{element:this,id:projectDocument.dataset.materialDocumentOpen||""}}));return;}
      const transition=t.closest<HTMLElement>("[data-transition]");if(transition){const item=this.snapshot.materials.find(row=>row.id===transition.dataset.transition);if(item)this.openTransition(item,false);return;}
      const edit=t.closest<HTMLElement>("[data-edit]");if(edit){const material=this.snapshot.materials.find(item=>item.id===edit.dataset.edit);if(material)this.state.next(s=>({...s,editing:material,error:null,pageTab:"list",activeStage:"inventory"}));return;}
      const del=t.closest<HTMLElement>("[data-delete]");if(del){const item=this.snapshot.materials.find(row=>row.id===del.dataset.delete);if(item&&confirm(`Excluir ${item.name} do cadastro operacional?`))this.dispatchEvent(new CustomEvent<AtlasMaterialDeleteCommandV1>("atlas:material-delete",{bubbles:true,detail:{element:this,id:item.id}}));return;}
      const columnDelete=t.closest<HTMLElement>("[data-column-delete]");if(columnDelete){const columnId=columnDelete.dataset.columnDelete;if(confirm("Excluir esta propriedade e os seus valores persistidos?"))this.dispatchEvent(new CustomEvent<AtlasMaterialColumnDeleteCommandV1>("atlas:material-column-delete",{bubbles:true,detail:{element:this,id:columnId}}));return;}
      const toggle=t.closest<HTMLInputElement>("[data-column-toggle]");if(toggle){const hidden=toggle.checked?this.snapshot.hiddenColumns.filter(id=>id!==toggle.dataset.columnToggle):[...new Set([...this.snapshot.hiddenColumns,String(toggle.dataset.columnToggle)])];writeAtlasMaterialHiddenColumns(hidden);this.state.next(s=>({...s,hiddenColumns:hidden}));return;}
      const cell=t.closest<HTMLElement>("[data-sheet-cell]");if(cell){this.querySelectorAll("[data-sheet-cell]").forEach(node=>node.setAttribute("aria-selected","false"));cell.setAttribute("aria-selected","true");const item=this.snapshot.materials.find(row=>row.id===cell.dataset.sheetCell);const label=this.snapshot.columns.find(column=>column.id===cell.dataset.sheetField)?.label||cell.dataset.sheetField||"";const selection=this.querySelector("[data-sheet-selection]");if(selection)selection.textContent=`${item?.name||cell.dataset.sheetCell} · ${label}`;return;}
    });
    this.addEventListener("change",event=>{const t=event.target;if(t instanceof HTMLSelectElement&&t.matches("[data-status-filter]"))this.state.next(s=>({...s,statusFilter:t.value,page:1}));});
    this.addEventListener("dragstart",event=>{const card=(event.target as Element)?.closest<HTMLElement>("[data-material-link-card]");if(card){this.dataset.dragMaterial=card.dataset.materialLinkCard||"";if(event.dataTransfer)event.dataTransfer.setData("text/plain",this.dataset.dragMaterial);}});
    this.addEventListener("dragover",event=>{const stage=(event.target as Element)?.closest<HTMLElement>("[data-stage-drop]");if(stage){event.preventDefault();stage.dataset.dropActive="true";}});
    this.addEventListener("dragleave",event=>{const stage=(event.target as Element)?.closest<HTMLElement>("[data-stage-drop]");if(stage)delete stage.dataset.dropActive;});
    this.addEventListener("drop",event=>{const stage=(event.target as Element)?.closest<HTMLElement>("[data-stage-drop]");if(stage){event.preventDefault();delete stage.dataset.dropActive;const id=event.dataTransfer?.getData("text/plain")||this.dataset.dragMaterial;if(id)this.dispatchEvent(new CustomEvent<AtlasMaterialAllocationCommandV1>("atlas:material-allocate",{bubbles:true,detail:{element:this,id,stageId:Number(stage.dataset.stageDrop)}}));delete this.dataset.dragMaterial;}});
    this.addEventListener("submit",event=>{const form=event.target;if(!(form instanceof HTMLFormElement))return;event.preventDefault();
      if(form.matches("[data-form]")){const data=new FormData(form),current=this.snapshot.editing,draft=buildAtlasMaterialSaveDraftV1({values:Object.fromEntries(data.entries()),columns:this.snapshot.columns});if(!draft.ok){this.setError(draft.error);return;}this.state.next(s=>({...s,saving:true,error:null}));this.dispatchEvent(new CustomEvent<AtlasMaterialSaveCommandV1>("atlas:material-save",{bubbles:true,detail:{element:this,id:current&&typeof current==="object"?current.id:null,payload:draft.payload}}));return;}
      if(form.matches("[data-column-form]")){const label=String(new FormData(form).get("label")||"").trim();if(label)this.dispatchEvent(new CustomEvent<AtlasMaterialColumnSaveCommandV1>("atlas:material-column-save",{bubbles:true,detail:{element:this,label}}));return;}
       if(form.matches("[data-transition-form]")){const data=new FormData(form),input=form.elements.namedItem("documents") as HTMLInputElement,material=this.snapshot.transition;if(!material)return;const draft=buildAtlasMaterialTransitionDraftV1({values:Object.fromEntries(data.entries()),files:Array.from(input?.files||[])});this.state.next(s=>({...s,saving:true,error:null}));this.dispatchEvent(new CustomEvent<AtlasMaterialTransitionSaveCommandV1>("atlas:material-transition-save",{bubbles:true,detail:{element:this,material,draft:!this.snapshot.materials.some(item=>item.id===material.id),draftFields:draft}}));}
    });
    this.addEventListener("dblclick",event=>{const button=(event.target as Element)?.closest<HTMLElement>("[data-sheet-cell]");if(!button)return;const material=this.snapshot.materials.find(item=>item.id===button.dataset.sheetCell),field=button.dataset.sheetField;if(!material||!field)return;const editor=projectAtlasMaterialInlineEditorV1(material,field);if(!editor)return;const input=document.createElement(editor.element);input.className="atlas-sheet-inline-editor";input.value=editor.value;if(editor.numeric){(input as HTMLInputElement).type="number";(input as HTMLInputElement).min="0";(input as HTMLInputElement).step="any";}button.hidden=true;button.after(input);input.focus();input.select?.();const cancel=()=>{input.remove();button.hidden=false;};const save=()=>{const payload=buildAtlasMaterialInlineEditPayloadV1({material,field,value:input.value});if(!payload){cancel();return;}this.dispatchEvent(new CustomEvent<AtlasMaterialSaveCommandV1>("atlas:material-save",{bubbles:true,detail:{element:this,id:material.id,payload}}));input.remove();};input.addEventListener("keydown",keyEvent=>{const keyboard=keyEvent as KeyboardEvent;if(keyboard.key==="Escape"){keyboard.preventDefault();cancel();}if(keyboard.key==="Enter"&&input.tagName!=="TEXTAREA"){keyboard.preventDefault();save();}});input.addEventListener("blur",cancel,{once:true});input.addEventListener("change",save,{once:true});});
    this.renderSafely();this.dispatchEvent(new CustomEvent("atlas:materials-connected",{bubbles:true,detail:{element:this}}));
  }
  private openTransition(material:OperationalMaterial,draft:boolean):void { this.state.next(s=>({...s,transition:material,transitionHistory:[],transitionAttachments:[],error:null,saving:false}));this.dispatchEvent(new CustomEvent<AtlasMaterialTransitionOpenCommandV1>("atlas:material-transition-open",{bubbles:true,detail:{element:this,material,draft}})); }
}
if(!customElements.get("atlas-materials"))customElements.define("atlas-materials",AtlasMaterials);

type AgendaState={events:OperationalAgendaEvent[];stages:OperationalStage[];materials:OperationalMaterial[];week:string;selectedDate:string;presentation:"status"|"timeline";calendarOpen:boolean;editor:OperationalAgendaEvent|null|false;relatedFrom:string;detailMode:boolean;notificationsEnabled:boolean;recordFormOpen:boolean;recordFeedback:string|null;error:string|null;loading:boolean;saving:boolean};
type AgendaSetter=(previous:AgendaState)=>AgendaState;
type AgendaPageCommandState=Pick<AgendaState,"events"|"week"|"selectedDate"|"presentation"|"calendarOpen"|"editor"|"relatedFrom"|"detailMode"|"recordFormOpen"|"recordFeedback"|"error">;
type AgendaPageCommand={kind:"toggle-calendar"}|{kind:"new-event"}|{kind:"close-editor"}|{kind:"navigate-week";delta:number}|{kind:"set-presentation";value:unknown}|{kind:"select-day";date:string}|{kind:"edit-event";id:string}|{kind:"create-related-event";sourceId:string}|{kind:"open-record-form"}|{kind:"close-record-form"};
function createAgendaPageCommandController(ports:{readState:()=>AgendaPageCommandState;commit:(patch:Partial<AgendaPageCommandState>)=>void}):{dispatch:(command:AgendaPageCommand)=>boolean}{
  return Object.freeze({dispatch(command){const state=ports.readState();let patch:Partial<AgendaPageCommandState>={};
    if(command.kind==="toggle-calendar")patch={calendarOpen:!state.calendarOpen};
    else if(command.kind==="new-event")patch={editor:null,relatedFrom:"",error:null};
    else if(command.kind==="close-editor")patch={editor:false,relatedFrom:"",error:null};
    else if(command.kind==="navigate-week"){const date=new Date(`${state.week}T12:00:00`);if(Number.isFinite(date.getTime())){date.setDate(date.getDate()+Number(command.delta||0)*7);const next=atlasAgendaPageDateIsoV1(date);patch={week:next,selectedDate:next};}}
    else if(command.kind==="set-presentation"){if(command.value==="status"||command.value==="timeline")patch={presentation:command.value};}
    else if(command.kind==="select-day")patch={selectedDate:String(command.date||""),presentation:"timeline"};
    else if(command.kind==="edit-event"){const event=state.events.find(item=>String(item.id)===String(command.id));if(event)patch={editor:event,relatedFrom:event.relatedFrom||"",error:null};}
    else if(command.kind==="create-related-event")patch={editor:null,relatedFrom:command.sourceId,error:null};
    else if(command.kind==="open-record-form")patch={recordFormOpen:true,recordFeedback:null,error:null};
    else if(command.kind==="close-record-form")patch={recordFormOpen:false,recordFeedback:null};
    if(!Object.keys(patch).length)return false;ports.commit(patch);return true;}});
}
