/** Live stage diary; all filters, disclosure, and form state are owned by this element. */
export class AtlasProgress extends AtlasHTMLElementBase {
  private snapshot: ProgressState;
  private readonly state: AtomicState<ProgressState>;

  constructor() {
    super();
    const initial: ProgressState = { stages: [], records: [], materials: [], agendaEvents: [], selectedStageId: "", period: "today", expandedRecordId: null, formOpen: false, loading: true, saving: false, error: null, feedback: "" };
    function* state(value: ProgressState): Generator<ProgressState, never, ProgressSetter> { while (true) value = (yield value)(value); }
    const iterator = state(initial); iterator.next(); this.snapshot = initial;
    this.state = { next: setter => { this.snapshot = iterator.next(setter).value; this.render(); return this.snapshot; } };
  }

  connectedCallback(): void {
    this.render();
    this.dispatchEvent(new CustomEvent("atlas:progress-connected", { bubbles: true, detail: { element: this } }));
  }

  setLoading(): void { this.state.next(s => ({ ...s, loading: true, error: null })); }
  setRouteStage(stageId: unknown): void { this.state.next(s => ({ ...s, selectedStageId: String(stageId ?? "") })); }
  setData(data: Pick<ProgressState, "stages" | "records" | "materials" | "agendaEvents">): void {
    this.state.next(s => ({ ...s, ...data, selectedStageId: projectAtlasProgressSelectedStageIdV1(data.stages, s.selectedStageId), loading: false, error: null }));
  }
  setSaving(saving: boolean): void { this.state.next(s => ({ ...s, saving, error: null, feedback: saving ? "Salvando registro…" : s.feedback })); }
  setError(message: string): void { this.state.next(s => ({ ...s, loading: false, saving: false, error: message })); }
  setFeedback(message: string): void { this.state.next(s => ({ ...s, saving: false, feedback: message })); }

  private esc(value: unknown): string { return String(value ?? "").replace(/[&<>"']/g, char => ({ "&":"&amp;", "<":"&lt;", ">":"&gt;", '"':"&quot;", "'":"&#39;" }[char] || char)); }
  private render(): void {
    const s = this.snapshot, esc = (value: unknown) => this.esc(value);
    const projection = projectAtlasProgressPageV1({ stages: s.stages, records: s.records, materials: s.materials, agendaEvents: s.agendaEvents, selectedStageId: s.selectedStageId, period: s.period });
    const { stage, today, stageRecords, filteredRecords, completedRecordIds, pendingCount, upcoming, materials, progressPercent, mapOverlay } = projection;
    const completedIds = new Set(completedRecordIds);
    const recordsMarkup = filteredRecords.map(record => {
      const complete = completedIds.has(String(record.id));
      const evidence = String(record.evidenceUri || "").trim();
      const safeEvidence = /^(https?:\/\/|\/)/i.test(evidence) ? evidence : "";
      const expanded = s.expandedRecordId === record.id;
      return `<article class="atlas-record" data-record="${esc(record.id)}" data-complete="${complete}"><time>${esc(record.hora || "—")}<small>${esc(record.data || "Data não informada")}</small></time><i class="atlas-marker" aria-hidden="true"></i><div class="atlas-record-main"><header><div><span class="atlas-eyebrow">${esc(record.atividade || "Registro de campo")}</span><h3>${esc(record.detalhes || "Registro sem descrição")}</h3><div class="atlas-record-meta"><span>${esc(record.responsavel || "Responsável não informado")}</span><span>${esc(record.etapa || stage?.name || "Etapa não informada")}</span></div></div><span class="atlas-status">${esc(record.status || "Status não informado")}</span></header>${expanded ? `<div class="atlas-record-detail">${record.mapArea ? `<span>Área vinculada: ${esc(typeof record.mapArea === "string" ? record.mapArea : JSON.stringify(record.mapArea))}</span>` : ""}${safeEvidence ? `<a href="${esc(safeEvidence)}" target="_blank" rel="noopener noreferrer">Abrir evidência persistida</a>` : evidence ? `<span>Evidência registrada: ${esc(evidence)}</span>` : `<span>Sem evidência vinculada a este registro.</span>`}</div>` : ""}</div></article>`;
    }).join("");
    const activityOptions = (stage?.activities || []).map(activity => `<option value="${esc(activity.name)}">${esc(activity.name)}</option>`).join("");
    const defaultDate = today;
    this.innerHTML = `${progressStyles}<section class="atlas-progress-page"><header><div><span class="atlas-eyebrow">DIÁRIO DE OBRA · ${esc(stage?.name || "Etapa")}</span><h1>Andamento da obra</h1><p class="atlas-muted">Registros de campo, evidências vinculadas e compromissos persistidos para a etapa.</p></div><div class="atlas-actions"><button type="button" data-progress-refresh>Atualizar</button><button type="button" class="atlas-primary" data-progress-new ${s.loading ? "disabled" : ""} aria-expanded="${s.formOpen}" aria-controls="atlas-progress-form">+ Novo apontamento</button></div></header>${stage ? `<section class="atlas-map" aria-label="Mapa da etapa"><map-scene data-stage-header-map data-stage="${esc(stage.name)}" aria-label="Mapa operacional de ${esc(stage.name)}"></map-scene></section>` : ""}${s.error ? `<p class="atlas-error" role="alert">${esc(s.error)}</p>` : ""}<section class="atlas-toolbar"><div class="atlas-periods" role="group" aria-label="Período do diário">${([["today","Hoje"],["yesterday","Ontem"],["week","Semana atual"],["all","Todo o período"]] as Array<[ProgressPeriod,string]>).map(([period,label]) => `<button type="button" data-progress-period="${period}" aria-pressed="${s.period === period}">${label}</button>`).join("")}</div><label class="atlas-stage-select">Etapa<select data-progress-stage>${s.stages.length ? s.stages.map(item => `<option value="${esc(item.id)}" ${String(item.id) === s.selectedStageId ? "selected" : ""}>${esc(item.name)}</option>`).join("") : `<option value="">Nenhuma etapa cadastrada</option>`}</select></label><span class="atlas-sync">${s.loading ? "Atualizando dados do serviço…" : `${stageRecords.length} registro(s) · sincronizado com o serviço`}</span></section><div class="atlas-layout"><main class="atlas-journal"><section class="atlas-panel"><header><div><span class="atlas-eyebrow">REGISTROS PERSISTIDOS</span><h2>Diário da etapa</h2></div><span class="atlas-count">${filteredRecords.length} neste período</span></header>${s.loading ? `<p class="atlas-muted">Carregando diário operacional…</p>` : recordsMarkup ? `<div class="atlas-records">${recordsMarkup}</div>` : `<p class="atlas-empty">Nenhum registro persistido corresponde a esta etapa e período.</p>`}</section>${s.formOpen ? `<form class="atlas-panel atlas-form" id="atlas-progress-form" data-progress-form><header><div><span class="atlas-eyebrow">NOVO APONTAMENTO</span><h2>Registrar avanço ou ocorrência</h2></div><button type="button" data-progress-cancel aria-label="Fechar formulário">Cancelar</button></header><div class="atlas-fields"><label>Etapa<select name="etapa" required>${s.stages.length ? s.stages.map(item => `<option value="${esc(item.id)}" ${String(item.id) === s.selectedStageId ? "selected" : ""}>${esc(item.name)}</option>`).join("") : `<option value="">Nenhuma etapa cadastrada</option>`}</select></label><label>Atividade<select name="atividade" data-progress-activity required>${activityOptions || `<option value="">Nenhuma atividade cadastrada para esta etapa</option>`}</select></label><label>Data<input type="date" name="data" value="${defaultDate}" required></label><label>Hora<input type="time" name="hora" value="${new Date().toTimeString().slice(0,5)}" required></label><label>Responsável<input name="responsavel" maxlength="160" required placeholder="Nome do responsável"></label><label>Status<select name="status"><option>Pendente</option><option>Em validação</option><option>Concluído</option></select></label><label class="atlas-wide">Detalhes / medição<textarea name="detalhes" maxlength="2000" required placeholder="Descreva o avanço, a ocorrência ou a medição observada"></textarea></label><label class="atlas-wide">Referência da evidência<input name="evidenceUri" maxlength="500" placeholder="URL ou caminho persistido, se houver"></label></div>${s.error ? `<p class="atlas-error" role="alert">${esc(s.error)}</p>` : ""}<p class="atlas-feedback" aria-live="polite">${esc(s.feedback)}</p><footer><button type="button" data-progress-cancel>Cancelar</button><button type="submit" class="atlas-primary" ${s.saving || !activityOptions ? "disabled" : ""}>${s.saving ? "Salvando…" : "Salvar no diário"}</button></footer></form>` : ""}</main><aside class="atlas-rail"><section class="atlas-panel"><header><div><span class="atlas-eyebrow">RESUMO</span><h2>Etapa em foco</h2></div></header><div class="atlas-metrics"><div><strong>${stageRecords.length}</strong><span>Registros</span></div><div><strong>${pendingCount}</strong><span>Em aberto</span></div><div><strong>${progressPercent}%</strong><span>Progresso</span></div></div>${stage ? `<div class="atlas-bar"><i style="width:${progressPercent}%"></i></div><p class="atlas-muted">${esc(stage.name)}${stage.owner ? ` · ${esc(stage.owner)}` : ""}</p>` : ""}</section><section class="atlas-panel"><header><div><span class="atlas-eyebrow">AGENDA</span><h2>Próximos compromissos</h2></div></header>${upcoming.length ? upcoming.map(event => `<div class="atlas-next"><time>${esc(event.date)} · ${esc(event.start)}</time><strong>${esc(event.title)}</strong><small>${esc(event.status)}${event.owner ? ` · ${esc(event.owner)}` : ""}</small></div>`).join("") : `<p class="atlas-empty">Não há compromissos futuros registrados para esta etapa.</p>`}<button type="button" data-progress-navigate="agenda">Abrir agenda</button></section><section class="atlas-panel"><header><div><span class="atlas-eyebrow">MATERIAIS</span><h2>Associados à etapa</h2></div><span class="atlas-count">${materials.length}</span></header>${materials.length ? `<ul class="atlas-materials">${materials.slice(0,6).map(item => `<li><span>${esc(item.name)}</span><span>${esc(item.receivedQuantity)} / ${esc(item.plannedQuantity)} ${esc(item.unit)}</span></li>`).join("")}</ul>` : `<p class="atlas-empty">Nenhum material persistido está associado à etapa.</p>`}<button type="button" data-progress-navigate="materials">Ver materiais</button></section><button type="button" data-progress-navigate="records">Abrir registros</button></aside></div><p class="atlas-feedback" aria-live="polite">${esc(s.feedback)}</p></section>`;

    const stageMap = this.querySelector<HTMLElement>("map-scene[data-stage-header-map]");
    if (stage && stageMap) {
      stageMap.dataset.overlay = mapOverlay;
      const mapHeader = document.createElement("header");
      mapHeader.className = "atlas-stage-map-header";
      mapHeader.innerHTML = `<div><span class="atlas-eyebrow">MAPA 3D · ${this.esc(stage.name)}</span><strong>Contexto físico da etapa</strong></div><span>${this.esc(stage.name)}</span>`;
      mapHeader.style.cssText = "position:absolute;z-index:2;inset:12px 12px auto auto;display:flex;justify-content:space-between;align-items:center;gap:12px;padding:10px 12px;border:1px solid #314253;border-radius:10px;background:#0d1a28e8;color:#fff";
      const mapFrame = stageMap.parentElement;
      if (mapFrame) mapFrame.style.position = "relative";
      mapHeader.querySelector("strong")!.style.cssText = "display:block;margin-top:4px;font-size:13px";
      (mapHeader.lastElementChild as HTMLElement).style.cssText = "padding:6px 9px;border:1px solid #54677a;border-radius:20px;font-size:11px";
      stageMap.before(mapHeader);
    }
    this.querySelectorAll<HTMLButtonElement>("[data-progress-period]").forEach(button => button.addEventListener("click", () => this.state.next(previous => ({ ...previous, period: button.dataset.progressPeriod as ProgressPeriod }))));
    this.querySelector<HTMLSelectElement>("[data-progress-stage]")?.addEventListener("change", event => this.state.next(previous => ({ ...previous, selectedStageId: (event.currentTarget as HTMLSelectElement).value, expandedRecordId: null })));
    this.querySelector<HTMLSelectElement>('[data-progress-form] select[name="etapa"]')?.addEventListener("change", event => {
      const stageId = (event.currentTarget as HTMLSelectElement).value, selectedStage = this.snapshot.stages.find(item => String(item.id) === stageId), activitySelect = this.querySelector<HTMLSelectElement>("[data-progress-activity]");
      if (!selectedStage || !activitySelect) return;
      const activities = selectedStage.activities || [], currentActivity = activitySelect.value, selectedActivity = activities.some(item => item.name === currentActivity) ? currentActivity : activities[0]?.name || "";
      activitySelect.innerHTML = activities.map(item => `<option value="${this.esc(item.name)}" ${item.name === selectedActivity ? "selected" : ""}>${this.esc(item.name)}</option>`).join("") || `<option value="">Nenhuma atividade cadastrada para esta etapa</option>`;
    });
    this.querySelector<HTMLButtonElement>("[data-progress-refresh]")?.addEventListener("click", () => this.dispatchEvent(new CustomEvent("atlas:progress-refresh", { bubbles: true, detail: { element: this } })));
    this.querySelector<HTMLButtonElement>("[data-progress-new]")?.addEventListener("click", () => { this.state.next(previous => ({ ...previous, formOpen: true, error: null, feedback: "" })); const focusForm = () => { const form = this.querySelector<HTMLFormElement>("[data-progress-form]"); form?.scrollIntoView({ behavior: "smooth", block: "center" }); form?.querySelector<HTMLInputElement>("[name=responsavel]")?.focus({ preventScroll: true }); }; if (typeof requestAnimationFrame === "function") requestAnimationFrame(focusForm); else focusForm(); });
    this.querySelectorAll<HTMLButtonElement>("[data-progress-cancel]").forEach(button => button.addEventListener("click", () => this.state.next(previous => ({ ...previous, formOpen: false, error: null }))));
    this.querySelectorAll<HTMLElement>("[data-record]").forEach(row => row.addEventListener("click", event => { if ((event.target as Element).closest("a,button")) return; this.state.next(previous => ({ ...previous, expandedRecordId: previous.expandedRecordId === row.dataset.record ? null : row.dataset.record || null })); }));
    this.querySelectorAll<HTMLButtonElement>("[data-progress-navigate]").forEach(button => button.addEventListener("click", () => this.dispatchEvent(new CustomEvent("atlas:navigate", { bubbles: true, detail: { view: button.dataset.progressNavigate, stageKey: stage?.key || String(stage?.id || "") } }))));
    this.querySelector<HTMLFormElement>("[data-progress-form]")?.addEventListener("submit", event => {
      event.preventDefault();
      const data = new FormData(event.currentTarget as HTMLFormElement);
      this.state.next(previous => ({ ...previous, saving: true, error: null, feedback: "Validando e enviando registro ao serviço persistente…" }));
      this.dispatchEvent(new CustomEvent("atlas:progress-record-create", { bubbles: true, detail: { element: this, values: Object.fromEntries(data.entries()) } }));
    });
  }
}
if (!customElements.get("atlas-progress")) customElements.define("atlas-progress", AtlasProgress);

/** Standalone mobile capture flow for field records. API effects stay in program.ts. */
export class AtlasPublicFieldRecords extends AtlasHTMLElementBase {
  private previewUrl = '';

  connectedCallback(): void {
    this.style.display = 'block';
    this.dataset.publicRecordsOwner = 'components-ts';
    this.render();
  }

  disconnectedCallback(): void {
    if (this.previewUrl) URL.revokeObjectURL(this.previewUrl);
    this.dispatchEvent(new CustomEvent('atlas:public-field-records-disconnected'));
  }

  private field(name: string): HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement | null {
    return this.querySelector<HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement>(`[name="${name}"]`);
  }

  private setStep(step: 'capture' | 'details'): void {
    const app = this.querySelector<HTMLElement>('.field-records-app');
    if (!app) return;
    app.dataset.step = step;
    this.querySelectorAll<HTMLElement>('[data-record-step]').forEach(panel => { panel.hidden = panel.dataset.recordStep !== step; });
    window.scrollTo({ top: 0, behavior: 'smooth' });
  }

  private setStatus(selector: string, message: string, tone = ''): void {
    const target = this.querySelector<HTMLElement>(selector);
    if (!target) return;
    target.textContent = message;
    if (tone) target.dataset.tone = tone; else delete target.dataset.tone;
  }

  private setEvidence(title: string, detail: string): void {
    const summary = this.querySelector<HTMLElement>('[data-evidence-summary]');
    if (summary) {
      const label = document.createElement('b'); label.textContent = title;
      const description = document.createElement('span'); description.textContent = detail;
      summary.replaceChildren(label, description);
    }
    const details = this.field('details');
    if (details && !details.value) details.value = String(this.field('chatNote')?.value || '');
  }

  private setMapSelectionFields(value: unknown): Record<string, unknown> | null {
    const area = normalizeAtlasPublicFieldRecordMapAreaV1(value);
    const mapArea = this.field('mapArea');
    const partIds = this.field('partIds');
    if (mapArea) mapArea.value = area ? JSON.stringify(area) : '';
    if (partIds) partIds.value = area ? area.partIds.join(',') : '';
    const form = this.querySelector<HTMLFormElement>('.field-record-form');
    if (form) {
      if (area) form.dataset.mapAreaSync = 'ready';
      else delete form.dataset.mapAreaSync;
    }
    return area;
  }

  private setNow(): void {
    const date = this.field('date'), time = this.field('time');
    const now = new Date();
    if (date) date.value = now.toISOString().slice(0, 10);
    if (time) time.value = now.toTimeString().slice(0, 5);
  }

  private applyInference(stage: string): void {
    const item = projectAtlasPublicFieldRecordInferenceV1(stage);
    const category = this.field('category');
    const progress = this.field('progress') as HTMLInputElement | null;
    const output = this.querySelector<HTMLOutputElement>('[data-progress-output]');
    if (category) category.value = item.category;
    if (progress) progress.value = String(item.progress);
    if (output) { output.value = `${item.progress}%`; output.textContent = `${item.progress}%`; }
    const card = this.querySelector<HTMLElement>('[data-inference-card]');
    if (card) {
      const label = document.createElement('span'); label.textContent = '✦ Inferência operacional';
      const title = document.createElement('b'); title.textContent = item.title;
      const reason = document.createElement('p'); reason.textContent = `${item.reason} Revise os valores antes de confirmar.`;
      card.replaceChildren(label, title, reason);
    }
    const fields = this.querySelector<HTMLElement>('[data-category-fields]');
    if (fields) fields.replaceChildren(...item.fields.map(field => {
      const label = document.createElement('label'); label.textContent = field.label;
      const input = document.createElement('input'); input.name = `inferred_${field.name}`; input.value = field.value;
      input.maxLength = 120; input.dataset.fieldLabel = field.label; label.append(input); return label;
    }));
    const form = this.querySelector<HTMLFormElement>('.field-record-form');
    if (form) form.dataset.inference = item.title;
  }

  private async readImage(file: File): Promise<string> {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.onload = () => resolve(String(reader.result || ''));
      reader.onerror = () => reject(reader.error || new Error('Não foi possível ler a imagem.'));
      reader.readAsDataURL(file);
    });
  }

  private async onSubmit(event: SubmitEvent): Promise<void> {
    event.preventDefault();
    const form = event.currentTarget as HTMLFormElement;
    const values = Object.fromEntries(new FormData(form).entries()) as Record<string, unknown>;
    const preparation = prepareAtlasPublicFieldRecordDraftV1({
      values,
      explicitArea: values.mapArea,
      paintedArea: this.querySelector<HTMLElement>('[data-mobile-record-map]')?.dataset.recordPaintArea,
      inferredFields: [...this.querySelectorAll<HTMLInputElement>('[data-category-fields] input')]
        .map(input => ({ label: input.dataset.fieldLabel, name: input.name, value: input.value })),
      inferenceTitle: form.dataset.inference || '',
    });
    if (!preparation.ok) {
      this.setStatus('[data-submit-status]', preparation.error, 'warning');
      return;
    }
    const submit = form.querySelector<HTMLButtonElement>('[type="submit"]');
    if (submit) submit.disabled = true;
    this.setStatus('[data-submit-status]', 'Enviando registro e evidência…', 'loading');
    try {
      const photo = (this.field('photo') as HTMLInputElement | null)?.files?.[0];
      const photoDataUrl = photo ? await this.readImage(photo) : '';
      const input = { ...preparation.draft, photoDataUrl };
      this.dispatchEvent(new CustomEvent('atlas:public-field-record-create', {
        bubbles: true,
        detail: { element: this, input },
      }));
    } catch (error) {
      if (submit) submit.disabled = false;
      this.setStatus('[data-submit-status]', error instanceof Error ? error.message : String(error), 'warning');
    }
  }

  setSubmissionPending(pending: boolean): void {
    const submit = this.querySelector<HTMLButtonElement>('.record-details [type="submit"]');
    if (submit) submit.disabled = pending;
    if (pending) this.setStatus('[data-submit-status]', 'Enviando registro e evidência…', 'loading');
  }

  setSubmissionError(message: string): void {
    this.setSubmissionPending(false);
    this.setStatus('[data-submit-status]', message, 'warning');
  }

  setSubmissionSuccess(id: string): void {
    const form = this.querySelector<HTMLFormElement>('.field-record-form');
    if (!form) return;
    form.reset();
    delete form.dataset.inference;
    this.setMapSelectionFields(null);
    this.setNow();
    const output = this.querySelector<HTMLOutputElement>('[data-progress-output]');
    if (output) { output.value = '0%'; output.textContent = '0%'; }
    const preview = this.querySelector<HTMLImageElement>('.field-preview');
    if (preview) { preview.hidden = true; preview.removeAttribute('src'); }
    if (this.previewUrl) URL.revokeObjectURL(this.previewUrl);
    this.previewUrl = '';
    this.querySelector<HTMLElement>('[data-category-fields]')?.replaceChildren();
    const summary = this.querySelector<HTMLElement>('[data-evidence-summary]');
    if (summary) {
      const title = document.createElement('b'); title.textContent = 'Aguardando evidência';
      const detail = document.createElement('span'); detail.textContent = 'Selecione um segmento ou adicione uma fotografia.';
      summary.replaceChildren(title, detail);
    }
    this.setStatus('[data-submit-status]', `Registro confirmado. Protocolo ${id || 'criado'}.`, 'success');
    this.setSubmissionPending(false);
  }

  private render(): void {
    this.innerHTML = `<main class="field-records-app" data-step="capture">
      <header class="field-header"><span class="field-mark" aria-hidden="true">◢</span><div><strong>Aliança Park</strong><small>CAMPO · REGISTROS</small></div><span class="field-online"><i></i> online</span></header>
      <form class="field-record-form" novalidate><input type="hidden" name="mapArea" value=""><input type="hidden" name="partIds" value="">
        <section class="record-step record-capture" data-record-step="capture"><div class="step-heading"><div><p class="eyebrow">EVIDÊNCIA DE CAMPO</p><h1>Mapa e câmera</h1></div><span>Toque em uma área ou registre uma foto</span></div>
          <div class="capture-tabs" role="tablist" aria-label="Origem da evidência"><button type="button" role="tab" aria-selected="true" data-capture-tab="map">Mapa</button><button type="button" role="tab" aria-selected="false" data-capture-tab="camera">Câmera</button></div>
          <div class="capture-panel map-capture-panel" data-capture-panel="map"><map-scene class="mobile-map-scene" data-mobile-record-map></map-scene><button type="button" class="map-paint-button" data-enable-map-paint>Selecionar segmento</button><p class="capture-help">Arraste com o dedo para mover. Ative a seleção apenas quando for pintar a área vinculada ao registro.</p></div>
          <div class="capture-panel camera-panel" data-capture-panel="camera" hidden><label class="field-camera"><input name="photo" type="file" accept="image/*" capture="environment"><span class="camera-icon">⌾</span><b>Abrir câmera</b><small>Fotografe a frente de serviço ou escolha uma imagem. Máximo de 12 MB.</small></label><img class="field-preview" alt="Prévia da evidência" hidden></div>
          <div class="message-dock"><label class="chat-entry">Mensagem do registro<textarea name="chatNote" maxlength="280" placeholder="Descreva rapidamente o que está vendo…"></textarea></label><button type="button" class="message-send" data-chat-send aria-label="Enviar mensagem">↑</button></div><p class="field-status capture-status" aria-live="polite"></p>
        </section>
        <section class="record-step record-details" data-record-step="details" hidden><div class="step-heading"><button type="button" class="back-button" data-back="capture">←</button><div><p class="eyebrow">CONFIRMAÇÃO</p><h1>Complete o registro</h1></div></div>
          <div class="evidence-summary" data-evidence-summary><b>Aguardando evidência</b><span>Selecione um segmento ou adicione uma fotografia.</span></div><section class="inference-card" data-inference-card aria-live="polite"><span>✦ Inferência operacional</span><b>Aguardando contexto</b><p>Os campos serão sugeridos conforme a área, foto e mensagem.</p></section>
          <label>Obra<select name="project" required><option value="Aliança Park">Aliança Park</option></select></label>
          <div class="field-grid"><label>Etapa<select name="stage" required><option value="Terraplanagem">Terraplanagem</option><option value="Drenagem Pluvial">Drenagem Pluvial</option><option value="Rede de Água">Rede de Água</option><option value="Rede Elétrica">Rede Elétrica</option><option value="Pavimentação">Pavimentação</option><option value="Praças / urbanização">Praças / urbanização</option></select></label><label>Natureza<select name="category" required><option value="Execução">Execução</option><option value="Medição">Medição</option><option value="Material">Material</option><option value="Qualidade / ensaio">Qualidade / ensaio</option><option value="Ocorrência">Ocorrência</option><option value="Segurança">Segurança</option></select></label></div>
          <label>Atividade<input name="activity" required maxlength="140" placeholder="Ex.: Assentamento de tubo PEAD"></label><div class="field-grid"><label>Data<input name="date" type="date" required></label><label>Hora<input name="time" type="time" required></label></div><label>Responsável<input name="responsible" required maxlength="120" placeholder="Nome do responsável no local"></label><label>Avanço físico <output data-progress-output>0%</output><input name="progress" type="range" min="0" max="100" value="0"></label><div class="category-fields" data-category-fields></div><label>Status<select name="status"><option>Em andamento</option><option>Concluído</option><option>Pendente</option><option>Bloqueado</option></select></label><label>Descrição / evidência<textarea name="details" required maxlength="1200" placeholder="Descreva a execução, a medição, a ocorrência ou o próximo passo."></textarea></label>
          <button class="primary-action" type="submit">Confirmar registro <span>→</span></button><p class="field-status" data-submit-status aria-live="polite"></p>
        </section>
      </form><footer>Os registros são enviados ao sistema operacional Aliança Park.</footer>
    </main>`;
    this.setNow();
    this.bindEvents();
  }

  private bindEvents(): void {
    const app = this.querySelector<HTMLElement>('.field-records-app');
    const form = this.querySelector<HTMLFormElement>('.field-record-form');
    if (!app || !form) return;
    this.querySelectorAll<HTMLButtonElement>('[data-back]').forEach(button => button.addEventListener('click', () => this.setStep('capture')));
    this.querySelectorAll<HTMLButtonElement>('[data-capture-tab]').forEach(tab => tab.addEventListener('click', () => {
      this.querySelectorAll<HTMLButtonElement>('[data-capture-tab]').forEach(item => item.setAttribute('aria-selected', String(item === tab)));
      this.querySelectorAll<HTMLElement>('[data-capture-panel]').forEach(panel => { panel.hidden = panel.dataset.capturePanel !== tab.dataset.captureTab; });
    }));
    this.querySelector<HTMLButtonElement>('[data-chat-send]')?.addEventListener('click', () => {
      const note = String(this.field('chatNote')?.value || '').trim();
      this.setStatus('.capture-status', note ? 'Mensagem vinculada à evidência. Selecione a área ou foto para continuar.' : 'Escreva uma mensagem ou selecione uma área do mapa.', note ? 'success' : 'warning');
    });
    this.field('progress')?.addEventListener('input', () => {
      const progress = this.field('progress') as HTMLInputElement;
      const output = this.querySelector<HTMLOutputElement>('[data-progress-output]');
      if (output) { output.value = `${progress.value}%`; output.textContent = `${progress.value}%`; }
    });
    this.querySelector<HTMLButtonElement>('[data-enable-map-paint]')?.addEventListener('click', () => {
      const map = this.querySelector<HTMLElement & { setRecordPaintMode?: (enabled: boolean, callback: (area: Record<string, any>) => void) => void }>('[data-mobile-record-map]');
      if (!map?.setRecordPaintMode) {
        this.setStatus('.capture-status', 'Preparando a cena 3D…', 'loading');
        return;
      }
      map.setRecordPaintMode(true, area => {
        const normalized = this.setMapSelectionFields(area);
        const context = projectAtlasPublicFieldRecordEvidenceContextV1({ source: 'map', nature: area.nature, label: area.label });
        const stageSelect = this.field('stage'); if (stageSelect) stageSelect.value = context.stage;
        const activity = this.field('activity'); if (activity && context.activity !== null) activity.value = context.activity;
        this.applyInference(context.stage);
        this.setEvidence(context.evidenceTitle, context.evidenceDetail);
        this.setStep('details');
        queueMicrotask(() => { if (normalized && !this.field('mapArea')?.value) this.setMapSelectionFields(map.dataset.recordPaintArea || area); });
        setTimeout(() => { if (normalized && !this.field('mapArea')?.value) this.setMapSelectionFields(map.dataset.recordPaintArea || area); }, 0);
      });
      this.setStatus('.capture-status', 'Modo de seleção ativo: toque em um lote, rua ou estrutura.', 'success');
    });
    this.field('photo')?.addEventListener('change', () => {
      const input = this.field('photo') as HTMLInputElement, file = input.files?.[0];
      const preview = this.querySelector<HTMLImageElement>('.field-preview');
      if (!file) { if (preview) { preview.hidden = true; preview.removeAttribute('src'); } return; }
      if (!file.type.startsWith('image/') || file.size > PUBLIC_FIELD_RECORD_MAX_IMAGE_BYTES_V1) {
        input.value = ''; if (preview) { preview.hidden = true; preview.removeAttribute('src'); }
        this.setStatus('.capture-status', 'Use uma imagem de até 12 MB.', 'warning'); return;
      }
      if (this.previewUrl) URL.revokeObjectURL(this.previewUrl);
      this.previewUrl = URL.createObjectURL(file);
      if (preview) { preview.src = this.previewUrl; preview.hidden = false; }
      this.setStatus('.capture-status', '');
      const note = String(this.field('chatNote')?.value || '');
      const activity = this.field('activity');
      const context = projectAtlasPublicFieldRecordEvidenceContextV1({ source: 'photo', note, label: file.name, currentActivity: activity?.value });
      const stageSelect = this.field('stage'); if (context.applyStage && stageSelect) stageSelect.value = context.stage;
      if (activity && context.activity !== null) activity.value = context.activity;
      this.applyInference(context.stage);
      this.setEvidence(context.evidenceTitle, context.evidenceDetail);
      this.setStep('details');
    });
    form.addEventListener('submit', event => { void this.onSubmit(event as SubmitEvent); });
  }
}
if (!customElements.get('atlas-public-field-records')) customElements.define('atlas-public-field-records', AtlasPublicFieldRecords);

