export interface AtlasRecordPropertyTypeViewV1 {
  type: string;
  label: string;
}

export function renderAtlasRecordPropertyValueControlV1(input: {
  type: string;
  ico(name: string): string;
}): string {
  const { type, ico } = input;
  if (type === 'map_area') return `<button type="button" class="records-property-map-v1" data-record-property-map>${ico('map-pin')} Assinalar no mapa</button><small data-record-property-map-status>Nenhuma área assinalada</small>`;
  if (type === 'boolean') return '<select data-record-property-value><option value="true">Sim</option><option value="false">Não</option></select>';
  if (type === 'select') return '<input data-record-property-options placeholder="Opções separadas por vírgula"><input data-record-property-value placeholder="Valor selecionado">';
  const inputType = type === 'number' ? 'number' : type === 'date' ? 'date' : 'text';
  return `<input data-record-property-value type="${inputType}" placeholder="Valor da propriedade">`;
}

/** Render a new, unsaved dynamic property row; listeners remain in the host adapter. */
export function renderAtlasRecordPropertyRowV1(input: {
  id: string;
  type: string;
  propertyTypes: AtlasRecordPropertyTypeViewV1[];
  esc(value: unknown): string;
  ico(name: string): string;
}): string {
  const { id, type, propertyTypes, esc, ico } = input;
  const options = propertyTypes.map(property => `<option value="${esc(property.type)}" ${property.type === type ? 'selected' : ''}>${esc(property.label)}</option>`).join('');
  const valueControl = renderAtlasRecordPropertyValueControlV1({type, ico});
  return `<article class="records-property-row-v1" data-record-property-row data-property-id="${esc(id)}" data-map-area="">
      <input data-record-property-label aria-label="Nome da propriedade" placeholder="Nome da propriedade">
      <select data-record-property-type aria-label="Tipo da propriedade">${options}</select>
      <div class="records-property-value-v1" data-record-property-value-host>${valueControl}</div>
      <button type="button" class="records-property-remove-v1" data-record-property-remove aria-label="Remover propriedade">${ico('trash-2')}</button>
    </article>`;
}

export interface AtlasRecordPropertyEntryV1 {
  id: string;
  label: string;
  type: string;
  value: unknown;
  options: string[];
}

/** Collect typed additional properties from the active record form controls. */
export function collectAtlasRecordPropertiesV1(form: HTMLFormElement): AtlasRecordPropertyEntryV1[] {
  return [...form.querySelectorAll<HTMLElement>('[data-record-property-row]')].map(row => {
    const type = row.querySelector<HTMLSelectElement>('[data-record-property-type]')?.value || 'text';
    let value: unknown = row.querySelector<HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement>('[data-record-property-value]')?.value ?? '';
    if (type === 'map_area') {
      try { value = JSON.parse(row.dataset.mapArea || 'null'); } catch { value = null; }
    }
    return {
      id: String(row.dataset.propertyId || ''),
      label: row.querySelector<HTMLInputElement>('[data-record-property-label]')?.value?.trim() || 'Propriedade sem nome',
      type,
      value,
      options: (row.querySelector<HTMLInputElement>('[data-record-property-options]')?.value || '').split(',').map(item => item.trim()).filter(Boolean),
    };
  }).filter(property => property.type === 'map_area' ? Boolean(property.value) : String(property.value || '').trim().length > 0);
}

