/** Render the complete records drill workspace from the program's typed view model. */
export function renderAtlasRecordsActivityDrillWorkspaceV1(input: {
  view: AtlasRecordsActivityDrillWorkspaceViewV1;
  esc(value: unknown): string;
  ico(name: string): string;
}): string {
  const {view, esc, ico} = input;
  const listMarkup = view.drillLevel === 'stages'
    ? renderAtlasRecordsActivityDrillStagesV1({rows: view.stageRows || [], esc, ico})
    : view.activityList
      ? renderAtlasRecordsActivityDrillActivitiesV1({...view.activityList, esc, ico})
      : '';
  const detailMarkup = view.detailRecord
    ? renderAtlasRecordDetailV1({record: view.detailRecord, esc, ico})
    : '';
  let registrationMarkup = '';
  if (view.registration) {
    const registration = view.registration;
    const formMarkup = renderAtlasRecordsActivityEntryFormV1({...registration, esc, ico});
    const mapMarkup = renderAtlasRecordsMapContextPanelV1({
      ...registration.mapContext,
      stage: registration.stage,
      activity: registration.activity,
      esc,
      ico,
    });
    const historyMarkup = renderAtlasRecordsActivityHistoryV1({rows: registration.historyRows, esc, ico});
    registrationMarkup = `<div class="records-drill-registration-v5377"><div class="records-drill-registration-main-v5377">${formMarkup}</div><div class="records-drill-registration-side-v5377">${mapMarkup}${historyMarkup}</div></div>`;
  }
  return renderAtlasRecordsActivityDrillPageV1({
    totals: view.totals,
    stageName: view.stageName,
    selectedActivityName: view.selectedActivityName,
    drillLevel: view.drillLevel,
    listMarkup,
    detailMarkup,
    registrationMarkup,
    esc,
    ico,
  });
}

