export type AtlasRecordsActivityDrillCommandV1 =
  | {action: 'record-open'; recordId: string}
  | {action: 'record-back'}
  | {action: 'stage-select'; stageKey: string; label: string}
  | {action: 'stage-root'}
  | {action: 'stage-back'}
  | {action: 'activity-select'; activityName: string}
  | {action: 'new-activity'}
  | {action: 'property-map'; row: HTMLElement}
  | {action: 'record-map-paint'}
  | {action: 'record-map-fit'}
  | {action: 'record-map-clear'}
  | {action: 'record-submit'; form: HTMLFormElement; values: Record<string, unknown>; properties: AtlasRecordPropertyEntryV1[]}
  | {action: 'image-read'; file: File}
  | {action: 'image-remove'}
  | {action: 'image-back'}
  | {action: 'image-next'}
  | {action: 'open-cash'};

export interface AtlasRecordsActivityDrillCommandContextV1 {
  root: HTMLElement;
  activeView: HTMLElement & {render?: () => void};
}

/** Route commands only from the mounted records page into the application program. */
export function bindAtlasRecordsActivityDrillProgramCommandsV1(
  host: Document,
  onCommand: (command: AtlasRecordsActivityDrillCommandV1, context: AtlasRecordsActivityDrillCommandContextV1) => void,
): () => void {
  const boundKey = 'recordsDrillTsCommandsBound';
  if (host.documentElement.dataset[boundKey] === 'true') return () => undefined;
  host.documentElement.dataset[boundKey] = 'true';
  const listener = (event: Event): void => {
    const activeView = host.querySelector('view-layer') as (HTMLElement & {render?: () => void}) | null;
    const path = event.composedPath();
    const root = path.find(node => node instanceof HTMLElement && node.matches('.records-drill-page-v5377')) as HTMLElement | undefined;
    const command = (event as CustomEvent<AtlasRecordsActivityDrillCommandV1>).detail;
    if (!root || !activeView || !path.includes(activeView) || !command || typeof command !== 'object') return;
    onCommand(command, {root, activeView});
  };
  host.addEventListener('atlas:records-drill-command', listener);
  return () => {
    host.removeEventListener('atlas:records-drill-command', listener);
    delete host.documentElement.dataset[boundKey];
  };
}

/** Apply pending feedback to the mounted record form without exposing its button to the program. */
export function setAtlasRecordsActivityPendingV1(root: Element, form: HTMLFormElement, pending: boolean): void {
  if (!form.matches('[data-activity-record-form]') || !root.contains(form)) return;
  const button = form.querySelector<HTMLButtonElement>('button[type="submit"]');
  if (button) button.disabled = pending;
}

export type AtlasRecordsImageReadResultV1 =
  | {dataUrl: string; fileName: string; mimeType: string}
  | {error: string};

/** Read image evidence through the browser API and return a validated data URL. */
export function readAtlasRecordsImageFileV1(
  host: Document,
  file: File,
  validate: (file: File) => string | null,
): Promise<AtlasRecordsImageReadResultV1> {
  const validation = validate(file);
  if (validation) return Promise.resolve({error: validation});
  const FileReaderCtor = host.defaultView?.FileReader;
  if (!FileReaderCtor) return Promise.resolve({error: 'Não foi possível ler a imagem selecionada'});
  return new Promise(resolve => {
    let reader: FileReader;
    try { reader = new FileReaderCtor(); }
    catch { resolve({error: 'Não foi possível ler a imagem selecionada'}); return; }
    reader.onload = () => {
      const dataUrl = String(reader.result || '');
      if (!/^data:image\/(?:png|jpeg|webp);base64,[A-Za-z0-9+/=]+$/i.test(dataUrl)) {
        resolve({error: 'Não foi possível preparar a imagem'});
        return;
      }
      resolve({
        dataUrl,
        fileName: String(file.name || 'imagem-de-campo'),
        mimeType: String(file.type || '').toLowerCase(),
      });
    };
    reader.onerror = () => resolve({error: 'Não foi possível ler a imagem selecionada'});
    try { reader.readAsDataURL(file); }
    catch { resolve({error: 'Não foi possível ler a imagem selecionada'}); }
  });
}

/** Update the visible status line for the activity-record form. */
export function setAtlasRecordsActivityStatusV1(root: Element, message: string, tone = ''): void {
  const status = root.querySelector<HTMLElement>('[data-activity-record-status]');
  if (!status) return;
  status.textContent = message;
  status.dataset.tone = tone;
}

/** Bind page controls to typed commands; state, routing, and persistence remain in the program. */
export function bindAtlasRecordsActivityDrillCommandsV1(root: HTMLElement, options: {
  propertyTypes?: AtlasRecordPropertyTypeViewV1[];
  esc?: (value: unknown) => string;
  ico?: (name: string) => string;
} = {}): void {
  if (root.dataset.recordsDrillCommandsBound === 'true') return;
  root.dataset.recordsDrillCommandsBound = 'true';
  const propertyTypes = options.propertyTypes || [];
  const esc = options.esc || escapeAtlasDomValueV1;
  const ico = options.ico || renderAtlasIconMarkupV1;
  const emit = (target: Element, command: AtlasRecordsActivityDrillCommandV1): void => {
    target.dispatchEvent(new CustomEvent<AtlasRecordsActivityDrillCommandV1>('atlas:records-drill-command', {
      bubbles: true,
      composed: true,
      detail: command,
    }));
  };
  root.addEventListener('click', event => {
    const path = event.composedPath();
    if (!path.includes(root)) return;
    const addProperty = path.find(node => node instanceof Element && node.matches('[data-record-property-add]')) as Element | undefined;
    if (addProperty) {
      event.preventDefault();
      const list = root.querySelector<HTMLElement>('[data-record-property-list]');
      if (list) {
        const id = `prop-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`;
        list.insertAdjacentHTML('beforeend', renderAtlasRecordPropertyRowV1({id, type: 'text', propertyTypes, esc, ico}));
        const row = list.lastElementChild as HTMLElement | null;
        if (row) row.dispatchEvent(new CustomEvent('atlas:records-property-row-added', {bubbles: true, composed: true, detail: {row}}));
        (globalThis as typeof globalThis & {lucide?: {createIcons?: () => void}}).lucide?.createIcons?.();
      }
      return;
    }
    const removeProperty = path.find(node => node instanceof Element && node.matches('[data-record-property-remove]')) as Element | undefined;
    if (removeProperty) {
      event.preventDefault();
      removeProperty.closest('[data-record-property-row]')?.remove();
      return;
    }
    const propertyMap = path.find(node => node instanceof Element && node.matches('[data-record-property-map]')) as Element | undefined;
    if (propertyMap) {
      event.preventDefault();
      const row = propertyMap.closest<HTMLElement>('[data-record-property-row]');
      if (row) emit(propertyMap, {action: 'property-map', row});
      return;
    }
    const route = (selector: string, command: (element: Element) => AtlasRecordsActivityDrillCommandV1 | null): boolean => {
      const element = path.find(node => node instanceof Element && node.matches(selector)) as Element | undefined;
      if (!element) return false;
      event.preventDefault();
      emit(element, command(element)!);
      return true;
    };
    if (route('[data-record-open]', element => ({action: 'record-open', recordId: String(element.getAttribute('data-record-open') || '')}))) return;
    if (route('[data-record-detail-back]', () => ({action: 'record-back'}))) return;
    if (route('[data-records-drill-stage]', element => ({
      action: 'stage-select',
      stageKey: String(element.getAttribute('data-records-drill-stage') || ''),
      label: element.textContent?.replace(/\s+/g, ' ').trim() || '',
    }))) return;
    if (route('[data-records-drill-root]', () => ({action: 'stage-root'}))) return;
    if (route('[data-records-drill-stage-back]', () => ({action: 'stage-back'}))) return;
    if (route('[data-records-drill-activity]', element => ({action: 'activity-select', activityName: String(element.getAttribute('data-records-drill-activity') || '')}))) return;
    if (route('[data-record-new-activity]', () => ({action: 'new-activity'}))) return;
    if (route('[data-record-drill-paint]', () => ({action: 'record-map-paint'}))) return;
    if (route('[data-record-drill-fit]', () => ({action: 'record-map-fit'}))) return;
    if (route('[data-record-drill-clear]', () => ({action: 'record-map-clear'}))) return;
    if (route('[data-record-image-remove]', () => ({action: 'image-remove'}))) return;
    if (route('[data-record-image-back]', () => ({action: 'image-back'}))) return;
    if (route('[data-record-image-next]', () => ({action: 'image-next'}))) return;
    route('[data-view="control"]', () => ({action: 'open-cash'}));
  });
  root.addEventListener('submit', event => {
    const form = event.target;
    if (!(form instanceof HTMLFormElement) || !form.matches('[data-activity-record-form]') || !root.contains(form)) return;
    event.preventDefault();
    const values = Object.fromEntries(new FormData(form).entries());
    emit(form, {
      action: 'record-submit',
      form,
      values,
      properties: collectAtlasRecordPropertiesV1(form),
    });
  });
  root.addEventListener('keydown', event => {
    if (!(event instanceof KeyboardEvent) || !['Enter', ' '].includes(event.key)) return;
    const path = event.composedPath();
    if (!path.includes(root)) return;
    const target = path.find(node => node instanceof Element && node.matches('[data-record-open]')) as Element | undefined;
    if (!target) return;
    event.preventDefault();
    emit(target, {action: 'record-open', recordId: String(target.getAttribute('data-record-open') || '')});
  });
  root.addEventListener('change', event => {
    const path = event.composedPath();
    if (!path.includes(root)) return;
    const input = path.find(node => node instanceof HTMLInputElement && node.matches('[data-record-image-input]')) as HTMLInputElement | undefined;
    const file = input?.files?.[0];
    if (input && file) emit(input, {action: 'image-read', file});
    const propertyType = path.find(node => node instanceof HTMLSelectElement && node.matches('[data-record-property-type]')) as HTMLSelectElement | undefined;
    const propertyRow = propertyType?.closest<HTMLElement>('[data-record-property-row]');
    const valueHost = propertyRow?.querySelector<HTMLElement>('[data-record-property-value-host]');
    if (propertyType && propertyRow && valueHost) {
      valueHost.innerHTML = renderAtlasRecordPropertyValueControlV1({type: propertyType.value, ico: renderAtlasIconMarkupV1});
      propertyRow.dataset.mapArea = '';
    }
  });
  root.addEventListener('dragover', event => {
    const path = event.composedPath();
    if (path.includes(root) && path.some(node => node instanceof Element && node.matches('[data-record-image-dropzone]'))) event.preventDefault();
  });
  root.addEventListener('drop', event => {
    const path = event.composedPath();
    if (!path.includes(root) || !path.some(node => node instanceof Element && node.matches('[data-record-image-dropzone]'))) return;
    event.preventDefault();
    const file = [...(event as DragEvent).dataTransfer?.files || []].find(item => String(item.type || '').toLowerCase().startsWith('image/'));
    if (file) emit(root, {action: 'image-read', file});
  });
  root.addEventListener('paste', event => {
    const path = event.composedPath();
    if (!path.includes(root)) return;
    const file = [...(event as ClipboardEvent).clipboardData?.files || []].find(item => String(item.type || '').toLowerCase().startsWith('image/'));
    if (!file) return;
    event.preventDefault();
    emit(root, {action: 'image-read', file});
  });
}

export interface AtlasRecordsActivityDrillRouteStoreV1 {
  get(): AtlasRecordsActivityDrillRouteStateV1;
}

export interface AtlasRecordsMapCommandSceneV1 extends HTMLElement {
  setRecordPaintMode?(enabled: boolean, callback?: (area: Record<string, any>) => void): void;
  fitSceneView?(reset?: boolean): void;
  lastRecordMapArea?: unknown;
}

export interface AtlasRecordsMapCommandInputV1 {
  action: 'property-map' | 'record-map-paint' | 'record-map-fit' | 'record-map-clear';
  root: Element;
  map: AtlasRecordsMapCommandSceneV1 | null;
  row?: HTMLElement | null;
  setStatus(message: string, tone?: string): void;
  onAreaSelected?(area: Record<string, any>): void;
}

/** Own record-map gesture feedback and property-area form updates. */
export function runAtlasRecordsMapCommandV1(input: AtlasRecordsMapCommandInputV1): void {
  const {action, map} = input;
  if (action === 'property-map') {
    const row = input.row;
    if (!row || !row.matches('[data-record-property-row]') || !input.root.contains(row)) return;
    if (!map?.setRecordPaintMode) {
      input.setStatus('Mapa operacional ainda está carregando. Tente novamente em instantes.', 'error');
      return;
    }
    map.setRecordPaintMode(true, area => {
      row.dataset.mapArea = JSON.stringify(area);
      const mapAreaInput = row.closest('form')?.querySelector<HTMLInputElement>('[name="mapArea"]');
      if (mapAreaInput) mapAreaInput.value = JSON.stringify(area);
      const status = row.querySelector<HTMLElement>('[data-record-property-map-status]');
      if (status) status.textContent = `${area.label || 'Área'} · ${(area.partIds || area.parts || []).length || 1} polígono(s)`;
      input.setStatus('Área assinalada e vinculada à propriedade.', 'success');
    });
    map.scrollIntoView({behavior: 'smooth', block: 'center'});
    return;
  }
  if (action === 'record-map-paint') {
    if (!map?.setRecordPaintMode) {
      input.setStatus('Mapa operacional ainda está carregando. Tente novamente em instantes.', 'error');
      return;
    }
    map.setRecordPaintMode(true, area => {
      input.onAreaSelected?.(area);
      input.setStatus(`${area.label} vinculada ao apontamento.`, 'success');
    });
    map.scrollIntoView({behavior: 'smooth', block: 'center'});
    return;
  }
  if (action === 'record-map-fit') {
    map?.fitSceneView?.(true);
    map?.scrollIntoView({behavior: 'smooth', block: 'center'});
    return;
  }
  map?.setRecordPaintMode?.(false);
  if (map) {
    map.lastRecordMapArea = null;
    delete map.dataset.recordPaintArea;
  }
}

export interface AtlasRecordsActivityDrillViewLayerV1 extends HTMLElement {
  records?: ((this: AtlasRecordsActivityDrillViewLayerV1) => string) & { __recordsActivityDrillRouteProgramV1?: boolean };
  bind?: ((this: AtlasRecordsActivityDrillViewLayerV1, ...args: unknown[]) => unknown) & { __recordsActivityDrillRouteProgramV1?: boolean };
}

/** Keep records route registration, rendering, and command binding with its view components. */
export function installAtlasRecordsActivityDrillRouteV1(input: {
  host: Document;
  ViewLayer: {prototype: AtlasRecordsActivityDrillViewLayerV1};
  appStore: AtlasRecordsActivityDrillRouteStoreV1;
  stages: AtlasRecordsActivityCatalogStageV1[];
  demoStages?: readonly Record<string, any>[];
  isLimitedOperationalActor(actor: unknown): boolean;
  esc(value: unknown): string;
  ico(name: string): string;
}): boolean {
  const host = input.host;
  const globalRef = host.defaultView as (Window & {lucide?: {createIcons?: () => void}}) | null;
  const activeViewLayer = (globalRef?.customElements.get('view-layer') || input.ViewLayer) as typeof input.ViewLayer;
  const prototype = activeViewLayer.prototype;
  const currentRecords = prototype.records;
  const currentBind = prototype.bind;
  if (currentRecords?.__recordsActivityDrillRouteProgramV1 && currentBind?.__recordsActivityDrillRouteProgramV1) return true;

  const demoStages = input.demoStages || [];
  const recordsRenderer: NonNullable<typeof prototype.records> = function recordsActivityDrillRouteProgramV1(this: AtlasRecordsActivityDrillViewLayerV1): string {
    const state = input.appStore.get();
    if (globalRef?.matchMedia?.('(max-width: 760px)').matches) {
      const page = projectAtlasMobileOperationalRecordsPageV5360({
        state: {...state, selectedStage: ''},
        activities: demoStages,
        isLimitedOperationalActor: input.isLimitedOperationalActor,
      });
      return renderAtlasMobileOperationalRecordsPageV5360({
        page: page as unknown as Parameters<typeof renderAtlasMobileOperationalRecordsPageV5360>[0]['page'],
        esc: input.esc,
        ico: input.ico,
      });
    }
    const search = globalRef?.location.search || '';
    const view = projectAtlasRecordsActivityDrillRouteV1({
      state,
      stages: input.stages,
      demoStages,
      requestedRecordId: new URLSearchParams(search).get('record'),
    });
    const content = renderAtlasRecordsActivityDrillWorkspaceV1({ view, esc: input.esc, ico: input.ico });
    const stage = projectAtlasRecordsStageShellV1({activities: demoStages, selectedStage: state.selectedStage});
    return renderAtlasRecordsStageShellV1({content, ...stage, esc: input.esc, ico: input.ico});
  };
  recordsRenderer.__recordsActivityDrillRouteProgramV1 = true;
  prototype.records = recordsRenderer;

  const bindRenderer: NonNullable<typeof prototype.bind> = function bindRecordsActivityDrillRouteProgramV1(
    this: AtlasRecordsActivityDrillViewLayerV1,
    ...args: unknown[]
  ): unknown {
    const result = currentBind?.apply(this, args);
    const root = this;
    if (input.appStore.get().view === 'records' || root.querySelector('.records-drill-page-v5377')) {
      bindAtlasRecordsActivityDrillCommandsV1(root, {
        propertyTypes: projectAtlasRecordPropertyTypesV1(),
        esc: input.esc,
        ico: input.ico,
      });
    }
    globalRef?.lucide?.createIcons?.();
    return result;
  };
  bindRenderer.__recordsActivityDrillRouteProgramV1 = true;
  prototype.bind = bindRenderer;
  return true;
}

export type AtlasRecordsShellCommandV1 =
  | {action: 'open-record-entry'; activityName: string}
  | {action: 'fit-stage-map'}
  | {action: 'open-profile-record'; recordId: string}
  | {action: 'close-profile-record'};

/** Capture cross-page record shortcuts and the stage map control at the shell boundary. */
export function bindAtlasRecordsShellCommandsV1(host: Document): void {
  const boundKey = 'recordsShellTsCaptureBound';
  if (host.documentElement.dataset[boundKey] === 'true') return;
  host.documentElement.dataset[boundKey] = 'true';
  host.addEventListener('click', event => {
    const path = event.composedPath();
    const target = path.find(node => node instanceof Element && node.matches(
      '[data-records-open-new], [data-record-new-activity], [data-records-drill-activity], [data-records-stage-fit], [data-v5360-record], [data-v5360-record-back]',
    )) as Element | undefined;
    if (!target) return;
    const isMapFit = target.matches('[data-records-stage-fit]');
    const isProfileRecord = target.matches('[data-v5360-record]');
    const isProfileBack = target.matches('[data-v5360-record-back]');
    if (isMapFit && !path.includes(host.querySelector('view-layer') as Element)) return;
    event.preventDefault();
    event.stopImmediatePropagation();
    const command: AtlasRecordsShellCommandV1 = isMapFit
      ? {action: 'fit-stage-map'}
      : isProfileRecord
        ? {action: 'open-profile-record', recordId: String(target.getAttribute('data-v5360-record') || '')}
        : isProfileBack
          ? {action: 'close-profile-record'}
          : {action: 'open-record-entry', activityName: String(target.getAttribute('data-records-drill-activity') || '')};
    target.dispatchEvent(new CustomEvent<AtlasRecordsShellCommandV1>('atlas:records-shell-command', {
      bubbles: true,
      composed: true,
      detail: command,
    }));
  }, true);
}

export interface AtlasRecordsShellCommandContextV1 {
  activeView: HTMLElement & {render?: () => void};
}

/** Validate shell commands at the mounted view and own the stage-map framing control. */
export function bindAtlasRecordsShellProgramCommandsV1(
  host: Document,
  onCommand: (command: AtlasRecordsShellCommandV1, context: AtlasRecordsShellCommandContextV1) => void,
): () => void {
  const boundKey = "recordsShellProgramCommandsBoundV1";
  if (host.documentElement.dataset[boundKey] === "true") return () => undefined;
  host.documentElement.dataset[boundKey] = "true";
  const listener = (event: Event): void => {
    const path = event.composedPath();
    const command = (event as CustomEvent<AtlasRecordsShellCommandV1>).detail;
    const activeView = host.querySelector("view-layer") as (HTMLElement & {render?: () => void}) | null;
    if (!command || !activeView || !path.includes(activeView)) return;
    const selector = command.action === "fit-stage-map"
      ? "[data-records-stage-fit]"
      : command.action === "open-profile-record"
        ? "[data-v5360-record]"
        : command.action === "close-profile-record"
          ? "[data-v5360-record-back]"
          : "[data-records-open-new], [data-record-new-activity], [data-records-drill-activity]";
    if (!path.some(node => node instanceof Element && node.matches(selector))) return;
    if (command.action === "fit-stage-map") {
      const map = activeView.querySelector<HTMLElement & {fitSceneView?: (reset?: boolean) => void}>("[data-records-stage-map]");
      map?.fitSceneView?.(true);
      return;
    }
    onCommand(command, {activeView});
  };
  host.addEventListener("atlas:records-shell-command", listener);
  return () => {
    host.removeEventListener("atlas:records-shell-command", listener);
    delete host.documentElement.dataset[boundKey];
  };
}

