/** Stage-scoped foremen view. Program supplies only the projected route data. */
export class AtlasForemen extends AtlasHTMLElementBase {
  private snapshot: ForemenRouteView | null = null;
  connectedCallback(): void {
    this.render();
    this.dispatchEvent(new CustomEvent("atlas:foremen-connected", { bubbles: true, detail: { element: this } }));
  }
  setData(data: ForemenRouteView): void { this.snapshot = data; this.render(); }
  private esc(value: unknown): string { return String(value ?? "").replace(/[&<>"']/g, char => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[char] || char)); }
  render(): void {
    const data = this.snapshot;
    if (!data) { this.innerHTML = `${foremenStyles}<section class="atlas-foremen"><p class="atlas-muted">Carregando responsáveis da etapa…</p></section>`; return; }
    const esc = (value: unknown) => this.esc(value), active = data.members.filter(member => /campo|operando|disponível|disponivel/i.test(member.status)).length;
    const members = data.members.map(member => `<article class="atlas-member"><div><div class="atlas-member-main"><span class="atlas-avatar">${esc(member.name.trim().slice(0, 2).toUpperCase() || "?")}</span><div><h3>${esc(member.name)}</h3><p>${esc(member.role)}</p></div></div><dl><div><dt>Vínculo na etapa</dt><dd>${esc(data.stage.name)}</dd></div><div><dt>Atividades acompanhadas</dt><dd>${esc(member.activityCount)} registros</dd></div><div><dt>Especialidades</dt><dd>${esc(member.skills.join(" · ") || "Atribuição em definição")}</dd></div></dl></div><span class="atlas-status" data-live="${/campo|operando/i.test(member.status)}">${esc(member.status || "Sem status")}</span></article>`).join("");
    this.innerHTML = `${foremenStyles}<section class="atlas-foremen"><header><div><span class="atlas-kicker">ETAPA EM FOCO · RESPONSÁVEIS</span><h1>Por encarregados</h1><p class="atlas-muted">Equipe vinculada à etapa <strong>${esc(data.stage.name)}</strong> e situação de campo.</p></div><div><b>${data.members.length} responsável${data.members.length === 1 ? "" : "es"}</b><p class="atlas-muted">${active} em acompanhamento ou disponibilidade</p></div></header><section class="atlas-summary"><article><small>ETAPA</small><b>${esc(data.stage.name)}</b><span>${esc(data.stage.unit || "Unidade de produção")}</span></article><article><small>AVANÇO</small><b>${Math.max(0, Math.min(100, Number(data.progress) || 0))}%</b><span>${esc(data.stageStatus || "Em acompanhamento")}</span></article><article><small>RESPONSÁVEIS</small><b>${data.members.length}</b><span>vínculos encontrados</span></article><article><small>PRÓXIMA AÇÃO</small><b>${esc(data.stage.nextAction || "Registrar avanço")}</b><span>${esc(data.stage.owner || "Responsável a definir")}</span></article></section><section class="atlas-panel"><header><div><span class="atlas-kicker">FRENTE DE TRABALHO</span><h2>Equipe por encarregado</h2><p class="atlas-muted">A lista acompanha a etapa selecionada e não altera o cadastro central.</p></div><button type="button" data-view="personnel">Abrir cadastro</button></header><div class="atlas-member-list">${members || '<p class="atlas-empty">Nenhum responsável vinculado à etapa.</p>'}</div></section></section>`;
  }
}
if (!customElements.get("atlas-foremen")) customElements.define("atlas-foremen", AtlasForemen);

/** Owns the foremen route and forwards the connected view to its typed data projection. */
export function installAtlasForemenComponentControllerV1(input: {
  ViewLayer: { prototype: HTMLElement & Record<string, unknown> };
  host: Document;
  onConnected: (element: AtlasForemen) => void;
}): void {
  input.ViewLayer.prototype.foremen = () => "<atlas-foremen></atlas-foremen>";
  input.host.addEventListener("atlas:foremen-connected", event => {
    const element = (event as CustomEvent<{ element?: AtlasForemen }>).detail?.element;
    if (element instanceof AtlasForemen) input.onConnected(element);
  });
}

