/** Cash-exit form. It owns only ephemeral form and attachment state. */
export class AtlasCashRecord extends AtlasHTMLElementBase {
  private snapshot: CashRecordState;
  private readonly state: AtomicState<CashRecordState>;
  constructor() {
    super();
    const initial: CashRecordState = { actorLabel: "", allowed: false, stages: [], returnView: "finance", attachment: null, saving: false, error: "", feedback: "" };
    function* state(value: CashRecordState): Generator<CashRecordState, never, CashRecordSetter> { while (true) value = (yield value)(value); }
    const iterator = state(initial); iterator.next(); this.snapshot = initial;
    this.state = { next: setter => { this.snapshot = iterator.next(setter).value; this.render(); return this.snapshot; } };
  }
  connectedCallback(): void { this.render(); this.dispatchEvent(new CustomEvent("atlas:cash-record-connected", { bubbles: true, detail: { element: this } })); }
  setContext(data: { actorLabel: string; allowed: boolean; stages: OperationalStage[]; returnView: string }): void { this.state.next(s => ({ ...s, ...data })); }
  setAttachment(file: File | null): void { this.state.next(s => ({ ...s, attachment: file, error: "" })); }
  setSaving(saving: boolean): void { this.state.next(s => ({ ...s, saving, feedback: saving ? "Salvando saída no livro-caixa…" : s.feedback })); }
  setError(message: string): void { this.state.next(s => ({ ...s, saving: false, error: message, feedback: "" })); }
  private esc(value: unknown): string { return String(value ?? "").replace(/[&<>"']/g, char => ({ "&":"&amp;", "<":"&lt;", ">":"&gt;", '"':"&quot;", "'":"&#39;" }[char] || char)); }
  private render(): void {
    const s = this.snapshot, esc = (value: unknown) => this.esc(value);
    const view = projectAtlasCashRecordPageV1({ actorLabel: s.actorLabel, allowed: s.allowed, stages: s.stages, attachment: s.attachment, saving: s.saving, error: s.error, feedback: s.feedback, now: new Date() });
    this.innerHTML = `${cashRecordStyles}<section class="atlas-cash-record"><header><div><button type="button" data-cash-back>← Voltar</button><span class="atlas-eyebrow">CAIXA · SAÍDA</span><h1>Registrar saída de caixa</h1><p class="atlas-muted">Entradas comerciais e repasses são registrados exclusivamente em Repasses.</p></div><span class="atlas-muted">${esc(view.actorLabel)}</span></header>${view.error ? `<p role="alert">${esc(view.error)}</p>` : ""}${view.allowed ? `<form class="atlas-panel atlas-form" data-cash-form novalidate><input type="hidden" name="date" value="${view.date}"><input type="hidden" name="kind" value="saida"><div class="atlas-fields"><label>Nome do registro<input name="name" required maxlength="120" placeholder="Ex.: pagamento de serviço"></label><label>Etapa<select name="stage"><option value="Geral">Geral</option>${view.stages.map(stage => `<option value="${esc(stage.value)}">${esc(stage.label)}</option>`).join("")}</select></label><label>Valor (R$)<input name="amount" inputmode="decimal" required placeholder="0,00" autocomplete="off"></label><label class="atlas-wide">Descrição<textarea name="description" required maxlength="800" rows="5" placeholder="Explique a finalidade e condição do lançamento."></textarea></label><section class="atlas-fiscal atlas-wide"><header><div><span class="atlas-eyebrow">CONTROLE FISCAL</span><h2>Documento do lançamento</h2><p class="atlas-muted">O anexo não altera o estado de conferência sozinho.</p></div></header><div class="atlas-fields"><label>Tipo<select name="fiscalDocumentType"><option value="">Não informado</option><option value="nota_fiscal">Nota fiscal</option><option value="recibo">Recibo</option><option value="contrato">Contrato</option><option value="outro">Outro</option></select></label><label>Número<input name="fiscalDocumentNumber" maxlength="80" placeholder="Número ou referência"></label><label>Emitente<input name="fiscalIssuer" maxlength="160" placeholder="Nome ou razão social"></label><label>Data de emissão<input name="fiscalIssueDate" type="date"></label><label>Conferência<select name="fiscalStatus"><option value="pendente">Pendente</option><option value="em_conferencia">Em conferência</option><option value="conferido">Conferido</option><option value="nao_aplicavel">Não aplicável</option></select></label></div><small>“Conferido” exige tipo, número, emitente, data e documento anexado; não substitui análise contábil.</small></section><label class="atlas-file atlas-wide">Anexo opcional<input type="file" name="attachment" accept="image/jpeg,image/png,image/webp,application/pdf"><span class="atlas-file-summary" data-cash-file-summary>${esc(view.attachmentSummary)}</span></label></div><footer><span class="atlas-status" role="status" aria-live="polite">${esc(view.feedback)}</span><button type="submit" class="atlas-primary" ${view.saving ? "disabled" : ""}>${view.saving ? "Salvando…" : "Registrar saída"}</button></footer></form>` : `<div class="atlas-panel atlas-permission">Este perfil pode consultar o caixa, mas não criar lançamentos. Apenas o perfil Dono pode registrar uma saída.</div>`}</section>`;
    this.querySelector<HTMLButtonElement>("[data-cash-back]")?.addEventListener("click", () => this.dispatchEvent(new CustomEvent("atlas:cash-record-back", { bubbles: true, detail: { element: this, view: s.returnView } })));
    const input = this.querySelector<HTMLInputElement>('[name="attachment"]');
    input?.addEventListener("change", () => { const selected = input.files?.[0] || null; this.setAttachment(selected); });
    const form = this.querySelector<HTMLFormElement>("[data-cash-form]");
    form?.addEventListener("submit", event => {
      event.preventDefault();
      const draft = buildAtlasCashRecordFormCommandV1({
        values: Object.fromEntries(new FormData(form).entries()),
        attachment: this.snapshot.attachment,
      });
      if (!draft.ok) { this.setError(draft.error); return; }
      this.setSaving(true);
      this.dispatchEvent(new CustomEvent("atlas:cash-record-create", { bubbles: true, detail: { element: this, payload: draft.payload } }));
    });
  }
}
if (!customElements.get("atlas-cash-record")) customElements.define("atlas-cash-record", AtlasCashRecord);

