/** Keep the cash-entry route and its view events beside the cash-entry element. */
export function installAtlasCashRecordComponentControllerV1(input: AtlasCashRecordComponentControllerInputV1): void {
  const options = replaceAtlasFieldPageComponentBindingsV1(input.host, "cash-record");
  let activeElement: AtlasCashRecord | null = null;
  const elementFrom = (event: Event): AtlasCashRecord | null => {
    const element = (event as CustomEvent<{ element?: AtlasCashRecord }>).detail?.element;
    return element instanceof AtlasCashRecord ? element : null;
  };
  input.ViewLayer.prototype["cash-record"] = () => '<atlas-cash-record></atlas-cash-record>';
  input.host.addEventListener("atlas:cash-record-connected", event => {
    const element = elementFrom(event);
    if (!element) return;
    activeElement = element;
    input.onConnected(element);
  }, options);
  input.host.addEventListener("atlas:cash-record-create", event => {
    if (elementFrom(event) === activeElement && activeElement) input.onCreate(event);
  }, options);
  input.host.addEventListener("atlas:cash-record-back", event => {
    const element = elementFrom(event);
    if (!element || element !== activeElement) return;
    const view = (event as CustomEvent<{ view?: string }>).detail?.view;
    input.onBack(element, String(view || "finance"));
  }, options);
}

