if (!customElements.get("atlas-settings")) customElements.define("atlas-settings", AtlasSettings);

/** Owns settings route mounting, connection, and delegated command dispatch. */
export function installAtlasSettingsComponentControllerV1(input: {
  ViewLayer: { prototype: HTMLElement & Record<string, unknown> };
  host: Document;
  onConnected: (element: AtlasSettings) => void;
  onCommand: (event: CustomEvent<{ element: AtlasSettings; command: string; [key: string]: unknown }>) => void;
}): void {
  input.ViewLayer.prototype.settings = () => "<atlas-settings></atlas-settings>";
  input.host.addEventListener("atlas:settings-connected", event => {
    const element = (event as CustomEvent<{ element?: AtlasSettings }>).detail?.element;
    if (element instanceof AtlasSettings) input.onConnected(element);
  });
  input.host.addEventListener("atlas:settings-command", event => {
    const detail = (event as CustomEvent<{ element?: AtlasSettings; command?: string }>).detail;
    if (detail?.element instanceof AtlasSettings && typeof detail.command === "string") {
      input.onCommand(event as CustomEvent<{ element: AtlasSettings; command: string; [key: string]: unknown }>);
    }
  });
}

