/** Install the typed administrative lot-selection and reservation panel on MapScene. */
export function installAtlasMapLotSelectionUi(MapScene: CustomElementConstructor, dependencies: AtlasMapLotSelectionDependencies): void {
  const { commands, document: documentRef, esc, FormData: FormDataRef, ico, notify, window: windowRef } = dependencies;
  const methods = {
    modelPartSource(this: AtlasMapSelectionScene, node: AtlasMapSelectionPart): AtlasMapSelectionPart | null {
      let source: AtlasMapSelectionPart | null = node;
      while (source && !source.userData?.partKind) source = source.parent || null;
      return source;
    },
    materialForColor(this: AtlasMapSelectionScene, material: unknown, color: number, opacity = 0.84): unknown {
      const paint = (value: unknown): unknown => {
        const source = value as AtlasMapSelectionMaterial | null;
        if (!source) return source;
        const clone = source.clone?.() || source;
        clone.color?.setHex?.(color);
        if (clone.emissive) {
          clone.emissive.setHex?.(color);
          clone.emissive.emissiveIntensity = 0.72;
        }
        clone.transparent = true;
        clone.opacity = Math.max(0.68, Math.min(0.94, opacity));
        clone.depthWrite = false;
        return clone;
      };
      return Array.isArray(material) ? material.map(paint) : paint(material);
    },
    restorePartMaterial(this: AtlasMapSelectionScene, item: AtlasMapSelectionPart): void {
      const data = item.userData || {};
      item.material = data.progressSelectionMaterial || data.progressMaterial || data.selectionMaterial || data.overlayMaterial || data.statusMaterial || data.recordStatusMaterial || data.publicStatusMaterial || data.defaultMaterial;
    },
    toggleLotSelection(this: AtlasMapSelectionScene, node: AtlasMapSelectionPart): boolean {
      if (this.matches("map-scene[data-public-map],map-scene[data-public-presentation]")) {
        if (this.dataset.publicSelectionEnabled !== "true") return false;
        const surface = documentRef.querySelector<HTMLElement & { selectPublicLot?: (mapHost: HTMLElement, node: unknown) => boolean }>("public-leads-surface");
        return surface?.selectPublicLot?.(this, node) === true;
      }
      const source = this.modelPartSource?.(node);
      if (!source) return false;
      const sourceData = source.userData || {};
      const command = createAtlasMapLotSelectionCommand({
        partId: sourceData.partId || source.name,
        partLabel: sourceData.partLabel,
        partKind: sourceData.partKind,
        sourceName: source.name,
        selectedLotIds: this.selectedLotIds || [],
      });
      if (!command) return false;
      const selected = this.selectedLotIds || new Set<string>();
      selected.clear();
      command.selectedLotIds.forEach(id => selected.add(id));
      this.selectedLotIds = selected;
      const matches = (this.physicalMapParts?.() || []).filter(item => item.userData?.partKind === "lots" && String(item.userData.partId || item.name || "") === command.partId);
      if (command.operation === "clear") {
        matches.forEach(item => {
          if (item.userData) delete item.userData.selectionMaterial;
          this.restorePartMaterial?.(item);
        });
      } else {
        matches.forEach(item => {
          if (!item.userData) item.userData = {};
          item.userData.selectionMaterial = this.materialForColor?.(item.userData.defaultMaterial, 0x2fe6ae, 0.9);
          item.material = item.userData.selectionMaterial;
        });
      }
      this.dataset.selectedPart = command.selectedCount ? command.label : "Nenhum lote selecionado";
      this.dataset.selectedKind = command.selectedCount ? "lots" : "";
      this.dataset.selectedLotCount = String(command.selectedCount);
      this.dataset.selectedLots = command.selectedLotIds.join("|");
      const three = this.THREE;
      if (three && this.selectionHalo) {
        const bounds = new three.Box3().setFromObject(source);
        const center = bounds.getCenter(new three.Vector3());
        const size = bounds.getSize(new three.Vector3());
        this.selectionHalo.position.set(center.x - (this.sceneStage?.position?.x || 0), center.y - (this.sceneStage?.position?.y || 0), 2);
        this.selectionHalo.scale.setScalar(Math.max(0.7, Math.min(4.5, Math.max(size.x, size.y) / 24)));
        this.selectionHalo.material.color.setHex(0x2fe6ae);
        this.selectionHalo.visible = command.selectedCount > 0;
      }
      if (command.selectedCount) this.renderLotReservationPanel?.();
      else this.removeMapSelectionPanel?.();
      commands.recordSelection(command.lastAction);
      this.sceneStage?.updateMatrixWorld?.(true);
      this.renderActiveSceneV5370?.();
      return true;
    },
    removeMapSelectionPanel(this: AtlasMapSelectionScene): void {
      this.querySelector("[data-map-selection-panel]")?.remove();
    },
    renderLotReservationPanel(this: AtlasMapSelectionScene): void {
      this.removeMapSelectionPanel?.();
      const ids = [...(this.selectedLotIds || [])];
      const labels = ids.map(id => {
        const source = (this.physicalMapParts?.() || []).find(item => String(item.userData?.partId || item.name || "") === id);
        return String(source?.userData?.partLabel || id);
      });
      const options = projectAtlasMapReservationOptions();
      const objectiveOptions = options.objectives.map(option => `<option${option === options.defaultObjective ? " selected" : ""}>${esc(option)}</option>`).join("");
      const termOptions = options.terms.map(option => `<option${option === options.defaultTerm ? " selected" : ""}>${esc(option)}</option>`).join("");
      const panel = documentRef.createElement("aside");
      panel.className = "map-selection-panel";
      panel.dataset.mapSelectionPanel = "reservation";
      panel.innerHTML = `<div class="map-selection-panel-head"><div><span class="activity-kind">RESERVA DE LOTES</span><h2>${ids.length} lote${ids.length === 1 ? "" : "s"} selecionado${ids.length === 1 ? "" : "s"}</h2></div><button type="button" data-map-selection-clear aria-label="Limpar seleção">×</button></div><div class="map-selection-chips">${labels.map(label => `<span class="map-selection-chip">${esc(label)}</span>`).join("")}</div><p class="map-selection-help">Clique em outros lotes para acumular a seleção. Clique novamente em um lote para removê-lo.</p><form data-lot-reservation-form><label>Interessado<input name="interessado" placeholder="Nome completo"></label><label>Objetivo<select name="objetivo">${objectiveOptions}</select></label><label>Prazo de reserva<select name="prazo">${termOptions}</select></label><label>Observações<textarea name="observacoes" rows="2" placeholder="Preferências, condições ou observações"></textarea></label><div class="map-selection-panel-actions"><button type="submit" class="primary">${ico("calendar-check")} Abrir reserva</button></div></form>`;
      this.appendChild(panel);
      panel.querySelector("[data-map-selection-clear]")?.addEventListener("click", event => {
        event.stopPropagation();
        this.clearLotSelection?.(true);
      });
      panel.querySelector("[data-lot-reservation-form]")?.addEventListener("submit", event => {
        event.preventDefault();
        const form = event.currentTarget as HTMLFormElement;
        const data = new FormDataRef(form);
        const result = commands.createReservation({
          lotLabels: labels,
          interested: data.get("interessado"),
          objective: data.get("objetivo"),
          term: data.get("prazo"),
          notes: data.get("observacoes"),
        });
        notify(result.feedback, "success");
        panel.classList.add("is-confirmed");
        const submit = panel.querySelector<HTMLButtonElement>('[type="submit"]');
        if (submit) submit.textContent = "Reserva preparada";
      });
      (windowRef as Window & typeof globalThis & { lucide?: { createIcons?: () => void } }).lucide?.createIcons?.();
    },
  };
  const prototype = MapScene.prototype as unknown as Record<string, unknown>;
  Object.entries(methods).forEach(([name, method]) => Object.defineProperty(prototype, name, { configurable: true, writable: true, value: method }));
}

interface AtlasPickingVector2 { x: number; y: number; set: (x: number, y: number) => void }
