type AtlasMapLoadingBrowser = typeof globalThis & { Capacitor?: { isNativePlatform?: () => boolean; getPlatform?: () => string } };

/** Install the typed loading surface and static-image fallback shared by both map routes. */
export function installAtlasMapLoadingScreen(
  MapScene: CustomElementConstructor,
  dependencies: {
    GENERATED_AERIAL_ASSET: string;
    browser: AtlasMapLoadingBrowser;
    beginBootStateV5367: (initial: Record<string, unknown>) => Record<string, unknown>;
    updateBootStateV5367: (patch: Record<string, unknown>) => Record<string, unknown>;
    persistBootPhaseV5367: (phase: string, extra: Record<string, unknown>) => Record<string, unknown>;
  },
): CustomElementConstructor {
  if (typeof (MapScene as unknown) !== "function" || !(MapScene as any).prototype)
    throw new TypeError("Map loading screen requires the existing MapScene constructor.");
  if (typeof dependencies.GENERATED_AERIAL_ASSET !== "string" || !dependencies.GENERATED_AERIAL_ASSET)
    throw new TypeError("Map loading screen requires GENERATED_AERIAL_ASSET.");
  for (const [name, port] of Object.entries({
    beginBootStateV5367: dependencies.beginBootStateV5367,
    updateBootStateV5367: dependencies.updateBootStateV5367,
    persistBootPhaseV5367: dependencies.persistBootPhaseV5367,
  })) {
    if (typeof port !== "function")
      throw new TypeError(`Map loading screen requires its TypeScript ${name} program port.`);
  }
  const browser = dependencies.browser;
  const documentRef = browser.document;
  const timerHost = browser.window || browser as unknown as Window;
  const setTimeoutRef = typeof browser.setTimeout === "function"
    ? browser.setTimeout.bind(browser)
    : timerHost.setTimeout.bind(timerHost);
  const clearTimeoutRef = typeof browser.clearTimeout === "function"
    ? browser.clearTimeout.bind(browser)
    : timerHost.clearTimeout.bind(timerHost);
  if (!documentRef || !browser.window || typeof browser.Image !== "function")
    throw new TypeError("Map loading screen requires browser Image, document and window services.");
  const captureSource = (scene: AtlasMapLoadingSceneElement): string => {
    const capacitor = browser.Capacitor;
    return projectAtlasMapStaticCaptureSource({
      nativePlatform: Boolean(capacitor?.isNativePlatform?.()),
      platform: capacitor?.getPlatform?.(),
      compactViewport: browser.matchMedia?.("(max-width: 900px)").matches || false,
      userAgent: browser.navigator?.userAgent || "",
      mobileCapture: scene.getAttribute("data-mobile-static-capture"),
      publicCapture: scene.getAttribute("data-public-static-capture"),
      generatedAsset: dependencies.GENERATED_AERIAL_ASSET,
    });
  };
  const methods = {
    mountMap3DLoadingScreenV1(this: AtlasMapLoadingSceneElement): void {
      if (this.hasAttribute("compact") || this.querySelector("[data-map-3d-loading]")) return;
      const initial = projectAtlasMapLoadingScreen({ phase: "waiting", extra: { progress: 4 } });
      const pdfBackdrop = `<div class="map-3d-loading-backdrop" data-map-3d-loading-backdrop="pdf-page" aria-hidden="true"><div class="map-3d-loading-backdrop-page"></div></div>`;
      this.insertAdjacentHTML("afterbegin", `<section class="map-3d-loading-screen" data-map-3d-loading data-map-3d-loading-state="loading" role="status" aria-live="polite">${pdfBackdrop}<div class="map-3d-loading-card"><div class="map-3d-loading-mark"><span>3D</span><i></i></div><span class="activity-kind">PRÉ-CARREGAMENTO · MAPA OPERACIONAL</span><h2 data-map-3d-loading-title>${initial.title}</h2><p data-map-3d-loading-detail>${initial.detail}</p><div class="map-3d-loading-track" aria-hidden="true"><i data-map-3d-loading-progress></i></div><footer><b data-map-3d-loading-value>${initial.value}</b><small data-map-3d-loading-phase>${initial.label}</small></footer></div></section>`);
      this.updateMap3DLoadingScreenV1("waiting", { progress: initial.progress });
    },
    preparePublicStaticBaseV1(this: AtlasMapLoadingSceneElement, state = "static-base-ready"): boolean {
      if (!this.isPublicCustomerExperience?.()) return false;
      this.dataset.renderMode = "3d-static-satellite";
      this.dataset.mapInit = "static-capture-no-maps";
      this.dataset.publicMapProvider = "local-capture";
      this.dataset.publicMapRequests = "0";
      this.dataset.publicStaticState = state;
      if (state === "static-base-loading") this.removeAttribute("data-public-static-base-ready");
      else this.dataset.publicStaticBaseReady = "true";
      this.querySelector("[data-map-3d-loading]")?.setAttribute("hidden", "");
      const sticky = this.closest(".public-map-sticky") as HTMLElement | null;
      const staticBackground = sticky?.querySelector<HTMLElement>(".public-map-static-bg");
      if (staticBackground) {
        staticBackground.hidden = false;
        staticBackground.removeAttribute("data-three-texture-active");
        staticBackground.dataset.publicFallback = "local-capture";
      }
      const source = captureSource(this);
      const adminStaticHost = this.isAdminPublicMapV1?.() ? this.querySelector<HTMLElement>(".map-host") : null;
      if (adminStaticHost) {
        adminStaticHost.style.setProperty("--admin-static-satellite-image", `url("${source}")`);
        adminStaticHost.style.backgroundImage = `url("${source}")`;
        adminStaticHost.style.backgroundSize = "cover";
        adminStaticHost.style.backgroundPosition = "center";
        adminStaticHost.style.backgroundRepeat = "no-repeat";
        adminStaticHost.style.backgroundColor = "#07101e";
        adminStaticHost.style.opacity = "1";
        adminStaticHost.style.visibility = "visible";
        adminStaticHost.style.display = "block";
        adminStaticHost.style.pointerEvents = "none";
        adminStaticHost.style.zIndex = "0";
        adminStaticHost.dataset.backgroundRole = "public-static-capture";
      }
      return true;
    },
    waitForPublicStaticBaseV1(this: AtlasMapLoadingSceneElement): Promise<boolean> {
      if (!this.isPublicCustomerExperience?.()) return Promise.resolve(false);
      if (this._publicStaticBasePromiseV1) return this._publicStaticBasePromiseV1;
      const source = captureSource(this);
      this._publicStaticBasePromiseV1 = new Promise(resolve => {
        const image = new browser.Image();
        let settled = false;
        let timeout: ReturnType<typeof globalThis.setTimeout> | undefined;
        const finish = (loaded: boolean, state: string): void => {
          if (settled) return;
          settled = true;
          if (timeout !== undefined) clearTimeoutRef(timeout);
          this.preparePublicStaticBaseV1(state);
          resolve(loaded);
        };
        image.decoding = "async";
        image.onload = () => finish(true, "static-base-loaded");
        image.onerror = () => finish(false, "static-base-unavailable");
        image.src = new URL(source, documentRef.baseURI).href;
        if (image.complete) globalThis.queueMicrotask(() => finish(image.naturalWidth > 0, image.naturalWidth > 0 ? "static-base-loaded" : "static-base-unavailable"));
        timeout = setTimeoutRef(() => finish(image.naturalWidth > 0, "static-base-timeout"), 5000);
      });
      return this._publicStaticBasePromiseV1;
    },
    updateMap3DLoadingScreenV1(this: AtlasMapLoadingSceneElement, phase = "waiting", extra: Record<string, unknown> = {}): void {
      const screen = this.querySelector<HTMLElement>("[data-map-3d-loading]");
      if (!screen) return;
      const snapshot = projectAtlasMapLoadingScreen({
        phase,
        extra,
        modelProgress: this.dataset.modelProgress,
        publicCustomer: this.isPublicCustomerExperience?.() === true,
        adminMasterplanOverlay: this.dataset.adminMasterplanOverlay === "true",
      });
      if (snapshot.state === "public-static") {
        screen.dataset.map3dLoadingState = snapshot.state;
        screen.setAttribute("hidden", "");
        return;
      }
      screen.dataset.map3dLoadingState = snapshot.state;
      screen.querySelector("[data-map-3d-loading-title]")?.replaceChildren(documentRef.createTextNode(snapshot.title));
      screen.querySelector("[data-map-3d-loading-detail]")?.replaceChildren(documentRef.createTextNode(snapshot.detail));
      screen.querySelector("[data-map-3d-loading-phase]")?.replaceChildren(documentRef.createTextNode(snapshot.label));
      const bar = screen.querySelector<HTMLElement>("[data-map-3d-loading-progress]");
      if (bar) bar.style.width = `${snapshot.progress}%`;
      const value = screen.querySelector<HTMLElement>("[data-map-3d-loading-value]");
      if (value) value.textContent = snapshot.value;
      if (snapshot.hidden) screen.setAttribute("hidden", "");
      else screen.removeAttribute("hidden");
    },
    begin3dBootStateV5367(this: AtlasMapLoadingSceneElement, initial: Record<string, unknown>): Record<string, unknown> {
      return dependencies.beginBootStateV5367(initial);
    },
    update3dBootStateV5367(this: AtlasMapLoadingSceneElement, patch: Record<string, unknown>): Record<string, unknown> {
      return dependencies.updateBootStateV5367(patch);
    },
    record3dBootPhaseV5367(this: AtlasMapLoadingSceneElement, phase: string, extra: Record<string, unknown> = {}): Record<string, unknown> {
      const state = dependencies.persistBootPhaseV5367(phase, extra);
      this.dataset.modelBootPhase = phase;
      this.dataset.modelBootVersion = String(state.version || "");
      this.updateMap3DLoadingScreenV1(phase, extra);
      return state;
    },
  };
  Object.defineProperties(MapScene.prototype, Object.getOwnPropertyDescriptors(methods));
  return MapScene;
}

