interface AtlasMapSceneAerialFrameDependencies {
  geoQuad: Readonly<Record<string, { u: unknown; v: unknown }>>;
  siteFrameV1: Readonly<Record<string, unknown>>;
  siteFrameV2: Readonly<Record<string, unknown>>;
}

/** Install the shared aerial reference frame computed from the canonical site corners. */
export function installAtlasMapSceneAerialFrame(
  MapScene: CustomElementConstructor,
  dependencies: AtlasMapSceneAerialFrameDependencies,
): CustomElementConstructor {
  const prototype = MapScene.prototype as unknown as AtlasMapSceneAerialFrameElement & Record<string, unknown>;
  prototype.isAdminReferenceAerialV1 = function(this: AtlasMapSceneAerialFrameElement): boolean {
    return Boolean(this.hasAttribute("data-admin-shared-public-map") && this.adminReferenceAerialTextureV1?.image);
  };
  prototype.adminReferenceAerialFrameV1 = function(this: AtlasMapSceneAerialFrameElement): Record<string, unknown> {
    if (!this._adminStandaloneWrapperV5370?.userData?.adminReferenceAerialGeoWarp) {
      const frame = { ...dependencies.siteFrameV1, ...dependencies.siteFrameV2 };
      const left = Number(frame.left), right = Number(frame.right), top = Number(frame.top), bottom = Number(frame.bottom);
      const siteWidth = Math.max(0.01, right - left);
      const siteDepth = Math.max(0.01, bottom - top);
      return {
        ...frame,
        siteWidth,
        siteDepth,
        siteCenterU: (left + right) / 2,
        siteCenterV: (top + bottom) / 2,
        frame: "legacy user supplied aerial site window",
      };
    }
    const corners = Object.values(dependencies.geoQuad);
    const left = Math.min(...corners.map(point => Number(point.u)));
    const top = Math.min(...corners.map(point => Number(point.v)));
    const right = Math.max(...corners.map(point => Number(point.u)));
    const bottom = Math.max(...corners.map(point => Number(point.v)));
    const siteWidth = Math.max(0.01, right - left);
    const siteDepth = Math.max(0.01, bottom - top);
    return {
      left, top, right, bottom, siteWidth, siteDepth,
      siteCenterU: (left + right) / 2,
      siteCenterV: (top + bottom) / 2,
      corners: dependencies.geoQuad,
      frame: "DWG EPSG:31984 four-corner projection · fixed aerial homography",
    };
  };
  return MapScene;
}

interface AtlasMapSceneCleanupElement extends HTMLElement {
  disconnectedCallback?: () => void;
  clearAdminAerialZoomTilesV1?: () => void;
  _compactResizeObserver?: { disconnect?: () => void } | null;
  _compactVisibilityObserver?: { disconnect?: () => void } | null;
  _compactVisible?: boolean;
  _compactStageMaterials?: { forEach?: (callback: (material: { dispose?: () => void } | null | undefined) => void) => void; clear?: () => void } | null;
  _compactRenderer?: { dispose?: () => void } | null;
  _compactCamera?: unknown;
  _persistentMapMounted?: boolean;
}

/** Own compact-map teardown while leaving persistent map scenes mounted across route changes. */
export function installAtlasMapSceneCleanup(
  MapScene: CustomElementConstructor,
  dependencies: { compactMapMirrors: { delete(scene: HTMLElement): unknown } },
): CustomElementConstructor {
  const prototype = MapScene.prototype as unknown as AtlasMapSceneCleanupElement;
  prototype.disconnectedCallback = function(this: AtlasMapSceneCleanupElement): void {
    this.clearAdminAerialZoomTilesV1?.();
    if (!this.hasAttribute("compact")) return;
    dependencies.compactMapMirrors.delete(this);
    this._compactResizeObserver?.disconnect?.();
    this._compactResizeObserver = null;
    this._compactVisibilityObserver?.disconnect?.();
    this._compactVisibilityObserver = null;
    this._compactVisible = false;
    this._compactStageMaterials?.forEach?.(material => material?.dispose?.());
    this._compactStageMaterials?.clear?.();
    this._compactStageMaterials = null;
    this._compactRenderer?.dispose?.();
    this._compactRenderer = null;
    this._compactCamera = null;
    this._persistentMapMounted = false;
  };
  return MapScene;
}

interface AtlasMapSceneGeometryNode {
  geometry?: unknown;
  userData?: Record<string, any>;
  add?: (object: unknown) => void;
  position?: { z: number };
}

interface AtlasMapSceneGeometryElement extends HTMLElement {
  curbOutlineGroup?: { removeFromParent?: () => void } | null;
  addCurbOutlines?: (THREE: Record<string, any>, sources?: AtlasMapSceneGeometryNode[]) => void;
  addFocusStructureOutlines?: (THREE: Record<string, any>, nodes: AtlasMapSceneGeometryNode[]) => void;
}

/** Own edge geometry used to highlight curb and focal structure meshes. */
export function installAtlasMapSceneGeometryOverlays(
  MapScene: CustomElementConstructor,
  dependencies: { logger?: Pick<Console, "warn"> } = {},
): CustomElementConstructor {
  const logger = dependencies.logger || globalThis.console;
  const prototype = MapScene.prototype as unknown as AtlasMapSceneGeometryElement;
  prototype.addCurbOutlines = function(this: AtlasMapSceneGeometryElement, THREE: Record<string, any>, sources: AtlasMapSceneGeometryNode[] = []): void {
    if (this.curbOutlineGroup) {
      this.curbOutlineGroup.removeFromParent?.();
      this.curbOutlineGroup = null;
    }
    const group = new THREE.Group();
    group.name = "BelavistaCurbs";
    group.renderOrder = 14;
    const material = new THREE.LineBasicMaterial({ color: 0xd9d3c6, transparent: true, opacity: 0.96, depthWrite: false, depthTest: true });
    let count = 0;
    for (const source of sources) {
      const geometry = source?.geometry as { getAttribute?: (name: string) => { count?: number } | undefined } | undefined;
      if (!geometry?.getAttribute?.("position")) continue;
      try {
        const edges = new THREE.EdgesGeometry(geometry, 18);
        if (!edges.getAttribute("position")?.count) { edges.dispose(); continue; }
        const curb = new THREE.LineSegments(edges, material);
        curb.name = `MeioFio_${String(count + 1).padStart(2, "0")}`;
        curb.renderOrder = 14;
        curb.position.z = 0.085;
        curb.userData = { belavistaRole: "curb", partKind: "curbs", partLabel: `Meio-fio · trecho ${count + 1}`, defaultMaterial: material };
        source.add?.(curb);
        count++;
      } catch (error) {
        logger.warn("Falha ao criar meio-fio visual.", error);
      }
    }
    this.curbOutlineGroup = group;
    this.dataset.curbOutlines = String(count);
    this.dataset.curbTarget = "aprox. 8000 m lineares · referência operacional";
  };
  prototype.addFocusStructureOutlines = function(this: AtlasMapSceneGeometryElement, THREE: Record<string, any>, nodes: AtlasMapSceneGeometryNode[]): void {
    nodes.forEach(node => {
      if (!node?.geometry || node.userData?.belavistaOutline) return;
      const outline = new THREE.LineSegments(node.geometry && new THREE.EdgesGeometry(node.geometry, 12), new THREE.LineBasicMaterial({ color: 0xffd166, transparent: true, opacity: 0.95, depthTest: false }));
      outline.name = "Belavista_3D_structure_outline";
      outline.raycast = () => {};
      node.add?.(outline);
      node.userData ||= {};
      node.userData.belavistaOutline = true;
    });
  };
  return MapScene;
}

interface AtlasLeafletSceneDependencies {
  viewThemes: Record<string, { center: readonly unknown[]; zoom: unknown }>;
  mapCameraView: string;
  validGeoPoint: (point: unknown) => boolean;
  appStore: { get(): Record<string, unknown> };
  commands: Pick<AtlasMapSceneStateCommandsV1, "markMapReady">;
  leaflet: Record<string, any>;
  windowRef: Window & { ResizeObserver?: typeof ResizeObserver };
  performanceRef: Pick<Performance, "now">;
  ResizeObserverImpl?: typeof ResizeObserver;
}

interface AtlasLeafletSceneElement extends HTMLElement {
  map?: any;
  _mapReady?: boolean;
  _suppressMapToggleUntil?: number;
  _lastObservedMapSize?: string;
  _lastResizeObserverSize?: string;
  _mapResizeFrame?: number;
  _mapResizeObserver?: ResizeObserver | null;
  initLeaflet?: () => void;
  syncThree?: () => void;
  pickModelAt?: (point: { x: number; y: number }) => boolean;
  clearCurrentMapSelectionV1?: (clearStage?: boolean) => void;
  setTheme?: (theme: string) => void;
  setMapContext?: (view: unknown) => void;
  isPublicCustomerExperience?: () => boolean;
}

/** Install the typed Leaflet lifecycle retained for administrative geographic views. */
export function installAtlasLeafletMapScene(
  MapScene: CustomElementConstructor,
  dependencies: AtlasLeafletSceneDependencies,
): CustomElementConstructor {
  const { viewThemes, mapCameraView, validGeoPoint, appStore, commands, leaflet: L, windowRef, performanceRef } = dependencies;
  const ResizeObserverRef = dependencies.ResizeObserverImpl || windowRef.ResizeObserver;
  const prototype = MapScene.prototype as unknown as AtlasLeafletSceneElement;
  prototype.initLeaflet = function(this: AtlasLeafletSceneElement): void {
    if (this.isPublicCustomerExperience?.()) {
      this.dataset.leaflet = "disabled-static-capture";
      this.dataset.publicMapProvider = "local-capture";
      this.dataset.publicMapRequests = "0";
      return;
    }
    const host = this.querySelector<HTMLElement>(".map-host");
    if (!host || this.map) return;
    const initial = viewThemes.assistant;
    const center = L.latLng(Number(initial.center[0]), Number(initial.center[1]));
    if (!validGeoPoint(center)) return;
    this.map = L.map(host, { zoomControl: false, attributionControl: true, preferCanvas: true, zoomAnimation: false, fadeAnimation: false, scrollWheelZoom: false, minZoom: 13, maxZoom: 22 }).setView(center, Number(initial.zoom));
    this.dataset.leaflet = "ready";
    this.dataset.mapNavigation = "free scene · no 3D viewbox";
    L.control.zoom({ position: "bottomright" }).addTo(this.map);
    this.map.on("moveend zoomend", () => this.syncThree?.());
    this.map.on("click", (event: any) => {
      const canvasRect = this.querySelector(".three-overlay")?.getBoundingClientRect();
      const hostRect = host.getBoundingClientRect();
      const point = { x: event.containerPoint.x + hostRect.left - (canvasRect?.left || hostRect.left), y: event.containerPoint.y + hostRect.top - (canvasRect?.top || hostRect.top) };
      if (this.pickModelAt?.(point)) this._suppressMapToggleUntil = performanceRef.now() + 280;
      else this.clearCurrentMapSelectionV1?.(true);
    });
    const refreshMap = (): void => {
      if (!this.map) return;
      const rect = host.getBoundingClientRect();
      const key = `${Math.max(1, Math.round(rect.width))}x${Math.max(1, Math.round(rect.height))}`;
      if (this._lastObservedMapSize === key) return;
      this._lastObservedMapSize = key;
      this.map.invalidateSize?.({ pan: false, debounceMoveend: true });
      this.syncThree?.();
    };
    if (ResizeObserverRef) {
      this._mapResizeObserver = new ResizeObserverRef(entries => {
        const rect = entries?.[0]?.contentRect;
        const key = `${Math.max(1, Math.round(rect?.width || host.clientWidth || 0))}x${Math.max(1, Math.round(rect?.height || host.clientHeight || 0))}`;
        if (key === this._lastResizeObserverSize) return;
        this._lastResizeObserverSize = key;
        if (this._mapResizeFrame) return;
        this._mapResizeFrame = windowRef.requestAnimationFrame(() => { this._mapResizeFrame = 0; refreshMap(); });
      });
      this._mapResizeObserver.observe(host);
    }
    this.map.whenReady(() => {
      this._mapReady = true;
      const active = viewThemes[mapCameraView] || viewThemes.assistant;
      this.map.setView(L.latLng(Number(active.center[0]), Number(active.center[1])), Number(active.zoom), { animate: false });
      commands.markMapReady();
      this.setTheme?.(mapCameraView);
      this.setMapContext?.(appStore.get().view);
      this._lastObservedMapSize = "";
      windowRef.requestAnimationFrame(refreshMap);
    });
  };
  return MapScene;
}

type AtlasPublicLotCommercialStatus = "available" | "reserved" | "negotiation" | "sold";
interface AtlasPublicLotScenePart {
  name?: string;
  userData?: Record<string, unknown>;
  material?: unknown;
}
interface AtlasPublicLotStatusScene extends HTMLElement {
  modelParts?: { lots?: AtlasPublicLotScenePart[] };
  publicLotStatusCounts?: Record<AtlasPublicLotCommercialStatus, number>;
  publicLotFilter?: string;
  canonicalPublicLotParts?: () => AtlasPublicLotScenePart[];
  setPublicLotStatuses?: (entries?: unknown) => void;
  setPublicLotFilter?: (status?: string) => void;
  clearPublicLotFilter?: () => void;
  materialForColor?: (material: unknown, color: number, opacity?: number) => unknown;
  restorePartMaterial?: (part: AtlasPublicLotScenePart) => void;
  renderer?: { render: (scene: unknown, camera: unknown) => void };
  scene?: unknown;
  camera?: unknown;
}

interface AtlasPublicLotStatusDependencies {
  CustomEventImpl?: typeof CustomEvent;
}

/** Install typed lot-status normalization and the matching 3D mesh filter. */
export function installAtlasPublicLotStatusController(MapScene: CustomElementConstructor, dependencies: AtlasPublicLotStatusDependencies = {}): CustomElementConstructor {
  if (typeof MapScene !== "function" || !MapScene.prototype)
    throw new TypeError("Public lot status requires the MapScene class.");
  const CustomEventRef = dependencies.CustomEventImpl || globalThis.CustomEvent;
  const methods = {
    canonicalPublicLotParts(this: AtlasPublicLotStatusScene): AtlasPublicLotScenePart[] {
      const lots = (this.modelParts?.lots || []).filter(lot => /^lote(?:[_ -]?\d+)$/i.test(String(lot?.name || "")));
      return [...new Map(lots.map(lot => [String(lot.name), lot])).values()];
    },
    setPublicLotStatuses(this: AtlasPublicLotStatusScene, entries: unknown = []): void {
      const lots = this.canonicalPublicLotParts?.() || [];
      const snapshot = projectAtlasPublicLotMeshStatuses(lots.map(lot => ({ name: String(lot.name || ""), partId: lot.userData?.partId })), entries);
      const statusByPartId = new Map(snapshot.rows.map(row => [row.partId, row.status]));
      this.publicLotStatusCounts = snapshot.counts;
      for (const lot of lots) {
        const key = String(lot.userData?.partId || lot.name);
        lot.userData ||= {};
        lot.userData.publicCommercialStatus = statusByPartId.get(key) || "available";
      }
      this.dataset.publicLotStatuses = "connected";
      this.dataset.publicLotStatusCount = String(lots.length);
      this.dataset.publicLotStatusCounts = JSON.stringify(snapshot.counts);
      this.dataset.publicLotStatusMapping = "canonical lot meshes only · duplicate GLB auxiliary meshes excluded";
      if (this.publicLotFilter) this.setPublicLotFilter?.(this.publicLotFilter);
      this.dispatchEvent(new CustomEventRef("public-commercial-marker-statuses", { detail: { entries } }));
    },
    setPublicLotFilter(this: AtlasPublicLotStatusScene, status = "available"): void {
      const valid = new Set<AtlasPublicLotCommercialStatus>(["available", "reserved", "negotiation", "sold"]);
      if (!valid.has(status as AtlasPublicLotCommercialStatus)) { this.clearPublicLotFilter?.(); return; }
      const color = publicMapCommercialStatusPresentation(status).color;
      for (const lot of this.canonicalPublicLotParts?.() || []) {
        const userData = lot.userData || {};
        if (userData.publicStatusMaterial) {
          delete userData.publicStatusMaterial;
          this.restorePartMaterial?.(lot);
        }
        if (userData.publicCommercialStatus !== status) continue;
        userData.publicStatusMaterial = this.materialForColor?.(userData.defaultMaterial, color, 0.98);
        lot.userData = userData;
        lot.material = userData.publicStatusMaterial;
      }
      this.publicLotFilter = status;
      this.dataset.publicLotFilter = status;
      this.dataset.publicLotMatches = String(this.publicLotStatusCounts?.[status as AtlasPublicLotCommercialStatus] || 0);
      this.renderer?.render(this.scene, this.camera);
    },
    clearPublicLotFilter(this: AtlasPublicLotStatusScene): void {
      for (const lot of this.canonicalPublicLotParts?.() || []) {
        const userData = lot.userData || {};
        if (!userData.publicStatusMaterial) continue;
        delete userData.publicStatusMaterial;
        lot.userData = userData;
        this.restorePartMaterial?.(lot);
      }
      this.publicLotFilter = "";
      delete this.dataset.publicLotFilter;
      delete this.dataset.publicLotMatches;
      this.renderer?.render(this.scene, this.camera);
    },
  };
  const prototype = MapScene.prototype as unknown as Record<string, unknown>;
  Object.entries(methods).forEach(([name, method]) => Object.defineProperty(prototype, name, { configurable: true, writable: true, value: method }));
  return MapScene;
}

interface AtlasMapSceneTiltConfig {
  ADMIN_STANDALONE_BASE_TILT_DEG_V1: number;
  DEFAULT_SCENE_ZOOM: number;
  MAP_CAMERA_VIEW: string;
  MAX_SCENE_TILT: number;
  MIN_SCENE_TILT: number;
  SCENE_TILT_ADJUST_LIMIT: number;
  SCENE_TILT_ANIMATION_DURATION_MS?: number;
}
interface AtlasMapSceneTiltDependencies {
  config: AtlasMapSceneTiltConfig;
  sceneTiltBoostForView: (view: string) => number;
  viewThemes: Record<string, { tilt?: number }>;
  browser: { performanceNow: () => number; requestAnimationFrame: (callback: FrameRequestCallback) => number };
}
interface AtlasMapSceneTiltElement extends HTMLElement {
  sceneTiltAdjust?: number;
  sceneManualRotation?: number;
  sceneManualZoom?: number;
  _sceneVisual?: { tilt?: number; rotation?: number; scale?: number };
  _sceneTransition?: unknown;
  _adminStandaloneTiltV5370?: number;
  isAdminStandaloneInteractiveV5370?: () => boolean;
  isPublicCameraPreset?: () => boolean;
  getSceneTiltBounds?: () => { min: number; max: number };
  markAdminCameraInteracted?: () => void;
  setAdminStandaloneTiltV5370?: (degrees: number, animate?: boolean) => void;
  setSceneVisual: (tilt: number, rotation: number, scale: number) => void;
  rememberMapView?: () => void;
  constrainScenePan: (reason: string) => void;
}

/** Validate the injected scene, map theme and animation services for the tilt controller. */
export function assertAtlasMapSceneTiltDependencies(MapScene: CustomElementConstructor, dependencies: AtlasMapSceneTiltDependencies): AtlasMapSceneTiltDependencies {
  if (typeof MapScene !== "function" || !MapScene.prototype) throw new TypeError("Scene tilt requires the existing MapScene constructor.");
  if (!dependencies || typeof dependencies !== "object") throw new TypeError("Scene tilt requires injected dependencies.");
  const config = dependencies.config;
  const numericKeys: Array<keyof AtlasMapSceneTiltConfig> = ["ADMIN_STANDALONE_BASE_TILT_DEG_V1", "DEFAULT_SCENE_ZOOM", "MAX_SCENE_TILT", "MIN_SCENE_TILT", "SCENE_TILT_ADJUST_LIMIT"];
  if (typeof config?.MAP_CAMERA_VIEW !== "string" || !config.MAP_CAMERA_VIEW) throw new TypeError("Scene tilt requires config.MAP_CAMERA_VIEW.");
  for (const key of numericKeys) if (!Number.isFinite(config?.[key])) throw new TypeError(`Scene tilt requires numeric config.${key}.`);
  if (typeof dependencies.sceneTiltBoostForView !== "function" || !dependencies.viewThemes?.assistant) throw new TypeError("Scene tilt requires camera theme services.");
  if (typeof dependencies.browser?.performanceNow !== "function" || typeof dependencies.browser?.requestAnimationFrame !== "function") throw new TypeError("Scene tilt requires browser animation services.");
  return dependencies;
}

/** Install the effective tilt controller after navigation methods on MapScene. */
export function installAtlasMapSceneTiltController(MapScene: CustomElementConstructor, dependencies: AtlasMapSceneTiltDependencies): CustomElementConstructor {
  assertAtlasMapSceneTiltDependencies(MapScene, dependencies);
  const { config, sceneTiltBoostForView, viewThemes, browser } = dependencies;
  const methods = {
    setSceneTiltAdjust(this: AtlasMapSceneTiltElement, value: unknown, animate = true): void {
      this.markAdminCameraInteracted?.();
      const standalone = this.isAdminStandaloneInteractiveV5370?.() === true;
      const view = config.MAP_CAMERA_VIEW;
      const theme = viewThemes[view] || viewThemes.assistant;
      const publicPresentation = standalone ? false : this.isPublicCameraPreset?.() === true;
      const bounds = standalone ? undefined : this.getSceneTiltBounds?.();
      const command = projectAtlasMapSceneTilt({
        requestedAdjust: value,
        previousAdjust: this.sceneTiltAdjust,
        previousTilt: this._sceneVisual?.tilt,
        previousStandaloneTilt: this._adminStandaloneTiltV5370,
        standalone,
        standaloneBaseTilt: config.ADMIN_STANDALONE_BASE_TILT_DEG_V1,
        sharedAdmin: this.hasAttribute("data-admin-shared-public-map"),
        publicPresentation,
        themeTilt: theme.tilt,
        tiltBoost: sceneTiltBoostForView(view),
        minTilt: config.MIN_SCENE_TILT,
        maxTilt: config.MAX_SCENE_TILT,
        adjustLimit: config.SCENE_TILT_ADJUST_LIMIT,
        bounds,
      });
      this.sceneTiltAdjust = command.sceneTiltAdjust;
      this.dataset.sceneTiltBounds = `${command.bounds.min}–${command.bounds.max}deg`;
      if (command.branch === "standalone") {
        this.dataset.sceneTiltControl = "range + buttons · standalone";
        this.dataset.sceneTilt = `${Math.round(command.targetTilt)}deg`;
        this.setAdminStandaloneTiltV5370?.(command.targetTilt, animate);
        this.rememberMapView?.();
        return;
      }
      this.dataset.sceneTiltControl = "ctrl-mouse";
      this.rememberMapView?.();
      this.dataset.sceneTilt = `${command.targetTilt}deg`;
      const current = this._sceneVisual || {
        tilt: command.targetTilt,
        rotation: this.sceneManualRotation || 0,
        scale: this.sceneManualZoom || config.DEFAULT_SCENE_ZOOM,
      };
      if (!animate) {
        this._sceneTransition = Symbol("manual-tilt");
        this.setSceneVisual(command.targetTilt, current.rotation ?? 0, current.scale ?? config.DEFAULT_SCENE_ZOOM);
        return;
      }
      const started = browser.performanceNow();
      const duration = Number(config.SCENE_TILT_ANIMATION_DURATION_MS) || 320;
      const token = Symbol("manual-tilt");
      this._sceneTransition = token;
      const tick: FrameRequestCallback = now => {
        if (this._sceneTransition !== token) return;
        const t = Math.min(1, (now - started) / duration);
        const eased = t * t * (3 - 2 * t);
        this.setSceneVisual(
          (current.tilt ?? command.targetTilt) + (command.targetTilt - (current.tilt ?? command.targetTilt)) * eased,
          current.rotation ?? 0,
          current.scale ?? config.DEFAULT_SCENE_ZOOM,
        );
        if (t < 1) browser.requestAnimationFrame(tick);
        else this.constrainScenePan("tilt-finish");
      };
      browser.requestAnimationFrame(tick);
    },
  };
  const prototype = MapScene.prototype as unknown as Record<string, unknown>;
  Object.entries(methods).forEach(([name, method]) => Object.defineProperty(prototype, name, { configurable: true, writable: true, value: method }));
  return MapScene;
}

