  initWhenReady: () => void;
  bindStaticSatelliteMapGesturesV1?: () => void;
  preparePublicStaticBaseV1: (phase: string) => unknown;
  isAdminPublicMapV1?: () => boolean;
  installAdminMasterplanOverlayV1?: () => void;
  installSatelliteLotPlanOverlayV1?: (options: { markers: boolean; outlines: boolean }) => void;
  fitStaticSatelliteMasterplanV1?: () => void;
  waitForPublicStaticBaseV1: () => Promise<boolean>;
  isPublicCustomerExperience?: () => boolean;
  isAdminStandalone3DV5370?: () => boolean;
