interface AtlasMapSceneStartupDependencies {
  windowRef?: Window & { L?: unknown; requestIdleCallback?: (callback: () => void, options?: { timeout?: number }) => number };
  performanceRef?: Pick<Performance, "now">;
  requestAnimationFrame?: (callback: FrameRequestCallback) => number;
  setTimeout?: typeof globalThis.setTimeout;
  now?: () => number;
  getComputedStyle?: typeof globalThis.getComputedStyle;
  consoleRef?: Pick<Console, "warn">;
}

/** Install typed startup gates for static, shared, and full 3D map surfaces. */
export function installAtlasMapSceneStartupReadiness(
  MapScene: CustomElementConstructor,
  dependencies: AtlasMapSceneStartupDependencies = {},
): CustomElementConstructor {
  const windowRef: Window & { L?: unknown; requestIdleCallback?: (callback: () => void, options?: { timeout?: number }) => number } = dependencies.windowRef || globalThis.window as Window & { L?: unknown; requestIdleCallback?: (callback: () => void, options?: { timeout?: number }) => number };
  const performanceRef = dependencies.performanceRef || globalThis.performance;
  const requestAnimationFrameRef = dependencies.requestAnimationFrame || windowRef.requestAnimationFrame.bind(windowRef);
  const setTimeoutRef = dependencies.setTimeout || globalThis.setTimeout.bind(globalThis);
  const now = dependencies.now || (() => Date.now());
  const getComputedStyleRef = dependencies.getComputedStyle || globalThis.getComputedStyle.bind(globalThis);
  const consoleRef = dependencies.consoleRef || globalThis.console;
  const methods = {
    waitForAdminShellViewportV5376(this: AtlasMapSceneStartupElement): void {
      if (this._adminShellViewportGateV5376) return;
      this._adminShellViewportGateV5376 = true;
      this.dataset.adminModelLifecycle = "waiting-for-visible-shell";
      this.dataset.modelBootPhase = "waiting-admin-shell";
      const started = performanceRef.now();
      const tick = (): void => {
        if (!this.isConnected) return;
        const app = this.closest("belavista-app") as HTMLElement | null;
        const host = this.querySelector<HTMLElement>(".map-host");
        const rect = host?.getBoundingClientRect?.();
        const visible = Boolean(
          (!app || !app.hidden) && host && rect && rect.width > 32 && rect.height > 32 &&
          getComputedStyleRef(host).display !== "none" && getComputedStyleRef(host).visibility !== "hidden",
        );
        if (visible) {
          this._adminShellViewportReadyV5376 = true;
          this.dataset.adminModelLifecycle = "shell-visible-viewport-ready";
          this.dataset.adminShellReadyMs = String(Math.round(performanceRef.now() - started));
          this.dataset.modelBootPhase = "admin-shell-ready-static";
          this.initWhenReady();
          return;
        }
        setTimeoutRef(tick, 180);
      };
      requestAnimationFrameRef(() => requestAnimationFrameRef(tick));
    },
    initWhenReady(this: AtlasMapSceneStartupElement): void {
      const adminShared = this.hasAttribute("data-admin-shared-public-map");
      const startupMode = projectAtlasMapSceneStartupPolicy({
        adminShared,
        viewportReady: this._adminShellViewportReadyV5376 === true,
        publicStaticOnly: this.hasAttribute("data-public-static-only"),
        publicCustomerExperience: this.isPublicCustomerExperience?.() === true,
      });
      if (startupMode === "wait-admin-shell") {
        this.waitForAdminShellViewportV5376();
        return;
      }
      if (startupMode === "static-only") {
        this.mapTileMode = "generated";
        this.dataset.renderMode = "static-satellite-markers";
        this.dataset.mapInit = "static-only";
        this.dataset.publicThree = "disabled-static-only";
        this.bindStaticSatelliteMapGesturesV1?.();
        this.preparePublicStaticBaseV1("static-base-loading");
        if (this.isAdminPublicMapV1?.()) {
          this.installAdminMasterplanOverlayV1?.();
          this.installSatelliteLotPlanOverlayV1?.({ markers: true, outlines: false });
          requestAnimationFrameRef(() => requestAnimationFrameRef(() => this.fitStaticSatelliteMasterplanV1?.()));
          this.querySelectorAll("[data-public-static-lot-markers]").forEach(layer => layer.remove());
          this.querySelector("[data-map-3d-loading]")?.setAttribute("hidden", "");
        }
        void this.waitForPublicStaticBaseV1().then(loaded => {
          if (!this.isConnected) return;
          this.dataset.publicStaticImage = loaded ? "loaded" : "unavailable";
          this.dataset.renderMode = "static-satellite-markers";
          this.dataset.publicThree = "disabled-static-only";
        });
        return;
      }
      if (startupMode === "public-static-first") {
        this.mapTileMode = "generated";
        this.dataset.publicThree = "waiting-static-base";
        this.preparePublicStaticBaseV1("static-base-loading");
        void this.waitForPublicStaticBaseV1().then(loaded => {
          if (!this.isConnected) return;
          this.dataset.publicStaticImage = loaded ? "loaded" : "unavailable";
          this.dataset.publicThree = "forced-after-static";
          this.scheduleThree({ force: true });
        });
        return;
      }
      if (startupMode === "shared-map") {
        this.dataset.renderMode = "3d-public-shared";
        this.dataset.mapInit = windowRef.L ? "leaflet-found" : "three-first";
        if (windowRef.L) {
          try {
            this.initLeaflet();
          } catch (error) {
            this.dataset.mapInit = "leaflet-error";
            consoleRef.warn("Leaflet falhou no mapa administrativo compartilhado.", error);
          }
        }
        this.scheduleThree();
        return;
      }

      const allowThree = true;
      this.dataset.renderMode = allowThree ? "3d-experimental" : "safe-map";
      this.dataset.mapInit = "waiting";
      const started = now();
      const tick = (): void => {
        this.dataset.mapInit = windowRef.L ? "leaflet-found" : "waiting";
        if (windowRef.L) {
          try {
            this.initLeaflet();
          } catch (error) {
            this.dataset.mapInit = "leaflet-error";
            consoleRef.warn("Leaflet indisponível, mantendo superfície de mapa.", error);
          }
          if (allowThree) this.scheduleThree();
          return;
        }
        if (now() - started < 7000) setTimeoutRef(tick, 100);
        else {
          this.dataset.mapInit = "timeout";
          if (allowThree) this.scheduleThree();
        }
      };
      tick();
    },
    scheduleThree(this: AtlasMapSceneStartupElement, { force = false }: { force?: boolean } = {}): boolean | void {
      const policy = projectAtlasMapSceneThreeSchedule({
        staticOnly: this.hasAttribute("data-public-static-only"),
        publicCustomerExperience: this.isPublicCustomerExperience?.() === true,
        force,
        standalone: this.isAdminStandalone3DV5370?.() === true,
        standaloneActivated: this._adminStandaloneActivatedV5370 === true,
        alreadyScheduled: this._threeScheduled === true,
        rendererInitialized: Boolean(this.renderer),
      });
      if (policy.action === "blocked-static-only") {
        this.dataset.three = "blocked-static-only";
        this.dataset.publicThree = "disabled-static-only";
        this.dataset.modelBootPhase = policy.modelBootPhase;
        return false;
      }
      if (policy.action === "blocked-static-first") {
        this.dataset.three = "blocked-static-first";
        this.dataset.modelBootPhase = policy.modelBootPhase;
        return;
      }
      if (policy.action === "already-initialized") return;
      this._threeScheduled = true;
      this.dataset.modelBootPhase = policy.modelBootPhase;
      const run = (): void => {
        void Promise.resolve(this.initThree()).catch(error => {
          const publicStaticFallback = this.isPublicCustomerExperience?.() === true;
          this.dataset.three = publicStaticFallback ? "fallback-static" : "fallback";
          this.dataset.modelError = "three-init-failed";
          this.dataset.modelBootPhase = "three-init-error";
          if (publicStaticFallback) this.preparePublicStaticBaseV1("static-fallback");
          else this.updateMap3DLoadingScreenV1("three-init-error");
          consoleRef.warn("[Aliança Park] inicialização 3D falhou; base pública preservada.", error);
        });
      };
      requestAnimationFrameRef(() => {
        if (policy.forcedPublicBoot) {
          run();
          return;
        }
        setTimeoutRef(() => {
          if (windowRef.requestIdleCallback) windowRef.requestIdleCallback(run, { timeout: 1200 });
          else run();
        }, 650);
      });
    },
  };
  const prototype = MapScene.prototype as unknown as Record<string, unknown>;
  Object.entries(methods).forEach(([name, method]) => Object.defineProperty(prototype, name, { configurable: true, writable: true, value: method }));
  return MapScene;
}

