/** Create the shared Three.js renderer, camera, map surface, and selection primitives. */
export function initializeAtlasMapThreeFoundationV1(
  sceneElement: HTMLElement,
  dependencies: AtlasMapThreeInitializationDependencies,
): void {
  const scene = sceneElement as AtlasMapThreeInitializationElement;
  const { threeModule: THREE, gltfLoader, appStore } = dependencies;
  const canvas = scene.querySelector<HTMLCanvasElement>('.three-overlay');
  const adminRuntime = !scene.isAdminPublicMapV1?.() && (
    dependencies.locationPath === '/admin' ||
    dependencies.locationPath.startsWith('/admin/') ||
    scene.hasAttribute('data-admin-shared-public-map') ||
    Boolean(scene.closest('belavista-app'))
  );
  const publicHighQuality = !adminRuntime && Boolean(scene.matches?.(
    'map-scene[data-public-map],map-scene[data-public-presentation]',
  ));
  const profile = projectAtlasMapThreeRendererProfile({
    adminRuntime,
    publicHighQuality,
    devicePixelRatio: dependencies.devicePixelRatio,
  });

  scene.THREE = THREE;
  scene.GLTFLoader = gltfLoader;
  if (adminRuntime) {
    scene.dataset.adminThreeContext = atlasMapThreeFoundation.renderer.adminContextLabel;
    scene.dataset.publicRendererProfile = atlasMapThreeFoundation.renderer.adminPublicProfileLabel;
  }
  scene.renderer = new THREE.WebGLRenderer({
    canvas,
    alpha: true,
    antialias: profile.antialias,
    powerPreference: profile.powerPreference,
    precision: profile.precision,
  });
  scene.renderer.shadowMap.enabled = true;
  scene.renderer.shadowMap.type = THREE.PCFSoftShadowMap;
  scene.renderer.setPixelRatio(profile.pixelRatio);
  if (publicHighQuality) {
    scene.dataset.publicRenderQuality = atlasMapThreeFoundation.renderer.publicQualityLabel;
    scene.dataset.publicRenderPixelRatio = profile.pixelRatio.toFixed(2);
  } else {
    scene.dataset.bootPixelRatio = atlasMapThreeFoundation.renderer.publicBootPixelRatioLabel;
    scene.dataset.adminRenderQuality = atlasMapThreeFoundation.renderer.adminQualityLabel;
  }
  scene.renderer.outputColorSpace = THREE.SRGBColorSpace;
  scene.renderer.toneMapping = THREE.ACESFilmicToneMapping;
  scene.renderer.toneMappingExposure = atlasMapThreeFoundation.renderer.toneMappingExposure;
  scene.dataset.modelRender = atlasMapThreeFoundation.renderer.modelRenderLabel;
  scene.dataset.modelRasterized = atlasMapThreeFoundation.renderer.modelRasterizedLabel;
  scene.dataset.three = 'ready';
  if (scene.isPublicMapVisual()) scene.dataset.publicThree = 'ready';

  scene.scene = new THREE.Scene();
  const hemisphereConfig = atlasMapThreeFoundation.hemisphereLight;
  const directionalConfig = atlasMapThreeFoundation.directionalLight;
  const hemisphere = new THREE.HemisphereLight(hemisphereConfig.skyColor, hemisphereConfig.groundColor, hemisphereConfig.intensity);
  const keyLight = new THREE.DirectionalLight(directionalConfig.color, directionalConfig.intensity);
  keyLight.castShadow = true;
  keyLight.position.set(...directionalConfig.position as [number, number, number]);
  keyLight.target.position.set(...directionalConfig.target as [number, number, number]);
  scene.scene.add(hemisphere, keyLight, keyLight.target);
  scene.solarHemisphere = hemisphere;
  scene.solarLight = keyLight;
  scene.sceneStage = new THREE.Group();
  scene.sceneStage.scale.setScalar(atlasMapThreeFoundation.sceneStageScale);
  scene.scene.add(scene.sceneStage);
  const cameraConfig = atlasMapThreeFoundation.camera;
  scene.camera = scene.isAdminOrthographicMapV1()
    ? new THREE.OrthographicCamera(cameraConfig.orthographic.left, cameraConfig.orthographic.right, cameraConfig.orthographic.top, cameraConfig.orthographic.bottom, cameraConfig.orthographic.near, cameraConfig.orthographic.far)
    : new THREE.PerspectiveCamera(cameraConfig.perspective.fieldOfView, cameraConfig.perspective.aspect, cameraConfig.perspective.near, cameraConfig.perspective.far);
  scene.dataset.cameraProjection = scene.isAdminOrthographicMapV1()
    ? 'orthographic'
    : 'perspective';
  scene.applySolarLighting(dependencies.solarStateForHour(
    scene.solarHour ?? appStore.get().solarHour ?? 9,
    scene.solarGeo || dependencies.mapGeoreferenceFallback,
  ));

  scene.mapSurfaceCanvas = dependencies.documentRef.createElement('canvas') as HTMLCanvasElement;
  scene.mapSurfaceTexture = new THREE.CanvasTexture(scene.mapSurfaceCanvas);
  scene.mapSurfaceTexture.colorSpace = THREE.SRGBColorSpace;
  scene.mapSurfaceTexture.generateMipmaps = false;
  scene.mapSurfaceTexture.minFilter = THREE.LinearFilter;
  scene.mapSurfaceTexture.magFilter = THREE.LinearFilter;
  scene.mapSurfaceTexture.anisotropy = Math.min(
    atlasMapThreeFoundation.mapSurface.anisotropyMaximum,
    scene.renderer.capabilities?.getMaxAnisotropy?.() || 1,
  );
  scene.mapSurface = new THREE.Mesh(
    new THREE.PlaneGeometry(atlasMapThreeFoundation.mapSurface.width, atlasMapThreeFoundation.mapSurface.height),
    new THREE.MeshBasicMaterial({
      map: scene.mapSurfaceTexture,
      color: 0xffffff,
      side: THREE.DoubleSide,
      transparent: false,
      depthTest: false,
      depthWrite: false,
    }),
  );
  scene.mapSurface.renderOrder = atlasMapThreeFoundation.mapSurface.renderOrder;
  scene.mapSurface.visible = !scene.hasAttribute('data-public-static-base');
  scene.mapSurface.position.z = dependencies.sceneMapZ;
  scene.sceneStage.add(scene.mapSurface);
  scene.dataset.mapRasterMode = 'webgl-raster';
  scene.dataset.mapContact = `Captura satélite local + GLB na mesma cena Three.js · sem Maps · surface z=${dependencies.sceneMapZ} · model base z=${dependencies.sceneModelBaseZ}`;

  scene.markerGroup = new THREE.Group();
  scene.sceneStage.add(scene.markerGroup);
  scene.gpsMarkerGeometry = new THREE.CircleGeometry(atlasMapThreeFoundation.gpsMarkers.radius, atlasMapThreeFoundation.gpsMarkers.segments);
  scene.gpsMarkerColors = [...atlasMapThreeFoundation.gpsMarkers.colors];
  scene.setGpsMarkers(THREE, [atlasMapThreeFoundation.gpsMarkers.fallbackCenter]);
  scene.dataset.dwgGeoreference = 'deferred-until-gpu-ready-v5367';
  scene.modelGroup = new THREE.Group();
  scene.sceneStage.add(scene.modelGroup);
  scene.dataset.modelHeight = 'native GLB scale';
  scene.modelParts = { lots: [], streets: [], other: [] };
  scene.stageOverlayTargets = {};
  scene.raycaster = new THREE.Raycaster();
  scene.pointer = new THREE.Vector2();
  scene.selectionHalo = new THREE.Mesh(
    new THREE.RingGeometry(atlasMapThreeFoundation.selectionHalo.innerRadius, atlasMapThreeFoundation.selectionHalo.outerRadius, atlasMapThreeFoundation.selectionHalo.segments),
    new THREE.MeshBasicMaterial({
      color: atlasMapThreeFoundation.selectionHalo.color,
      transparent: true,
      opacity: atlasMapThreeFoundation.selectionHalo.opacity,
      side: THREE.DoubleSide,
      depthTest: false,
    }),
  );
  scene.selectionHalo.visible = false;
  scene.sceneStage.add(scene.selectionHalo);
  scene.applySceneView(dependencies.mapCameraView, false);
}

interface AtlasMapThreeGestureDependencies {
  zoomDragSensitivity: number;
  tiltDragSensitivity: number;
}

/** Bind wheel, pointer, selection, and WebGL recovery to the mounted 3D map. */
export function bindAtlasMapThreeGesturesV1(
  sceneElement: HTMLElement,
  canvas: HTMLCanvasElement,
  dependencies: AtlasMapThreeGestureDependencies,
): void {
  const scene = sceneElement as AtlasMapThreeInitializationElement;
  let down: { x: number; y: number } | null = null;
  let lastX = 0;
  let lastY = 0;
  let dragging = false;
  let panning = false;
  let tilting = false;
  let rotating = false;
  let zooming = false;
  let selecting = false;

  canvas.addEventListener('contextmenu', event => event.preventDefault());
  const zoomSceneAtCursorByCtrlWheel = (event: WheelEvent): void => {
    if (event.defaultPrevented) return;
    const target = event.target as Element | null;
    if (target?.closest?.('button,input,select,textarea,label,a,[contenteditable="true"]')) return;
    const rect = canvas.getBoundingClientRect?.();
    if (!rect || event.clientX < rect.left || event.clientX > rect.right || event.clientY < rect.top || event.clientY > rect.bottom) return;
    event.preventDefault();
    event.stopPropagation();
    const command = projectAtlasMapThreeWheelZoom({ currentZoom: scene.sceneManualZoom, deltaY: event.deltaY, ctrlKey: event.ctrlKey });
    scene.setSceneZoomAt(command.nextZoom, event.clientX, event.clientY, false);
    scene.dataset.mapGesture = command.gesture;
    scene.dataset.sceneWheelZoom = command.label;
    scene.queueSceneBoundsCommit('wheel-zoom');
  };
  scene.addEventListener('wheel', zoomSceneAtCursorByCtrlWheel, { capture: true, passive: false });
  canvas.addEventListener('pointerdown', (event: PointerEvent) => {
    down = { x: event.clientX, y: event.clientY };
    lastX = event.clientX;
    lastY = event.clientY;
    dragging = false;
    const command = projectAtlasMapThreePointerStartCommand({
      recordPaintMode: Boolean(scene.recordPaintMode),
      mapSelectionMode: scene.mapSelectionMode,
      button: event.button,
      altKey: event.altKey,
      shiftKey: event.shiftKey,
      ctrlKey: event.ctrlKey,
    });
    selecting = command.selecting;
    panning = command.panning;
    zooming = command.zooming;
    tilting = command.tilting;
    rotating = command.rotating;
    scene.dataset.mapGesture = command.gesture;
    if (command.enableProgressSelection) scene.setMapSelectionMode('progress');
    if (selecting) scene.beginMapAreaSelection(event.clientX, event.clientY);
    canvas.setPointerCapture?.(event.pointerId);
  });
  canvas.addEventListener('pointermove', (event: PointerEvent) => {
    const start = down;
    if (!start) return;
    const total = Math.hypot(event.clientX - start.x, event.clientY - start.y);
    if (!dragging && total > 6) dragging = true;
    if (!dragging) return;
    const dx = event.clientX - lastX;
    const dy = event.clientY - lastY;
    if (selecting) {
      scene.updateMapAreaSelection(event.clientX, event.clientY);
    } else if (zooming) {
      scene.setSceneZoomAt(scene.sceneManualZoom - dy * dependencies.zoomDragSensitivity, event.clientX, event.clientY, false);
    } else if (tilting) {
      scene.setSceneTiltAdjust(scene.sceneTiltAdjust + dy * dependencies.tiltDragSensitivity, false);
    } else if (rotating) {
      scene.setSceneRotation(scene.sceneManualRotation + dx * 0.32, false);
    } else if (panning) {
      const projectedDelta = scene.screenDragPanDelta(lastX, lastY, event.clientX, event.clientY);
      const delta = { x: Number(projectedDelta?.x) || 0, y: Number(projectedDelta?.y) || 0 };
      const currentPan = scene.sceneManualPan || { x: 0, y: 0 };
      const bounds = scene.getScenePanBounds?.() || { x: Infinity, y: Infinity };
      const nextPan = projectAtlasMapThreePan({ currentPan, delta, bounds });
      scene.setScenePan(nextPan.x, nextPan.y, false);
      scene.dataset.mapPanBehavior = 'world-translation · projected screen delta · zoom-aware v5332';
    }
    lastX = event.clientX;
    lastY = event.clientY;
    scene._suppressMapToggleUntil = performance.now() + 300;
  });
  canvas.addEventListener('pointerup', (event: PointerEvent) => {
    const start = down;
    if (!start) return;
    const shouldConstrain = dragging && !selecting && (panning || tilting || rotating || zooming);
    const total = Math.hypot(event.clientX - start.x, event.clientY - start.y);
    if (selecting) {
      if (dragging) {
        if (scene.recordPaintMode) {
          const parts = scene.collectModelPartsInRect(start, { x: event.clientX, y: event.clientY });
          if (parts.length > 1) scene.selectRecordMapParts(parts);
          else if (parts.length === 1) scene.selectRecordMapPart(parts[0]);
          else scene.clearCurrentMapSelectionV1(true);
        } else {
          scene.finishMapAreaSelection(event.clientX, event.clientY);
        }
      } else {
        scene.removeMapAreaSelection();
        const point = scene.pointFromClient(event.clientX, event.clientY);
        const picked = point ? scene.pickModelAt(point) : false;
        if (!picked) scene.clearCurrentMapSelectionV1(true);
      }
      scene._suppressMapToggleUntil = performance.now() + 520;
    } else if (event.button !== 2 && !dragging && total <= 6 && event.pointerType !== 'touch') {
      const point = scene.pointFromClient(event.clientX, event.clientY);
      const picked = point ? scene.pickModelAt(point) : false;
      if (!picked) scene.clearCurrentMapSelectionV1(true);
      scene._suppressMapToggleUntil = performance.now() + 520;
    } else {
      scene._suppressMapToggleUntil = performance.now() + 520;
    }
    canvas.releasePointerCapture?.(event.pointerId);
    if (shouldConstrain) scene.constrainScenePan('pointer-release');
    down = null;
    dragging = false;
    panning = false;
    tilting = false;
    rotating = false;
    zooming = false;
    selecting = false;
    delete scene.dataset.mapGesture;
  });
  canvas.addEventListener('pointercancel', () => {
    const shouldConstrain = dragging && !selecting && (panning || tilting || rotating || zooming);
    scene.removeMapAreaSelection();
    if (shouldConstrain) scene.constrainScenePan('pointer-cancel');
    down = null;
    dragging = false;
    panning = false;
    tilting = false;
    rotating = false;
    zooming = false;
    selecting = false;
    delete scene.dataset.mapGesture;
  });
  canvas.addEventListener('pointerdown', () => {
    if (!scene.dataset.mapGesture) scene.dataset.mapGesture = 'holding';
  });
  const releaseMapGesture = (): void => { delete scene.dataset.mapGesture; };
  canvas.addEventListener('pointerup', releaseMapGesture);
  canvas.addEventListener('pointercancel', releaseMapGesture);
  canvas.addEventListener('webglcontextlost', (event: Event) => {
    event.preventDefault();
    scene.dataset.threeContext = 'lost';
    scene.dataset.mapTexture = 'fallback';
  });
  canvas.addEventListener('webglcontextrestored', () => {
    delete scene.dataset.threeContext;
    scene.dataset.mapTexture = 'loading';
    if (scene._modelGpuReady) scene.syncThree();
  });
  scene.dataset.threeBoot = 'renderer-ready-awaiting-glb';
}

interface AtlasMapThreeInitializationInstallerDependencies extends Omit<
  AtlasMapThreeInitializationDependencies,
  'threeModule' | 'gltfLoader' | 'locationPath' | 'devicePixelRatio'
> {
  importThree: () => Promise<Record<string, any>>;
  importGltfLoader: () => Promise<{ GLTFLoader: unknown }>;
  tiltDragSensitivity: number;
  zoomDragSensitivity: number;
  windowRef?: Pick<Window, 'devicePixelRatio'>;
  locationRef?: Pick<Location, 'pathname'>;
  consoleRef?: Pick<Console, 'warn'>;
}

/** Own the complete initThree gate, runtime setup, loader handoff, and fallback. */
export function installAtlasMapThreeInitializationV1(
  MapScene: CustomElementConstructor,
  dependencies: AtlasMapThreeInitializationInstallerDependencies,
): CustomElementConstructor {
  if (typeof MapScene !== 'function' || !MapScene.prototype) {
    throw new TypeError('Three.js initialization requires the existing MapScene constructor.');
  }
  const prototype = MapScene.prototype as unknown as AtlasMapThreeInitializationElement;
  const windowRef = dependencies.windowRef || globalThis.window;
  const locationRef = dependencies.locationRef || globalThis.location;
  const consoleRef = dependencies.consoleRef || globalThis.console;
  prototype.initThree = async function(this: AtlasMapThreeInitializationElement): Promise<boolean | void> {
    if (this.hasAttribute('data-public-static-only')) {
      this.dataset.three = 'blocked-static-only';
      this.dataset.publicThree = 'disabled-static-only';
      this.dataset.modelBootPhase = 'static-only-no-webgl';
      return false;
    }
    if (this.isAdminStandalone3DV5370?.() && !this._adminStandaloneActivatedV5370) {
      this.dataset.three = 'blocked-static-first';
      this.dataset.modelBootPhase = 'blocked-until-explicit-activation';
      return false;
    }
    this.dataset.three = 'loading';
    if (this.isPublicMapVisual()) this.dataset.publicThree = 'loading';
    try {
      const THREE = await dependencies.importThree();
      const { GLTFLoader } = await dependencies.importGltfLoader();
      const canvas = this.querySelector<HTMLCanvasElement>('.three-overlay') as HTMLCanvasElement;
      initializeAtlasMapThreeFoundationV1(this, {
        threeModule: THREE,
        gltfLoader: GLTFLoader,
        mapCameraView: dependencies.mapCameraView,
        mapGeoreferenceFallback: dependencies.mapGeoreferenceFallback,
        sceneMapZ: dependencies.sceneMapZ,
        sceneModelBaseZ: dependencies.sceneModelBaseZ,
        appStore: dependencies.appStore,
        solarStateForHour: dependencies.solarStateForHour,
        documentRef: dependencies.documentRef,
        locationPath: locationRef.pathname,
        devicePixelRatio: windowRef.devicePixelRatio || 1,
      });
      this.loadMasterplan(THREE, GLTFLoader);
      // Load georeferencing alongside the model so either completion order
      // converges on the same calibrated GPS marker positions.
      this.loadDwgGeoreference(THREE);
      bindAtlasMapThreeGesturesV1(this, canvas, {
        zoomDragSensitivity: dependencies.zoomDragSensitivity,
        tiltDragSensitivity: dependencies.tiltDragSensitivity,
      });
    } catch (error) {
      const failure = error as { message?: unknown } | null;
      const publicStaticFallback = this.isPublicCustomerExperience?.();
      this.dataset.three = publicStaticFallback ? 'fallback-static' : 'fallback';
      if (this.isPublicMapVisual()) this.dataset.publicThree = publicStaticFallback ? 'fallback-static' : 'fallback';
      this.dataset.modelError = String(failure?.message || error || 'three-init-failed').slice(0, 240);
      this.dataset.modelBootPhase = 'three-init-error';
      if (publicStaticFallback) this.preparePublicStaticBaseV1('static-fallback');
      else this.updateMap3DLoadingScreenV1('three-init-error');
      consoleRef.warn('Three.js indisponível, mantendo a base pública estática.', error);
    }
  };
  return MapScene;
}

export interface AtlasMapDwgGeoreferenceControllerDependenciesV1 {
  url: string;
  fallback: AtlasMapSolarGeoPoint;
  appStore: { get: () => Record<string, unknown> };
  localClockHourForGeo: (point: Partial<AtlasMapSolarGeoPoint>) => number;
  validGeoPoint: (point: { lat: unknown; lng: unknown }) => boolean;
  fetchRef?: typeof fetch;
  consoleRef?: Pick<Console, 'warn'>;
}

/** Own DWG data normalization, GPS marker rendering, lot binding, and solar initialization. */
export function installAtlasMapDwgGeoreferenceControllerV1(
  MapScene: CustomElementConstructor,
  dependencies: AtlasMapDwgGeoreferenceControllerDependenciesV1,
): CustomElementConstructor {
  if (typeof MapScene !== 'function' || !MapScene.prototype) {
    throw new TypeError('DWG georeference requires the existing MapScene constructor.');
  }
  if (!dependencies.url || !dependencies.appStore?.get ||
      typeof dependencies.localClockHourForGeo !== 'function' ||
      typeof dependencies.validGeoPoint !== 'function') {
    throw new TypeError('DWG georeference requires URL, app store, solar clock, and coordinate validator.');
  }
  const prototype = MapScene.prototype as unknown as AtlasMapThreeInitializationElement;
  const fetchRef = dependencies.fetchRef || globalThis.fetch.bind(globalThis);
  const consoleRef = dependencies.consoleRef || globalThis.console;

  prototype.setGpsMarkers = function(
    this: AtlasMapThreeInitializationElement,
    THREE: Record<string, any>,
    points: AtlasMapDwgControlPointV1[] = [],
  ): void {
    if (!this.markerGroup) return;
    this.markerGroup.clear();
    const geometry = this.gpsMarkerGeometry || new THREE.CircleGeometry(8, 32);
    points.filter(point => dependencies.validGeoPoint({ lat: point.lat, lng: point.lng }))
      .forEach((point, index) => {
        const material = new THREE.MeshBasicMaterial({
          color: this.gpsMarkerColors?.[index % this.gpsMarkerColors.length] || 0x2fe6ae,
          transparent: true,
          opacity: 0.92,
          depthTest: false,
          depthWrite: false,
        });
        const marker = new THREE.Mesh(geometry, material);
        marker.userData = {
          latlng: [Number(point.lat), Number(point.lng)],
          gpsId: point.id || `gps-${index + 1}`,
          gpsLabel: point.label || 'Ponto GPS',
          utmEast: point.utmEast,
          utmNorth: point.utmNorth,
        };
        marker.scale.setScalar(point.id === 'site-center' ? 1.22 : 1);
        this.markerGroup.add(marker);
      });
    this.dataset.gpsMarkers = String(this.markerGroup.children.length);
    this.dataset.gpsSource = 'DWG · SIRGAS 2000 / UTM 24S · EPSG:31984';
    this.syncThree();
  };

  prototype.applyDwgLotMetadata = function(this: AtlasMapThreeInitializationElement): void {
    if (!this.dwgGeo || !this.lotStatusBadges?.length) return;
    const byObject = projectAtlasMapDwgLotMetadataByObjectV1(this.dwgGeo as AtlasMapDwgGeoreferenceV1);
    this.lotStatusBadges.forEach((badge: { userData?: Record<string, any> }) => {
      const lot = byObject.get(String(badge.userData?.glbObject || badge.userData?.lotObject || ''));
      if (!lot) return;
      badge.userData ||= {};
      badge.userData.gps = {
        lat: lot.lat,
        lng: lot.lng,
        utmEast: lot.utmEast,
        utmNorth: lot.utmNorth,
        areaM2: lot.areaM2,
        alignmentErrorM: lot.alignmentErrorM,
      } satisfies AtlasMapDwgLotMetadataV1;
    });
    this.dataset.dwgLotGpsAttached = String((this.dwgGeo as AtlasMapDwgGeoreferenceV1).lots?.length || 0);
  };

  prototype.loadDwgGeoreference = async function(
    this: AtlasMapThreeInitializationElement,
    THREE: Record<string, any>,
  ): Promise<void> {
    try {
      const response = await fetchRef(dependencies.url, { cache: 'no-store' });
      if (!response.ok) throw new Error(`DWG georeference HTTP ${response.status}`);
      const geo = normalizeAtlasMapDwgGeoreferenceV1(await response.json());
      this.dwgGeo = geo;
      const solar = projectAtlasMapDwgSolarInitializationV1(
        geo,
        dependencies.fallback,
        dependencies.appStore.get(),
        dependencies.localClockHourForGeo,
      );
      this.setSolarHour(solar.selectedHour, false, false);
      this.dataset.solarInitialMode = solar.manual ? 'manual' : 'clock';
      this.dataset.solarClockHour = solar.clockHour.toFixed(2);
      this.setGpsMarkers(THREE, geo.controlPoints);
      this.dataset.dwgCrs = `EPSG:${geo.crs.epsg}`;
      this.dataset.dwgLotCount = String(geo.lots?.length || 0);
      const alignment = geo.alignment || {};
      this.dataset.dwgAlignmentError = `mediana ${alignment.medianErrorM ?? '—'} m · P90 ${alignment.p90ErrorM ?? '—'} m`;
      if (this.masterplanModel) {
        this.masterplanModel.userData.dwgGeoreferenced = true;
        this.masterplanModel.userData.dwgCrs = geo.crs.epsg;
        this.masterplanModel.userData.dwgAlignment = geo.alignment;
      }
      this.applyDwgLotMetadata();
      this.dataset.dwgGeoreference = 'ready';
      this.dataset.dwgSyncState = `model:${this.masterplanModel ? '1' : '0'}|parts:${this.modelParts?.lots?.length || 0}|gpu:${this._modelGpuReady ? '1' : '0'}`;
      if (this.masterplanModel && this._modelGpuReady) this.syncThree();
    } catch (error) {
      const failure = error as { message?: unknown } | null;
      this.dataset.dwgGeoreference = 'fallback';
      this.dataset.dwgGeoreferenceError = String(failure?.message || error);
      consoleRef.warn('Georreferência DWG indisponível; usando o ponto central de fallback.', error);
    }
  };
  return MapScene;
}

interface AtlasMapMasterplanLoadProgressV1 {
  loaded?: number;
  total?: number;
  lengthComputable?: boolean;
  clientCacheSource?: 'network' | 'cache-storage';
}

interface AtlasMapGltfLoaderV1 {
  parse(
    buffer: ArrayBuffer,
    path: string,
    onLoad: (gltf: { scene: Record<string, any> }) => void,
    onError?: (error: unknown) => void,
  ): void;
}

/** Build normalized UVs on native GLB geometry without duplicating the scene math in MJS. */
export function projectAtlasAdminPdfElementGeometryV1(input: {
  THREE: Record<string, any>;
  node: Record<string, any>;
  model: Record<string, any>;
  sourceWidth: number;
  sourceDepth: number;
  pageFrame: AtlasAdminPdfMasterplanFrameV1;
  adminSharedPublicMap: boolean;
  cloneGeometry?: boolean;
}): { geometry: Record<string, any>; relative: Record<string, any> } | null {
  const { THREE, node, model, sourceWidth, sourceDepth, pageFrame } = input;
  const geometry = input.cloneGeometry === false ? node?.geometry : node?.geometry?.clone?.();
  const position = geometry?.getAttribute?.('position');
  if (!geometry || !position?.count) return null;
  const relative = new THREE.Matrix4().copy(model.matrixWorld).invert().multiply(node.matrixWorld);
  const currentUv = geometry.getAttribute?.('uv');
  const canReuseUv = currentUv?.count === position.count && currentUv.itemSize >= 2;
  const uv = canReuseUv ? currentUv : new Float32Array(position.count * 2);
  const point = new THREE.Vector3();
  const orientedPoint = new THREE.Vector3();
  const identity = new THREE.Matrix4();
  const orientationMatrix = input.adminSharedPublicMap
    ? model.userData?.publicDwgAffine?.orientationMatrix || identity
    : null;
  for (let index = 0; index < position.count; index++) {
    point.set(position.getX(index), position.getY(index), position.getZ(index)).applyMatrix4(relative);
    orientedPoint.copy(point).applyMatrix4(orientationMatrix || identity);
    const projectedUv = projectAtlasAdminPdfTextureUvV1(orientedPoint, sourceWidth, sourceDepth, pageFrame);
    if (canReuseUv) currentUv.setXY(index, projectedUv.u, projectedUv.v);
    else {
      uv[index * 2] = projectedUv.u;
      uv[index * 2 + 1] = projectedUv.v;
    }
  }
  if (!canReuseUv) geometry.setAttribute('uv', new THREE.BufferAttribute(uv, 2));
  geometry.attributes.uv.needsUpdate = true;
  return { geometry, relative };
}

export interface AtlasAdminPdfTextureBindingDependenciesV1 {
  aerialAsset: string;
  textureVersion: string;
  brightness: number;
  vehicleAnchors: Array<{ u: number; v: number; angle: number }>;
  documentRef: Pick<Document, 'createElement'>;
}

export interface AtlasAdminPdfMasterplanLayerDependenciesV1 {
  aerialAsset: string;
  layerVersion: string;
  sourceManifest: string;
}

export interface AtlasAdminPdfUnderlayDependenciesV1 {
  aerialAsset: string;
  aerialVersion: string;
  imageFactory?: () => HTMLImageElement;
  consoleRef?: Pick<Console, 'warn'>;
}

/** Install semantic GLB texture binding while keeping lots and streets selectable. */
export function installAtlasAdminPdfTextureBindingV1(
  MapScene: CustomElementConstructor,
  dependencies: AtlasAdminPdfTextureBindingDependenciesV1,
): CustomElementConstructor {
  if (typeof MapScene !== 'function' || !MapScene.prototype) throw new TypeError('PDF texture binding requires MapScene.');
  const prototype = MapScene.prototype as unknown as Record<string, any>;
  prototype.bindPdfMapTextureToMasterplanV1 = function(this: Record<string, any>, THREE: Record<string, any>, texture: Record<string, any>): number {
    if (!this.hasAttribute('data-admin-shared-public-map') || !THREE || !texture?.image || !this.masterplanModel || !this.modelParts) return 0;
    const model = this.masterplanModel;
    const sourceSize = model.userData?.sourceSize;
    const sourceWidth = Math.max(0.1, Number(sourceSize?.x) || 1);
    const sourceDepth = Math.max(0.1, Number(sourceSize?.z) || 1);
    const pageFrame = this.isAdminReferenceAerialV1?.()
      ? this.adminReferenceAerialProjectionFrameV1(sourceWidth, sourceDepth, texture.image)
      : this.pdfMasterplanPageFrameV1(sourceWidth, sourceDepth);
    const modelTexture = texture.clone();
    modelTexture.name = 'BelavistaPdfMasterplanModelTexture';
    modelTexture.userData = { ...(modelTexture.userData || {}), brightness: dependencies.brightness, projection: 'PDF site frame → source GLB X/Z' };
    modelTexture.wrapS = THREE.ClampToEdgeWrapping;
    modelTexture.wrapT = THREE.ClampToEdgeWrapping;
    modelTexture.repeat.set(1, 1);
    modelTexture.offset.set(0, 0);
    modelTexture.center.set(0, 0);
    modelTexture.rotation = 0;
    modelTexture.needsUpdate = true;
    const materials = new Map<string, Record<string, any>>();
    const materialForKind = (kind: string): Record<string, any> => {
      if (materials.has(kind)) return materials.get(kind)!;
      const material = new THREE.MeshBasicMaterial({
        map: modelTexture,
        color: new THREE.Color(dependencies.brightness, dependencies.brightness, dependencies.brightness),
        side: THREE.DoubleSide,
        transparent: false,
        opacity: 1,
        alphaTest: 0,
        depthTest: true,
        depthWrite: true,
        toneMapped: false,
        polygonOffset: true,
        polygonOffsetFactor: -1,
        polygonOffsetUnits: -1,
      });
      material.name = `BelavistaPdfMasterplanModelMaterial_${kind}`;
      material.userData = { pdfSemanticKind: kind, pdfTextureSource: dependencies.aerialAsset, pdfTextureVersion: dependencies.textureVersion };
      materials.set(kind, material);
      return material;
    };
    const candidates: Array<{ node: Record<string, any>; kind: string }> = [];
    const addCandidates = (items: Array<Record<string, any>> | undefined, kind: string): void => items?.forEach(node => candidates.push({ node, kind }));
    addCandidates(this.modelLandscapeNodes, 'tree');
    addCandidates(this.modelLeisureNodes, 'structure');
    addCandidates(this.modelParts.other, 'asset');
    const geometryReferences = new Map<Record<string, any>, number>();
    candidates.forEach(({ node }) => {
      if (!node?.isMesh || !node.geometry) return;
      geometryReferences.set(node.geometry, (geometryReferences.get(node.geometry) || 0) + 1);
    });
    const seen = new Set<Record<string, any>>();
    let bound = 0;
    candidates.forEach(({ node, kind: hint }) => {
      if (!node?.isMesh || seen.has(node) || /^divisa(?:[_\s-]|$)/i.test(String(node.name || ''))) return;
      seen.add(node);
      const kind = this.classifyPdfElementKindV1(node, hint);
      if (!['tree', 'structure', 'asset'].includes(kind)) return;
      const projected = projectAtlasAdminPdfElementGeometryV1({
        THREE,
        node,
        model,
        sourceWidth,
        sourceDepth,
        pageFrame,
        adminSharedPublicMap: this.hasAttribute('data-admin-shared-public-map'),
        cloneGeometry: (geometryReferences.get(node.geometry) || 0) > 1,
      });
      if (!projected) return;
      node.geometry = projected.geometry;
      node.material = materialForKind(kind);
      node.userData.defaultMaterial = node.material;
      node.userData.pdfMapTextureBound = true;
      node.userData.pdfMapTextureSource = dependencies.aerialAsset;
      node.userData.pdfMapTextureVersion = dependencies.textureVersion;
      node.userData.pdfMapTextureProjection = 'full PDF page · semantic UV 0..1';
      node.userData.pdfMapTextureKind = kind;
      bound++;
    });
    if (!bound) {
      modelTexture.dispose?.();
      return 0;
    }
    this.adminPdfMasterplanModelTextureV1 = modelTexture;
    this.dataset.adminPdfModelTexture = 'bound to source GLB semantic meshes';
    this.dataset.adminPdfModelTextureVersion = dependencies.textureVersion;
    this.dataset.adminPdfModelTextureSource = dependencies.aerialAsset;
    this.dataset.adminPdfModelTextureFrame = 'full PDF page · normalized UV 0..1 · no crop';
    this.dataset.adminPdfModelTextureElements = String(bound);
    model.userData.pdfMapTextureBinding = { source: dependencies.aerialAsset, version: dependencies.textureVersion, elements: bound, frame: 'full PDF page · normalized UV 0..1 · no crop' };
    return bound;
  };
  prototype.createPdfVehicleExtrusionsV1 = function(
    this: Record<string, any>,
    THREE: Record<string, any>,
    group: Record<string, any>,
    image: HTMLImageElement,
    sourceWidth: number,
    sourceDepth: number,
    pageFrame: AtlasAdminPdfMasterplanFrameV1,
  ): number {
    if (!image?.naturalWidth || !image?.naturalHeight) return 0;
    const vehicleGroup = new THREE.Group();
    vehicleGroup.name = 'BelavistaPdfVehicleExtrusions';
    vehicleGroup.renderOrder = 13;
    const imageWidth = image.naturalWidth;
    const imageHeight = image.naturalHeight;
    let count = 0;
    dependencies.vehicleAnchors.forEach((anchor, index) => {
      const cropWidth = 34;
      const cropHeight = 24;
      const canvas = dependencies.documentRef.createElement('canvas');
      canvas.width = 72;
      canvas.height = 52;
      const context = canvas.getContext('2d');
      if (!context) return;
      const sx = Math.max(0, Math.min(imageWidth - cropWidth, anchor.u * imageWidth - cropWidth * 0.5));
      const sy = Math.max(0, Math.min(imageHeight - cropHeight, anchor.v * imageHeight - cropHeight * 0.5));
      context.drawImage(image, sx, sy, cropWidth, cropHeight, 0, 0, canvas.width, canvas.height);
      const patch = new THREE.CanvasTexture(canvas);
      patch.colorSpace = THREE.SRGBColorSpace;
      patch.minFilter = THREE.LinearFilter;
      patch.magFilter = THREE.LinearFilter;
      patch.needsUpdate = true;
      const material = new THREE.MeshBasicMaterial({
        map: patch,
        side: THREE.DoubleSide,
        transparent: false,
        depthTest: true,
        depthWrite: true,
        polygonOffset: true,
        polygonOffsetFactor: -2,
        polygonOffsetUnits: -2,
      });
      material.name = `BelavistaPdfVehicleTexture_${index + 1}`;
      const width = pageFrame.pageWidth * (cropWidth / pageFrame.width);
      const depth = pageFrame.pageDepth * (cropHeight / pageFrame.height);
      const height = 0.42;
      const car = new THREE.Mesh(new THREE.BoxGeometry(width, height, depth), material);
      car.name = `PDF3D_Veiculo_${String(index + 1).padStart(2, '0')}`;
      car.position.set(
        (anchor.u - 0.5) * pageFrame.pageWidth + pageFrame.offsetX,
        height * 0.5 + 0.08,
        (anchor.v - 0.5) * pageFrame.pageDepth + pageFrame.offsetZ,
      );
      car.rotation.y = Number(anchor.angle) || 0;
      car.renderOrder = 13;
      car.frustumCulled = false;
      car.raycast = () => {};
      car.userData = {
        pdf3dElement: true,
        pdfElementKind: 'vehicle',
        pdfTextureSource: dependencies.aerialAsset,
        textureRegion: { u: anchor.u, v: anchor.v, width: cropWidth / imageWidth, height: cropHeight / imageHeight },
        extrusionDepth: height,
        placement: 'reference aerial UV anchor · visible parking vehicle',
      };
      vehicleGroup.add(car);
      count++;
    });
    group.add(vehicleGroup);
    this.pdfVehicleExtrusionGroupV1 = vehicleGroup;
    this.dataset.adminPdf3dVehicleCount = String(count);
    return count;
  };
  return MapScene;
}

/** Build the selectable-aware 3D projection layer from semantic masterplan meshes. */
export function installAtlasAdminPdfMasterplanLayerV1(
  MapScene: CustomElementConstructor,
  dependencies: AtlasAdminPdfMasterplanLayerDependenciesV1,
): CustomElementConstructor {
  if (typeof MapScene !== 'function' || !MapScene.prototype) throw new TypeError('PDF masterplan layer requires MapScene.');
  const prototype = MapScene.prototype as unknown as Record<string, any>;
  prototype.buildPdfMasterplan3DLayerV1 = function(this: Record<string, any>, THREE: Record<string, any>, texture: Record<string, any>): boolean {
    if (!this.hasAttribute('data-admin-shared-public-map') || !THREE || !texture || !this.sceneStage || !this.masterplanModel || !this.modelParts || !['classified', 'ready'].includes(String(this.dataset.modelEnrichment || ''))) return false;
    if (this.adminPdfMasterplan3DGroupV1) return true;
    const model = this.masterplanModel;
    const sourceSize = model.userData?.sourceSize;
    const sourceWidth = Math.max(0.1, Number(sourceSize?.x) || 1);
    const sourceDepth = Math.max(0.1, Number(sourceSize?.z) || 1);
    const pageFrame = this.isAdminReferenceAerialV1?.()
      ? this.adminReferenceAerialProjectionFrameV1(sourceWidth, sourceDepth, texture.image)
      : this.pdfMasterplanPageFrameV1(sourceWidth, sourceDepth);
    const sourceModelTextureCount = this.bindPdfMapTextureToMasterplanV1(THREE, texture);
    model.updateMatrixWorld(true);
    this.sceneStage.updateMatrixWorld(true);
    for (const key of ['publicVegetationGroup', 'publicTerrainVegetationGroup', 'publicForestGroup', 'publicGreenReliefGroup', 'publicSocialGrassGroup', 'publicGpsContextEnvironment']) {
      const generated = this[key];
      generated?.removeFromParent?.();
      if (generated) generated.visible = false;
      this[key] = null;
    }
    const group = new THREE.Group();
    group.name = 'BelavistaPdfMasterplan3DExtrusions';
    group.matrixAutoUpdate = false;
    group.matrix.copy(model.matrix);
    group.matrixWorldNeedsUpdate = true;
    group.renderOrder = 11;
    const materials = new Map<string, Record<string, any>>();
    const materialForKind = (kind: string): Record<string, any> => {
      if (materials.has(kind)) return materials.get(kind)!;
      const material = new THREE.MeshBasicMaterial({
        map: texture,
        side: THREE.DoubleSide,
        transparent: false,
        opacity: 1,
        depthTest: true,
        depthWrite: true,
        polygonOffset: true,
        polygonOffsetFactor: -1,
        polygonOffsetUnits: -1,
      });
      material.name = `BelavistaPdfProjectedElementTexture_${kind}`;
      material.userData = { pdfSemanticKind: kind, pdfTextureSource: dependencies.aerialAsset };
      materials.set(kind, material);
      return material;
    };
    const candidates: Array<{ node: Record<string, any>; kind: string }> = [];
    const addCandidates = (items: Array<Record<string, any>> | undefined, kind: string): void => items?.forEach(node => candidates.push({ node, kind }));
    addCandidates(this.modelLandscapeNodes, 'tree');
    addCandidates(this.modelLeisureNodes, 'structure');
    addCandidates(this.modelParts.other, 'asset');
    const seen = new Set<Record<string, any>>();
    const counts = { tree: 0, structure: 0, asset: 0 };
    const lotIntegration = (this.modelParts.lots || []).map((node: Record<string, any>) => {
      const number = this.pdfLotNumberV1(node);
      if (!number) return null;
      return {
        number,
        pdfImageNumber: `Lote ${number}`,
        integrationKey: `lot:${number}`,
        sourceNode: String(node.name || ''),
        partId: String(node.userData?.partId || node.name || ''),
        imageAnchor: this.pdfElementImageAnchorV1(THREE, node, model, sourceWidth, sourceDepth, pageFrame),
        pdfTextureSource: dependencies.aerialAsset,
      };
    }).filter(Boolean);
    candidates.forEach(({ node, kind: hint }) => {
      if (!node?.isMesh || seen.has(node) || /^divisa(?:[_\s-]|$)/i.test(String(node.name || ''))) return;
      seen.add(node);
      const kind = String(this.classifyPdfElementKindV1(node, hint)) as keyof typeof counts;
      if (!Object.prototype.hasOwnProperty.call(counts, kind)) return;
      if (node.userData?.pdfMapTextureBound) {
        node.visible = true;
        node.userData.pdf3dNativeVisible = true;
        node.userData.pdfSemanticKind = kind;
        counts[kind]++;
        return;
      }
      const projected = this.projectPdfElementGeometryV1(THREE, node, model, sourceWidth, sourceDepth, pageFrame);
      if (!projected) return;
      node.visible = true;
      node.userData.pdf3dNativeVisible = true;
      node.userData.pdfSemanticKind = kind;
      const mesh = new THREE.Mesh(projected.geometry, materialForKind(kind));
      mesh.name = `PDF3D_${kind}_${String(counts[kind] + 1).padStart(3, '0')}`;
      mesh.matrixAutoUpdate = false;
      mesh.matrix.copy(projected.relative);
      mesh.matrixWorldNeedsUpdate = true;
      mesh.renderOrder = 12;
      mesh.frustumCulled = true;
      mesh.raycast = () => {};
      mesh.visible = !sourceModelTextureCount;
      mesh.userData = {
        pdf3dElement: true,
        pdfElementKind: kind,
        pdfTextureSource: dependencies.aerialAsset,
        sourceNode: String(node.name || ''),
        sourceGeometry: 'native semantic GLB mesh with preserved volume',
        extrusion: 'native tree/structure/asset geometry only',
        textureFrame: 'reference aerial · projected UV 0..1',
        pageFrame,
      };
      group.add(mesh);
      counts[kind]++;
    });
    const vehicleCount = this.createPdfVehicleExtrusionsV1(THREE, group, texture.image, sourceWidth, sourceDepth, pageFrame);
    group.userData = {
      pdf3dLayer: true,
      version: dependencies.layerVersion,
      source: dependencies.aerialAsset,
      sourceManifest: dependencies.sourceManifest,
      policy: 'trees + structures + vehicles in 3D · lots and streets remain selectable surfaces',
      geometrySource: 'native semantic GLB meshes + reference aerial vehicle crops',
      classification: 'manifest roles + modelParts + landscapeNodes + leisureNodes → semantic visual classes',
      sourceModelTextureBinding: sourceModelTextureCount,
      semanticGeometryPolicy: sourceModelTextureCount ? 'reuse native semantic meshes · no projected duplicate buffers' : 'projected overlay fallback · native texture binding unavailable',
      textureFrame: 'reference aerial · UV 0..1 · original aspect ratio',
      pageFrame,
      counts: { ...counts, vehicle: vehicleCount },
      lotIntegration: {
        identity: 'Lote_### / DWG glbObject',
        numberField: 'lotNumber',
        keyField: 'pdfLotIntegrationKey',
        imageAnchorField: 'pdfImageAnchor',
        records: lotIntegration,
      },
      elementClasses: ['lot-selection', 'street-selection', 'tree', 'structure', 'vehicle'],
    };
    this.sceneStage.add(group);
    this.adminPdfMasterplan3DGroupV1 = group;
    this.adminPdfMasterplan3DTextureV1 = texture;
    this.dataset.adminPdf3dLayer = 'ready';
    this.dataset.adminPdf3dVersion = dependencies.layerVersion;
    this.dataset.adminPdf3dSource = dependencies.aerialAsset;
    this.dataset.adminPdf3dManifest = dependencies.sourceManifest;
    this.dataset.adminPdf3dTexture = 'reference aerial projected only on trees/structures · cars use image crops';
    this.dataset.adminPdf3dSourceModelTexture = sourceModelTextureCount ? 'bound · source GLB meshes' : 'overlay only';
    this.dataset.adminPdf3dGeometryPolicy = sourceModelTextureCount ? 'native semantic mesh reuse · projected duplicates disabled' : 'projected overlay fallback · native binding unavailable';
    this.dataset.adminPdf3dVisibility = 'trees + structures + cars only · lots/streets selection surfaces';
    this.dataset.adminPdf3dPolicy = 'árvores, estruturas e carros em 3D · lotes e ruas selecionáveis';
    this.dataset.adminPdf3dElements = `lotes-selecao:${this.modelParts.lots?.length || 0}|ruas-selecao:${this.modelParts.streets?.length || 0}|arvores:${counts.tree}|estruturas:${counts.structure}|ativos:${counts.asset}|veiculos:${vehicleCount}`;
    this.dataset.adminPdf3dNativeGeometry = 'only trees + structures + cars · no lot/street visual extrusion';
    this.dataset.adminPdf3dTexturePolicy = 'single reference aerial surface · semantic visual objects only';
    this.pdfLotIntegrationV1 = lotIntegration.sort((a: any, b: any) => Number(a.number) - Number(b.number));
    this.dataset.adminPdfLotCount = String(this.pdfLotIntegrationV1.length);
    this.dataset.adminPdfLotNumbers = this.pdfLotIntegrationV1.map((item: any) => item.number).join('|');
    this.dataset.adminPdfLotIntegration = 'lotNumber + pdfLotIntegrationKey + pdfImageAnchor';
    this.dispatchEvent(new CustomEvent('pdf-lot-integration-ready', {
      bubbles: true,
      detail: { sourceManifest: dependencies.sourceManifest, textureSource: dependencies.aerialAsset, records: this.pdfLotIntegrationV1 },
    }));
    this.renderer?.render(this.scene, this.camera);
    return true;
  };
  return MapScene;
}

/** Load the original aerial image once and bind it as the shared scene texture. */
export function installAtlasAdminPdfUnderlayV1(
  MapScene: CustomElementConstructor,
  dependencies: AtlasAdminPdfUnderlayDependenciesV1,
): CustomElementConstructor {
  if (typeof MapScene !== 'function' || !MapScene.prototype) throw new TypeError('PDF underlay requires MapScene.');
  const prototype = MapScene.prototype as unknown as Record<string, any>;
  const consoleRef = dependencies.consoleRef || console;
  prototype.loadAdminPdfMasterplanUnderlayV1 = function(this: Record<string, any>): void {
    if (!this.hasAttribute('data-admin-shared-public-map') || !this.THREE || !this.sceneStage || !this.masterplanModel) return;
    if (this.adminPdfMasterplanUnderlayTextureV1 || this._adminPdfMasterplanUnderlayLoading) return;
    this._adminPdfMasterplanUnderlayLoading = true;
    this.dataset.adminPdfUnderlay = 'loading';
    const image = (dependencies.imageFactory || (() => new Image()))();
    image.decoding = 'async';
    image.onload = () => {
      try {
        const THREE = this.THREE;
        const sourceSize = this.masterplanModel.userData?.sourceSize;
        const sourceWidth = Math.max(0.1, Number(sourceSize?.x) || 1);
        const sourceDepth = Math.max(0.1, Number(sourceSize?.z) || 1);
        const imageWidth = Math.max(1, image.naturalWidth || image.width || 1);
        const imageHeight = Math.max(1, image.naturalHeight || image.height || 1);
        const pageFrame = this.hasAttribute('data-admin-shared-public-map')
          ? this.adminReferenceAerialProjectionFrameV1(sourceWidth, sourceDepth, { naturalWidth: imageWidth, naturalHeight: imageHeight })
          : this.pdfMasterplanPageFrameV1(sourceWidth, sourceDepth);
        const texture = new THREE.Texture(image);
        texture.colorSpace = THREE.SRGBColorSpace;
        texture.wrapS = THREE.ClampToEdgeWrapping;
        texture.wrapT = THREE.ClampToEdgeWrapping;
        texture.repeat.set(1, 1);
        texture.offset.set(0, 0);
        texture.center.set(0, 0);
        texture.rotation = 0;
        texture.minFilter = THREE.LinearFilter;
        texture.magFilter = THREE.LinearFilter;
        texture.generateMipmaps = false;
        const textureRenderer = this._adminStandaloneRendererV5370 || this.renderer;
        texture.anisotropy = Math.max(1, Number(textureRenderer?.capabilities?.getMaxAnisotropy?.()) || 1);
        texture.needsUpdate = true;
        texture.userData = {
          source: dependencies.aerialAsset,
          textureFrame: 'full image · UV 0..1 · site window preserved',
          documentTreatment: 'original user supplied aerial reference',
          usage: 'single map surface + trees/structures/cars only',
          brightness: 1,
        };
        this.adminReferenceAerialTextureV1 = texture;
        this.adminReferenceAerialImageV1 = image;
        this.adminPdfMasterplanUnderlayTextureV1 = texture;
        this.adminPdfMasterplanTextureImageV1 = image;
        this.dataset.adminPdfUnderlay = 'texture-only';
        this.dataset.adminPdfUnderlaySource = dependencies.aerialAsset;
        this.dataset.adminPdfUnderlayProjection = 'single map surface · semantic 3D objects only';
        this.dataset.adminPdfUnderlayPlacement = 'single surface · contain · no duplicate PDF/image plane';
        this.dataset.adminPdfUnderlayImage = `${imageWidth}x${imageHeight}`;
        this.dataset.adminPdfUnderlayResolution = `${imageWidth}x${imageHeight} · textura usada pelo modelo · anisotropia ${texture.anisotropy}`;
        this.dataset.adminPdfUnderlayFrame = 'full image · UV 0..1 · original aspect ratio · no crop';
        this.dataset.adminPdfUnderlaySiteFrame = `${pageFrame.left.toFixed(3)},${pageFrame.top.toFixed(3)} → ${pageFrame.right.toFixed(3)},${pageFrame.bottom.toFixed(3)}`;
        this.dataset.adminPdfDocumentTreatment = 'reference aerial · original · no crop';
        this.dataset.adminPdfTextureMode = 'single reference aerial · semantic objects only';
        this.dataset.adminPdfTextureBrightness = '1';
        this.dataset.adminPdfTextureVerticalShift = '0';
        this.dataset.adminReferenceAerial = 'loading-surface';
        this.syncAdminReferenceAerialSurfaceV1();
        this.buildPdfMasterplan3DLayerV1(THREE, texture);
        this.syncAdminPdfMasterplanUnderlayV1();
        this.dataset.adminReferenceAerial = 'ready';
        this.syncAdminReferenceAerialSurfaceV1();
        this.syncPublicTerrainRelief?.();
        this.renderer?.render(this.scene, this.camera);
      } catch (error) {
        this.dataset.adminPdfUnderlay = 'error';
        this.dataset.adminPdfUnderlayError = String((error as { message?: unknown } | null)?.message || error).slice(0, 160);
        consoleRef.warn('[Belavista admin] projeção PDF do loteamento indisponível.', error);
      } finally {
        this._adminPdfMasterplanUnderlayLoading = false;
      }
    };
    image.onerror = () => {
      this._adminPdfMasterplanUnderlayLoading = false;
      this.dataset.adminPdfUnderlay = 'error';
      this.dataset.adminPdfUnderlayError = 'asset-load-failed';
    };
    image.src = runtimeRouteV1(dependencies.aerialAsset, `v=${dependencies.aerialVersion}`);
  };
  prototype.syncAdminPdfMasterplanUnderlayV1 = function(this: Record<string, any>): boolean {
    const group = this.adminPdfMasterplanUnderlayGroupV1;
    const model = this.masterplanModel;
    if (!model?.matrix) return false;
    if (group) {
      group.removeFromParent?.();
      this.adminPdfMasterplanUnderlayGroupV1 = null;
      this.adminPdfMasterplanUnderlayPlaneV1 = null;
    }
    const elements = this.adminPdfMasterplan3DGroupV1;
    if (elements) {
      elements.matrix.copy(model.matrix);
      elements.matrixWorldNeedsUpdate = true;
    }
    this.syncAdminReferenceAerialSurfaceV1?.();
    this.dataset.adminPdfUnderlayProjectionMatrix = 'not applicable · texture-only GLB scene';
    if (elements) this.dataset.adminPdf3dProjectionMatrix = 'synced with masterplanModel';
    return Boolean(elements);
  };
  return MapScene;
}

/** Keep GLB cache/fetch and GLTF parsing in the TypeScript component owner. */
export function loadAtlasMapGlbWithClientCacheV1(
  loader: AtlasMapGltfLoaderV1,
  url: string,
  onLoad: (gltf: { scene: Record<string, any> }) => void,
  onProgress?: (progress: AtlasMapMasterplanLoadProgressV1) => void,
  onError?: (error: unknown) => void,
): void {
  void loadAtlasMapModelBufferV1(url, onProgress as ((progress: AtlasMapModelCacheProgressV1) => void) | undefined)
    .then(({ buffer, fetchUrl }) => {
      loader.parse(buffer, new URL('./', fetchUrl).href, gltf => {
        try {
          onLoad(gltf);
        } catch (error) {
          onError?.(error);
        }
      }, error => onError?.(error));
    })
    .catch(error => onError?.(error));
}

/** Apply the cache preload route and persistence request for admin/map consumers. */
export function preloadAtlasMapModelClientCacheV1(): ReturnType<typeof preloadAtlasMapModelV1> {
  return preloadAtlasMapModelV1();
}

interface AtlasMapMasterplanLoaderDependenciesV1 {
  modelVerticalExaggeration: number;
  dwgPlanHeadingDeg: number;
  dwgPlanHeadingRad: number;
  sceneModelBaseZ: number;
  browserRef: Record<string, any>;
}

/** Own GLB request orchestration, world-frame placement, progressive GPU handoff, and status. */
export function installAtlasMapMasterplanLoaderV1(
  MapScene: CustomElementConstructor,
  dependencies: AtlasMapMasterplanLoaderDependenciesV1,
): CustomElementConstructor {
  if (typeof MapScene !== 'function' || !MapScene.prototype) {
    throw new TypeError('Masterplan loading requires the existing MapScene constructor.');
  }
  for (const [name, value] of Object.entries(dependencies)) {
    if (value === undefined) throw new TypeError(`Masterplan loading requires ${name}.`);
  }
  const browser = dependencies.browserRef;
  const prototype = MapScene.prototype as unknown as AtlasMapThreeInitializationElement;
  prototype.loadMasterplan = function(
    this: AtlasMapThreeInitializationElement,
    THREE: Record<string, any>,
    GLTFLoader: new () => unknown,
  ): void {
    if (this._modelLoadStarted) return;
    this._modelLoadStarted = true;
    const bootState = this.begin3dBootStateV5367({
      phase: 'network',
      progress: 0,
      meshCount: 0,
      processedMeshes: 0,
      operationalGeometry: 'deferred',
    });
    const startedAt = Number(bootState.startedAt);
    const bootVersion = String(bootState.version);
    const mark = (phase: string, extra: Record<string, unknown> = {}): void => {
      this.dataset.modelBootPhase = phase;
      this.dataset.modelBootVersion = bootVersion;
      this.record3dBootPhaseV5367(phase, extra);
    };
    const loader = new GLTFLoader();
    const modelUrl = runtimeRouteV1(
      ATLAS_MAP_MODEL_ASSET_V1,
      'v=gpu-staged-5367',
    );
    this.dataset.modelSource = 'loaded-glb';
    this.dataset.modelRender = 'webgl-live-glb';
    this.dataset.modelRasterized = 'false';
    this.dataset.modelProgress = '2';

    loadAtlasMapGlbWithClientCacheV1(
      loader as AtlasMapGltfLoaderV1,
      modelUrl,
      gltf => {
        try {
          this.dataset.modelProgress = '42';
          mark('parsed', {
            parsedAt: browser.performance.now(),
            downloadAndParseMs: Math.round(browser.performance.now() - startedAt),
          });
          const sourceModel = gltf.scene;
          const sourceBox = new THREE.Box3().setFromObject(sourceModel);
          const size = sourceBox.getSize(new THREE.Vector3());
          const sourceCenter = sourceBox.getCenter(new THREE.Vector3());
          sourceModel.position.set(-sourceCenter.x, -sourceBox.min.y, -sourceCenter.z);
          const model = new THREE.Group();
          model.name = 'MasterplanFrame';
          model.add(sourceModel);
          const largest = Math.max(size.x, size.y, size.z) || 1;
          const factor = 145 / largest;
          model.scale.set(factor, factor * dependencies.modelVerticalExaggeration, factor);
          model.rotation.set(Math.PI / 2, 0, dependencies.dwgPlanHeadingRad);
          model.updateMatrixWorld(true);
          const rawOrientedBox = new THREE.Box3().setFromObject(model);
          const baseLift = Math.max(0, -rawOrientedBox.min.z) + dependencies.sceneModelBaseZ;
          model.position.z += baseLift;
          model.updateMatrixWorld(true);
          const orientedBox = new THREE.Box3().setFromObject(model);
          const groundedCenter = orientedBox.getCenter(new THREE.Vector3());
          const orientedSize = orientedBox.getSize(new THREE.Vector3());

          model.userData.baseScale = factor;
          model.userData.verticalExaggeration = dependencies.modelVerticalExaggeration;
          model.userData.sourceSize = size;
          model.userData.alignedToMapPlane = true;
          model.userData.planHeadingRad = dependencies.dwgPlanHeadingRad;
          model.userData.planHeadingDeg = dependencies.dwgPlanHeadingDeg;
          model.userData.aerialGuideAlignment = 'DWG affine heading · visual road-guide fit';
          model.userData.mapBaseZ = dependencies.sceneModelBaseZ;
          model.userData.mapBaseLift = baseLift;
          model.userData.sourceBoundsCenter = sourceCenter.clone();
          model.userData.centeredBoundsCenter = groundedCenter.clone();
          model.userData.canonicalReference = 'PDF-derived GLB checked against DWG lot geometry';

          this.modelSourceFootprint = { x: orientedSize.x, y: orientedSize.y, scale: factor };
          this.masterplanModel = model;
          this.loadAdminPdfMasterplanUnderlayV1();
          this._solarShadowBounds = orientedBox.clone();
          this.configureSolarShadows(this._solarShadowBounds);
          this.masterplanLargest = largest;
          this.dataset.modelHeight = `${dependencies.modelVerticalExaggeration.toFixed(2)}x vertical · base no plano do mapa`;
          this.dataset.modelBaseZ = String(dependencies.sceneModelBaseZ);
          this.dataset.modelBaseLift = baseLift.toFixed(3);
          this.dataset.modelLocalOrigin = `centered GLB frame · ${groundedCenter.x.toFixed(3)},${groundedCenter.y.toFixed(3)},${groundedCenter.z.toFixed(3)}`;
          this.dataset.modelAxis = 'source Y → world +Z · footprint Y corrigido';
          this.dataset.modelPlanHeading = `${dependencies.dwgPlanHeadingDeg.toFixed(3)}° · DWG affine`;
          this.dataset.modelAerialGuide = 'lateral + superior · transformação geográfica aplicada';

          const meshes: Array<Record<string, any>> = [];
          let triangleEstimate = 0;
          model.traverse((node: Record<string, any>) => {
            if (!node.isMesh) return;
            const geometry = node.geometry;
            const triangles = geometry?.index
              ? Math.floor((geometry.index.count || 0) / 3)
              : Math.floor((geometry?.getAttribute?.('position')?.count || 0) / 3);
            node.userData.__v5367Triangles = Number(triangles) || 0;
            node.castShadow = true;
            node.receiveShadow = true;
            triangleEstimate += node.userData.__v5367Triangles;
            node.visible = false;
            node.frustumCulled = true;
            meshes.push(node);
          });
          meshes.sort((a, b) => (a.userData.__v5367Triangles || 0) - (b.userData.__v5367Triangles || 0));
          this.dataset.modelMeshCount = String(meshes.length);
          this.dataset.modelTriangleEstimate = String(triangleEstimate);
          this.modelGroup.add(model);
          this.modelGroup.visible = true;
          this.modelReady = false;
          this._modelGpuReady = false;
          this.dataset.modelReady = 'false';
          this.dataset.modelGpuReady = 'false';
          this.dataset.modelRender = 'webgl-staging';
          this.dataset.modelParts = 'staging GPU';
          this.classList.remove('model-ready');
          mark('gpu-staging', { meshCount: meshes.length, triangleEstimate });
          this.renderer?.render(this.scene, this.camera);
          this.stageMasterplanGpuV5367(THREE, model, meshes, startedAt, mark).catch((error: unknown) => {
            const failure = error as { message?: unknown } | null;
            mark('gpu-stage-error', { error: String(failure?.message || error) });
            this.dataset.modelError = 'gpu-stage-failed';
            browser.console.error('[Aliança Park 3D v5.3.67] staging GPU falhou.', error);
          });
        } catch (error) {
          const failure = error as { message?: unknown } | null;
          mark('processing-error', { error: String(failure?.message || error) });
          this.dataset.modelError = 'processamento-falhou';
          this.dataset.modelRender = 'fallback';
          browser.console.warn('Modelo GLB carregado mas não pôde ser processado.', error);
        }
      },
      progress => {
        if (progress.total) {
          const percent = Math.round(((progress.loaded || 0) / progress.total) * 100);
          this.dataset.modelProgress = String(percent);
          this.update3dBootStateV5367({ progress: percent });
          this.updateMap3DLoadingScreenV1('download', { progress: percent });
        }
      },
      err => {
        const failure = err as { message?: unknown } | null;
        mark('network-error', { error: String(failure?.message || err) });
        this.dataset.modelError = 'arquivo-indisponivel';
        this.dataset.modelRender = 'fallback';
        browser.console.warn('Modelo GLB indisponível, mantendo mapa 2D.', err);
      },
    );
  };
  return MapScene;
}


/** Install progressive GPU staging and semantic enrichment on the shared MapScene. */
export function installAtlasMapMasterplanGpuEnrichmentV1(
  MapScene: CustomElementConstructor,
  dependencies: AtlasMapMasterplanGpuEnrichmentDependenciesV1,
): CustomElementConstructor {
  if (!MapScene?.prototype) throw new TypeError("Model enrichment requires MapScene.prototype.");
  const { PUBLIC_SOCIAL_GREEN_LIFT_V1, appStore, publishMapPreview, syncCompactMapMirrors } = dependencies;
  for (const [name, value] of Object.entries({ PUBLIC_SOCIAL_GREEN_LIFT_V1, appStore, publishMapPreview, syncCompactMapMirrors, browserRef: dependencies.browserRef })) {
    if (value === undefined) throw new TypeError(`Model enrichment requires ${name}.`);
  }
  const browser = dependencies.browserRef;
  if (typeof browser?.requestAnimationFrame !== "function" || typeof browser?.setTimeout !== "function" || typeof browser?.performance?.now !== "function") {
    throw new TypeError("Model enrichment requires requestAnimationFrame, setTimeout, and performance.now().");
  }
  const requestAnimationFrame = browser.requestAnimationFrame.bind(browser);
  const setTimeout = browser.setTimeout.bind(browser);
  const performance = { now: () => browser.performance.now() };
  const methods: Record<string, (...args: any[]) => any> = {
  stageMasterplanGpuV5367: async function(this: any, THREE: any, model: any, meshes: any[], startedAt: number, mark: (phase: string, extra?: any) => void) {
    if (this._modelGpuStagePromiseV5367) return this._modelGpuStagePromiseV5367;

    const nextFrame = () =>
      new Promise<void>((resolve) => requestAnimationFrame(() => resolve()));

    const run = async () => {
      const total = meshes.length;
      this.dataset.modelProgress = "46";

      for (let index = 0; index < total; index++) {
        const node = meshes[index];
        const triangles = Number(node.userData.__v5367Triangles) || 0;

        mark("gpu-mesh", {
          meshIndex: index,
          meshNumber: index + 1,
          meshCount: total,
          meshName: String(node.name || "mesh").slice(0, 120),
          meshTriangles: triangles,
        });

        // No modo público a fonte viária do GLB não pode aparecer durante o
        // staging. Ela é a geometria escura/verde que atravessa o terreno
        // antes de a camada de paralelepípedos ser construída. O overlay
        // segmentado entra depois, já recortado pelo eixo real da rua.
        const stagingSemantics = projectAtlasMapMasterplanMeshSemanticsV1({
          name: node.name,
          role: node.userData?.belavistaRole || node.userData?.partKind || "",
          publicMap: this.isPublicMapVisual(),
          publicRoadBaseHidden: Boolean(node.userData?.publicRoadBaseHidden),
        });
        const publicRoadSource = stagingSemantics.isPublicRoadSource;
        const publicDividerSource = stagingSemantics.isPublicDividerSource;
        const rasterMaskIsPrimary = Boolean(
          this._adminStandaloneRasterMaskModelV1,
        );
        node.visible = rasterMaskIsPrimary
          ? false
          : !(publicRoadSource || publicDividerSource);
        if (rasterMaskIsPrimary) {
          node.userData.rasterMaskSourceHidden = true;
          node.raycast = () => {};
        }
        if (publicRoadSource) {
          node.userData.publicRoadBaseHidden = true;
          node.raycast = () => {};
        }
        if (publicDividerSource) {
          node.userData.publicInternalDividerHidden = true;
          node.raycast = () => {};
        }

        const started = performance.now();
        this.renderer?.render(this.scene, this.camera);
        const renderMs = performance.now() - started;

        this.update3dBootStateV5367({ stagedMeshes: index + 1 });
        this.dataset.modelProcessedMeshes = `${index + 1}/${total}`;
        // O staging é trabalho real de geometria/GPU. Ele alimenta a mesma
        // barra de carregamento que antes só recebia bytes da rede.
        const stagedProgress =
          46 + Math.round(((index + 1) / Math.max(1, total)) * 30);
        this.dataset.modelProgress = String(Math.min(76, stagedProgress));
        this.dataset.modelLastGpuRenderMs = renderMs.toFixed(1);

        mark("gpu-mesh-visible", {
          meshIndex: index,
          meshNumber: index + 1,
          meshCount: total,
          meshName: String(node.name || "mesh").slice(0, 120),
          meshTriangles: triangles,
          renderMs: Number(renderMs.toFixed(1)),
          stagedMeshes: index + 1,
        });

        await nextFrame();
      }

      this.modelReady = true;
      this._modelGpuReady = false;
      this.dataset.modelReady = "true";
      this.dataset.modelGpuReady = "false";
      this.dataset.modelProgress = "78";
      this.dataset.modelRender = "webgl-live-glb";
      this.classList.add("model-ready");

      mark("gpu-visible", {
        meshCount: total,
        stagedMeshes: total,
      });

      await nextFrame();

      return this.enrichMasterplanProgressively(THREE, model, meshes, startedAt);
    };

    this._modelGpuStagePromiseV5367 = run().finally(() => {
      this._modelGpuStagePromiseV5367 = null;
    });

    return this._modelGpuStagePromiseV5367;
  },
  enrichMasterplanProgressively: async function(this: any, THREE: any, model: any, meshes: any[], startedAt: number) {
    if (this._modelEnrichmentPromise) return this._modelEnrichmentPromise;

    const nextFrame = () =>
      new Promise<void>((resolve) => requestAnimationFrame(() => resolve()));
    const run = async () => {
      const lots = [],
        streets = [],
        other = [];
      const leisureNodes = [],
        landscapeNodes = [],
        structureNodes = [];
      let hiddenPublicDividers = 0;
      const chunkSize = 18;

      this.dataset.modelEnrichment = "classifying";
      this.update3dBootStateV5367({ phase: "classifying" });

      for (let cursor = 0; cursor < meshes.length; cursor += chunkSize) {
        const end = Math.min(meshes.length, cursor + chunkSize);

        for (let index = cursor; index < end; index++) {
          const node = meshes[index];
          node.frustumCulled = true;
          node.renderOrder = 8;

          const prepare = (mat: any) => {
            if (!mat) return mat;
            const clone = mat.clone();
            clone.opacity = Math.max(0.86, Math.min(1, clone.opacity ?? 1));
            clone.transparent = clone.opacity < 0.98;
            clone.side = THREE.DoubleSide;
            clone.depthWrite = true;
            return clone;
          };

          node.material = Array.isArray(node.material)
            ? node.material.map(prepare)
            : prepare(node.material);
          node.userData.defaultMaterial = node.material;

          const meshName = String(node.name || "");
          const name = meshName.toLowerCase();
          const role = String(node.userData?.belavistaRole || "").toLowerCase();
          const semantics = projectAtlasMapMasterplanMeshSemanticsV1({
            name: meshName,
            role,
            publicMap: this.isPublicMapVisual(),
            streetIndex: streets.length,
            otherIndex: other.length,
          });
          const { isLotDivider, isSocial, kind } = semantics;

          if (semantics.isStructure) {
            node.userData.focusStructure = true;
            node.renderOrder = 18;
            structureNodes.push(node);
          }

          // A superfície original das vias é apenas uma fonte geométrica.
          // No mapa público ela fica invisível para não vazar por baixo das
          // fatias de pedra que serão criadas logo adiante.
          if (
            kind === "streets" &&
            this.isPublicMapVisual() &&
            !this.hasAttribute("data-admin-shared-public-map")
          ) {
            node.visible = false;
            node.userData.publicRoadBaseHidden = true;
            node.raycast = () => {};
          }

          // O GLB também traz Divisa_* como linhas físicas das divisas dos
          // lotes. No mapa público elas eram interpretadas como lotes verdes
          // e apareciam como riscos/malha sobre o satélite; os contornos
          // públicos dos lotes já são desenhados separadamente em branco.
          if (isLotDivider && this.isPublicMapVisual()) {
            node.visible = false;
            node.userData.publicInternalDividerHidden = true;
            node.raycast = () => {};
            hiddenPublicDividers++;
          }

          if (kind === "streets") {
            const pave = (mat: any) =>
              this.makeSiteSurfaceMaterial(
                THREE,
                mat,
                this.isPublicMapVisual() ? "asphalt" : "cobble",
              );
            node.material = Array.isArray(node.material)
              ? node.material.map(pave)
              : pave(node.material);
            node.userData.defaultMaterial = node.material;
          } else if (kind === "lots") {
            const grass = (mat: any) =>
              this.makeSiteSurfaceMaterial(THREE, mat, "grass");
            node.material = Array.isArray(node.material)
              ? node.material.map(grass)
              : grass(node.material);
            node.userData.defaultMaterial = node.material;
            const earth = (mat: any) =>
              this.makeSiteSurfaceMaterial(THREE, mat, "earth");
            node.userData.earthworkMaterial = Array.isArray(node.material)
              ? node.material.map(earth)
              : earth(node.material);
          }

          if (isSocial) {
            const social = (mat: any) =>
              this.makeSocialAreaMaterial(THREE, mat, name);
            node.material = Array.isArray(node.material)
              ? node.material.map(social)
              : social(node.material);
            node.userData.defaultMaterial = node.material;
            node.userData.belavistaSocialSurface = true;
            const socialMaterials = Array.isArray(node.material)
              ? node.material
              : [node.material];
            const isGreenSocialSurface = socialMaterials.some(
              (mat: any) => mat?.userData?.belavistaSocialSurface === "grass",
            );
            if (
              isGreenSocialSurface &&
              !node.userData.publicGrassSurfaceLiftApplied
            ) {
              // Levanta somente o piso verde social; estruturas, quadras e
              // ruas continuam nas cotas originais do modelo do loteamento.
              node.position.z += PUBLIC_SOCIAL_GREEN_LIFT_V1;
              node.userData.publicGrassSurfaceLiftApplied = true;
              node.userData.publicGrassSurfaceLift =
                PUBLIC_SOCIAL_GREEN_LIFT_V1;
            }
            node.castShadow = true;
            node.receiveShadow = true;
          }

          node.userData.partKind = kind;
          node.userData.partId = semantics.partId;
          node.userData.partLabel = semantics.partLabel;
          if (kind === "lots" || kind === "streets") {
            node.userData.selectableMapArea = true;
            node.userData.mapSelectionKind = semantics.mapSelectionKind;
            node.userData.mapSelectionSource =
              "canonical GLB footprint · no 3D visual extrusion";
          }

          if (kind === "lots") lots.push(node);
          else if (kind === "streets") streets.push(node);
          else other.push(node);

          if (semantics.isLandscape) landscapeNodes.push(node);
          if (isSocial) leisureNodes.push(node);
        }

        this.update3dBootStateV5367({ processedMeshes: end });
        this.dataset.modelProcessedMeshes = `${end}/${meshes.length}`;
        const enrichedProgress =
          78 + Math.round((end / Math.max(1, meshes.length)) * 17);
        this.dataset.modelProgress = String(Math.min(95, enrichedProgress));
        this.renderer?.render(this.scene, this.camera);
        await nextFrame();
      }

      this.modelParts = { lots, streets, other };
      this._streetSourceCandidates = streets.slice();
      this.modelLandscapeNodes = landscapeNodes;
      this.modelLeisureNodes = leisureNodes;
      this.modelLeisureFocusNodes = structureNodes.length
        ? structureNodes
        : leisureNodes;

      this.dataset.modelParts = `lotes:${lots.length}|ruas:${streets.length}|outros:${other.length}`;
      this.dataset.mapSelectionAreas = `lotes:${lots.length}|ruas:${streets.length}`;
      this.dataset.mapSelectionPolicy =
        "lotes e ruas como áreas selecionáveis · sem modelo 3D adicional";
      this.dataset.publicInternalDividersHidden = String(hiddenPublicDividers);
      this.dataset.landscapeNodes = String(landscapeNodes.length);
      this.dataset.leisureNodes = String(leisureNodes.length);
      this.dataset.focusStructureNodes = String(
        this.modelLeisureFocusNodes.length,
      );
      this.dataset.socialMaterials = `${leisureNodes.length}:social-pbr-v552`;
      this.dataset.modelEnrichment = "classified";

      await nextFrame();
      this.applyPublicPresentationStyle(THREE);
      // No mapa administrativo, a malha viária precisa nascer junto da cena:
      // superfície integral primeiro, divisões transversais de meio lote por
      // cima. A versão pública continua usando apenas a fotografia aérea.
      if (
        !this.isPublicMapVisual() ||
        this.hasAttribute("data-admin-shared-public-map")
      ) {
        // A apresentação pública marca esta flag como pronta ao esconder seus
        // overlays. No mapa compartilhado do admin, reabra a construção.
        this._streetOperationalGeometryReady = false;
        this.ensureOperationalStreetGeometry();
      }
      this.buildPdfMasterplan3DLayerV1(
        THREE,
        this.adminPdfMasterplanUnderlayTextureV1,
      );
      this.buildStageOverlayTargets();
      if (this._stageOverlaySelectionInitializedV1)
        this.setStageOverlays?.(this._requestedStageOverlayKeysV1 || [], false);
      else if (this.stageOverlayKey)
        this.setStageOverlay(this.stageOverlayKey, false);
      this.syncDashboardModeHighlightV1?.();

      this.dataset.modelEnrichment = "ready";
      this.dataset.modelOperationalGeometry = "source-meshes";
      this.paintProgressAreaSelectionV1(
        appStore.get().mapProgressSelection || [],
      );
      this.update3dBootStateV5367({
        phase: "ready",
        readyAt: performance.now(),
        readyMs: Math.round(performance.now() - startedAt),
        lots: lots.length,
        streets: streets.length,
        other: other.length,
      });

      this._modelGpuReady = true;
      this.dataset.modelGpuReady = "true";
      this.dataset.modelProgress = "96";
      this.dataset.publicModelSyncState = `model:${this.masterplanModel ? "1" : "0"}|largest:${Number.isFinite(this.masterplanLargest) ? "1" : "0"}|group:${this.modelGroup ? "1" : "0"}|geo:${this.dwgGeo ? "1" : "0"}|lots:${lots.length}`;
      // O GLB do loteamento termina primeiro. Árvores, relevo e entorno são
      // enriquecimento visual e entram depois do primeiro enquadramento.
      this.schedulePublicEnvironmentLoadingV1();
      this.record3dBootPhaseV5367("gpu-ready", {
        meshCount: meshes.length,
        processedMeshes: meshes.length,
        lots: lots.length,
        streets: streets.length,
        other: other.length,
      });
      setTimeout(() => syncCompactMapMirrors(), 1800);

      // Sync geográfico sai do callback de parse/classificação.
      setTimeout(() => this.syncThree(), 0);
      publishMapPreview();
      return true;
    };

    this._modelEnrichmentPromise = run().finally(() => {
      this._modelEnrichmentPromise = null;
    });
    return this._modelEnrichmentPromise;
  }
  };
  const prototype = MapScene.prototype as unknown as Record<string, unknown>;
  Object.entries(methods).forEach(([name, method]) => Object.defineProperty(prototype, name, { configurable: true, writable: true, value: method }));
  return MapScene;
}

interface AtlasMapSceneStateDependencies extends Pick<AtlasMapScenePresentationConfig,
  | "ADMIN_FIXED_MAP_ROTATION_DEG"
  | "ADMIN_REFERENCE_AERIAL_INITIAL_SCENE_ZOOM"
  | "ADMIN_REFERENCE_AERIAL_VIEW_VERSION"
  | "DASHBOARD_INITIAL_SCENE_ZOOM"
  | "INITIAL_SCENE_ZOOM"
  | "MAP_SCENE_STATE_VERSION"
  | "MAX_SCENE_ZOOM"
  | "MIN_SCENE_ZOOM"
> {
  appStore: { get: () => Record<string, unknown> };
  demoData: { activities: Array<{ id: string; name: string }> };
  stageOverlayKey: (value: unknown) => string;
}
interface AtlasMapSceneStateElement extends HTMLElement {
  mapTileMode?: string;
  sceneManualRotation?: number;
  sceneManualZoom?: number;
  sceneManualPan?: { x: number; y: number };
  sceneTiltAdjust?: number;
  sceneUserInteracted?: boolean;
  initialSceneFocusApplied?: boolean;
  stageOverlayKey?: string;
  isAdminPublicMapV1?: () => boolean;
  isPublicCustomerExperience?: () => boolean;
}

/** Initialize camera and tile state from the current persisted map view. */
export function initializeAtlasMapSceneState(scene: AtlasMapSceneStateElement, dependencies: AtlasMapSceneStateDependencies): {
  isAdminPublicMap: boolean; isAdminReferenceAerial: boolean; isCurrentSceneState: boolean; initialSceneZoom: number;
} {
  const { appStore, demoData, stageOverlayKey, ...configuration } = dependencies;
  const state = appStore.get();
  const isDashboardScene = scene.hasAttribute("data-dashboard-progress-map") || scene.hasAttribute("data-dashboard-operational-map");
  const isAdminPublicMap = scene.isAdminPublicMapV1?.() === true;
  const isAdminReferenceAerial = scene.hasAttribute("data-admin-shared-public-map");
  const selectedStage = demoData.activities.find(activity => activity.id === state.selectedStage);
  const command = createAtlasMapSceneInitialStateCommand({
    savedMap: state.mapView,
    isDashboardScene,
    isAdminPublicMap,
    isAdminReferenceAerial,
    isPublicCustomer: Boolean(scene.isPublicCustomerExperience?.()),
    storedTileMode: state.mapTileMode,
    stageOverlayKey: stageOverlayKey(selectedStage?.name),
    ...configuration,
  });
  scene.mapTileMode = command.mapTileMode;
  scene.dataset.mapTileMode = command.mapTileMode;
  scene.sceneManualRotation = command.sceneManualRotation;
  scene.sceneManualZoom = command.sceneManualZoom;
  scene.sceneManualPan = command.sceneManualPan;
  scene.sceneTiltAdjust = command.sceneTiltAdjust;
  scene.sceneUserInteracted = command.sceneUserInteracted;
  scene.initialSceneFocusApplied = command.sceneUserInteracted;
  scene.stageOverlayKey = command.stageOverlayKey;
  scene.dataset.sceneRotation = `${Math.round(command.sceneManualRotation)}deg`;
  scene.dataset.sceneRotationLock = command.isAdminReferenceAerial ? `${configuration.ADMIN_FIXED_MAP_ROTATION_DEG}deg · fixo` : "";
  scene.dataset.sceneZoom = `${Math.round(command.sceneManualZoom * 100)}%`;
  scene.dataset.sceneZoomMin = `${Math.round(configuration.MIN_SCENE_ZOOM * 100)}%`;
  scene.dataset.sceneZoomMax = `${Math.round(configuration.MAX_SCENE_ZOOM * 100)}%`;
  scene.dataset.scenePan = `${Math.round(command.sceneManualPan.x)},${Math.round(command.sceneManualPan.y)}`;
  scene.dataset.scenePanAxis = "x/y compartilhados · z fixo";
  scene.dataset.sceneAnchor = "center";
  scene.dataset.sceneStateVersion = String(configuration.MAP_SCENE_STATE_VERSION);
  scene.dataset.adminReferenceAerialViewVersion = command.isAdminReferenceAerial ? String(configuration.ADMIN_REFERENCE_AERIAL_VIEW_VERSION) : "";
  scene.style.setProperty("--scene-anchor-x", "50%");
  scene.style.setProperty("--scene-anchor-y", "50%");
  return {
    isAdminPublicMap: command.isAdminPublicMap,
    isAdminReferenceAerial: command.isAdminReferenceAerial,
    isCurrentSceneState: command.isCurrentSceneState,
    initialSceneZoom: command.initialSceneZoom,
  };
}

interface AtlasMapSceneStoreDependencies {
  appStore: {
    get: () => Record<string, unknown>;
    subscribe: (listener: (state: Record<string, unknown>) => void) => unknown;
  };
  commands: Pick<AtlasMapSceneStateCommandsV1, "toggleMapMode">;
  demoData: { activities: Array<{ id: string; name: string }> };
  performanceRef: { now: () => number };
  publicPresentation: boolean;
}
interface AtlasMapSceneStoreElement extends HTMLElement {
  _lastStoreView?: unknown;
  _lastRecordsRef?: unknown;
  _lastOverlayStageId?: unknown;
  _suppressMapToggleUntil?: number;
  _publicRequestedMapTileMode?: string;
  solarHour?: number;
  setMapContext?: (view: unknown) => void;
  syncOperationalRecordMapV5370?: (records: unknown[]) => void;
  setSolarHour?: (hour: unknown, render?: boolean, announce?: boolean) => void;
  setMapTileMode?: (mode?: string, announce?: boolean) => void;
  setStageOverlay?: (stage: string, render?: boolean) => void;
}

/** Bind map subscriptions and backdrop focus toggling to the mounted scene. */
export function installAtlasMapSceneStoreEvents(scene: AtlasMapSceneStoreElement, dependencies: AtlasMapSceneStoreDependencies): void {
  const { appStore, commands, demoData, performanceRef, publicPresentation } = dependencies;
  appStore.subscribe(state => {
    if (scene._lastStoreView !== state.view) {
      scene._lastStoreView = state.view;
      scene.setMapContext?.(state.view);
    }
    if (scene._lastRecordsRef !== state.records) {
      scene._lastRecordsRef = state.records;
      scene.syncOperationalRecordMapV5370?.(Array.isArray(state.records) ? state.records : []);
    }
    if (state.solarHourMode === "manual" && Number.isFinite(Number(state.solarHour)) && Math.abs(Number(state.solarHour) - Number(scene.solarHour || 0)) > 0.01) {
      scene.setSolarHour?.(state.solarHour, false, false);
    }
    scene.dataset.mode = String(state.mapMode ?? "");
    scene.setMapTileMode?.(scene._publicRequestedMapTileMode || String(state.mapTileMode || "satellite"), false);
    const stage = demoData.activities.find(activity => activity.id === state.selectedStage);
    if (!publicPresentation && stage && scene._lastOverlayStageId !== state.selectedStage) {
      scene._lastOverlayStageId = state.selectedStage;
      scene.setStageOverlay?.(stage.name, false);
    }
  });
  scene.addEventListener("click", event => {
    const target = event.target;
    if (!(target instanceof Element)) return;
    if (target.closest(".leaflet-control,.map-solar-control,.map-badge,.map-category-switcher,.map-selection-tools,.map-selection-panel,.map-gesture-legend,.map-rotation-controls") || performanceRef.now() < Number(scene._suppressMapToggleUntil || 0)) return;
    commands.toggleMapMode();
  });
}

interface AtlasMapSceneActivationElement extends AtlasMapSceneStoreElement {
  mapTileMode?: string;
  mountMap3DLoadingScreenV1: () => void;
  isPublicCustomerExperience: () => boolean;
  isAdminPublicMapV1?: () => boolean;
  bindSolarControl: () => void;
  bindSceneControls: () => void;
  isAdminStandalone3DV5370?: () => boolean;
  mountAdminStandalone3DV5370?: () => void;
  initWhenReady: () => void;
}

/** Activate the existing map controls and store bindings after shell creation. */
export function activateAtlasMapScene(
  scene: AtlasMapSceneActivationElement,
  input: AtlasMapSceneStoreDependencies & { solarMarkup: string },
): boolean {
  scene.mountMap3DLoadingScreenV1();
  scene.querySelector(".map-tint")?.insertAdjacentHTML("afterend", input.solarMarkup);
  const publicPresentation = scene.isPublicCustomerExperience() && !scene.isAdminPublicMapV1?.();
  if (publicPresentation) {
    scene.dataset.mapControls = "public-disabled";
    scene.querySelectorAll(".map-badge,.map-category-switcher,.map-rotation-controls,.map-gesture-legend,.map-selection-tools,.map-selection-panel,.map-v5-launcher,.compact-map-controls,.map-status-panel,[data-map-controls],[data-scene-selection]").forEach(node => node.remove());
  } else {
    scene.dataset.mapControls = "admin-enabled";
  }
  scene.bindSolarControl();
  scene.setMapTileMode?.(scene.mapTileMode, false);
  if (!publicPresentation) scene.bindSceneControls();
  scene._lastOverlayStageId = input.appStore.get().selectedStage;
  scene._lastStoreView = input.appStore.get().view;
  scene.setMapContext?.(scene._lastStoreView);
  if (scene.isAdminStandalone3DV5370?.()) scene.mountAdminStandalone3DV5370?.();
  else scene.initWhenReady();
  installAtlasMapSceneStoreEvents(scene, input);
  return publicPresentation;
}

interface AtlasMapSceneConnectionElement extends Omit<AtlasMapSceneStartupElement, "isPublicCustomerExperience" | "isAdminPublicMapV1">, AtlasMapSceneActivationElement {
  _persistentMapMounted?: boolean;
  _lastOverlayStageId?: unknown;
  connectedCallback?: () => void;
  selectedLotIds?: Set<unknown>;
  mapSelectionMode?: unknown;
  progressSelectionParts?: unknown[];
  renderCompact: () => void;
}

interface AtlasMapSceneConnectionDependencies extends Omit<AtlasMapSceneStateDependencies, "appStore"> {
  appStore: AtlasMapSceneStoreDependencies["appStore"];
  commands: AtlasMapSceneStoreDependencies["commands"];
  esc: (value: unknown) => string;
  ico: (name: string) => string;
  performanceRef: { now: () => number };
  setSharedMapScene: (scene: HTMLElement) => void;
  stageOverlayLabels: Record<string, string>;
}

/** Own the shared MapScene connection, static shell, and activation lifecycle. */
export function installAtlasMapSceneConnection(
  MapScene: CustomElementConstructor,
  dependencies: AtlasMapSceneConnectionDependencies,
): CustomElementConstructor {
  const prototype = MapScene.prototype as unknown as AtlasMapSceneConnectionElement;
  prototype.connectedCallback = function(this: AtlasMapSceneConnectionElement): void {
    if (this._persistentMapMounted) return;
    this._persistentMapMounted = true;
    this.dataset.mapLifecycle = "persistent-mounted";
    this.dataset.mapInstanceId = `map-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`;
    this.selectedLotIds = new Set();
    this.mapSelectionMode = null;
    this.progressSelectionParts = [];
    initializeAtlasMapSceneState(this, dependencies);
    if (this.hasAttribute("compact")) {
      const full3d = true;
      if (!full3d) {
        const stage = dependencies.esc(this.getAttribute("data-stage") || "Etapa");
        this.dataset.renderMode = "safe-thumbnail";
        this.dataset.mapInit = "safe-thumbnail";
        this.innerHTML = `<div class="safe-map-thumbnail"><span>MAPA OPERACIONAL</span><b>${stage}</b><small>Visualização segura</small></div>`;
        return;
      }
      this.renderCompact();
      return;
    }
    if (false) {
      this.dataset.renderMode = "safe-map";
      this.dataset.mapInit = "safe-placeholder";
      this.innerHTML = '<div class="safe-map-placeholder"><span>ALIANÇA PARK</span><strong>Mapa operacional</strong><small>Visualização segura ativada</small></div>';
      return;
    }
    dependencies.setSharedMapScene(this);
    const { solarMarkup, mapMarkup } = renderAtlasMapSceneShell({
      stageOverlayLabels: dependencies.stageOverlayLabels,
      ico: dependencies.ico,
      persistent: this.hasAttribute("data-persistent-map"),
    });
    this.innerHTML = mapMarkup;
    applyAtlasMapSceneCoverLayout(this);
    activateAtlasMapScene(this, {
      appStore: dependencies.appStore,
      commands: dependencies.commands,
      demoData: dependencies.demoData,
      performanceRef: dependencies.performanceRef,
      publicPresentation: this.isPublicCustomerExperience() && !this.isAdminPublicMapV1?.(),
      solarMarkup,
    });
  };
  return MapScene;
}

