type PublicMapGesture = { zoom: number; panX: number; panY: number; tilt: number; rotation: number; drag: { x: number; y: number; mode: "pan" | "zoom" | "tilt" | "rotation" } | null };
interface PublicLeadsSurfaceState { gesture: PublicMapGesture; returnToTitle: { armed: boolean; resetting: boolean; lastY: number; resetCount: number } }
const initialPublicMapGesture = (): PublicMapGesture => ({ zoom: 1, panX: 0, panY: 0, tilt: 0, rotation: 0, drag: null });

type PublicMapQualityTextureSlotV1 = 'map' | 'emissiveMap' | 'normalMap' | 'roughnessMap' | 'metalnessMap' | 'aoMap' | 'alphaMap' | 'bumpMap' | 'displacementMap' | 'lightMap';
interface PublicMapQualityTextureV1 { anisotropy: number; magFilter: unknown; minFilter: unknown; generateMipmaps: boolean; colorSpace?: unknown; needsUpdate: boolean }
interface PublicMapQualityMaterialV1 extends Partial<Record<PublicMapQualityTextureSlotV1, PublicMapQualityTextureV1 | null>> { needsUpdate: boolean }
interface PublicMapQualityNodeV1 { isMesh?: boolean; material?: PublicMapQualityMaterialV1 | PublicMapQualityMaterialV1[] | null }
interface PublicMapQualityModelV1 { traverse(callback: (node: PublicMapQualityNodeV1) => void): void }
interface PublicMapQualityRendererV1 {
  capabilities?: { getMaxAnisotropy?: () => number };
  setPixelRatio(value: number): void;
  setSize(width: number, height: number, updateStyle: boolean): void;
  outputColorSpace: unknown;
  toneMapping: unknown;
  toneMappingExposure: number;
  render(scene: unknown, camera: unknown): void;
}
interface PublicMapQualityThreeV1 { SRGBColorSpace: unknown; ACESFilmicToneMapping: unknown; LinearFilter: unknown; LinearMipmapLinearFilter: unknown }
interface PublicMapQualitySceneV1 extends HTMLElement {
  THREE?: PublicMapQualityThreeV1;
  renderer?: PublicMapQualityRendererV1;
  masterplanModel?: PublicMapQualityModelV1;
  modelGroup?: PublicMapQualityModelV1;
  modelReady?: boolean;
  scene?: unknown;
  camera?: unknown;
}

/** Apply the public map's texture and render quality when its live scene is ready. */
export function installAtlasPublicMapTextureQualityV1(input: {
  project: (input: import('./program.js').PublicMapTextureQualityProjectionInputV1) => import('./program.js').PublicMapTextureQualityProjectionV1;
  root?: ParentNode;
}): void {
  if (typeof document === 'undefined' || typeof window === 'undefined') return;
  const root = input.root || document;
  const selector = 'map-scene[data-public-map],map-scene[data-public-presentation]';
  const textureKeys: Array<[PublicMapQualityTextureSlotV1, boolean]> = [
    ['map', true], ['emissiveMap', true], ['normalMap', false], ['roughnessMap', false],
    ['metalnessMap', false], ['aoMap', false], ['alphaMap', false], ['bumpMap', false],
    ['displacementMap', false], ['lightMap', false],
  ];
  const applyQuality = (map: PublicMapQualitySceneV1): boolean => {
    const three = map.THREE, renderer = map.renderer, model = map.masterplanModel || map.modelGroup;
    if (!three || !renderer || !model || !map.modelReady) return false;
    const maximumAnisotropy = renderer.capabilities?.getMaxAnisotropy?.() || 1;
    const quality = input.project({ devicePixelRatio: window.devicePixelRatio || 1, maximumAnisotropy });
    renderer.setPixelRatio(quality.pixelRatio);
    const canvas = map.querySelector<HTMLElement>('.three-overlay');
    const width = Math.max(1, canvas?.clientWidth || map.clientWidth || window.innerWidth);
    const height = Math.max(1, canvas?.clientHeight || map.clientHeight || window.innerHeight);
    renderer.setSize(width, height, false);
    renderer.outputColorSpace = three.SRGBColorSpace;
    renderer.toneMapping = three.ACESFilmicToneMapping;
    renderer.toneMappingExposure = 1.06;
    const textures = new Set<PublicMapQualityTextureV1>();
    let materialCount = 0;
    model.traverse(node => {
      if (!node?.isMesh) return;
      const materials = Array.isArray(node.material) ? node.material : [node.material];
      materials.forEach(material => {
        if (!material) return;
        materialCount++;
        textureKeys.forEach(([key, colorTexture]) => {
          const texture = material[key];
          if (!texture || textures.has(texture)) return;
          textures.add(texture);
          texture.anisotropy = quality.anisotropy;
          texture.magFilter = three.LinearFilter;
          texture.minFilter = three.LinearMipmapLinearFilter;
          texture.generateMipmaps = true;
          if (colorTexture) texture.colorSpace = three.SRGBColorSpace;
          texture.needsUpdate = true;
        });
        material.needsUpdate = true;
      });
    });
    map.dataset.publicTextureQuality = 'anisotropic-mipmaps-v5337';
    map.dataset.publicTextureAnisotropy = String(quality.anisotropy);
    map.dataset.publicTextureCount = String(textures.size);
    map.dataset.publicMaterialCount = String(materialCount);
    map.dataset.publicRenderPixelRatio = quality.pixelRatio.toFixed(2);
    renderer.render(map.scene, map.camera);
    return true;
  };
  const install = (map: PublicMapQualitySceneV1, attempt = 0): void => {
    if (map.dataset.publicTextureQuality === 'anisotropic-mipmaps-v5337') return;
    if (applyQuality(map)) return;
    if (attempt >= 18) return;
    window.setTimeout(() => install(map, attempt + 1), 250 + attempt * 80);
  };
  const scan = (): void => root.querySelectorAll<PublicMapQualitySceneV1>(selector).forEach(map => install(map));
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', scan, { once: true });
  else scan();
  window.addEventListener('resize', () => {
    root.querySelectorAll<PublicMapQualitySceneV1>(selector).forEach(map => {
      const renderer = map.renderer;
      if (!renderer) return;
      const canvas = map.querySelector<HTMLElement>('.three-overlay');
      const width = Math.max(1, canvas?.clientWidth || map.clientWidth || window.innerWidth);
      const height = Math.max(1, canvas?.clientHeight || map.clientHeight || window.innerHeight);
      renderer.setSize(width, height, false);
      renderer.render?.(map.scene, map.camera);
    });
  }, { passive: true });
}

