/** Install public leads map presentation styles from the component monolith. */
export function installAtlasPublicLeadsMapStylesV1(documentRef: Document = document): boolean {
  const id = 'belavista-public-selection-focus-v5318-style';
  const existing = documentRef.getElementById(id);
  if (existing) { existing.dataset.atlasOwnerV1 = 'components-ts'; return true; }
  const style = documentRef.createElement('style');
  style.id = id;
  style.dataset.atlasOwnerV1 = 'components-ts';
  style.textContent = ATLAS_PUBLIC_LEADS_MAP_STYLES_V1;
  documentRef.head.append(style);
  return true;
}

/** Apply a static DWG-marker selection and publish the event consumed by chat and widgets. */
export function selectPublicStaticLotMarker(
  map: import("./program.js").PublicMapSelectionScenePort,
  model: import("./program.js").PublicStaticLotMarkerModel,
  marker: HTMLElement,
  restoreView: () => void,
  hideWidget: () => void,
): boolean {
  if (!map || !model || !marker) return false;
  clearPublicMapSelection(map, true, restoreView, hideWidget);
  const source = projectPublicStaticLotSelection(model.record, model.index, marker.dataset.status || model.status);
  marker.classList.add("is-selected");
  map.__publicStaticLotMarker = marker;
  map.dataset.selectedPart = source.data.partLabel as string;
  map.dataset.selectedKind = "lots";
  map.dataset.selectedLotCount = "1";
  map.dataset.selectedLots = source.data.partId as string;
  map.dataset.publicSelectionFocus = "static-marker";
  marker.dispatchEvent(new CustomEvent("belavista:lot-marker-selected", {
    bubbles: true,
    composed: true,
    detail: {lotId: source.id, label: source.label, sourceName: source.id, lotData: {...source.data}} satisfies import("./program.js").PublicLeadMapMarkerSelectionDetail,
  }));
  map.ownerDocument.body.dataset.publicWidgetsVisible = "true";
  map.ownerDocument.body.dataset.publicControlsVisible = "true";
  return true;
}

/** Apply the single-lot scene selection and its transient visual effects. */
export function applyPublicMapLotSelection(
  map: import("./program.js").PublicMapSelectionScenePort,
  source: import("./program.js").PublicMapLotSelectionSceneSource,
  effects: import("./program.js").PublicMapLotSelectionEffects,
): import("./program.js").PublicMapLotSelectionCommand | null {
  const data = source?.userData || {};
  const command = publicMapLotSelectionCommand({
    sourceName: source?.name,
    partId: data.partId,
    partLabel: data.partLabel,
    partKind: data.partKind,
    userData: data,
    selectedLotIds: map.selectedLotIds || [],
  });
  if (!command) return null;
  clearPublicMapSelection(map, false, effects.restoreView, effects.hideWidget);
  if (command.operation === "clear") {
    effects.restoreView();
    return command;
  }
  map.selectedLotIds = new Set([command.partId]);
  map.dataset.selectedPart = command.label;
  map.dataset.selectedKind = "lots";
  map.dataset.selectedLotCount = "1";
  map.dataset.selectedLots = command.partId;
  map.dispatchEvent(new CustomEvent("belavista:lot-marker-selected", {bubbles: true, composed: true, detail: command.detail}));
  effects.highlight();
  effects.focus();
  return command;
}

/** Clear map selection state, highlight materials, halo, and detail panel. */
export function clearPublicMapSelection(
  map: import("./program.js").PublicMapSelectionScenePort | null,
  restore: boolean,
  restoreView: () => void,
  hideWidget: () => void,
): boolean {
  if (!map) return false;
  map.__publicStaticLotMarker?.classList.remove("is-selected");
  delete map.__publicStaticLotMarker;
  delete map.dataset.publicSelectionFocus;
  const ids = map.selectedLotIds || new Set<string>();
  for (const id of ids) {
    const matches = (map.modelParts?.lots || []).filter(part => (part.userData?.partId || part.name) === id);
    for (const part of matches) {
      if (part.userData) delete part.userData.selectionMaterial;
      map.restorePartMaterial?.(part);
    }
  }
  ids.clear();
  map.selectedLotIds = ids;
  if (map.selectionHalo) map.selectionHalo.visible = false;
  map.removeMapSelectionPanel?.();
  delete map.dataset.selectedPart;
  delete map.dataset.selectedKind;
  map.dataset.selectedLotCount = "0";
  map.dataset.selectedLots = "";
  map.dispatchEvent(new CustomEvent("belavista:lot-selection-cleared", {bubbles: true, composed: true}));
  hideWidget();
  if (restore) restoreView();
  map.sceneStage?.updateMatrixWorld?.(true);
  map.renderer?.render?.(map.scene, map.camera);
  return true;
}

/** Typed program ports for public-map data, projection, and interaction. */
