/** Public map lot details and commercial shortcuts; map geometry remains owned by map-scene. */
export class AtlasPublicLotWidget extends AtlasHTMLElementBase {
  private snapshot: PublicLotWidgetState = { selection: null };
  setSelection(selection: import("./program.js").PublicLeadChatSelection | null): void { this.snapshot = { selection }; this.render(); }
  connectedCallback(): void {
    this.dataset.publicLotDetailsV5335 = "";
    this.addEventListener("click", event => {
      const target = event.target;
      if (!(target instanceof Element)) return;
      const button = target.closest<HTMLButtonElement>("button");
      if (!button) return;
      if (button.hasAttribute("data-public-lot-close")) {
        event.preventDefault(); event.stopPropagation();
        this.setSelection(null);
        this.dispatchEvent(new CustomEvent("belavista:public-map-lot-clear", { bubbles: true, composed: true }));
        return;
      }
      const requestKind = button.dataset.publicLotAgentAction;
      const selection = this.snapshot.selection;
      if (!selection || !["availability", "characteristics", "conditions"].includes(requestKind || "")) return;
      event.preventDefault(); event.stopPropagation();
      this.querySelectorAll<HTMLButtonElement>("[data-public-lot-agent-action]").forEach(item => item.disabled = true);
      const data = selection.selectedLotData || {};
      this.dispatchEvent(new CustomEvent("belavista:public-map-lot-action", { bubbles: true, composed: true, detail: { requestKind, sourceName: String(data.sourceName || data.id || ""), lotData: { ...data } } }));
      setTimeout(() => this.querySelectorAll<HTMLButtonElement>("[data-public-lot-agent-action]").forEach(item => item.disabled = false), 700);
    });
    this.render();
  }
  private render(): void {
    const selection = this.snapshot.selection;
    this.hidden = !selection;
    this.className = "public-selected-lot public-lot-info-v5318";
    this.toggleAttribute("data-selected-lot", Boolean(selection));
    if (!selection) { this.innerHTML = `${publicLotWidgetStyles}`; return; }
    const data = selection.selectedLotData || {};
    const esc = (value: unknown): string => String(value ?? "").replace(/[&<>\"']/g, char => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", "\"": "&quot;", "'": "&#39;" }[char] || char));
    const projected = (globalThis as PublicChatRuntime).belavistaPublicMapLotWidgetDetails?.({ name: String(data.sourceName || data.id || ""), userData: data });
    const label = String(projected?.label || data.label || selection.selectedLot || data.id || "Lote selecionado");
    const facts = projected?.rows.slice(0, 4) || [["Referência", data.id || selection.selectedLotId], ["Quadra", data.block], ["Área", data.area], ["Situação", data.status || "Disponibilidade sob consulta"], ["Orientação", data.orientation]].filter(([, value]) => String(value || "").trim()).slice(0, 4);
    this.innerHTML = `${publicLotWidgetStyles}<div class="lot-info-head"><div><small>LOTE SELECIONADO</small><strong>${esc(label)}</strong></div><button type="button" data-public-lot-close aria-label="Fechar informações">×</button></div><div class="lot-info-facts">${facts.map(([name, value]) => `<div class="lot-info-fact"><small>${esc(name)}</small><strong title="${esc(value)}">${esc(value)}</strong></div>`).join("")}</div><div class="lot-agent-actions"><small>Perguntar à IA sobre esta seleção</small><div class="lot-agent-actions-grid"><button type="button" data-public-lot-agent-action="availability">Disponibilidade</button><button type="button" data-public-lot-agent-action="characteristics">Características</button><button type="button" data-public-lot-agent-action="conditions">Condições</button></div></div><p class="lot-info-note">Clique novamente no lote ou feche este card para retornar ao enquadramento anterior.</p>`;
  }
}
if (!customElements.get("atlas-public-lot-widget")) customElements.define("atlas-public-lot-widget", AtlasPublicLotWidget);

