export interface AtlasPublicLeadChatEventControllerDependenciesV1 {
  host: Document;
  readSession(): PublicLeadChatSession;
  getSelection(): import("./program.js").PublicLeadChatSelection;
  selectLot(detail: import("./program.js").PublicLeadMapMarkerSelectionDetail): import("./program.js").PublicLeadChatSelection;
  clearSelection(): void;
  converse(payload: PublicLeadChatPayload): Promise<PublicLeadChatResult>;
  upload(input: {sessionId: string; files: Record<string, File | undefined>; scope: string}): Promise<Record<string, unknown>>;
  clearMapSelection(map: HTMLElement, hideWidget: () => void): void;
  projectMapAction(detail: import("./program.js").PublicLeadMapActionDetail): {selection: import("./program.js").PublicLeadChatSelection; prompt: string; status: string} | null;
}

/** Own public-lead chat, map-selection, and upload event wiring; services remain injected. */
export function installAtlasPublicLeadChatEventControllerV1(
  dependencies: AtlasPublicLeadChatEventControllerDependenciesV1,
): () => void {
  const {host} = dependencies;
  const boundKey = "publicLeadChatEventControllerV1";
  if (host.documentElement.dataset[boundKey] === "true") return () => undefined;
  host.documentElement.dataset[boundKey] = "true";
  const runtime = globalThis as typeof globalThis & {__BELAVISTA_PUBLIC_LEAD_CHAT_EVENTS_INSTALLED?: boolean};
  runtime.__BELAVISTA_PUBLIC_LEAD_CHAT_EVENTS_INSTALLED = true;
  const publicLotWidget = (create: boolean): AtlasPublicLotWidget | null => {
    let widget = host.querySelector<AtlasPublicLotWidget>("atlas-public-lot-widget");
    if (widget || !create) return widget;
    const map = host.querySelector<HTMLElement>('map-scene[data-public-map],map-scene[data-public-presentation]');
    const parent = host.querySelector<HTMLElement>(".public-map-sticky") || map;
    if (!parent) return null;
    widget = host.createElement("atlas-public-lot-widget") as AtlasPublicLotWidget;
    parent.append(widget);
    return widget;
  };
  const initializeChat = (element: AtlasPublicLeadChat): void => {
    element.session = dependencies.readSession();
    const selected = dependencies.getSelection().selectedLotData;
    if (selected?.id) element.session = {
      ...element.session,
      selectedLot: { ...selected, id: selected.id, label: selected.label || selected.id, status: selected.status || "unknown" },
    };
  };
  const onChatConnected = (event: Event): void => {
    const element = event.target as AtlasPublicLeadChat | null;
    if (element && typeof element.resolveConversation === "function") initializeChat(element);
  };
  const onLotSelected = (event: Event): void => {
    const detail = (event as CustomEvent<import("./program.js").PublicLeadMapMarkerSelectionDetail>).detail || {};
    const selection = dependencies.selectLot(detail);
    const selected = selection.selectedLotData;
    if (detail.lotData) publicLotWidget(true)?.setSelection(selection);
    const element = host.querySelector<AtlasPublicLeadChat>("public-lead-chat");
    if (!element || !selected?.id) return;
    element.session = {
      ...element.session,
      selectedLot: { ...selected, id: selected.id, label: selected.label || selected.id, status: selected.status || "unknown" },
    };
  };
  const onLotSelectionCleared = (): void => {
    dependencies.clearSelection();
    publicLotWidget(false)?.setSelection(null);
  };
  const onPublicMapLotClear = (): void => {
    const map = host.querySelector<HTMLElement>('map-scene[data-public-map],map-scene[data-public-presentation]');
    if (map) dependencies.clearMapSelection(map, () => publicLotWidget(false)?.setSelection(null));
  };
  const onChatRequest = (event: Event): void => {
    const request = event as CustomEvent<PublicLeadChatRequestDetail>;
    const element = request.target as AtlasPublicLeadChat | null;
    const detail = request.detail;
    if (!element || typeof element.resolveConversation !== "function" || !detail?.requestId || !detail.payload) return;
    void dependencies.converse(detail.payload)
      .then(result => element.resolveConversation(detail.requestId, result))
      .catch(error => element.resolveConversation(detail.requestId, error instanceof Error ? error : new Error(String(error))));
  };
  const onChatUpload = (event: Event): void => {
    const request = event as CustomEvent<PublicLeadChatUploadDetail>;
    const element = request.target as AtlasPublicLeadChat | null;
    const detail = request.detail;
    if (!element || typeof element.resolveFilesUpload !== "function" || !detail?.requestId) return;
    void dependencies.upload(detail)
      .then(result => element.resolveFilesUpload(detail.requestId, result))
      .catch(error => element.resolveFilesUpload(detail.requestId, error instanceof Error ? error : new Error(String(error))));
  };
  const onMapLotAction = (event: Event): void => {
    const detail = (event as CustomEvent<import("./program.js").PublicLeadMapActionDetail>).detail || {requestKind: "" as import("./program.js").PublicLeadChatRequestKind};
    const action = dependencies.projectMapAction(detail);
    if (!action) return;
    const chat = host.querySelector<AtlasPublicLeadChat>("public-lead-chat");
    if (chat) chat.dispatchEvent(new CustomEvent("belavista:public-map-lot-request", {bubbles: true, detail: action}));
  };

  host.addEventListener("atlas:public-lead-chat-connected", onChatConnected);
  host.querySelectorAll<AtlasPublicLeadChat>("public-lead-chat").forEach(initializeChat);
  host.addEventListener("belavista:lot-marker-selected", onLotSelected);
  host.addEventListener("belavista:lot-selection-cleared", onLotSelectionCleared);
  host.addEventListener("belavista:public-map-lot-clear", onPublicMapLotClear);
  host.addEventListener("atlas:public-lead-chat-request", onChatRequest);
  host.addEventListener("atlas:public-lead-chat-upload", onChatUpload);
  host.addEventListener("belavista:public-map-lot-action", onMapLotAction);
  return () => {
    host.removeEventListener("atlas:public-lead-chat-connected", onChatConnected);
    host.removeEventListener("belavista:lot-marker-selected", onLotSelected);
    host.removeEventListener("belavista:lot-selection-cleared", onLotSelectionCleared);
    host.removeEventListener("belavista:public-map-lot-clear", onPublicMapLotClear);
    host.removeEventListener("atlas:public-lead-chat-request", onChatRequest);
    host.removeEventListener("atlas:public-lead-chat-upload", onChatUpload);
    host.removeEventListener("belavista:public-map-lot-action", onMapLotAction);
    delete host.documentElement.dataset[boundKey];
    delete runtime.__BELAVISTA_PUBLIC_LEAD_CHAT_EVENTS_INSTALLED;
  };
}

