const atlasPublicReservationPresentation = publicReservationPresentationData as unknown as AtlasPublicReservationPresentationV1;

/** Reservation intake, browser OCR and Pix presentation; persistence is owned by program.ts. */
export class AtlasPublicReservationFlow extends AtlasHTMLElementBase {
  private requestId = "";
  private pixRequestId = "";

  connectedCallback(): void {
    this.render();
    const intro = this.querySelector<HTMLElement>(".reservation-form>header p"), submit = this.querySelector<HTMLButtonElement>(".reservation-submit");
    if (intro) intro.textContent = atlasPublicReservationPresentation.dialog.validatedDescription;
    if (submit) submit.textContent = atlasPublicReservationPresentation.status.submit;
    this.bind();
  }

  private render(): void {
    const dialogId = `reservation-${Math.random().toString(36).slice(2)}`;
    const copy = atlasPublicReservationPresentation, accept = copy.documents.accept.join(",");
    this.innerHTML = `<section class="reservation-entry"><a class="reservation-start" data-reservation-start href="#${dialogId}">${copy.entry.startLabel} <span>${copy.entry.arrow}</span></a><small>${copy.entry.subtitle}</small></section>
      <dialog class="reservation-dialog" id="${dialogId}" popover="manual"><form class="reservation-form" method="dialog"><header><div><span>${copy.dialog.eyebrow}</span><h2>${copy.dialog.title}</h2><p>${copy.dialog.initialDescription}</p></div><a href="#" data-reservation-close aria-label="${copy.dialog.closeAriaLabel}">${copy.dialog.closeLabel}</a></header><nav class="reservation-steps">${copy.steps.map((label, index) => `<span${index === 0 ? ' class="active"' : ""}>${index + 1} · ${label}</span>`).join("")}</nav><div class="reservation-grid"><label>${copy.fields.fullName.label}<input name="fullName" required autocomplete="${copy.fields.fullName.autocomplete}"></label><label>${copy.fields.cpf.label}<input name="cpf" required inputmode="${copy.fields.cpf.inputMode}" placeholder="${copy.fields.cpf.placeholder}"></label><label>${copy.fields.birthDate.label}<input name="birthDate" required type="date"></label><label>${copy.fields.lot.label}<input name="lot" required placeholder="${copy.fields.lot.placeholder}"></label></div><fieldset><legend>${copy.documents.legend}</legend><label>${copy.documents.identityFront}<input name="identityFront" required type="file" accept="${accept}"></label><label>${copy.documents.identityBack}<input name="identityBack" required type="file" accept="${accept}"></label><label>${copy.documents.addressProof}<input name="addressProof" required type="file" accept="${accept}"></label></fieldset><label class="reservation-consent"><input name="consent" type="checkbox" required> ${copy.documents.consent}</label><button type="button" class="reservation-analyze" data-reservation-analyze>${copy.documents.analyzeButton}</button><section class="document-review" data-document-review><span>${copy.review.eyebrow}</span><p>${copy.review.waiting}</p></section><section class="reservation-pix" data-reservation-pix hidden><div><span>${copy.pix.eyebrow}</span><h3 data-pix-value>${copy.pix.emptyAmount}</h3><p>${copy.pix.description}</p><textarea data-pix-code readonly></textarea><button type="button" data-copy-pix>${copy.pix.copyButton}</button></div><canvas width="220" height="220" data-pix-qr></canvas></section><label class="payment-proof" hidden>${copy.documents.paymentProof}<input name="paymentProof" type="file" accept="${accept}"></label><footer><p class="reservation-status" aria-live="polite"></p><button type="submit" class="reservation-submit" disabled>${copy.status.initialSubmit}</button></footer></form></dialog>`;
  }

  private parentValues(): Record<string, FormDataEntryValue> {
    const form = this.closest("public-lead-form")?.querySelector<HTMLFormElement>(".public-lead-form");
    return form ? Object.fromEntries(new FormData(form)) : {};
  }

  openReservation(values: Record<string, unknown> = {}): void {
    const form = this.querySelector<HTMLFormElement>("form"), dialog = this.querySelector<HTMLDialogElement>("dialog");
    if (!form || !dialog) return;
    const lead = { ...this.parentValues(), ...values }, name = form.elements.namedItem("fullName") as HTMLInputElement | null;
    if (name) name.value = String(lead.name || lead.fullName || "");
    const popover = dialog as HTMLDialogElement & { showPopover?: () => void };
    try { popover.showPopover?.(); } catch {}
    if (!dialog.matches(":popover-open") && !dialog.open) { try { dialog.showModal(); } catch { dialog.setAttribute("open", ""); } }
    dialog.classList.add("is-open");
  }

  private bind(): void {
    const dialog = this.querySelector<HTMLDialogElement>("dialog"), form = this.querySelector<HTMLFormElement>("form");
    this.addEventListener("click", event => {
      const target = event.target;
      if (!(target instanceof Element)) return;
      const action = target.closest<HTMLElement>("[data-reservation-start], [data-reservation-close], [data-reservation-analyze], [data-copy-pix]");
      if (!action || !this.contains(action)) return;
      if (action.matches("[data-reservation-start]")) { this.openReservation(); return; }
      if (action.matches("[data-reservation-close]")) {
        dialog?.classList.remove("is-open");
        try { (dialog as (HTMLDialogElement & { hidePopover?: () => void }) | null)?.hidePopover?.(); } catch {}
        try { dialog?.close(); } catch { dialog?.removeAttribute("open"); }
        return;
      }
      if (action.matches("[data-reservation-analyze]")) { void this.analyze(); return; }
      const value = this.querySelector<HTMLTextAreaElement>("[data-pix-code]")?.value || "";
      void navigator.clipboard?.writeText(value);
    });
    form?.addEventListener("submit", event => { void this.submit(event); });
    this.addEventListener("atlas:public-reservation-result", event => {
      const result = (event as CustomEvent<AtlasPublicReservationResultDetailV1>).detail;
      if (!result || result.requestId !== this.requestId) return;
      const submit = this.querySelector<HTMLButtonElement>(".reservation-submit"), status = this.querySelector<HTMLElement>(".reservation-status");
      if (submit) submit.disabled = false;
      if (result.ok) {
        if (status) status.textContent = atlasPublicReservationPresentation.status.successTemplate.replace("{reservationId}", () => String(result.reservationId));
        form?.reset();
      } else if (status) status.textContent = result.error || atlasPublicReservationPresentation.status.errorFallback;
    });
    this.addEventListener("atlas:public-reservation-pix-result", event => {
      const result = (event as CustomEvent<AtlasPublicReservationPixResultDetailV1>).detail;
      if (!result || result.requestId !== this.pixRequestId) return;
      if (!result.ok || !result.payment) {
        if (result.reason === "pix-key-missing") {
          const status = this.querySelector<HTMLElement>(".reservation-status");
          if (status) status.textContent = atlasPublicReservationPresentation.status.missingPixKey;
        }
        return;
      }
      void this.presentPixPayment(result.payment);
    });
  }

  private async analyze(): Promise<void> {
    const form = this.querySelector<HTMLFormElement>("form"), status = this.querySelector<HTMLElement>(".reservation-status"), review = this.querySelector<HTMLElement>("[data-document-review]");
    if (!form || !status || !review) return;
    const input = (name: string) => form.elements.namedItem(name) as HTMLInputElement | null;
    const files = ["identityFront", "identityBack", "addressProof"].map(name => input(name)?.files?.[0]);
    const fullName = input("fullName")?.value.trim() || "", cpf = input("cpf")?.value || "";
    if (!isAtlasPublicReservationIdentityReadyV1(fullName, cpf) || files.some(file => !file)) { status.textContent = atlasPublicReservationPresentation.status.missingRequiredData; return; }
    status.textContent = atlasPublicReservationPresentation.status.readingDocuments;
    const reviewCodes = PUBLIC_RESERVATION_REVIEW_RESULT_CODES_V1;
    let recognizedText: string | null = null, ocrUnavailable = false;
    try {
      const image = files.find(file => file?.type.startsWith("image/"));
      if (image) {
        const globals = globalThis as typeof globalThis & Record<string, any>;
        const loadScript = (src: string, globalName: string): Promise<any> => new Promise((resolve, reject) => {
          if (globals[globalName]) { resolve(globals[globalName]); return; }
          const script = document.createElement("script"); script.src = src; script.onload = () => resolve(globals[globalName]); script.onerror = reject; document.head.appendChild(script);
        });
        const tesseract = await loadScript(PUBLIC_RESERVATION_OCR_POLICY_V1.tesseractLibraryUrl, "Tesseract");
        const scan = await tesseract.recognize(image, PUBLIC_RESERVATION_OCR_POLICY_V1.language, { logger: () => {} });
        recognizedText = String(scan?.data?.text || "");
      }
    } catch { ocrUnavailable = true; }
    const result = evaluateAtlasPublicReservationReviewV1({ fullName, cpf, recognizedText, ocrUnavailable });
    this.dataset.reviewResult = result;
    review.innerHTML = `<span>${atlasPublicReservationPresentation.review.resultEyebrow}</span><b>${result === reviewCodes.compatible ? atlasPublicReservationPresentation.review.compatibleTitle : atlasPublicReservationPresentation.review.manualTitle}</b><p>${result === reviewCodes.compatible ? atlasPublicReservationPresentation.review.compatibleDescription : atlasPublicReservationPresentation.review.manualDescription}</p>`;
    if (result === reviewCodes.compatible) await this.generatePix();
    else { const pix = this.querySelector<HTMLElement>("[data-reservation-pix]"), proof = this.querySelector<HTMLElement>(".payment-proof"); if (pix) pix.hidden = true; if (proof) proof.hidden = true; }
    const submit = form.querySelector<HTMLButtonElement>(".reservation-submit"); if (submit) submit.disabled = false;
    status.textContent = atlasPublicReservationPresentation.status.documentsPrepared;
  }

  private async generatePix(): Promise<void> {
    this.pixRequestId = globalThis.crypto?.randomUUID?.() || `reservation-pix-${Date.now()}-${Math.random().toString(36).slice(2, 9)}`;
    this.dispatchEvent(new CustomEvent("atlas:public-reservation-pix-request", {
      bubbles: true,
      detail: { element: this, requestId: this.pixRequestId },
    }));
  }

  private async presentPixPayment(payment: NonNullable<AtlasPublicReservationPixResultDetailV1["payment"]>): Promise<void> {
    const status = this.querySelector<HTMLElement>(".reservation-status"), pix = this.querySelector<HTMLElement>("[data-reservation-pix]");
    if (!status || !pix) return;
    const { amount, payload, transactionId } = payment;
    this.dataset.pixPayload = payload; this.dataset.txid = transactionId; pix.hidden = false;
    const value = this.querySelector<HTMLElement>("[data-pix-value]"), code = this.querySelector<HTMLTextAreaElement>("[data-pix-code]"), proof = this.querySelector<HTMLElement>(".payment-proof");
    if (value) value.textContent = amount.toLocaleString("pt-BR", { style: "currency", currency: "BRL" });
    if (code) code.value = payload; if (proof) proof.hidden = false;
    try {
      const globals = globalThis as typeof globalThis & Record<string, any>;
      const qrCode = globals.QRCode || await new Promise<any>((resolve, reject) => { const script = document.createElement("script"); script.src = atlasPublicReservationPresentation.pix.qrCodeLibraryUrl; script.onload = () => resolve(globals.QRCode); script.onerror = reject; document.head.appendChild(script); });
      await qrCode.toCanvas(this.querySelector("[data-pix-qr]"), payload, { width: atlasPublicReservationPresentation.pix.qrWidth, margin: atlasPublicReservationPresentation.pix.qrMargin });
    } catch { status.textContent = atlasPublicReservationPresentation.status.pixCopyFallback; }
  }

  private async submit(event: Event): Promise<void> {
    event.preventDefault();
    const form = event.currentTarget as HTMLFormElement, status = this.querySelector<HTMLElement>(".reservation-status"), consent = form.elements.namedItem("consent") as HTMLInputElement | null;
    if (!consent?.checked || !this.dataset.reviewResult) { if (status) status.textContent = atlasPublicReservationPresentation.status.consentRequired; return; }
    const submit = form.querySelector<HTMLButtonElement>(".reservation-submit"); if (!status || !submit) return;
    submit.disabled = true; status.textContent = atlasPublicReservationPresentation.status.submitting;
    const value = (name: string) => (form.elements.namedItem(name) as HTMLInputElement | null)?.value || "";
    const file = (name: string) => (form.elements.namedItem(name) as HTMLInputElement | null)?.files?.[0] || null;
    this.requestId = globalThis.crypto?.randomUUID?.() || `reservation-${Date.now()}-${Math.random().toString(36).slice(2, 9)}`;
    const draft = buildAtlasPublicReservationSubmissionDraftV1({
      values: { fullName: value("fullName"), cpf: value("cpf"), birthDate: value("birthDate"), lot: value("lot") },
      parentValues: this.parentValues(),
      reviewResult: this.dataset.reviewResult || "",
      pixTxid: this.dataset.txid,
      pixPayload: this.dataset.pixPayload,
      files: { identityFront: file("identityFront"), identityBack: file("identityBack"), addressProof: file("addressProof"), paymentProof: file("paymentProof") },
    });
    this.dispatchEvent(new CustomEvent<AtlasPublicReservationSubmitDetailV1>("atlas:public-reservation-submit", { bubbles: true, detail: { element: this, requestId: this.requestId, ...draft } }));
  }
}
