/** Loteamento directory/profile element. API orchestration remains in program.ts. */
export class AtlasLotDevelopment extends AtlasHTMLElementBase {
  private snapshot: LotDevelopmentState;
  private readonly state: AtomicState<LotDevelopmentState>;
  constructor(){super();const initial:LotDevelopmentState={profiles:null,cashEntries:[],query:"",filter:"all",selectedId:"",formOpen:false,loading:true,saving:false,error:"",feedback:""};function* state(value:LotDevelopmentState):Generator<LotDevelopmentState,never,StateSetter<LotDevelopmentState>>{while(true)value=(yield value)(value);}const iterator=state(initial);iterator.next();this.snapshot=initial;this.state={next:setter=>{this.snapshot=iterator.next(setter).value;this.render();return this.snapshot;}};}
  private esc(value:unknown):string{return String(value??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]||c));}
  setData(profiles:LotDevelopmentProfile[],cashEntries:CashFlowRecord[],selectedId?:string):void{this.state.next(s=>({...s,profiles,cashEntries,selectedId:selectedId&&profiles.some(p=>p.id===selectedId)?selectedId:profiles.some(p=>p.id===s.selectedId)?s.selectedId:"",loading:false,error:""}));}
  profilesSnapshot():LotDevelopmentProfile[]{return (this.snapshot.profiles||[]).map(profile=>({...profile}));}
  setError(error:string):void{this.state.next(s=>({...s,loading:false,saving:false,error}));}
  setSaving(saving:boolean):void{this.state.next(s=>({...s,saving,error:""}));}
  setFeedback(feedback:string):void{this.state.next(s=>({...s,saving:false,feedback}));}
  private render():void{
    const s=this.snapshot,e=(value:unknown)=>this.esc(value),pageProjection=projectAtlasLotDevelopmentPageV1({profiles:s.profiles,cashEntries:s.cashEntries,query:s.query,filter:s.filter,selectedId:s.selectedId,formOpen:s.formOpen}),{visible,selectedProfile:selected,creatingProfile:creating,selectedCashEntries,lotCount,commonAreaCount,updatedProfileCount,totalCount,visibleCount}=pageProjection;
    const cards=visible.map(({profile:p,selected,typeLabel,statusLabel,descriptionLabel,details})=>`<article class="atlas-panel atlas-card"><button type="button" ${p.kind==="lot"?`data-lot-detail-open="${e(p.lotLabel)}" aria-label="Abrir ficha do lote ${e(p.lotLabel)}"`:`data-profile-select="${e(p.id)}" aria-pressed="${selected}"`}><header><span class="atlas-eyebrow">${typeLabel}</span><span>${e(statusLabel)}</span></header><h2>${e(p.title)}</h2><p>${e(descriptionLabel)}</p><dl>${details.map(({label,value})=>`<div><dt>${e(label)}</dt><dd>${e(value)}</dd></div>`).join("")}</dl><footer>${p.kind==="lot"?"Abrir ficha do lote →":"Ver perfil →"}</footer></button>${p.kind==="lot"?`<button type="button" class="atlas-profile-edit" data-profile-select="${e(p.id)}">Editar perfil</button>`:""}</article>`).join("");
    const profile=selected,form=pageProjection.formVisible?`<section class="atlas-panel"><header><div><span class="atlas-eyebrow">${creating?"NOVO CADASTRO":profile?.kind==="lot"?"LOTE · PERFIL":"ÁREA COMUM · PERFIL"}</span><h2>${creating?"Adicionar área comum":e(profile?.title)}</h2><p class="atlas-muted">${profile?.kind==="lot"?"Quadra, área, preço e situação vêm das fontes comerciais oficiais.":"Dados editáveis são salvos no banco operacional."}</p></div>${profile?.kind==="lot"?`<button type="button" data-lot-detail-open="${e(profile.lotLabel)}">Abrir ficha do lote</button>`:""}<button type="button" data-close-profile>Fechar</button></header><form class="atlas-form" data-profile-form><div class="atlas-form-grid"><label class="wide">Nome<input name="title" required maxlength="120" value="${e(profile?.title||"")}" placeholder="Nome da área comum"></label>${profile?.kind==="lot"||creating?`<label>${profile?.kind==="lot"?"Quadra":"Localização / setor"}<input name="quadra" ${profile?.kind==="lot"?"readonly":""} maxlength="120" value="${e(profile?.quadra||"")}"></label><label>Área (m²)<input name="area" type="number" min="0" step="0.01" ${profile?.kind==="lot"?"readonly":""} value="${profile?.area||""}"></label>${creating?`<label>Orçamento de referência (R$)<input name="value" type="number" min="0" step="0.01" value=""></label><label>Situação<input name="status" maxlength="80" value="Em planejamento"></label>`:""}`:""}<label class="wide">Descrição<textarea name="description" maxlength="2000" rows="5" placeholder="Descrição factual, uso e contexto">${e(profile?.description||"")}</textarea></label></div>${profile?.kind==="lot"?`<section class="atlas-panel"><span class="atlas-eyebrow">CAIXA · ${e(profile.lotLabel)}</span><h2>Entradas de caixa</h2><ul class="atlas-cash-list">${selectedCashEntries.map(row=>`<li><span><b>${e(row.categoryLabel)}</b><small> ${e(row.date)} · ${e(row.description||"")}</small></span><strong>${e(row.amountLabel)}</strong></li>`).join("")||`<li class="atlas-muted">Nenhuma entrada persistida vinculada a este lote.</li>`}</ul><button type="button" data-cash-entry="${e(profile.lotLabel)}">Registrar entrada em Repasses</button></section>`:""}<footer class="atlas-actions">${profile&&(profile.kind==="common-area"||profile.customized)?`<button type="button" data-profile-delete="${e(profile.id)}" ${s.saving?"disabled":""}>${profile.kind==="lot"?"Restaurar descrição original":"Excluir área comum"}</button>`:""}<button type="submit" class="atlas-primary" ${s.saving?"disabled":""}>${s.saving?"Salvando…":"Salvar perfil"}</button></footer></form>${s.feedback?`<p role="status">${e(s.feedback)}</p>`:""}</section>`:"";
    this.innerHTML=`${lotDevelopmentStyles}<main class="atlas-lot-development" data-lot-development-page data-lot-development-profile><header><div><span class="atlas-eyebrow">EMPREENDIMENTO · PERFIS</span><h1>Lotes</h1><p class="atlas-muted">Quadro oficial de lotes e áreas comuns cadastradas no sistema.</p></div><button type="button" class="atlas-primary" data-profile-new>Adicionar área comum</button></header><section class="atlas-kpis"><article class="atlas-kpi"><small>LOTES NO QUADRO OFICIAL</small><strong>${lotCount}</strong><span>Valores e áreas sem edição local</span></article><article class="atlas-kpi"><small>ÁREAS COMUNS CADASTRADAS</small><strong>${commonAreaCount}</strong><span>Registros persistidos</span></article><article class="atlas-kpi"><small>PERFIS ALTERADOS</small><strong>${updatedProfileCount}</strong><span>Com atualização registrada</span></article></section><section class="atlas-panel atlas-toolbar"><label class="atlas-search">Buscar perfil<input type="search" data-profile-query value="${e(s.query)}" placeholder="Lote, quadra, área comum…"></label><nav class="atlas-filters" aria-label="Tipo de perfil">${(["all","lot","common-area"] as const).map((key,i)=>`<button type="button" data-profile-filter="${key}" aria-pressed="${s.filter===key}">${["Todos","Lotes","Áreas comuns"][i]}</button>`).join("")}</nav><span class="atlas-muted">${visibleCount} de ${totalCount}</span></section>${s.loading?`<p class="atlas-empty">Consultando os perfis persistidos e o quadro oficial de lotes…</p>`:s.error?`<p role="alert">${e(s.error)}</p>`:`<section class="atlas-cards">${cards||`<p class="atlas-empty">Nenhum perfil persistido corresponde à busca.</p>`}</section>`}${form}</main>`;
  }
  connectedCallback():void{this.render();this.addEventListener("input",event=>{const target=event.target;if(target instanceof HTMLInputElement&&target.matches("[data-profile-query]")){const cursor=target.selectionStart;this.state.next(s=>({...s,query:target.value}));const next=this.querySelector<HTMLInputElement>("[data-profile-query]");next?.focus();if(cursor!==null)next?.setSelectionRange(cursor,cursor);}});this.addEventListener("click",event=>{const target=event.target;if(!(target instanceof Element))return;const button=target.closest<HTMLButtonElement>("button");if(!button)return;if(button.dataset.profileFilter){this.state.next(s=>({...s,filter:button.dataset.profileFilter as LotDevelopmentState["filter"]}));return;}if(button.dataset.lotDetailOpen){this.dispatchEvent(new CustomEvent("atlas:lot-detail-open",{bubbles:true,detail:{element:this,lotKey:button.dataset.lotDetailOpen}}));return;}if(button.dataset.profileSelect){this.dispatchEvent(new CustomEvent("atlas:lot-profile-open",{bubbles:true,detail:{element:this,id:button.dataset.profileSelect}}));return;}if(button.hasAttribute("data-profile-new")){this.state.next(s=>({...s,selectedId:"__new__",formOpen:true,feedback:"",error:""}));return;}if(button.hasAttribute("data-close-profile")){this.dispatchEvent(new CustomEvent("atlas:lot-profile-close",{bubbles:true,detail:{element:this}}));return;}if(button.dataset.profileDelete){if(!confirm(button.dataset.profileDelete.startsWith("lot:")?"Restaurar a descrição oficial deste lote?":"Excluir esta área comum persistida?"))return;this.dispatchEvent(new CustomEvent("atlas:lot-profile-delete",{bubbles:true,detail:{element:this,id:button.dataset.profileDelete}}));return;}if(button.dataset.cashEntry){this.dispatchEvent(new CustomEvent("atlas:lot-cash-entry",{bubbles:true,detail:{element:this,lotKey:button.dataset.cashEntry}}));}});this.addEventListener("submit",event=>{const form=event.target;if(!(form instanceof HTMLFormElement)||!form.matches("[data-profile-form]"))return;event.preventDefault();const data=new FormData(form),profile=this.snapshot.profiles?.find(item=>item.id===this.snapshot.selectedId)||null,payload=buildAtlasLotDevelopmentProfileSaveDraftV1({values:Object.fromEntries(data.entries()),profile});this.setSaving(true);this.dispatchEvent(new CustomEvent("atlas:lot-profile-save",{bubbles:true,detail:{element:this,id:profile?.id||"",payload}}));});this.dispatchEvent(new CustomEvent("atlas:lot-development-connected",{bubbles:true,detail:{element:this,profileRoute:this.hasAttribute("data-profile-route"),selectedId:this.getAttribute("data-selected-profile")||""}}));}
}
if(!customElements.get("atlas-lot-development"))customElements.define("atlas-lot-development",AtlasLotDevelopment);

