      const row=matrix.findIndex(cells=>cells.some(cell=>cell.dataset.documentCell===selection.id&&cell.dataset.documentField===selection.field));if(row<0)return;
      const column=matrix[row].findIndex(cell=>cell.dataset.documentCell===selection.id&&cell.dataset.documentField===selection.field),nextRow=Math.max(0,Math.min(matrix.length-1,row+(event.key==="ArrowDown"?1:event.key==="ArrowUp"?-1:0))),nextColumn=Math.max(0,Math.min((matrix[nextRow]?.length||1)-1,column+(event.key==="ArrowRight"?1:event.key==="ArrowLeft"?-1:0))),next=matrix[nextRow]?.[nextColumn];
