        const draft=buildAtlasReportBuilderDraftV1({values:Object.fromEntries(data.entries()),sources:data.getAll("source").map(String),indicators:data.getAll("indicator").map(String)});
        this.emit("atlas:report-builder-save",{ ...draft });
