  stageRecordServiceRowsV1: AtlasStageRecordServicesV1["stageRecordServiceRowsV1"];
  stageMaterialReportDialogV1: ReturnType<typeof createAtlasStageMaterialReportViewV1>["dialogMarkup"];
  stageMaterialReportBindV1: ReturnType<typeof createAtlasStageMaterialReportViewV1>["bind"];
  stageRecordCenterItemModalMarkupV1(state: AtlasStageRecordUiStateV1, materialRows: AtlasStageRecordRowV1[], serviceRows: AtlasStageRecordRowV1[], stages: AtlasStageRecordStageV1[]): string;
