  executionModel: { stages: Array<Record<string, any>> };
  demoData: { activities: Array<Record<string, any>> };
  commissionDeals: Array<Record<string, any>>;
  brokerReasonsV9(state: Record<string, any>): Array<Record<string, any>>;
  controlCenterMaterialRowsV1(state: Record<string, any>): Array<Record<string, any>>;
  controlCenterFinanceRowsV1(state: Record<string, any>): Array<Record<string, any>>;
  controlCenterMoneyV1(row: Record<string, any>): string;
