  controlCenterPublishV1(...args: any[]): unknown;
  controlCenterRealtimeLabelV1(state: Record<string, any>): string;
  controlStageProfileV1(stage: Record<string, any>, state: Record<string, any>): Record<string, any>;
  controlStageContextMarkupV1(state: Record<string, any>, stages: Array<Record<string, any>>): string;
  controlStageUnifiedFormMarkupV1(state: Record<string, any>, stages: Array<Record<string, any>>): string;
