/** Cartão editável de uma entrada operacional; eventos e persistência ficam no adapter da rota. */
export function renderAtlasWorkerStageInputSessionV1(input: AtlasWorkerWorkbenchInputSessionViewV1): string {
  const escape = atlasWorkerRequirementsEscapeV1;
  const id = escape(input.id);
  const composition = input.composition;
  const properties = renderAtlasWorkerInputPropertiesV1({ id: input.id, properties: composition?.properties || input.properties || [] });
  const optionsMarkup = composition
    ? `<div class="stage-input-options">${renderAtlasWorkerInputProgrammingOptionsV1({ id: input.id, options: composition.programmingOptions })}</div><div class="stage-input-settings">${renderAtlasWorkerInputProgrammingSettingsV1({ id: input.id, ...composition.programmingSettings })}</div>`
    : '<div class="stage-input-options"></div>';
  const productionMarkup = composition
    ? `<section class="stage-input-production" data-stage-input-production>${renderAtlasWorkerInputProductionEditorV1({ id: input.id, sessionUnit: input.unit || 'registro', manual: Boolean(composition.inference?.manual), badge: composition.inference?.manual ? 'EDIÇÃO LOCAL' : composition.inference?.production ? 'ESTRUTURADO' : 'PRÉVIA', spec: composition.productionDraft.spec, conditions: composition.productionDraft.conditions })}</section>`
    : '';
  const inferenceMarkup = composition ? renderAtlasWorkerInputInferenceV1({ inference: composition.inference }) : '';
  return `<form class="stage-input-card ${input.custom ? 'is-custom' : ''}" draggable="true" data-stage-input-card="${id}"><header><button type="button" class="input-drag-handle stage-input-editor-only" data-stage-input-drag aria-label="Reordenar entrada ${input.index + 1}">↕</button><div><span class="eyebrow">ENTRADA ${String(input.index + 1).padStart(2, '0')} · ${input.custom ? 'NOVA ATIVIDADE' : 'ATIVIDADE DO CATÁLOGO'}</span><b>${escape(input.calendarDate === input.currentCalendarDate ? 'Data compartilhada' : 'Data sincronizada')}</b></div>${input.custom ? '<button type="button" class="input-remove stage-input-editor-only" data-stage-input-remove aria-label="Remover atividade adicionada">×</button>' : ''}</header><div class="stage-input-view"><h3>${escape(input.title)}</h3><p>${escape(input.text || 'Sem descrição registrada. Abra Editar compreensão para adicionar a lógica operacional.')}</p><div class="stage-input-view-meta"><span>${escape(input.unit || 'Unidade a definir')}</span><span>${escape(input.release || 'Sem dependência informada')}</span><span data-stage-input-view-status>${input.hasInference ? 'Compreensão disponível' : 'Aguardando compreensão'}</span></div><div data-stage-input-inference="${id}">${inferenceMarkup}</div></div><div class="stage-input-editor-only stage-input-editor"><div class="stage-input-fields stage-input-fields-split"><div class="stage-input-description"><span class="eyebrow">DESCRIÇÃO E CONTEXTO</span><label>Atividade<input data-stage-input-title="${id}" value="${escape(input.title)}" placeholder="Nome da atividade"></label><label>Descrição, fato, requisito ou dependência<textarea data-stage-input-text="${id}" rows="3" placeholder="Descreva a lógica que o endpoint deve compreender">${escape(input.text)}</textarea></label></div><section class="stage-input-properties">${properties}</section></div><section class="stage-input-execution"><header><div><span class="eyebrow">CONTROLES DA ENTRADA</span><strong>Propagação e geração</strong><p>Escolha quais saídas esta compreensão pode atualizar no ciclo operacional.</p></div><div class="stage-input-execution-actions"><button type="button" class="button" data-stage-input-run="${id}">Compreender agora</button><button type="button" class="button button-primary" data-stage-input-cycle="${id}">Executar diretrizes</button></div></header>${optionsMarkup}</section>${productionMarkup}<footer><time>Data do cronograma · ${escape(input.scheduleDateLabel)}</time><span data-stage-input-inference="${id}"></span></footer></div></form>`;
}

