/** Página operacional da etapa; o adapter injeta a projeção autenticada e conecta ações/serviços. */
export function renderAtlasWorkerStageWorkspaceV1(input: {
  projection: AtlasWorkerStageWorkspaceProjectionViewV1;
  stages: AtlasWorkerWorkbenchStageViewV1[];
  attachments: AtlasWorkerWorkbenchAttachmentViewV1[];
  route: (path: string, query?: string) => string;
}): string {
  const escape = atlasWorkerRequirementsEscapeV1;
  const { definition, context, calendarDate } = input.projection;
  const automation = context.automation;
  const production = automation.production && typeof automation.production === 'object' ? automation.production : {};
  const personnel = automation.personnel && typeof automation.personnel === 'object' ? automation.personnel : {};
  const materialPlan = Array.isArray(automation.materialPlan) ? automation.materialPlan : [];
  const overlap = automation.overlapPlan && typeof automation.overlapPlan === 'object' ? automation.overlapPlan : {};
  const percent = (value: unknown): string => `${Number(value) || 0}%`;
  const number = (value: unknown): string => new Intl.NumberFormat('pt-BR', { maximumFractionDigits: 2 }).format(Number(value) || 0);
  const money = (value: unknown): string => new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL', maximumFractionDigits: 0 }).format((Number(value) || 0) / 100);
  const physical = (value: unknown, unit: unknown): string => `${number(value)}${unit ? ` ${String(unit)}` : ''}`;
  const updated = input.projection.generatedAt
    ? new Date(input.projection.generatedAt).toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' })
    : 'Agora';
  const plannedStart = String(automation.plannedStart || calendarDate);
  const plannedFinish = String(automation.plannedFinish || plannedStart);
  const flowCards = input.projection.flowCards.map(card => renderAtlasWorkerFlowCardV1({
    item: card.item,
    index: card.index,
    total: card.total,
    stageKey: definition.key,
    position: card.position,
    progress: card.progress,
    blocked: card.blocked,
    plannedStart,
    plannedFinish,
    route: input.route,
  })).join('');
  const navigation = renderAtlasWorkerStageNavigationV1({ stages: input.stages, currentKey: definition.key, route: input.route });
  const operations = renderAtlasWorkerOperationalStageV1(definition);
  const agenda = renderAtlasWorkerStageAgendaV1({
    definition,
    activities: input.projection.flowCards.map(card => card.item),
    attachments: input.attachments,
    plannedStart,
    plannedFinish,
    route: input.route,
  });
  const basis = Array.isArray(production.basis) ? production.basis[0] : 'Base de cálculo registrada no worker.';
  const releases = definition.activities.map(item => `<li>${escape(item.release)}</li>`).join('');
  const alerts = Array.isArray(automation.materialAlerts) ? automation.materialAlerts : [];
  const dateLabels = input.projection.dates.map(date => `<time>${escape(atlasWorkerWorkbenchDateLabelV1(date))}</time>`).join('');

  return `<main class="workbench-main"><a class="detail-back" href="${escape(input.route('/admin/workers'))}">← Todas as etapas</a>${navigation}<section class="workbench-hero"><div><span class="eyebrow">ETAPA · CRONOGRAMA GERADO PELO WORKER</span><h1>${escape(definition.title)}</h1><p>${escape(context.live.executionProfile?.typicalDescription || 'Execução organizada por dependências, cobertura de caixa, materiais e fatos confirmados em campo.')}</p></div><div class="hero-live"><i></i><b>LOOP VIVO</b><span>Atualizado ${escape(updated)}</span></div></section>${agenda}${operations}<section class="workbench-metrics"><article><small>ANDAMENTO</small><strong>${Math.round(context.progress)}%</strong><span>${escape(context.live.status || 'planejada')}</span></article><article><small>CAIXA DA ETAPA</small><strong>${escape(money(context.summary.budgetCents))}</strong><span>${escape(percent(automation.cashCoverage))} de cobertura</span></article><article><small>VOLUME BASE DWG</small><strong>${escape(physical(production.totalQuantity, production.unit))}</strong><span>ritmo ${escape(physical(production.adjustedRate, production.rateUnit))}</span></article><article><small>EQUIPE REGISTRADA</small><strong>${escape(personnel.assignedHeadcount || 0)}/${escape(personnel.requiredHeadcount || 0)}</strong><span>${escape(personnel.status === 'registration_pending' ? 'cadastro pendente' : 'equipe parcial ou suficiente')}</span></article><article><small>JANELA INFERIDA</small><strong>${escape(atlasWorkerWorkbenchDateLabelV1(plannedStart))}</strong><span>até ${escape(atlasWorkerWorkbenchDateLabelV1(plannedFinish))}</span></article></section><section class="planning-brief"><header><div><span class="eyebrow">PROJEÇÃO FÍSICA · DWG</span><h2>Base de produção desta frente</h2><p>Os números servem para agenda e priorização. Áreas/contagens são cartográficas; comprimentos e coeficientes devem ser validados no projeto executivo.</p></div><span class="planning-source">${escape(production.source || 'calibration')}</span></header><div class="planning-brief-grid"><article><small>NECESSÁRIO</small><strong>${escape(physical(production.totalQuantity, production.unit))}</strong><span>${escape(basis)}</span></article><article><small>RITMO AJUSTADO</small><strong>${escape(physical(production.adjustedRate, production.rateUnit))}</strong><span>caixa, materiais e equipe aplicados</span></article><article><small>MATERIAIS</small><strong>${number(materialPlan.length)} itens</strong><span>${escape(materialPlan.filter(item => Number(item.shortfallQuantity) > 0).length)} com falta quantitativa</span></article><article><small>RELAÇÃO</small><strong>${escape(overlap.mode || 'sequencial')}</strong><span>${escape(overlap.rule || 'Sem sobreposição operacional registrada.')}</span></article></div></section><section class="stage-inputs-panel"><header><div><span class="eyebrow">ENTRADAS DA ETAPA · IA</span><h2>Atividades, fatos e requisitos</h2><p>Escreva o fato ou a dependência de cada atividade. A compreensão é consultada imediatamente e a relação aprovada pela inferência é refletida no fluxograma.</p></div><div class="stage-input-actions"><label>Data compartilhada<input type="date" data-stage-calendar-date value="${escape(calendarDate)}"></label><button class="button button-primary" type="button" data-stage-input-add>Adicionar atividade</button></div></header><div class="stage-inputs-list" data-stage-inputs></div><footer class="stage-inputs-footer"><span>Arraste pelo controle ↕ para reorganizar as sessões.</span><span>A data acima é a mesma usada no cronograma abaixo.</span></footer></section><section class="timeline-panel"><header><div><span class="eyebrow">SUPERFÍCIE DE CALENDÁRIO · ${escape(atlasWorkerWorkbenchDateLabelV1(calendarDate))}</span><h2>Calendário de atividades</h2><p>Arraste os cards para encaixá-los nas linhas de data. Redimensione horizontalmente a janela de execução; a avaliação da IA aparece na borda inferior.</p></div><div class="timeline-legend"><span><i class="blue"></i> atividade</span><span><i class="amber"></i> bloqueio</span><span><i class="green"></i> concluído</span></div></header><div class="flow-scroll"><div class="flow-surface" data-flow-surface style="width:${input.projection.canvasWidth}px"><div class="calendar-axis">${dateLabels}</div><svg data-flow-lines width="${input.projection.canvasWidth}" height="490" aria-hidden="true"></svg><div data-flow-labels></div><div data-flow-cards>${flowCards}</div></div></div></section><section class="gate-grid"><article><span class="eyebrow">PORTÕES DE LIBERAÇÃO</span><ul>${releases}</ul></article><article><span class="eyebrow">LEITURA DO WORKER</span><ul><li>${escape(automation.nextStep || 'Aguardando próximo ciclo.')}</li><li>Produção: ${escape(production.adjustedRate || '—')} ${escape(production.rateUnit || production.unit || '')}</li><li>${alerts.length ? escape(alerts.join(' · ')) : 'Sem alerta material calculado nesta leitura.'}</li></ul></article></section></main>`;
}

export function renderAtlasWorkerFlowCardV1(input: {
  item: AtlasWorkerWorkbenchActivityViewV1;
  index: number;
  total: number;
  stageKey: string;
  position: { x: number; y: number; width?: number };
  progress: number;
  blocked: boolean;
  plannedStart?: string;
  plannedFinish?: string;
  route: (path: string, query?: string) => string;
}): string {
  const escape = atlasWorkerRequirementsEscapeV1;
  const today = new Date().toISOString().slice(0, 10);
  const start = new Date(`${input.plannedStart || today}T12:00:00`);
  const end = new Date(`${input.plannedFinish || input.plannedStart || today}T12:00:00`);
  const span = Math.max(input.total, (end.getTime() - start.getTime()) / 86400000);
  const segment = span / Math.max(1, input.total);
  const activityStart = new Date(start), activityEnd = new Date(start);
  activityStart.setDate(start.getDate() + Math.floor(segment * input.index));
  activityEnd.setDate(start.getDate() + Math.max(Math.floor(segment * (input.index + 1)), Math.floor(segment * input.index) + 1));
  const dateStart = activityStart.toISOString().slice(0, 10), dateEnd = activityEnd.toISOString().slice(0, 10);
  const width = Math.max(180, Math.min(520, Number(input.position.width) || 220));
  const progress = Math.max(0, Math.min(100, Number(input.progress) || 0));
  const status = progress >= 100 ? 'concluída' : input.blocked ? 'bloqueada' : progress > 0 ? 'em execução' : 'planejada';
  const fmt = (value: string): string => atlasWorkerWorkbenchDateLabelV1(value);
  const query = `stage=${encodeURIComponent(input.stageKey)}&activity=${encodeURIComponent(input.item.id)}`;
  return `<article class="flow-card status-${status.replace(' ', '-')} ${input.item.custom ? 'is-input-derived' : ''}" data-flow-card="${escape(input.item.id)}" data-calendar-start="${dateStart}" style="width:${width}px;transform:translate(${input.position.x}px,${input.position.y}px)"><header><span>${String(input.index + 1).padStart(2, '0')} · ${escape(input.item.unit)}</span><i>${Math.round(progress)}%</i></header><h3>${escape(input.item.title)}</h3><p>${escape(input.item.release)}</p><div class="flow-card-progress"><i style="width:${progress}%"></i></div><footer><time data-flow-window>${escape(fmt(dateStart))} → ${escape(fmt(dateEnd))}</time><a href="${escape(input.route('/admin/workers/activity', query))}">Abrir atividade →</a></footer></article>`;
}

/** Render and replace only the dynamic flow-card list owned by the stage component. */
export function renderAtlasWorkerFlowCardListV1(input: {
  target: HTMLElement;
  cards: readonly Parameters<typeof renderAtlasWorkerFlowCardV1>[0][];
}): void {
  input.target.innerHTML = input.cards.map(card => renderAtlasWorkerFlowCardV1(card)).join('');
}

export function renderAtlasWorkerFlowConnectionsV1(input: {
  svg: SVGSVGElement;
  labels: HTMLElement;
  links: readonly Record<string, unknown>[];
  layout: Record<string, unknown>;
  updateLabel(index: number, value: string): void;
}): void {
  const escape = atlasWorkerRequirementsEscapeV1;
  const connections = projectWorkerWorkbenchFlowConnectionsV1({ links: input.links, layout: input.layout });
  input.svg.innerHTML = connections.map(item => `<path d="${item.path}"/><circle cx="${item.targetX}" cy="${item.targetY}" r="4"/>`).join('');
  input.labels.innerHTML = connections.map(item => `<label class="flow-link-label" style="left:${item.labelX}px;top:${item.labelY}px"><span>REQUISITO</span><input data-link-label="${item.index}" value="${escape(item.label)}" aria-label="Rótulo da dependência"></label>`).join('');
  input.labels.querySelectorAll<HTMLInputElement>('[data-link-label]').forEach(control => control.addEventListener('change', () => {
    input.updateLabel(Number(control.dataset.linkLabel), control.value.trim() || 'depende de');
  }));
}

const atlasWorkerFlowResizeObserversV1 = new WeakMap<HTMLElement, ResizeObserver>();

/** Own pointer drag, calendar snapping and resize observation for worker flow cards. */
export function installAtlasWorkerStageFlowCanvasEventsV1(input: {
  surface: HTMLElement;
  layout: Record<string, unknown>;
  setPosition(id: string, position: { x: number; y: number }): void;
  setWidth(id: string, width: number): void;
  renderConnections(): void;
  save(): void;
}): boolean {
  const surface = input.surface;
  const cards = [...surface.querySelectorAll<HTMLElement>('[data-flow-card]')];
  if (!cards.length) return false;
  atlasWorkerFlowResizeObserversV1.get(surface)?.disconnect();
  cards.forEach(card => {
    card.addEventListener('pointerdown', event => {
      if (event.target instanceof Element && event.target.closest('a,button,input')) return;
      if (event.offsetX >= card.clientWidth - 14) return;
      const id = String(card.dataset.flowCard || ''), origin = input.layout[id] as { x?: unknown; y?: unknown } | undefined;
      if (!id || !origin) return;
      event.preventDefault();
      card.setPointerCapture(event.pointerId);
      card.classList.add('is-dragging');
      const startX = event.clientX, startY = event.clientY, startLeft = Number(origin.x) || 0, startTop = Number(origin.y) || 0;
      const move = (moveEvent: PointerEvent): void => {
        const next = projectWorkerWorkbenchFlowCardDragV1({
          origin: { x: startLeft, y: startTop },
          delta: { x: moveEvent.clientX - startX, y: moveEvent.clientY - startY },
          surface: { width: surface.scrollWidth, height: surface.scrollHeight },
        });
        input.setPosition(id, next);
        card.style.transform = `translate(${next.x}px,${next.y}px)`;
        input.renderConnections();
      };
      const finish = (): void => {
        const current = input.layout[id] as { x?: unknown; y?: unknown } | undefined;
        if (current) {
          const snapped = projectWorkerWorkbenchFlowCardSnapV1({ x: Number(current.x) || 0, y: Number(current.y) || 0 });
          input.setPosition(id, snapped);
          card.style.transform = `translate(${snapped.x}px,${snapped.y}px)`;
        }
        card.classList.remove('is-dragging');
        card.removeEventListener('pointermove', move);
        card.removeEventListener('pointerup', finish);
        card.removeEventListener('pointercancel', finish);
        input.renderConnections();
        input.save();
        let bar = document.querySelector<HTMLElement>('[data-calendar-evaluation]');
        if (!bar) {
          bar = document.createElement('aside');
          bar.dataset.calendarEvaluation = '';
          bar.className = 'calendar-evaluation';
          bar.innerHTML = '<span></span><button type="button" aria-label="Fechar avaliação">×</button>';
          document.body.append(bar);
          bar.querySelector('button')?.addEventListener('click', () => bar?.remove());
        }
        const message = bar.querySelector('span');
        if (message) message.textContent = 'IA avaliou o encaixe na linha de data e atualizou a janela de execução da atividade.';
      };
      card.addEventListener('pointermove', move);
      card.addEventListener('pointerup', finish);
      card.addEventListener('pointercancel', finish);
    });
  });
  if (typeof ResizeObserver !== 'undefined') {
    const observer = new ResizeObserver(entries => entries.forEach(({ target, contentRect }) => {
      const card = target as HTMLElement, id = String(card.dataset.flowCard || ''), start = String(card.dataset.calendarStart || '');
      const resized = projectWorkerWorkbenchFlowCardResizeV1({ width: contentRect.width, start });
      if (!id) return;
      input.setWidth(id, resized.width);
      const label = card.querySelector<HTMLElement>('[data-flow-window]');
      if (label) label.textContent = `${atlasWorkerWorkbenchDateLabelV1(start)} → ${atlasWorkerWorkbenchDateLabelV1(resized.finish)} · ${resized.days}d`;
      input.renderConnections();
      input.save();
    }));
    atlasWorkerFlowResizeObserversV1.set(surface, observer);
    cards.forEach(card => observer.observe(card));
  }
  return true;
}

type AtlasWorkerRequirementsCatalogSetterV1 = (state: AtlasWorkerRequirementsCatalogStateV1) => AtlasWorkerRequirementsCatalogStateV1;

function* atlasWorkerRequirementsCatalogStateV1(
  initial: AtlasWorkerRequirementsCatalogStateV1,
): Generator<AtlasWorkerRequirementsCatalogStateV1, never, AtlasWorkerRequirementsCatalogSetterV1> {
  let state = initial;
  while (true) state = (yield state)(state);
}

const atlasWorkerRequirementsEscapeV1 = (value: unknown): string => String(value ?? '').replace(/[&<>"']/g, character => ({
  '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;',
}[character] || character));

/** Imperative DOM owner for the worker's static stage requirements catalog. */
export class AtlasWorkerRequirementsCatalogV1 extends AtlasHTMLElementBase {
  private readonly state = atlasWorkerRequirementsCatalogStateV1({ expanded: false, query: '', phase: 'all' });
  private snapshot = this.state.next().value;
  private stages: readonly WorkerDevelopmentStageV1[] = [];
  private sources: readonly WorkerDevelopmentStageSourceV1[] = [];
  private version = '';

  initialize(input: {
    stages: readonly WorkerDevelopmentStageV1[];
    sources: readonly WorkerDevelopmentStageSourceV1[];
    version: string;
  }): boolean {
    if (this.dataset.tsCatalogMounted === 'true') return true;
    const phase = this.querySelector<HTMLSelectElement>('[data-requirements-phase]');
    const search = this.querySelector<HTMLInputElement>('[data-requirements-search]');
    const expand = this.querySelector<HTMLButtonElement>('[data-expand-requirements]');
    if (!phase || !search || !expand || !this.querySelector('[data-requirements-list]')) return false;

    this.stages = input.stages;
    this.sources = input.sources;
    this.version = input.version;
    [...new Set(this.stages.map(stage => stage.phase))].forEach(value => {
      const option = document.createElement('option');
      option.value = value;
      option.textContent = value;
      phase.append(option);
    });
    search.addEventListener('input', () => {
      this.state.next(previous => ({ ...previous, query: search.value }));
      this.render();
    });
    phase.addEventListener('change', () => {
      this.state.next(previous => ({ ...previous, phase: phase.value }));
      this.render();
    });
    expand.addEventListener('click', () => {
      this.state.next(previous => ({ ...previous, expanded: !previous.expanded }));
      this.render();
    });
    this.dataset.tsCatalogMounted = 'true';
    this.render();
    return true;
  }

  private render(): void {
    const list = this.querySelector<HTMLElement>('[data-requirements-list]');
    const count = this.querySelector<HTMLElement>('[data-requirements-count]');
    const summary = this.querySelector<HTMLElement>('[data-requirements-summary]');
    const sources = this.querySelector<HTMLElement>('[data-requirements-sources]');
    const expand = this.querySelector<HTMLButtonElement>('[data-expand-requirements]');
    if (!list || !count || !summary || !sources || !expand) return;

    const query = this.snapshot.query.trim().toLocaleLowerCase('pt-BR');
    const searchable = (stage: WorkerDevelopmentStageV1): string => [
      stage.title, stage.phase, stage.objective, ...stage.dependsOn, ...stage.entryGates,
      ...stage.activities, ...stage.requirements, ...stage.materials, ...stage.evidence, ...stage.workerRules,
    ].join(' ').toLocaleLowerCase('pt-BR');
    const stages = this.stages.filter(stage => (this.snapshot.phase === 'all' || stage.phase === this.snapshot.phase)
      && (!query || searchable(stage).includes(query)));
    const escape = atlasWorkerRequirementsEscapeV1;
    const renderColumn = (title: string, items: readonly string[], className = '') =>
      `<section class="requirement-column ${className}"><h4>${escape(title)} <span>${items.length}</span></h4><ul>${items.map(item => `<li>${escape(item)}</li>`).join('')}</ul></section>`;

    count.textContent = `${stages.length} de ${this.stages.length} etapas`;
    summary.innerHTML = `<span><b>${this.stages.length}</b> ETAPAS</span><span><b>${this.stages.reduce((sum, item) => sum + item.activities.length, 0)}</b> ATIVIDADES</span><span><b>${this.stages.reduce((sum, item) => sum + item.materials.length, 0)}</b> GRUPOS DE MATERIAL</span><span><b>${this.stages.reduce((sum, item) => sum + item.evidence.length, 0)}</b> EVIDÊNCIAS</span><span><b>v${escape(this.version)}</b> REVISÃO</span>`;
    list.innerHTML = stages.map(stage => `<details class="requirement-stage" data-catalog-stage="${escape(stage.id)}" ${this.snapshot.expanded || query ? 'open' : ''}><summary><span class="requirement-order">${String(this.stages.indexOf(stage) + 1).padStart(2, '0')}</span><span><small>${escape(stage.phase)}</small><strong>${escape(stage.title)}</strong><em>${escape(stage.objective)}</em></span><i>${stage.dependsOn.length ? `depende de ${stage.dependsOn.length}` : 'início'} · ${stage.activities.length} atividades</i></summary><div class="requirement-body"><div class="dependency-strip"><b>DEPENDÊNCIAS</b><span>${stage.dependsOn.length ? stage.dependsOn.map(id => escape(this.stages.find(item => item.id === id)?.title || id)).join(' → ') : 'Nenhuma etapa anterior; depende da decisão formal de viabilidade.'}</span></div><div class="requirement-grid">${renderColumn('Portões de entrada', stage.entryGates, 'is-gate')}${renderColumn('Atividades reais', stage.activities)}${renderColumn('Requisições', stage.requirements)}${renderColumn('Materiais e insumos', stage.materials)}${renderColumn('Evidências de aceite', stage.evidence, 'is-evidence')}${renderColumn('Diretrizes do worker', stage.workerRules, 'is-worker')}</div></div></details>`).join('') || '<div class="empty-state">Nenhuma etapa corresponde aos filtros.</div>';
    sources.innerHTML = [...this.sources.map(source => `<a href="${escape(source.url)}" target="_blank" rel="noreferrer">${escape(source.label)} ↗</a>`), '<a href="/docs/ai-construction-operational-playbook.md" target="_blank" rel="noreferrer">Documento operacional usado pela IA ↗</a>'].join('');
    expand.textContent = this.snapshot.expanded ? 'Recolher tudo' : 'Expandir tudo';
  }
}

if (!customElements.get('atlas-worker-requirements-catalog')) {
  customElements.define('atlas-worker-requirements-catalog', AtlasWorkerRequirementsCatalogV1);
}

function* atlasWorkerMonitorDashboardStateV1(
  initial: WorkerMonitorDashboardViewV1 | null,
): Generator<WorkerMonitorDashboardViewV1 | null, never, (value: WorkerMonitorDashboardViewV1 | null) => WorkerMonitorDashboardViewV1 | null> {
  let state = initial;
  while (true) state = (yield state)(state);
}

/** Presentation owner for the live worker monitor; API calls remain in the host program. */
export class AtlasWorkerMonitorDashboardV1 extends AtlasHTMLElementBase {
  private readonly state = atlasWorkerMonitorDashboardStateV1(null);
  private snapshot = this.state.next().value;

  initialize(): boolean {
    if (this.dataset.tsMonitorMounted === 'true') return true;
    const required = ['[data-worker-status]', '[data-cash]', '[data-stage-list]', '[data-agenda-list]', '[data-event-list]', '[data-physical-site]', '[data-physical-plan-list]', '[data-run-cycle]', '[data-run-suite]', '[data-run-development-cycle]', '[data-run-single]', '[data-test-result]', '[data-suite-summary]'];
    if (required.some(selector => !this.querySelector(selector))) return false;
    this.dataset.tsMonitorMounted = 'true';
    this.querySelector<HTMLButtonElement>('[data-run-cycle]')?.addEventListener('click', () => {
      this.dispatchEvent(new CustomEvent('atlas:worker-monitor-run-cycle-v1', {
        bubbles: true,
        detail: { element: this },
      }));
    });
    this.querySelector<HTMLButtonElement>('[data-run-suite]')?.addEventListener('click', () => this.requestTest('suite'));
    this.querySelector<HTMLButtonElement>('[data-run-development-cycle]')?.addEventListener('click', () => this.requestTest('development-cycle'));
    this.querySelectorAll<HTMLButtonElement>('[data-test-case]').forEach(button => {
      button.addEventListener('click', () => this.requestTest('single', button.dataset.testCase || ''));
    });
    this.querySelector<HTMLButtonElement>('[data-run-single]')?.addEventListener('click', () => this.requestTest('single'));
    return true;
  }

  private requestTest(scenario: WorkerAutomationTestResultViewV1['kind'] | 'single', caseId = ''): void {
    this.dispatchEvent(new CustomEvent('atlas:worker-monitor-test-v1', {
      bubbles: true,
      detail: { scenario, caseId },
    }));
  }

  setSnapshot(snapshot: WorkerMonitorDashboardViewV1): void {
    if (this.dataset.tsMonitorMounted !== 'true') return;
    this.state.next(() => snapshot);
    this.render();
  }

  setUnavailable(message: string): void {
    const connection = this.querySelector<HTMLElement>('[data-connection]');
    if (connection) connection.textContent = 'Worker indisponível';
    this.querySelector('.live-indicator')?.classList.remove('ready');
    this.setCycleStatus(`Não foi possível atualizar a monitoria: ${message}`);
  }

  setCycleStatus(message: string): void {
    const status = this.querySelector<HTMLElement>('[data-cycle-status]');
    if (status) status.textContent = message;
  }

  setCycleRunning(running: boolean): void {
    const button = this.querySelector<HTMLButtonElement>('[data-run-cycle]');
    if (button) button.disabled = running;
  }

  getFreeTestEvent(): string {
    return this.querySelector<HTMLSelectElement>('[data-test-event]')?.value || 'record.created';
  }

  setTestPending(pending: boolean): void {
    this.querySelectorAll<HTMLButtonElement>('[data-test-case],[data-run-suite],[data-run-single],[data-run-cycle],[data-run-development-cycle]')
      .forEach(button => { button.disabled = pending; });
    if (!pending) return;
    const result = this.querySelector<HTMLElement>('[data-test-result]');
    if (!result) return;
    result.className = 'test-result';
    const message = this.ownerDocument.createElement('span');
    message.textContent = 'Executando leitura, avaliação das diretrizes e propagação local…';
    result.replaceChildren(message);
  }

  setTestFailure(message: string): void {
    const result = this.querySelector<HTMLElement>('[data-test-result]');
    if (!result) return;
    result.className = 'test-result error';
    const detail = this.ownerDocument.createElement('span');
    detail.textContent = `Falha no teste: ${message}`;
    result.replaceChildren(detail);
  }

  setTestResult(resultView: WorkerAutomationTestResultViewV1): void {
    const result = this.querySelector<HTMLElement>('[data-test-result]');
    const summary = this.querySelector<HTMLElement>('[data-suite-summary]');
    if (!result) return;
    const escape = atlasWorkerRequirementsEscapeV1;
    result.className = 'test-result success';
    if (resultView.kind === 'suite' && resultView.suite) {
      const suite = resultView.suite;
      if (summary) summary.textContent = suite.cases.length
        ? `${suite.caseCount} casos avaliados · ${suite.triggerCount} gatilhos · saída externa desabilitada`
        : `${this.querySelectorAll('[data-test-case]').length} casos disponíveis · aguardando execução`;
      result.innerHTML = `<header><b>Suíte concluída · ${escape(suite.mode)}</b><span>${escape(suite.externalMessaging)} · ${escape(suite.caseCount)} casos</span></header><div class="suite-result-summary"><span>CASOS<b>${escape(suite.caseCount)}</b></span><span>GATILHOS<b>${escape(suite.triggerCount)}</b></span><span>NOTIFICAÇÕES<b>${escape(suite.notificationCount)}</b></span><span>PROPAGAÇÕES<b>${escape(suite.propagationCount)}</b></span></div><div class="case-details">Cobertura: ${escape(suite.categorySummary)}</div><ol>${suite.cases.map(item => `<li><div class="case-line"><span class="case-kind">${escape(item.category)}</span><code>${escape(item.event)}</code><span class="case-output">${escape(item.label)} → ${escape(item.actions)}</span></div><small class="case-details">geração: ${escape(item.generation)} · notificação pseudo: ${escape(item.notificationCount)} · propagação: ${escape(item.propagationCount)} · ${escape(item.storedStatus)}</small></li>`).join('')}</ol>`;
      return;
    }

    const cycle = resultView.cycle;
    if (!cycle) return;
    if (summary) summary.textContent = `Ciclo confirmado · ${cycle.agendaItems} atividades · ${cycle.materialItems} materiais · dry-run`;
    const checks = cycle.checks.map(item => `<li class="cycle-check ${escape(item.statusClass)}"><span>${escape(item.status)}</span><div><strong>${escape(item.label)}</strong><small>${escape(item.detail)}</small></div></li>`).join('');
    const schedule = cycle.schedule.map(item => `<li class="cycle-schedule-row"><time>${escape(item.date)}</time><div><strong>${escape(item.title)}</strong><small>${escape(item.stage)} · ${escape(item.owner)}</small></div><em>${escape(item.status)}</em></li>`).join('') || '<li class="empty-state">Nenhuma atividade entrou na agenda.</li>';
    const materials = cycle.materials.map(item => `<tr><td>${escape(item.stage)}</td><td><strong>${escape(item.material)}</strong></td><td>${escape(item.required)}</td><td>${escape(item.available)}</td><td class="${item.critical ? 'is-critical' : ''}">${escape(item.shortfall)}</td><td>${escape(item.coverage)}</td></tr>`).join('') || '<tr><td colspan="6">Nenhum material foi calculado.</td></tr>';
    const charts = cycle.charts.map(chart => `<article class="cycle-chart"><header><div><span class="eyebrow">${escape(chart.unit)}</span><h3>${escape(chart.title)}</h3></div><span class="cycle-chart-count">${escape(chart.count)} linhas</span></header>${chart.rows.map(row => `<div class="cycle-bar-row"><div class="cycle-bar-label"><span>${escape(row.label)}</span><b>${escape(row.display)}</b></div><div class="cycle-bar-track" role="meter" aria-label="${escape(row.label || 'Indicador')}" aria-valuenow="${escape(row.value)}" aria-valuemin="0" aria-valuemax="${escape(row.max)}"><i style="width:${row.width}%"></i></div><small>${escape(row.meta)}</small></div>`).join('') || '<div class="empty-state">Nenhum dado foi gerado para este gráfico.</div>'}</article>`).join('');
    result.innerHTML = `<section class="development-cycle-result"><header class="cycle-result-header"><div><span class="eyebrow">CONFIRMAÇÃO DE CICLO · DRY-RUN</span><h3>Ciclo de desenvolvimento concluído</h3><p>${escape(cycle.objective)}</p></div><span class="cycle-confirmed">✓ confirmado</span></header><div class="cycle-confirmation"><strong>${escape(cycle.confirmation)}</strong><small>Saída externa desabilitada · dados calculados pela mesma leitura operacional do worker.</small></div><ul class="cycle-check-list">${checks}</ul><div class="cycle-summary-line"><span>AGENDA <b>${escape(cycle.agendaItems)}</b></span><span>ETAPAS <b>${escape(cycle.stages)}</b></span><span>PESSOAL <b>${escape(cycle.assignedPeople)}/${escape(cycle.requiredPeople)}</b></span><span>MATERIAIS <b>${escape(cycle.materialItems)}</b></span></div><div class="cycle-chart-grid">${charts}</div><div class="cycle-detail-grid"><article class="cycle-chart cycle-timeline"><header><div><span class="eyebrow">ORDENAÇÃO TEMPORAL</span><h3>Itens de agenda gerados</h3></div><span class="cycle-chart-count">${cycle.schedule.length} itens</span></header><ol>${schedule}</ol></article><article class="cycle-material-table"><header><div><span class="eyebrow">TABELA DE ATIVIDADES</span><h3>Lista de materiais por etapa</h3></div><span class="cycle-chart-count">${escape(cycle.materialItems)} itens</span></header><div class="physical-table-wrap"><table class="physical-table"><thead><tr><th>Etapa</th><th>Material</th><th>Necessário</th><th>Disponível</th><th>Falta</th><th>Cobertura</th></tr></thead><tbody>${materials}</tbody></table></div></article></div></section>`;
  }

  private render(): void {
    const snapshot = this.snapshot;
    if (!snapshot) return;
    const text = (selector: string, value: string): void => {
      const target = this.querySelector<HTMLElement>(selector);
      if (target) target.textContent = value;
    };
    const escape = atlasWorkerRequirementsEscapeV1;
    text('[data-worker-status]', snapshot.workerStatus);
    text('[data-worker-mode]', snapshot.workerMode);
    text('[data-cash]', snapshot.cashBalance);
    text('[data-cash-available]', snapshot.cashAvailable);
    text('[data-event-count]', snapshot.eventCount);
    text('[data-agenda-count]', snapshot.agendaCount);
    text('[data-input-count]', snapshot.inputCount);
    text('[data-rule-count]', snapshot.ruleCount);
    text('[data-inference-count]', snapshot.inferenceCount);
    text('[data-propagation-count]', snapshot.propagationCount);
    text('[data-stage-count]', snapshot.stageCount);
    text('[data-updated]', snapshot.updatedAt);
    text('[data-connection]', 'Worker conectado');
    this.querySelector('.live-indicator')?.classList.add('ready');

    const physicalSite = this.querySelector<HTMLElement>('[data-physical-site]');
    if (physicalSite) physicalSite.innerHTML = snapshot.physicalSite.map(metric => `<article><small>${escape(metric.label)}</small><strong>${escape(metric.value)}</strong><span>${escape(metric.detail)}</span></article>`).join('');
    const physicalPlan = this.querySelector<HTMLElement>('[data-physical-plan-list]');
    if (physicalPlan) physicalPlan.innerHTML = snapshot.physicalPlan.map(row => `<article class="physical-plan-row"><div class="physical-plan-title"><span class="eyebrow">${escape(row.key)}</span><h3>${escape(row.name)}</h3><p>${escape(row.nextStep)}</p></div><div class="physical-plan-metric"><small>PRODUÇÃO</small><strong>${escape(row.production)}</strong><span>ritmo ${escape(row.rate)}</span>${row.secondary ? `<span>${escape(row.secondary)}</span>` : ''}</div><div class="physical-plan-metric"><small>EQUIPE</small><strong>${escape(row.teamCount)}</strong><span>${escape(row.availability)}</span><span>${escape(row.matchedPeople)}</span></div><div class="physical-plan-materials"><small>MATERIAIS / RELAÇÕES</small><span class="coverage-chip ${row.materialCritical ? 'is-critical' : ''}">${escape(row.materialCoverage)}</span><p>${escape(row.shortfalls)}</p><p>${escape(row.overlap)}</p></div><a class="physical-plan-open" href="${escape(row.href)}">Abrir etapa →</a></article>`).join('') || '<div class="empty-state">Nenhum plano físico disponível.</div>';
    const stageList = this.querySelector<HTMLElement>('[data-stage-list]');
    if (stageList) stageList.innerHTML = snapshot.stages.map((stage, index) => `<a class="stage-card ${stage.stateClass} ${stage.critical ? 'is-critical' : ''}" href="${escape(stage.href)}"><header><small>${String(index + 1).padStart(2, '0')} · ${escape(stage.key)}</small><span class="stage-state">${escape(stage.status)}</span></header><h3>${escape(stage.label)}</h3><p>${escape(stage.nextStep)}</p><span class="stage-next">${escape(stage.blockerSummary)}</span><span class="stage-physical">${escape(stage.physicalSummary)}</span><div class="progress"><i style="width:${stage.progress}%"></i></div><span class="stage-coverage">${escape(stage.coverage)}</span></a>`).join('') || '<div class="empty-state">Nenhuma etapa foi encontrada.</div>';
    const agenda = this.querySelector<HTMLElement>('[data-agenda-list]');
    if (agenda) agenda.innerHTML = snapshot.agenda.map(item => `<article class="agenda-row"><span class="agenda-index">${escape(item.order)}</span><time>${escape(item.date)}</time><div><strong>${escape(item.name)}</strong><span>${escape(item.stageOwner)}</span><small>${escape(item.production)}</small></div><em>${escape(item.status)}</em></article>`).join('') || '<div class="empty-state">Nenhuma atividade entrou no cronograma atual.</div>';
    const events = this.querySelector<HTMLElement>('[data-event-list]');
    if (events) events.innerHTML = snapshot.events.map(item => `<article class="event-row"><time>${escape(item.date)}</time><div><strong>${escape(item.label)}</strong><span>${escape(item.detail)}</span></div><em class="${item.isJob ? 'job' : ''}">${escape(item.status)}</em></article>`).join('') || '<div class="empty-state">Nenhum evento registrado ainda.</div>';
    if (snapshot.latestLoop) text('[data-cycle-status]', snapshot.latestLoop);
  }
}

if (!customElements.get('atlas-worker-monitor-dashboard')) {
  customElements.define('atlas-worker-monitor-dashboard', AtlasWorkerMonitorDashboardV1);
}

export interface AtlasWorkerNotificationWidgetPortsV1 {
  root: HTMLElement;
  load(): Promise<unknown>;
  markRead(id: string): Promise<unknown>;
  project(payload: unknown): WorkerNotificationProjectionV1;
  projectRead(items: readonly WorkerNotificationItemV1[], id: string): WorkerNotificationProjectionV1;
}

const atlasWorkerNotificationRootsV1 = new WeakSet<HTMLElement>();

/** Render the Worker notification trigger and its shared drawer surface. */
export function renderAtlasWorkerNotificationMarkupV1(): { triggerMarkup: string; panelMarkup: string } {
  return {
    triggerMarkup: '<button type="button" data-notification-toggle aria-haspopup="dialog" aria-controls="notification-widget"><span>Notificações</span><b data-notification-count>0</b></button>',
    panelMarkup: '<div class="notification-backdrop" data-notification-backdrop></div><aside class="notification-widget" id="notification-widget" data-notification-widget role="dialog" aria-modal="true" aria-labelledby="notification-title" aria-hidden="true"><header><div><span class="eyebrow">WORKER · TEMPO REAL</span><h2 id="notification-title">Notificações</h2></div><button type="button" data-notification-close aria-label="Fechar notificações">×</button></header><div class="notification-summary"><strong data-notification-summary>Carregando alertas…</strong><button type="button" data-notification-refresh>Atualizar</button></div><div class="notification-list" data-notification-list><div class="notification-empty">Abra o widget para consultar os alertas.</div></div></aside>',
  };
}

/** Own loading, status updates, safe rendering and drawer events; HTTP remains injected. */
export function installAtlasWorkerNotificationWidgetV1(input: AtlasWorkerNotificationWidgetPortsV1): boolean {
  const root = input.root;
  if (atlasWorkerNotificationRootsV1.has(root)) return true;
  const toggle = root.querySelector<HTMLButtonElement>('[data-notification-toggle]');
  const widget = root.querySelector<HTMLElement>('[data-notification-widget]');
  const backdrop = root.querySelector<HTMLElement>('[data-notification-backdrop]');
  const close = root.querySelector<HTMLButtonElement>('[data-notification-close]');
  const refresh = root.querySelector<HTMLButtonElement>('[data-notification-refresh]');
  const badge = root.querySelector<HTMLElement>('[data-notification-count]');
  const summary = root.querySelector<HTMLElement>('[data-notification-summary]');
  const list = root.querySelector<HTMLElement>('[data-notification-list]');
  if (!toggle || !widget || !backdrop || !close || !refresh || !badge || !summary || !list) return false;
  atlasWorkerNotificationRootsV1.add(root);

  const escape = atlasWorkerRequirementsEscapeV1;
  let projection = input.project({ notifications: [] });
  const render = (): void => {
    badge.textContent = String(projection.unreadCount);
    badge.hidden = projection.unreadCount === 0;
    summary.textContent = projection.summary;
    list.innerHTML = projection.items.map(item => {
      const isRead = ['read', 'acknowledged'].includes(item.status);
      const severity = ['critical', 'warning'].includes(item.severity) ? item.severity : 'info';
      const severityLabel = severity === 'critical' ? 'CRÍTICO' : severity === 'warning' ? 'ATENÇÃO' : 'INFORMAÇÃO';
      const createdAt = item.createdAt ? new Date(item.createdAt).toLocaleString('pt-BR', { day: '2-digit', month: 'short', hour: '2-digit', minute: '2-digit' }) : 'Agora';
      const action = item.actionUrl.startsWith('/') ? `<a href="${escape(item.actionUrl)}">Abrir área</a>` : '<span></span>';
      const command = isRead ? '<em>Lida</em>' : `<button type="button" data-notification-read="${escape(item.id)}">Marcar como lida</button>`;
      return `<article class="notification-card severity-${severity} ${isRead ? 'is-read' : ''}"><div class="notification-card-head"><span>${severityLabel}</span><time>${escape(createdAt)}</time></div><h3>${escape(item.title)}</h3><p>${escape(item.message)}</p><footer>${action}${command}</footer></article>`;
    }).join('') || '<div class="notification-empty"><strong>Nenhuma notificação</strong><span>O worker não encontrou alertas para este perfil.</span></div>';
  };
  const load = async (): Promise<void> => {
    try {
      projection = input.project(await input.load());
      render();
    } catch (error) {
      badge.textContent = '0'; badge.hidden = true; summary.textContent = 'Falha ao carregar notificações';
      const message = error instanceof Error ? error.message : String(error);
      list.innerHTML = `<div class="notification-empty"><strong>Não foi possível carregar</strong><span>${escape(message)}</span></div>`;
    }
  };
  const setOpen = (open: boolean): void => {
    widget.classList.toggle('is-open', open);
    backdrop.classList.toggle('is-open', open);
    widget.setAttribute('aria-hidden', String(!open));
    root.ownerDocument.body.classList.toggle('notification-widget-open', open);
    if (open) { void load(); close.focus(); } else toggle.focus();
  };

  toggle.addEventListener('click', () => setOpen(true));
  close.addEventListener('click', () => setOpen(false));
  backdrop.addEventListener('click', () => setOpen(false));
  refresh.addEventListener('click', () => { void load(); });
  list.addEventListener('click', async event => {
    const source = event.target instanceof HTMLElement ? event.target.closest<HTMLButtonElement>('[data-notification-read]') : null;
    const id = source?.dataset.notificationRead || '';
    if (!source || !id) return;
    source.disabled = true;
    try {
      await input.markRead(id);
      projection = input.projectRead(projection.items, id);
      render();
    } catch (error) {
      source.textContent = error instanceof Error ? error.message : String(error);
      source.disabled = false;
    }
  });
  root.ownerDocument.addEventListener('keydown', event => {
    if (event.key === 'Escape' && widget.classList.contains('is-open')) setOpen(false);
  });
  void load();
  return true;
}

/** Shared chrome for the dedicated worker stage, activity, and record routes. */
