const escapeAtlasRecordOcrValueV1 = (value: unknown): string => String(value ?? "").replace(/[&<>"']/g, character => ({
  "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;",
}[character] || character));

/** Own the editable OCR review fields inside the existing operational record form. */
export class AtlasRecordOcrReviewV1 extends AtlasHTMLElementBase {
  private result: AtlasRecordOcrPayloadV1 | null = null;
  private stageOptions: AtlasRecordOcrStageOptionV1[] = [];

  setStageOptions(options: readonly AtlasRecordOcrStageOptionV1[]): void {
    this.stageOptions = options
      .filter(option => String(option.key || "").trim() && String(option.name || "").trim())
      .map(option => ({ key: String(option.key), name: String(option.name) }));
    if (this.result) this.render();
  }

  setOcrResult(result: AtlasRecordOcrPayloadV1): void {
    this.result = result;
    this.render();
  }

  clearOcrResult(): void {
    this.result = null;
    this.replaceChildren();
  }

  getOcrProperties(): AtlasRecordOcrSerializedPropertyV1[] {
    if (!this.result) return [];
    const items = [...this.querySelectorAll<HTMLElement>("[data-record-ocr-item]")].map(article => {
      const get = (key: string): string => article.querySelector<HTMLInputElement | HTMLSelectElement>(`[data-item-key="${key}"]`)?.value || "";
      return {
        itemKind: get("itemKind"),
        stageName: get("stageName"),
        activityName: get("activityName"),
        materialName: get("materialName"),
        materialId: get("materialId"),
        description: get("description"),
        quantity: get("quantity"),
        unit: get("unit"),
        unitPriceCents: get("unitPriceCents"),
        totalPriceCents: get("totalPriceCents"),
      };
    });
    const fields = [...this.querySelectorAll<HTMLInputElement>("[data-record-dynamic-field]")].map(input => ({
      key: input.dataset.key || "",
      label: input.dataset.label || "",
      type: input.dataset.type || "text",
      value: input.value,
    }));
    return projectAtlasRecordOcrReviewPropertiesV1({ result: this.result, fields, items });
  }

  private render(): void {
    if (!this.result) return;
    const escape = escapeAtlasRecordOcrValueV1;
    const properties = (this.result.properties || []).filter(item => item?.key !== "items");
    const items = Array.isArray(this.result.items) ? this.result.items : [];
    const stageOptionsMarkup = (item: AtlasRecordOcrItemV1): string => {
      const current = String(item.stageName || item.stageKey || "").trim();
      const options = [...this.stageOptions];
      if (current && !options.some(stage => stage.key === current || stage.name === current))
        options.unshift({ key: current, name: current });
      return `<select data-item-key="stageName"><option value="">Selecione o destino</option>${options.map(stage => `<option value="${escape(stage.name)}"${stage.name === current || stage.key === current ? " selected" : ""}>${escape(stage.name)}</option>`).join("")}</select>`;
    };
    const fieldMarkup = properties.map(property => {
      const type = property.type === "date" ? "date" : property.type === "number" || property.type === "currency" ? "number" : "text";
      const value = property.type === "currency" ? Number(property.value || 0) / 100 : property.value ?? "";
      const step = property.type === "currency" ? "0.01" : property.type === "number" ? "any" : "";
      return `<label><span>${escape(property.label || property.key)}</span><input data-record-dynamic-field data-key="${escape(property.key)}" data-label="${escape(property.label || property.key)}" data-type="${escape(property.type || "text")}" type="${type}" value="${escape(value)}" ${step ? `step="${step}"` : ""}><small>conf. ${Math.round(Number(property.confidence || 0) * 100)}%</small></label>`;
    }).join("");
    const itemMarkup = items.length ? `<section class="record-ocr-items-v21"><h4>Itens detectados · confirme a alocação</h4>${items.map((item, index) => `<article data-record-ocr-item data-index="${index}"><label>Tipo<select data-item-key="itemKind"><option ${item.itemKind === "material" ? "selected" : ""}>material</option><option ${item.itemKind === "servico" ? "selected" : ""}>servico</option><option ${item.itemKind === "outro" ? "selected" : ""}>outro</option></select></label><label>Etapa${stageOptionsMarkup(item)}</label><label>Serviço / atividade<input data-item-key="activityName" value="${escape(item.activityName || item.activityId || "")}"></label><label>Material<input data-item-key="materialName" value="${escape(item.materialName || item.materialId || "")}"></label><label>Código / material<input data-item-key="materialId" value="${escape(item.materialId || "")}"></label><label>Descrição<input data-item-key="description" value="${escape(item.description || "")}"></label><label>Quantidade<input data-item-key="quantity" type="number" step="any" value="${escape(item.quantity || 0)}"></label><label>Unidade<input data-item-key="unit" value="${escape(item.unit || "")}"></label><label>Valor unitário<input data-item-key="unitPriceCents" type="number" step="0.01" value="${escape(Number(item.unitPriceCents || 0) / 100)}"></label><label>Valor total<input data-item-key="totalPriceCents" type="number" step="0.01" value="${escape(Number(item.totalPriceCents || 0) / 100)}"></label></article>`).join("")}</section>` : "";
    this.innerHTML = `<header><div><span>PROPRIEDADES DETECTADAS</span><b>Revise antes de confirmar</b></div><small>OCR · ${escape(this.result.model || "vision")}</small></header><div class="record-ocr-field-grid-v21">${fieldMarkup}</div>${itemMarkup}`;
  }
}

if (globalThis.customElements && !globalThis.customElements.get("atlas-record-ocr-review"))
  globalThis.customElements.define("atlas-record-ocr-review", AtlasRecordOcrReviewV1);

export interface AtlasRecordOcrFormControlsV1 {
  fileInput: HTMLInputElement;
  review: AtlasRecordOcrReviewV1;
  status: HTMLElement | null;
}

/** Build and return the OCR controls hosted by an existing operational record form. */
export function prepareAtlasRecordOcrFormControlsV1(
  form: HTMLFormElement,
  documentRef: Document,
  stageOptions: readonly AtlasRecordOcrStageOptionV1[],
): AtlasRecordOcrFormControlsV1 | null {
  let fileInput = form.querySelector<HTMLInputElement>("[data-activity-record-attachments],input[name=\"evidence\"]");
  if (!fileInput) {
    const section = documentRef.createElement("section");
    section.className = "record-ocr-upload-v21";
    section.innerHTML = '<header><span>NOTA / COMPROVANTE</span><b>OCR dinâmico</b></header><label><span>Anexar imagem para leitura</span><input type="file" name="attachments" data-record-ocr-file accept="image/png,image/jpeg,image/webp"></label><small data-record-ocr-status>Ao anexar, os campos detectados aparecem abaixo.</small>';
    const footer = form.querySelector("footer");
    if (footer) footer.before(section); else form.append(section);
    fileInput = section.querySelector<HTMLInputElement>("[data-record-ocr-file]");
  } else {
    fileInput.dataset.recordOcrFile = "true";
    if (!fileInput.closest("section")?.querySelector("[data-record-ocr-status]")) {
      const note = documentRef.createElement("small");
      note.dataset.recordOcrStatus = "";
      note.textContent = "Imagens anexadas também alimentam os campos OCR.";
      fileInput.closest("section")?.append(note);
    }
  }
  if (!fileInput) return null;

  let review = form.querySelector<AtlasRecordOcrReviewV1>("atlas-record-ocr-review");
  if (!review) {
    review = documentRef.createElement("atlas-record-ocr-review") as AtlasRecordOcrReviewV1;
    review.className = "record-ocr-properties-v21";
    review.dataset.recordOcrProperties = "";
    review.hidden = true;
    const footer = form.querySelector("footer");
    if (footer) footer.before(review); else form.append(review);
  }
  review.setStageOptions(stageOptions);
  return {
    fileInput,
    review,
    status: form.querySelector<HTMLElement>("[data-record-ocr-status]"),
  };
}

type AtlasRecordOcrFormHostV1 = typeof globalThis & { __BELAVISTA_RECORD_OCR_TS_OWNER_V1?: boolean };
type AtlasRecordOcrFormStoreV1 = { get(): Record<string, unknown> };
const atlasRecordOcrObserversV1 = new WeakMap<Document, MutationObserver>();

/** Own form discovery, image inference, review hydration, and hidden payload serialization. */
export function installAtlasRecordOcrFormsV1(input: {
  documentRef: Document;
  host: AtlasRecordOcrFormHostV1;
  appStore: AtlasRecordOcrFormStoreV1;
  requestOcr: (request: AtlasRecordOcrRequestV1) => Promise<AtlasRecordOcrPayloadV1>;
  stageOptions?: readonly AtlasRecordOcrStageOptionV1[];
}): boolean {
  const { documentRef, host } = input;
  if (atlasRecordOcrObserversV1.has(documentRef)) {
    host.__BELAVISTA_RECORD_OCR_TS_OWNER_V1 = true;
    return true;
  }
  const Observer = documentRef.defaultView?.MutationObserver;
  if (!Observer || !documentRef.defaultView?.customElements.get("atlas-record-ocr-review")) return false;
  const stateFor = new WeakMap<HTMLFormElement, AtlasRecordOcrPayloadV1>();
  const ensureHidden = (form: HTMLFormElement, name: string): HTMLInputElement => {
    let hidden = form.querySelector<HTMLInputElement>(`input[type="hidden"][name="${name}"]`);
    if (!hidden) {
      hidden = documentRef.createElement("input");
      hidden.type = "hidden";
      hidden.name = name;
      form.append(hidden);
    }
    return hidden;
  };
  const readDataUrl = (file: File): Promise<string> => new Promise((resolve, reject) => {
    const Reader = documentRef.defaultView?.FileReader;
    if (!Reader) { reject(new Error("Leitor de imagem indisponível.")); return; }
    const reader = new Reader();
    reader.onload = () => resolve(String(reader.result || ""));
    reader.onerror = () => reject(new Error("Falha ao ler imagem."));
    reader.readAsDataURL(file);
  });
  const serialize = (form: HTMLFormElement, review: AtlasRecordOcrReviewV1): void => {
    const ocr = stateFor.get(form);
    if (!ocr) return;
    const requestId = form.dataset.ocrRequestId;
    if (requestId) ensureHidden(form, "requestId").value = requestId;
    ensureHidden(form, "properties").value = JSON.stringify(review.getOcrProperties());
  };
  const runOcr = async (form: HTMLFormElement, review: AtlasRecordOcrReviewV1, file: File, status: HTMLElement | null): Promise<void> => {
    if (!/^image\/(?:png|jpeg|webp)$/i.test(file.type || "")) return;
    if (status) status.textContent = "Lendo nota com OCR…";
    try {
      const dataUrl = await readDataUrl(file);
      const payload = await input.requestOcr({
        attachment: { name: file.name, mimeType: file.type, dataUrl },
        context: {
          source: 'record-form',
          stage: form.querySelector<HTMLInputElement | HTMLSelectElement>('[name="etapa"]')?.value || '',
          activity: form.querySelector<HTMLInputElement | HTMLSelectElement>('[name="atividade"]')?.value || '',
        },
      });
      stateFor.set(form, payload);
      review.setOcrResult(payload);
      review.hidden = false;
      serialize(form, review);
      if (status) status.textContent = "Campos OCR adicionados. Revise e confirme.";
      form.dispatchEvent(new CustomEvent("belavista:record-ocr-ready", { bubbles: true, detail: payload }));
    } catch (error) {
      if (status) status.textContent = `OCR falhou: ${error instanceof Error ? error.message : String(error)}`;
    }
  };
  const decorate = (form: HTMLFormElement): void => {
    if (form.dataset.recordOcrTsOwnerV1) return;
    const controls = prepareAtlasRecordOcrFormControlsV1(form, documentRef, input.stageOptions || []);
    if (!controls) return;
    form.dataset.recordOcrTsOwnerV1 = "true";
    const { fileInput, review: reviewElement, status } = controls;
    const updateSerializedProperties = (): void => serialize(form, reviewElement);
    form.addEventListener("input", updateSerializedProperties);
    form.addEventListener("change", updateSerializedProperties);
    form.addEventListener("submit", updateSerializedProperties, true);
    fileInput.addEventListener("change", () => {
      if (fileInput.dataset.chatOcrPrepared === "true") { delete fileInput.dataset.chatOcrPrepared; return; }
      const files = fileInput.files ? [...fileInput.files] : [];
      if (!files.length) {
        stateFor.delete(form);
        reviewElement.clearOcrResult();
        reviewElement.hidden = true;
        for (const name of ["properties", "evidenceUri"]) {
          const hidden = form.querySelector<HTMLInputElement>(`input[type="hidden"][name="${name}"]`);
          if (hidden) hidden.value = name === "properties" ? "[]" : "";
        }
        return;
      }
      const image = files.find(candidate => /^image\//i.test(candidate.type));
      if (image) void runOcr(form, reviewElement, image, status);
    });
    const appState = input.appStore.get();
    const context = appState.recordContext && typeof appState.recordContext === "object" ? appState.recordContext as Record<string, unknown> : null;
    if (context?.attachmentDataUrl) ensureHidden(form, "evidenceUri").value = String(context.attachmentDataUrl);
    if (context?.ocr && typeof context.ocr === "object" && !(context.ocr as Record<string, unknown>).error) {
      const ocr = context.ocr as AtlasRecordOcrPayloadV1;
      if (context.requestId) form.dataset.ocrRequestId = String(context.requestId);
      stateFor.set(form, ocr);
      reviewElement.setOcrResult(ocr);
      reviewElement.hidden = false;
      serialize(form, reviewElement);
      const reference = context.attachmentRef && typeof context.attachmentRef === "object" ? context.attachmentRef as Record<string, unknown> : null;
      if (reference?.stored && reference.reference) ensureHidden(form, "evidenceUri").value = String(reference.reference);
    }
  };
  const scan = (): void => documentRef.querySelectorAll<HTMLFormElement>(".records-entry-panel-v1 .record-form,[data-activity-record-form],[data-control-general-event]").forEach(decorate);
  const observer = new Observer(scan);
  observer.observe(documentRef.documentElement, { childList: true, subtree: true });
  atlasRecordOcrObserversV1.set(documentRef, observer);
  host.__BELAVISTA_RECORD_OCR_TS_OWNER_V1 = true;
  documentRef.documentElement.dataset.recordOcrTsOwnerV1 = "true";
  scan();
  return true;
}

type AtlasDesktopSetupStateV1 = {
  setup: AtlasDesktopSetupViewV1 | null;
  environment: AtlasDesktopEnvironmentViewV1 | null;
  status: string;
  tone: "" | "error" | "success";
  pending: "" | "save" | "instagram" | "environment";
};
type AtlasDesktopSetupSetterV1 = (previous: AtlasDesktopSetupStateV1) => AtlasDesktopSetupStateV1;

/** First-access desktop screen. It renders the branded setup form and emits typed program commands. */
export class AtlasDesktopSetup extends AtlasHTMLElementBase {
  private snapshot: AtlasDesktopSetupStateV1 = {
    setup: null,
    environment: null,
    status: "Preencha os dados para preparar a estação.",
    tone: "",
    pending: "",
  };
  private readonly state: AtomicState<AtlasDesktopSetupStateV1>;

  constructor() {
    super();
    function* state(value: AtlasDesktopSetupStateV1): Generator<AtlasDesktopSetupStateV1, never, AtlasDesktopSetupSetterV1> {
      while (true) value = (yield value)(value);
    }
    const iterator = state(this.snapshot);
    iterator.next();
    this.state = { next: setter => { this.snapshot = iterator.next(setter).value; return this.snapshot; } };
  }

  connectedCallback(): void {
    if (this.dataset.mounted === "true") return;
    this.dataset.mounted = "true";
    this.render();
    this.bind();
  }

  disconnectedCallback(): void {
    this.dispatchEvent(new CustomEvent("atlas:desktop-setup-disconnected", { detail: { element: this } }));
  }

  setSetup(setup: AtlasDesktopSetupViewV1): void {
    this.state.next(previous => ({ ...previous, setup }));
    const ownerName = this.querySelector<HTMLInputElement>("#owner-name");
    const ownerEmail = this.querySelector<HTMLInputElement>("#owner-email");
    const enterpriseName = this.querySelector<HTMLInputElement>("#enterprise-name");
    const instagramHandle = this.querySelector<HTMLInputElement>("#instagram-handle");
    const consent = this.querySelector<HTMLInputElement>("#instagram-consent");
    if (ownerName) ownerName.value = setup.owner?.name || "";
    if (ownerEmail) ownerEmail.value = setup.owner?.email || "";
    if (enterpriseName) enterpriseName.value = setup.enterprise?.name || "Aliança Park";
    if (instagramHandle) instagramHandle.value = String(setup.instagram?.handle || "").replace(/^@/, "");
    if (consent) consent.checked = Boolean(setup.instagram?.consent);
    const openButton = this.querySelector<HTMLButtonElement>("#open-instagram");
    if (openButton) openButton.disabled = !setup.complete;
    if (setup.complete) this.setStatus("Esta estação está pronta. O Direct local pode ser aberto quando a ponte estiver ativa.", "success");
  }

  setEnvironment(environment: AtlasDesktopEnvironmentViewV1 | null): void {
    this.state.next(previous => ({ ...previous, environment }));
    const switcher = this.querySelector<HTMLElement>("#environment-switch");
    const label = this.querySelector<HTMLElement>("#environment-label");
    const description = this.querySelector<HTMLElement>("#environment-description");
    const toggle = this.querySelector<HTMLButtonElement>("#environment-toggle");
    const modes = environment?.availableModes || [];
    const enabled = modes.includes("local") && modes.includes("router") && Boolean(environment?.mode);
    if (switcher) switcher.hidden = !enabled;
    if (!enabled || !label || !description || !toggle) return;
    const local = environment?.mode === "local";
    label.textContent = local ? "Ambiente de teste local" : "Ambiente conectado ao Router";
    description.textContent = local ? "Gravações ficam isoladas neste computador." : "Usa os dados compartilhados pelo Router.";
    toggle.textContent = local ? "Usar Router remoto" : "Usar teste local";
    toggle.dataset.nextMode = local ? "router" : "local";
  }

  setStatus(message: string, tone: "" | "error" | "success" = ""): void {
    this.state.next(previous => ({ ...previous, status: message, tone }));
    const output = this.querySelector<HTMLElement>("#setup-status");
    if (output) {
      output.textContent = message;
      output.className = `status${tone ? ` ${tone}` : ""}`;
    }
  }

  setBusy(action: AtlasDesktopSetupStateV1["pending"], busy: boolean): void {
    const pending = busy ? action : "";
    this.state.next(previous => ({ ...previous, pending }));
    const save = this.querySelector<HTMLButtonElement>('[data-action="save"]');
    const instagram = this.querySelector<HTMLButtonElement>('[data-action="instagram"]');
    const environment = this.querySelector<HTMLButtonElement>('[data-action="environment"]');
    if (save) { save.disabled = pending === "save"; save.textContent = pending === "save" ? "Preparando…" : "Salvar e preparar desktop"; }
    if (instagram) { instagram.disabled = pending === "instagram" || !this.snapshot.setup?.complete; instagram.textContent = pending === "instagram" ? "Abrindo Direct…" : "Abrir Direct local"; }
    if (environment) { environment.disabled = pending === "environment"; }
  }

  private render(): void {
    this.innerHTML = `<main class="setup-shell">
      <section class="setup-brand" aria-label="Aliança Park">
        <img src="/assets/public/alianca-park-logo-full-letter-cutouts-v555.png" alt="Aliança Park Loteamento">
        <p class="eyebrow">VERSÃO DESKTOP · INSTALAÇÃO LOCAL</p>
        <h1>Seu centro de operação, no computador da equipe.</h1>
        <p>Configure o primeiro responsável e o canal de atendimento. O painel continuará usando a autenticação e os perfis administrativos do sistema.</p>
        <ul><li>Dados operacionais isolados no perfil local do aplicativo.</li><li>Leads do Direct entram no CRM com o histórico da conversa.</li><li>A IA prepara rascunhos; a aprovação e o envio permanecem humanos.</li></ul>
      </section>
      <section class="setup-card" aria-labelledby="setup-title">
        <p class="eyebrow">PRIMEIRO ACESSO</p>
        <h2 id="setup-title">Configure a estação de atendimento</h2>
        <p class="muted">Nenhuma senha do Instagram é salva aqui. A sessão é aberta manualmente no navegador local conectado.</p>
        <div id="environment-switch" class="environment-switch" hidden>
          <div><strong id="environment-label">Ambiente local</strong><small id="environment-description">Os dados de teste ficam neste computador.</small></div>
          <button id="environment-toggle" data-action="environment" class="button ghost" type="button">Alternar ambiente</button>
        </div>
        <form id="setup-form">
          <fieldset><legend>Responsável inicial</legend><label>Nome<input id="owner-name" name="ownerName" autocomplete="name" required minlength="2" placeholder="Nome do responsável"></label><label>E-mail administrativo<input id="owner-email" name="ownerEmail" type="email" autocomplete="email" required placeholder="voce@empresa.com"></label></fieldset>
          <fieldset><legend>Empreendimento e canal</legend><label>Nome do empreendimento<input id="enterprise-name" name="enterpriseName" required value="Aliança Park"></label><label>Instagram do empreendimento<span class="input-prefix"><b>@</b><input id="instagram-handle" name="instagramHandle" required pattern="[A-Za-z0-9._]+" placeholder="aliancapark"></span></label></fieldset>
          <label class="consent"><input id="instagram-consent" name="instagramConsent" type="checkbox" required><span>Confirmo que a conta será autenticada manualmente pelo responsável e que os Directs serão tratados conforme a política de atendimento do empreendimento.</span></label>
          <p id="setup-status" class="status" role="status" aria-live="polite">Preencha os dados para preparar a estação.</p>
          <div class="setup-actions"><button data-action="save" class="button primary" type="submit">Salvar e preparar desktop</button><button id="open-instagram" data-action="instagram" class="button" type="button" disabled>Abrir Direct local</button><button id="open-admin" class="button ghost" type="button">Ir ao painel</button></div>
        </form>
        <aside class="security-note"><strong>Como funciona o Direct</strong><p>Após salvar, inicie a ponte local do Camofox e faça login você mesmo. A integração cria leads e rascunhos auditáveis, mas não envia mensagens reais sozinha.</p></aside>
      </section>
    </main>`;
  }

  private bind(): void {
    this.querySelector<HTMLFormElement>("#setup-form")?.addEventListener("submit", event => {
      event.preventDefault();
      const form = event.currentTarget as HTMLFormElement;
      if (!form.reportValidity()) return;
      const detail = buildAtlasDesktopSetupFormDraftV1(Object.fromEntries(new FormData(form).entries()));
      this.emit("atlas:desktop-setup-save", detail);
    });
    this.querySelector<HTMLButtonElement>("#open-instagram")?.addEventListener("click", () => this.emit("atlas:desktop-setup-open-instagram", {}));
    this.querySelector<HTMLButtonElement>("#open-admin")?.addEventListener("click", () => this.emit("atlas:desktop-setup-open-admin", {}));
    this.querySelector<HTMLButtonElement>("#environment-toggle")?.addEventListener("click", () => {
      const mode = this.querySelector<HTMLButtonElement>("#environment-toggle")?.dataset.nextMode;
      const nextMode = projectAtlasDesktopEnvironmentModeV1(mode);
      if (nextMode) this.emit("atlas:desktop-setup-switch-environment", { mode: nextMode });
    });
  }

  private emit(type: string, detail: unknown): void {
    this.dispatchEvent(new CustomEvent(type, { bubbles: true, composed: true, detail }));
  }
}

if (globalThis.customElements && !globalThis.customElements.get("atlas-desktop-setup"))
  globalThis.customElements.define("atlas-desktop-setup", AtlasDesktopSetup);

export interface AtlasAdminTestCaseItemV1 { id: string; label: string }
export interface AtlasAdminTestCaseGroupV1 { label: string; items: readonly AtlasAdminTestCaseItemV1[] }
export interface AtlasAdminTestControlsViewV1 {
  root: HTMLElement;
  setEnabled(enabled: boolean): void;
  setBusy(busy: boolean): void;
  setContext(context: string): void;
  setResult(result: { tone?: "ok" | "error" | ""; title: string; body: string; note?: string }): void;
  focus(button?: HTMLElement | null): void;
}

/** Mount the administrative scenario drawer; network calls and storage stay in program.ts. */
export function mountAtlasAdminTestControlsV1(input: {
  documentRef: Document;
  groups: readonly AtlasAdminTestCaseGroupV1[];
  enabled: boolean;
  pageContext(): string;
}): AtlasAdminTestControlsViewV1 {
  const { documentRef } = input;
  const root = documentRef.createElement("aside");
  root.className = "admin-test-controls";
  root.hidden = true;
  root.dataset.adminTestControlsOwnerV1 = "typescript";
  root.setAttribute("aria-label", "Casos de teste administrativos");
  const escapeHtml = (value: unknown): string => String(value ?? "").replace(/[&<>\"']/g, char => ({
    "&": "&amp;", "<": "&lt;", ">": "&gt;", "\"": "&quot;", "'": "&#39;",
  }[char] || char));
  const scenarioCount = input.groups.reduce((count, group) => count + group.items.length, 0);
  root.innerHTML = `<button class="admin-test-launcher" type="button" aria-expanded="false"><span>Casos de teste</span><small>${scenarioCount}</small></button><section class="admin-test-drawer" aria-hidden="true"><header><div><span>LABORATÓRIO GLOBAL</span><strong>Entradas, gerações e propagações</strong></div><button class="admin-test-close" type="button" aria-label="Fechar">×</button></header><div class="admin-test-context"><span data-admin-test-context></span><b>SAÍDA EXTERNA DESATIVADA</b></div><div class="admin-test-groups">${input.groups.map(group => `<section class="admin-test-group"><h3>${escapeHtml(group.label)}</h3><div>${group.items.map(item => `<button class="admin-test-case" type="button" data-case-id="${escapeHtml(item.id)}">${escapeHtml(item.label)}</button>`).join("")}</div></section>`).join("")}</div><button class="admin-test-all" type="button" data-run-all>Executar suíte completa</button><div class="admin-test-result" data-admin-test-result><strong>Pronto para executar</strong><span>Escolha um cenário para inspecionar sua propagação nesta página.</span><small></small></div></section>`;
  documentRef.body.appendChild(root);
  const launcher = root.querySelector<HTMLButtonElement>(".admin-test-launcher")!;
  const drawer = root.querySelector<HTMLElement>(".admin-test-drawer")!;
  const context = root.querySelector<HTMLElement>("[data-admin-test-context]")!;
  const result = root.querySelector<HTMLElement>("[data-admin-test-result]")!;
  const toggleDrawer = (open: boolean): void => {
    root.classList.toggle("is-open", open);
    launcher.setAttribute("aria-expanded", String(open));
    drawer.setAttribute("aria-hidden", String(!open));
    if (open) context.textContent = input.pageContext();
  };
  root.addEventListener("click", event => {
    const target = event.target;
    if (!(target instanceof Element)) return;
    if (target.closest(".admin-test-launcher")) {
      toggleDrawer(!root.classList.contains("is-open"));
      return;
    }
    if (target.closest(".admin-test-close")) {
      toggleDrawer(false);
      return;
    }
    const caseButton = target.closest<HTMLButtonElement>("button[data-case-id]");
    if (caseButton) {
      root.dispatchEvent(new CustomEvent("atlas:admin-test-case-run", { bubbles: true, composed: true, detail: { caseId: caseButton.dataset.caseId || "", button: caseButton } }));
      return;
    }
    const runAll = target.closest<HTMLButtonElement>("button[data-run-all]");
    if (runAll) root.dispatchEvent(new CustomEvent("atlas:admin-test-case-run", { bubbles: true, composed: true, detail: { caseId: "", button: runAll } }));
  });
  documentRef.addEventListener("keydown", event => {
    if (event.key === "Escape") toggleDrawer(false);
  });
  const view: AtlasAdminTestControlsViewV1 = {
    root,
    setEnabled(enabled) {
      root.hidden = !enabled;
      root.ownerDocument.querySelectorAll<HTMLInputElement>("[data-admin-test-mode]").forEach(input => {
        input.checked = enabled;
        input.setAttribute("aria-checked", String(enabled));
      });
      root.ownerDocument.documentElement.dataset.adminTestControls = enabled ? "enabled" : "disabled";
    },
    setBusy(busy) {
      root.querySelectorAll<HTMLButtonElement>("button[data-case-id],button[data-run-all]").forEach(button => { button.disabled = busy; });
    },
    setContext(value) { context.textContent = value; },
    setResult(value) {
      result.dataset.tone = value.tone || "";
      const [title, body, note] = [
        result.querySelector("strong"), result.querySelector("span"), result.querySelector("small"),
      ];
      if (title) title.textContent = value.title;
      if (body) body.textContent = value.body;
      if (note) note.textContent = value.note || "";
    },
    focus(button) { button?.focus(); },
  };
  view.setEnabled(input.enabled);
  return view;
}

export interface AtlasAdminTwaPushCardStateV1 {
  buttonLabel?: string;
  status?: string;
  tone?: 'ok' | 'error' | '';
  disabled?: boolean;
}

export interface AtlasAdminTwaPushCardViewV1 {
  root: HTMLElement;
  setState(state: AtlasAdminTwaPushCardStateV1): void;
  setHidden(hidden: boolean): void;
}

/** Render the admin notification card; lifecycle and Firebase requests stay in the program. */
export function mountAtlasAdminTwaPushCardV1(input: {
  documentRef?: Document;
  onEnable(): void;
  onDismiss(): void;
}): AtlasAdminTwaPushCardViewV1 | null {
  const documentRef = input.documentRef || globalThis.document;
  if (!documentRef?.body || documentRef.querySelector('[data-belavista-twa-push]')) return null;
  if (!documentRef.querySelector('[data-belavista-twa-style]')) {
    const style = documentRef.createElement('style');
    style.dataset.belavistaTwaStyle = 'typescript';
    style.textContent = '.belavista-twa-push{position:fixed;right:18px;bottom:max(18px,env(safe-area-inset-bottom));z-index:1200;width:min(360px,calc(100vw - 36px));display:grid;gap:12px;padding:15px;background:#161616;color:#f4f4f4;border:1px solid #525252;box-shadow:0 8px 28px rgba(0,0,0,.34);font:12px/1.4 "IBM Plex Sans",Arial,sans-serif}.belavista-twa-push[hidden]{display:none}.belavista-twa-push header{display:flex;justify-content:space-between;gap:12px;align-items:start}.belavista-twa-push header span{color:#78a9ff;font:9px "IBM Plex Mono",monospace;letter-spacing:.08em;text-transform:uppercase}.belavista-twa-push header button{border:0;background:none;color:#c6c6c6;cursor:pointer;font-size:16px;line-height:1}.belavista-twa-push strong{display:block;margin-top:5px;font-size:14px}.belavista-twa-push p{margin:0;color:#c6c6c6;font-size:11px}.belavista-twa-push footer{display:flex;align-items:center;gap:8px}.belavista-twa-push [data-twa-push-enable]{min-height:34px;padding:7px 12px;border:1px solid #0f62fe;background:#0f62fe;color:#fff;font-weight:600;cursor:pointer}.belavista-twa-push [data-twa-push-enable]:disabled{opacity:.55;cursor:wait}.belavista-twa-push [data-twa-push-status]{color:#a8a8a8;font-size:10px}.belavista-twa-push[data-tone="ok"] [data-twa-push-status]{color:#42be65}.belavista-twa-push[data-tone="error"] [data-twa-push-status]{color:#ffb3b8}@media(max-width:600px){.belavista-twa-push{right:10px;bottom:max(10px,env(safe-area-inset-bottom));width:calc(100vw - 20px)}}';
    documentRef.head.appendChild(style);
  }
  const root = documentRef.createElement('section');
  root.className = 'belavista-twa-push';
  root.dataset.belavistaTwaPush = 'typescript';
  root.setAttribute('aria-label', 'Notificações do painel no celular');
  root.innerHTML = '<header><div><span>TWA administrativo</span><strong>Receba os avisos do Aliança Park</strong></div><button type="button" data-twa-push-dismiss aria-label="Fechar">×</button></header><p>Agendamentos, cronogramas, caixa, materiais e mensagens aparecem nas notificações do celular.</p><footer><button type="button" data-twa-push-enable>Ativar notificações</button><small data-twa-push-status aria-live="polite">Este dispositivo ainda não foi vinculado.</small></footer>';
  const enable = root.querySelector<HTMLButtonElement>('[data-twa-push-enable]');
  const status = root.querySelector<HTMLElement>('[data-twa-push-status]');
  root.querySelector('[data-twa-push-dismiss]')?.addEventListener('click', input.onDismiss);
  enable?.addEventListener('click', input.onEnable);
  documentRef.body.appendChild(root);
  return {
    root,
    setState(state) {
      if (enable && state.buttonLabel !== undefined) enable.textContent = state.buttonLabel;
      if (enable && state.disabled !== undefined) enable.disabled = state.disabled;
      if (status && state.status !== undefined) status.textContent = state.status;
      if (state.tone !== undefined) root.dataset.tone = state.tone;
    },
    setHidden(hidden) { root.hidden = hidden; },
  };
}

