const escapeAtlasWorkerStageAdminHtmlV1 = (value: unknown): string => String(value ?? '').replace(/[&<>"']/g, char => ({
  '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;',
}[char] || char));

const atlasWorkerStageEditorActivityMarkupV1 = (
  activity: AtlasWorkerStageAdminActivityV1,
  statuses: readonly string[],
): string => {
  const escape = escapeAtlasWorkerStageAdminHtmlV1;
  return `<fieldset class="stage-editor-activity" data-stage-editor-activity data-activity-id="${escape(activity.id)}"><label>Atividade<input name="activityName" required value="${escape(activity.name)}" placeholder="Ex.: Executar rede principal"></label><label>Categoria<input name="activityCategory" value="${escape(activity.category)}" placeholder="Execução"></label><label>Status<select name="activityStatus">${statuses.map(value => `<option value="${escape(value)}" ${activity.status.toLocaleLowerCase('pt-BR') === value ? 'selected' : ''}>${escape(value)}</option>`).join('')}</select></label><label>Progresso %<input name="activityProgress" type="number" min="0" max="100" value="${escape(activity.progress)}"></label><label>Início<input name="activityStart" type="date" value="${escape(activity.plannedStart)}"></label><label>Fim<input name="activityEnd" type="date" value="${escape(activity.plannedEnd)}"></label><button type="button" class="button button-ghost" data-stage-editor-remove-activity>Remover</button></fieldset>`;
};

/** Render and bind the worker stage authoring form; semantic save command stays in program.ts. */
export function mountAtlasWorkerStageAdminEditorV1(input: {
  root: HTMLElement;
  model: AtlasWorkerStageAdminEditorModelV1;
}): AtlasWorkerStageAdminEditorViewV1 {
  const { root, model } = input;
  const escape = escapeAtlasWorkerStageAdminHtmlV1;
  const title = model.isNew ? 'Adicionar etapa' : 'Editar etapa';
  const activities = model.activities.length ? model.activities : [{
    id: '', name: '', category: model.defaultActivityCategory, status: model.activityStatuses[0] || 'planejado',
    progress: '0', plannedStart: '', plannedEnd: '',
  }];
  root.innerHTML = `<header class="worker-header"><a class="worker-brand" href="${escape(model.homeHref)}"><span class="brand-symbol">◢</span><span><strong>ALIANÇA PARK</strong><small>WORKERS · FORMULÁRIO DE ETAPA</small></span></a><a class="header-link" href="${escape(model.adminHref)}">Admin</a></header><main class="worker-main worker-detail stage-editor-page"><a class="detail-back" href="${escape(model.cancelHref)}">← Cancelar e voltar</a><section class="detail-hero"><span class="eyebrow">${model.isNew ? 'NOVA FRENTE' : `ETAPA · ${escape(model.key)}`}</span><h1>${title}</h1><p>Defina a etapa, seus critérios de execução e as atividades que o worker deverá acompanhar.</p></section><form data-stage-editor data-stage-id="${escape(model.stageId)}"><section class="detail-block"><h2>Identificação e execução</h2><div class="stage-editor-grid"><label>Nome da etapa<input name="name" required value="${escape(model.name)}" placeholder="Ex.: Drenagem complementar"></label><label>Responsável<input name="owner" value="${escape(model.owner)}" placeholder="Equipe ou encarregado"></label><label>Situação<select name="status">${model.stageStatuses.map(value => `<option value="${escape(value)}" ${model.status.toLocaleLowerCase('pt-BR') === value ? 'selected' : ''}>${escape(value)}</option>`).join('')}</select></label><label>Progresso %<input name="progress" type="number" min="0" max="100" value="${escape(model.progress)}"></label><label>Fase / semana<input name="week" value="${escape(model.week)}" placeholder="Ex.: Semana 03"></label><label class="stage-editor-wide">Descrição típica<textarea name="typicalDescription" rows="4" placeholder="Escopo, condições e ordem de execução.">${escape(model.typicalDescription)}</textarea></label><label class="stage-editor-wide">Requisitos do worker <small>uma linha por requisito</small><textarea name="requirements" rows="4">${escape(model.requirements)}</textarea></label></div></section><section class="detail-block"><header class="stage-editor-section-head"><div><h2>Atividades da etapa</h2><p>Os itens passam a compor a agenda e a leitura do worker.</p></div><button type="button" class="button button-primary" data-stage-editor-add-activity>＋ Adicionar atividade</button></header><div class="stage-editor-activities" data-stage-editor-activities>${activities.map(activity => atlasWorkerStageEditorActivityMarkupV1(activity, model.activityStatuses)).join('')}</div></section><footer class="stage-editor-footer"><p data-stage-editor-status>Revise os dados antes de salvar. A atualização ficará disponível para o worker no próximo ciclo.</p><button type="submit" class="button button-primary">Salvar etapa e atividades</button></footer></form></main>`;
  const form = root.querySelector<HTMLFormElement>('[data-stage-editor]')!;
  const list = root.querySelector<HTMLElement>('[data-stage-editor-activities]')!;
  const add = root.querySelector<HTMLButtonElement>('[data-stage-editor-add-activity]');
  const status = root.querySelector<HTMLElement>('[data-stage-editor-status]');
  const submit = form.querySelector<HTMLButtonElement>('[type="submit"]');
  add?.addEventListener('click', () => {
    const activity: AtlasWorkerStageAdminActivityV1 = {
      id: '', name: '', category: model.defaultActivityCategory, status: model.activityStatuses[0] || 'planejado',
      progress: '0', plannedStart: '', plannedEnd: '',
    };
    list.insertAdjacentHTML('beforeend', atlasWorkerStageEditorActivityMarkupV1(activity, model.activityStatuses));
    list.lastElementChild?.querySelector<HTMLInputElement>('[name="activityName"]')?.focus();
  });
  list.addEventListener('click', event => {
    const target = event.target;
    if (target instanceof Element) target.closest('[data-stage-editor-remove-activity]')?.closest('[data-stage-editor-activity]')?.remove();
  });
  form.addEventListener('submit', event => {
    event.preventDefault();
    root.dispatchEvent(new CustomEvent('atlas:worker-stage-admin-save', { bubbles: true, composed: true, detail: { form } }));
  });
  return {
    form,
    setStatus(message) { if (status) status.textContent = message; },
    setSaving(saving) { if (submit) submit.disabled = saving; },
  };
}

/** Render the worker stage detail; the test command is delegated to program.ts. */
export function mountAtlasWorkerStageAdminDetailV1(input: {
  root: HTMLElement;
  model: AtlasWorkerStageAdminDetailModelV1;
}): AtlasWorkerStageAdminDetailViewV1 {
  const { root, model } = input;
  const escape = escapeAtlasWorkerStageAdminHtmlV1;
  const list = (items: readonly string[], fallback: string): string => items.length
    ? items.map(item => `<li>${escape(item)}</li>`).join('')
    : `<li>${escape(fallback)}</li>`;
  const materialRows = model.materialRows.map(item => `<tr><td><b>${escape(item.name)}</b>${item.inventory ? `<small>estoque: ${escape(item.inventory)}</small>` : ''}</td><td>${escape(item.required)}</td><td>${escape(item.available)}</td><td class="${item.critical ? 'is-critical' : ''}">${escape(item.coverage)}%</td></tr>`).join('')
    || '<tr><td colspan="4">Nenhum material físico calculado para esta etapa.</td></tr>';
  const crewRows = model.crewRows.map(item => `<li><b>${escape(item.count)}×</b> ${escape(item.role)}</li>`).join('') || '<li>Equipe não definida.</li>';
  const profileMaterials = list(model.profileMaterials, 'Materiais ainda não dimensionados.');
  const relationRows = model.relationRows.map(item => `<li><b>${escape(item.direction)}</b> ${escape(item.label)} <small>${escape(item.type)}</small></li>`).join('') || '<li>Sem relação registrada.</li>';
  const activities = model.activities.map(item => `<div class="activity-row"><strong>${escape(item.name)}</strong><em>${escape(item.status)}</em><span>${escape(item.ownerAndDate)}</span></div>`).join('') || '<div class="empty-state">Nenhuma atividade planejada nesta etapa.</div>';
  root.innerHTML = `<header class="worker-header"><a class="worker-brand" href="${escape(model.homeHref)}"><span class="brand-symbol">◢</span><span><strong>ALIANÇA PARK</strong><small>WORKERS · ETAPA DEDICADA</small></span></a><a class="header-link" href="${escape(model.adminHref)}">Admin</a></header><main class="worker-main worker-detail"><a class="detail-back" href="${escape(model.homeHref)}">← Voltar à monitoria</a><section class="detail-hero"><span class="eyebrow">ETAPA · ${escape(model.key)}</span><h1>${escape(model.name)}</h1><p>${escape(model.typicalDescription)}</p><div class="detail-status"><span>${escape(model.status)}</span><span>${escape(model.progress)}% realizado</span><span>Caixa ${escape(model.cashCoverage)}%</span><span>Prioridade ${escape(model.priority)}</span></div><button type="button" class="button button-primary" data-detail-test>Testar gatilho desta etapa</button></section><section class="detail-grid"><article><small>INÍCIO INFERIDO</small><strong>${escape(model.plannedStart)}</strong></article><article><small>PREVISÃO</small><strong>${escape(model.plannedFinish)}</strong></article><article><small>VOLUME BASE DWG</small><strong>${escape(model.productionQuantity)}</strong></article><article><small>RITMO AJUSTADO</small><strong>${escape(model.productionRate)}</strong></article><article><small>EQUIPE REGISTRADA</small><strong>${escape(model.assignedCrew)}</strong></article><article><small>DEPENDÊNCIAS</small><strong>${escape(model.dependencies)}</strong></article></section><section class="detail-block"><h2>Projeção física e disponibilidade</h2><p class="detail-note">${escape(model.productionBasis)}</p><div class="detail-subgrid"><div><h3>MATERIAIS CALCULADOS</h3><div class="physical-table-wrap"><table class="physical-table"><thead><tr><th>Material</th><th>Necessário</th><th>Disponível</th><th>Cobertura</th></tr></thead><tbody>${materialRows}</tbody></table></div></div><div><h3>EQUIPE PREVISTA</h3><ul class="compact-list">${crewRows}</ul><p class="detail-note">${escape(model.crewNames)}</p><span class="status-pill status-${escape(model.personnelStatus)}">${escape(model.personnelStatus === 'ready' ? 'equipe suficiente' : model.personnelStatus === 'registration_pending' ? 'equipe a cadastrar' : 'equipe parcial')}</span></div></div></section><section class="detail-block"><h2>Diretrizes que alimentam o worker</h2><h3>REQUISITOS</h3><ul>${list(model.requirements, 'Nenhum requisito cadastrado.')}</ul><h3>CONDIÇÕES DE LIBERAÇÃO</h3><ul>${list(model.conditions, 'Nenhuma condição cadastrada.')}</ul><h3>MATERIAIS E RECURSOS DE PERFIL</h3><ul>${profileMaterials}</ul></section><section class="detail-block"><h2>Fluxo planejado e agenda</h2><p class="detail-note">${escape(model.activityRule)}</p>${activities}</section><section class="detail-block"><h2>Correlações e sobreposições</h2><div class="detail-subgrid"><div><h3>RELAÇÕES</h3><ul class="compact-list">${relationRows}</ul></div><div><h3>REGRA DA FRENTE</h3><p class="detail-note">Modo: <b>${escape(model.overlapMode)}</b><br>${escape(model.overlapRule)}</p><p class="detail-note">Confirmações de campo e documentos continuam humanas; a IA apenas organiza e sugere a propagação.</p></div></div></section></main><footer class="worker-footer"><span>Aliança Park · etapa dedicada</span><a href="${escape(model.homeHref)}">Monitoria geral</a></footer>`;
  const runTestButton = root.querySelector<HTMLButtonElement>('[data-detail-test]');
  runTestButton?.addEventListener('click', () => root.dispatchEvent(new CustomEvent('atlas:worker-stage-admin-test', { bubbles: true, composed: true })));
  return {
    runTestButton,
    setTestButton(label, disabled) { if (runTestButton) { runTestButton.textContent = label; runTestButton.disabled = disabled; } },
  };
}

/** Render a recoverable worker-stage route error through the typed page owner. */
export function mountAtlasWorkerStageAdminErrorV1(input: { root: HTMLElement; message: string; homeHref: string }): void {
  const escape = escapeAtlasWorkerStageAdminHtmlV1;
  input.root.innerHTML = `<main class="worker-main"><a class="detail-back" href="${escape(input.homeHref)}">← Monitoria</a><section class="detail-hero"><h1>Falha ao abrir a etapa</h1><p>${escape(input.message)}</p></section></main>`;
}

export type AtlasStageAdministrationTabV1 = 'overview' | 'activities' | 'purchases' | 'materials' | 'services' | 'records' | 'history';
interface AtlasStageAdministrationPresentationCatalogV1 {
  tabs: Array<{ key: AtlasStageAdministrationTabV1; label: string }>;
  stageStatuses: Array<{ value: string; label: string }>;
  columns: Record<'activities' | 'purchases' | 'materials' | 'services' | 'records', string[]>;
  emptyStates: Record<'activities' | 'purchases' | 'receipts' | 'materials' | 'services' | 'records' | 'history', string>;
  kpis: Record<'activities' | 'purchases' | 'materials' | 'services' | 'evidence' | 'cash', { label: string; note?: string }>;
}
const atlasStageAdministrationPresentationV1 = stageAdministrationPresentationData as AtlasStageAdministrationPresentationCatalogV1;
const atlasStageAdministrationHeadersV1 = (group: keyof AtlasStageAdministrationPresentationCatalogV1['columns']): string =>
  atlasStageAdministrationPresentationV1.columns[group].map(label => `<th>${escapeAtlasStageAdministrationHtmlV1(label)}</th>`).join('');
