/** Own the admin cash evidence form, canvas gestures, and submit command binding. */
export function mountAtlasAdminCashEvidenceFormV1(input: AtlasAdminCashEvidenceFormInputV1): AtlasAdminCashEvidenceFormViewV1 {
  const { documentRef, windowRef } = input;
  const today = (): string => new windowRef.Date().toISOString().slice(0, 10);
  const enhance = (): void => {
    const page = documentRef.querySelector('view-layer[data-view="finance"],.finance-control-page');
    if (!page) return;
    let form = page.querySelector<HTMLFormElement>('form[data-v8-cash-entry]');
    if (!form) {
      const boundary = page.querySelector('.role-boundary-notice');
      if (boundary) {
        const holder = documentRef.createElement('div');
        holder.innerHTML = renderAtlasAdminCashEvidenceBlankFormV1(today(), input.stageNames);
        boundary.replaceWith(holder.firstElementChild!);
        form = page.querySelector<HTMLFormElement>('form[data-v8-cash-entry]');
      }
    }
    if (!form) return;
    form.dataset.cashEvidenceV11 = '1';
    if (!form.querySelector('[data-cash-evidence]')) form.querySelector('footer')?.insertAdjacentHTML('beforebegin', renderAtlasAdminCashEvidenceProofV1());
    const canvas = form.querySelector<HTMLCanvasElement>('[data-cash-signature]');
    if (canvas && !canvas.dataset.bound) {
      canvas.dataset.bound = '1';
      const context = canvas.getContext('2d');
      if (context) {
        context.lineCap = 'round'; context.lineJoin = 'round'; context.lineWidth = 3; context.strokeStyle = '#f4f4f4';
        let active = false, last: { x: number; y: number } | null = null;
        const point = (event: PointerEvent): { x: number; y: number } => {
          const rect = canvas.getBoundingClientRect();
          return { x: (event.clientX - rect.left) * canvas.width / rect.width, y: (event.clientY - rect.top) * canvas.height / rect.height };
        };
        canvas.addEventListener('pointerdown', event => {
          event.preventDefault(); active = true; last = point(event); canvas.dataset.dirty = '1'; canvas.setPointerCapture?.(event.pointerId);
        });
        canvas.addEventListener('pointermove', event => {
          if (!active || !last) return;
          event.preventDefault(); const next = point(event); context.beginPath(); context.moveTo(last.x, last.y); context.lineTo(next.x, next.y); context.stroke(); last = next;
        });
        const finish = (event: PointerEvent): void => {
          active = false; last = null;
          try { canvas.releasePointerCapture?.(event.pointerId); } catch { /* pointer may already be released */ }
        };
        canvas.addEventListener('pointerup', finish); canvas.addEventListener('pointercancel', finish);
      }
    }
    const clear = form.querySelector<HTMLButtonElement>('[data-cash-sign-clear]');
    if (clear && !clear.dataset.bound) {
      clear.dataset.bound = '1';
      clear.addEventListener('click', () => {
        const target = form?.querySelector<HTMLCanvasElement>('[data-cash-signature]');
        target?.getContext('2d')?.clearRect(0, 0, target.width, target.height);
        if (target) delete target.dataset.dirty;
      });
    }
  };
  const view: AtlasAdminCashEvidenceFormViewV1 = {
    setStatus(form, message, busy = false): void {
      const status = form.querySelector<HTMLElement>('[data-v8-cash-status]');
      const button = form.querySelector<HTMLButtonElement>('button[type="submit"]');
      if (status) status.textContent = message;
      if (button) button.disabled = busy;
    },
    reset(form): void {
      form.reset();
      const canvas = form.querySelector<HTMLCanvasElement>('[data-cash-signature]');
      canvas?.getContext('2d')?.clearRect(0, 0, canvas.width, canvas.height);
      if (canvas) delete canvas.dataset.dirty;
    },
    dispose(): void { observer.disconnect(); documentRef.removeEventListener('submit', onSubmit, true); },
  };
  const onSubmit = (event: Event): void => {
    const target = event.target as Element | null;
    const form = target?.closest?.('form[data-v8-cash-entry][data-cash-evidence-v11]') as HTMLFormElement | null;
    if (!form) return;
    event.preventDefault(); event.stopImmediatePropagation(); input.onSubmit(form, view);
  };
  const observer = new windowRef.MutationObserver(enhance);
  documentRef.addEventListener('submit', onSubmit, true);
  if (documentRef.documentElement) observer.observe(documentRef.documentElement, { childList: true, subtree: true });
  windowRef.queueMicrotask(enhance);
  return view;
}

export interface AtlasAdminMapContextPresentationInputV1 {
  documentRef: Document;
  windowRef: Window & typeof globalThis;
  registry: CustomElementRegistry;
}

function patchAtlasAdminMapContextPresentationV1(input: AtlasAdminMapContextPresentationInputV1): void {
  const MapScene = input.registry.get('map-scene') as (CustomElementConstructor & { prototype: any }) | undefined;
  if (MapScene && !MapScene.prototype.__adminMapV11) {
    MapScene.prototype.__adminMapV11 = true;
    const previous = MapScene.prototype.setMapContext;
    MapScene.prototype.setMapContext = function (this: any, view: string): unknown {
      const result = previous?.call(this, view);
      const isPublic = this.hasAttribute('data-public-presentation') && !this.isAdminPublicMapV1?.();
      this.dataset.mapContext = isPublic ? 'public-leads' : view;
      const category = this.querySelector('.map-category-switcher');
      const rotation = this.querySelector('.map-rotation-controls');
      const legend = this.querySelector('.map-gesture-legend');
      const badge = this.querySelector('.map-badge');
      const interactiveViews = new Set(['assistant', 'map', 'records']);
      if (category) category.hidden = isPublic || !interactiveViews.has(view);
      if (rotation) rotation.hidden = isPublic || !interactiveViews.has(view);
      if (legend) legend.hidden = isPublic || !interactiveViews.has(view);
      if (badge) badge.hidden = isPublic || !interactiveViews.has(view);
      if (isPublic) this.dataset.mapControls = 'public-disabled';
      else if (view === 'map') this.dataset.mapControls = 'admin-map-enabled';
      return result;
    };
  }
  const ViewLayer = input.registry.get('view-layer') as (CustomElementConstructor & { prototype: any }) | undefined;
  if (ViewLayer && !ViewLayer.prototype.__adminMapViewV11) {
    ViewLayer.prototype.__adminMapViewV11 = true;
    const previous = ViewLayer.prototype.map;
    ViewLayer.prototype.map = function (this: any): string { return String(previous.call(this)).replace('<stage-cash-dashboard></stage-cash-dashboard>', ''); };
  }
  input.documentRef.querySelectorAll('map-scene').forEach(map => {
    const publicMap = map.hasAttribute('data-public-presentation') && !(map as HTMLElement & { isAdminPublicMapV1?: () => boolean }).isAdminPublicMapV1?.();
    const view = publicMap ? 'public-leads' : (input.documentRef.querySelector<HTMLElement>('view-layer')?.dataset.view || 'map');
    (map as HTMLElement & { setMapContext?: (value: string) => void }).setMapContext?.(view);
  });
}

/** Keep admin/public map controls aligned with the current view and presentation mode. */
export function installAtlasAdminMapContextPresentationV1(input: AtlasAdminMapContextPresentationInputV1): () => void {
  let frame = 0;
  let disposed = false;
  const patch = (): void => {
    frame = 0;
    if (!disposed && input.documentRef.querySelector('view-layer[data-view="map"],map-scene')) patchAtlasAdminMapContextPresentationV1(input);
  };
  const schedule = (): void => {
    if (disposed || frame) return;
    frame = input.windowRef.requestAnimationFrame(patch);
  };
  const subscription = subscribeAtlasComponentMutationHubV1(input.documentRef, input.windowRef, records => {
    const relevant = records.some(record => {
      if (record.type === 'attributes') {
        return record.attributeName === 'data-view' && record.target instanceof Element && record.target.matches('view-layer');
      }
      if (record.type !== 'childList') return false;
      const target = record.target instanceof Element ? record.target : record.target.parentElement;
      if (target?.closest('map-scene,view-layer')) return true;
      return [...record.addedNodes].some(node => node instanceof Element && (node.matches('map-scene,view-layer') || Boolean(node.querySelector('map-scene,view-layer'))));
    });
    if (relevant) schedule();
  });
  void input.registry.whenDefined('map-scene').then(schedule);
  void input.registry.whenDefined('view-layer').then(schedule);
  input.windowRef.queueMicrotask(schedule);
  return () => { disposed = true; if (frame) input.windowRef.cancelAnimationFrame(frame); subscription.unsubscribe(); };
}

interface AtlasAdminPublicMapRuntimeCatalogV1 {
  selector: string;
  staticMapInit: string;
  observerTimeoutMs: number;
  georeferenceUrl: string;
  georeferenceRetryCount: number;
  georeferenceRetryMs: number;
  centerControlPointId: string;
  georeferenceZoom: number;
  camera: { panX: number; panY: number; rotation: number; tilt: number; zoom: number; sceneZoom: number };
  surfaceLabels: { source: string; preset: string; rotationLock: string; base: string; textureReady: string; textureUnavailable: string; staticBridge: string };
  status: { probe: string; intervalMs: number; warningAfterMs: number; marker: string };
}

export interface AtlasAdminMapComponentControllerInputV1 extends AtlasAdminMapContextPresentationInputV1 {
  loadGeoreference(url: string): Promise<Record<string, any>>;
}

export interface AtlasAdminMapComponentControllerV1 { dispose(): void }

const atlasAdminMapComponentControllersV1 = new WeakMap<Document, AtlasAdminMapComponentControllerV1>();
const atlasAdminPublicMapRuntimeCatalogV1 = adminPublicMapSurfaceData as AtlasAdminPublicMapRuntimeCatalogV1;

/** Own map chrome, satellite preset, 3D status, and material readiness as one component controller. */
export function installAtlasAdminMapComponentControllerV1(
  input: AtlasAdminMapComponentControllerInputV1,
): AtlasAdminMapComponentControllerV1 {
  const mounted = atlasAdminMapComponentControllersV1.get(input.documentRef);
  if (mounted) return mounted;

  const { documentRef, windowRef } = input;
  const config = atlasAdminPublicMapRuntimeCatalogV1;
  const globals = globalThis as Record<string, unknown>;
  const ownerKeys = ['__belavistaAdminPublicMapBridgeV5352', config.status.marker, '__belavistaAdminPublicMapMaterialsV50'];
  ownerKeys.forEach(key => { globals[key] = true; });
  documentRef.documentElement.dataset.adminPublicMapSurfaceOwnerV1 = 'typescript';
  documentRef.documentElement.dataset.adminPublicMap3dStatusOwnerV1 = 'typescript';
  documentRef.documentElement.dataset.adminPublicMapMaterialsOwnerV1 = 'typescript';
  documentRef.documentElement.dataset.adminMapComponentRuntimeOwnerV1 = 'typescript';

  const contextInput: AtlasAdminMapContextPresentationInputV1 = {
    documentRef, windowRef, registry: input.registry,
  };
  let disposed = false;
  let frame = 0;
  const timeouts = new Set<number>();
  const probes = new Map<AtlasAdminPublicMapSceneElementV1, number>();
  const warnings = new Map<AtlasAdminPublicMapSceneElementV1, number>();
  const environment = atlasPublicMapEnvironment();

  const setTimeoutTracked = (callback: () => void, delay: number): number => {
    const timer = windowRef.setTimeout(() => { timeouts.delete(timer); callback(); }, delay);
    timeouts.add(timer);
    return timer;
  };
  const clearProbe = (map: AtlasAdminPublicMapSceneElementV1): void => {
    const timer = probes.get(map);
    if (timer !== undefined) windowRef.clearInterval(timer);
    probes.delete(map);
  };
  const alignDwgSatelliteFrame = async (map: AtlasAdminPublicMapSceneElementV1, attempt = 0): Promise<void> => {
    if (disposed || !map.isConnected || map.dataset.adminPublicGeoState === 'error') return;
    if (!map.THREE || !map.mapSurface) {
      if (attempt < config.georeferenceRetryCount) setTimeoutTracked(() => { void alignDwgSatelliteFrame(map, attempt + 1); }, config.georeferenceRetryMs);
      return;
    }
    if (map.dataset.adminPublicGeoState === 'ready' || map.dataset.adminPublicGeoState === 'loading') return;
    map.dataset.adminPublicGeoState = 'loading';
    try {
      const geo = await input.loadGeoreference(config.georeferenceUrl);
      if (disposed || !map.isConnected) return;
      const controlPoints = Array.isArray(geo.controlPoints) ? geo.controlPoints as Array<Record<string, unknown>> : [];
      const center = controlPoints.find(point => point.id === config.centerControlPointId) || controlPoints[0];
      const latitude = Number(center?.lat), longitude = Number(center?.lng);
      if (!Number.isFinite(latitude) || !Number.isFinite(longitude)) throw new Error('Centro GPS ausente no DWG');
      const theme = { center: [latitude, longitude] as [number, number], zoom: config.georeferenceZoom };
      map.dwgGeo = geo;
      map._publicGeoTheme = theme;
      map._mapSurfaceKey = '';
      map._lastRasterSignature = '';
      map.mapSurface.visible = true;
      map.setMapTileMode?.('satellite', false);
      map.refreshMapSurface?.(theme, windowRef.innerWidth, windowRef.innerHeight);
      map.dataset.adminPublicDwgCenter = `${latitude.toFixed(8)},${longitude.toFixed(8)}`;
      const crs = geo.crs && typeof geo.crs === 'object' ? geo.crs as Record<string, unknown> : {};
      map.dataset.adminPublicDwgCrs = `EPSG:${crs.epsg || '31984'}`;
      map.dataset.adminPublicGeoState = 'ready';
      map.dataset.publicMapTexture = config.surfaceLabels.textureReady;
    } catch (error) {
      map.dataset.adminPublicGeoState = 'error';
      map.dataset.publicMapTexture = config.surfaceLabels.textureUnavailable;
      windowRef.console.warn('[Belavista admin v5.3.52] base satélite do DWG indisponível.', error);
    }
  };
  const configureSurface = (candidate: Element | null): void => {
    if (!candidate || disposed) return;
    const map = candidate as AtlasAdminPublicMapSceneElementV1;
    const result = applyAtlasAdminPublicMapSurfacePresetV1({
      map, documentRef,
      view: { ...config.surfaceLabels, staticMapInit: config.staticMapInit, camera: config.camera },
    });
    if (result === 'configured') void alignDwgSatelliteFrame(map);
  };
  const attachStatus = (candidate: Element | null): void => {
    if (!candidate || disposed) return;
    const map = candidate as AtlasAdminPublicMapSceneElementV1;
    if (map.dataset.admin3dProbe === config.status.probe || map.dataset.admin3dProbe === 'static-first-isolated') return;
    if (map.dataset.mapInit === config.staticMapInit) {
      setAtlasAdminPublicMap3dStatusV1(map, { probe: 'static-first-isolated', state: 'idle-explicit-activation' });
      return;
    }
    setAtlasAdminPublicMap3dStatusV1(map, { probe: config.status.probe, state: map.modelReady ? 'ready' : 'loading' });
    const started = windowRef.performance.now();
    const timer = windowRef.setInterval(() => {
      if (!map.isConnected) { clearProbe(map); return; }
      if (map.modelReady || map.dataset.modelReady === 'true') {
        setAtlasAdminPublicMap3dStatusV1(map, { state: 'ready', readyMs: Math.round(windowRef.performance.now() - started) });
        clearProbe(map);
        return;
      }
      const error = map.dataset.modelError || map.dataset.threeError;
      if (error) {
        setAtlasAdminPublicMap3dStatusV1(map, { state: 'error' });
        windowRef.console.error('[BELAVISTA v5.3.53] mapa 3D falhou', {
          error, three: map.dataset.three, modelRender: map.dataset.modelRender,
          modelSource: map.dataset.modelSource, modelProgress: map.dataset.modelProgress,
        });
        clearProbe(map);
      }
    }, config.status.intervalMs);
    probes.set(map, timer);
    const warning = windowRef.setTimeout(() => {
      warnings.delete(map);
      if (map.modelReady || map.dataset.modelReady === 'true' || !map.isConnected) return;
      windowRef.console.warn('[BELAVISTA v5.3.53] mapa 3D ainda não pronto após 8s', {
        mapInit: map.dataset.mapInit, three: map.dataset.three,
        modelError: map.dataset.modelError, modelProgress: map.dataset.modelProgress,
        modelRender: map.dataset.modelRender,
      });
    }, config.status.warningAfterMs);
    warnings.set(map, warning);
  };
  const tuneMaterials = (candidate: Element | null): void => {
    if (!candidate || disposed) return;
    const map = candidate as AtlasAdminPublicMapSceneElementV1 & Record<string, any>;
    if (map.dataset.publicMapTsOwner) return;
    map.setAttribute('data-public-presentation', 'true');
    if (applyAtlasAdminPublicMapNaturalMaterialsV1({ map, environment })) map.dataset.publicMapTsOwner = 'true';
  };
  const refresh = (): void => {
    frame = 0;
    if (disposed) return;
    patchAtlasAdminMapContextPresentationV1(contextInput);
    const map = documentRef.querySelector(config.selector);
    configureSurface(map);
    attachStatus(map);
    tuneMaterials(documentRef.querySelector('map-scene[data-public-presentation],map-scene[data-public-map]'));
  };
  const schedule = (): void => {
    if (disposed || frame) return;
    frame = windowRef.requestAnimationFrame(refresh);
  };
  const mutationSubscription = subscribeAtlasComponentMutationHubV1(documentRef, windowRef, records => {
    const relevant = records.some(record => {
      if (record.type === 'attributes') {
        const target = record.target instanceof Element ? record.target : null;
        return Boolean(target?.matches('map-scene,view-layer') && ['data-view', 'data-model-ready', 'data-model-enrichment'].includes(record.attributeName || ''));
      }
      if (record.type !== 'childList') return false;
      const target = record.target instanceof Element ? record.target : record.target.parentElement;
      if (target?.closest('map-scene,view-layer')) return true;
      return [...record.addedNodes].some(node => node instanceof Element && (node.matches('map-scene,view-layer') || Boolean(node.querySelector('map-scene,view-layer'))));
    });
    if (relevant) schedule();
  });
  const controller: AtlasAdminMapComponentControllerV1 = {
    dispose(): void {
      if (disposed) return;
      disposed = true;
      if (frame) windowRef.cancelAnimationFrame(frame);
      mutationSubscription.unsubscribe();
      timeouts.forEach(timer => windowRef.clearTimeout(timer));
      timeouts.clear();
      probes.forEach(timer => windowRef.clearInterval(timer));
      probes.clear();
      warnings.forEach(timer => windowRef.clearTimeout(timer));
      warnings.clear();
      ownerKeys.forEach(key => { delete globals[key]; });
      delete documentRef.documentElement.dataset.adminPublicMapSurfaceOwnerV1;
      delete documentRef.documentElement.dataset.adminPublicMap3dStatusOwnerV1;
      delete documentRef.documentElement.dataset.adminPublicMapMaterialsOwnerV1;
      delete documentRef.documentElement.dataset.adminMapComponentRuntimeOwnerV1;
      atlasAdminMapComponentControllersV1.delete(documentRef);
    },
  };
  atlasAdminMapComponentControllersV1.set(documentRef, controller);
  void input.registry.whenDefined('map-scene').then(schedule);
  void input.registry.whenDefined('view-layer').then(schedule);
  schedule();
  return controller;
}

