/** Translate workspace gestures into explicit commands for the program owner. */
export function bindAtlasExecutionPlanningCommandsV1(root: Document): () => void {
  const command = (name: string, detail: Record<string, unknown> = {}): void => { root.dispatchEvent(new CustomEvent(name, { bubbles: true, composed: true, detail })); };
  const onSubmit = (event: Event): void => {
    const target = event.target instanceof HTMLFormElement ? event.target : null;
    if (!target) return;
    if (target.matches('[data-v8-cash-form]')) { event.preventDefault(); command('atlas:execution-planning-cash-submit', { form: target }); }
    else if (target.matches('[data-v8-reason-form]')) { event.preventDefault(); command('atlas:execution-planning-commission-save', { form: target, id: target.dataset.v8ReasonForm || '' }); }
    else if (target.matches('[data-v8-outsourcing-form]')) { event.preventDefault(); command('atlas:execution-planning-outsourcing-submit', { form: target }); }
  };
  const onClick = (event: Event): void => {
    const target = event.target instanceof Element ? event.target : null;
    const focus = target?.closest<HTMLElement>('[data-v8-focus-stage]');
    if (focus) { command('atlas:execution-planning-focus-stage', { stageId: focus.dataset.v8FocusStage || '' }); return; }
    if (target?.closest('[data-v8-cash-close]')) command('atlas:execution-planning-cash-close');
  };
  root.addEventListener('submit', onSubmit, true);
  root.addEventListener('click', onClick, true);
  return () => { root.removeEventListener('submit', onSubmit, true); root.removeEventListener('click', onClick, true); };
}

export type AtlasDashboardMapModeV1 = 'visualization' | 'progress';

export function renderAtlasDashboardMapTabsV1(mode: AtlasDashboardMapModeV1): string {
  return `<nav class="map-dashboard-tabs-v3" aria-label="Modos de visualização do dashboard"><button type="button" data-map-dashboard-tab="visualization" aria-pressed="${mode === 'visualization'}">⌖ <span>Visualização</span></button><button type="button" data-map-dashboard-tab="progress" aria-pressed="${mode === 'progress'}">≋ <span>Andamento e etapas</span></button></nav>`;
}

export function bindAtlasDashboardMapTabCommandsV1(root: Document): () => void {
  const onClick = (event: Event): void => {
    const target = event.target instanceof Element ? event.target : null;
    const button = target?.closest<HTMLButtonElement>('[data-map-dashboard-tab]');
    if (!button) return;
    event.preventDefault(); event.stopPropagation();
    const mode = button.dataset.mapDashboardTab;
    if (mode === 'visualization' || mode === 'progress') {
      root.dispatchEvent(new CustomEvent('atlas:dashboard-map-mode', { bubbles: true, composed: true, detail: { mode } }));
    }
  };
  const onPointerDown = (event: Event): void => {
    if ((event.target instanceof Element ? event.target : null)?.closest('[data-map-dashboard-tab]')) event.stopPropagation();
  };
  root.addEventListener('click', onClick, true);
  root.addEventListener('pointerdown', onPointerDown, true);
  return () => { root.removeEventListener('click', onClick, true); root.removeEventListener('pointerdown', onPointerDown, true); };
}

