  return `<button type="button" class="icon-btn compact chat-tab-toggle-v5359" data-chat-tab-toggle-v5359="true" data-chat-tab-owner-v5359="typescript" data-state="${collapsed ? 'collapsed' : 'expanded'}" aria-label="${label}" title="${title}"><span data-chat-tab-glyph-v5359 aria-hidden="true">${glyph}</span></button>`;
