/** Bind the chat tab's native control and publish only a semantic command. */
export function bindAtlasChatTabToggleCommandsV5359(button: HTMLButtonElement, documentRef: Document): () => void {
  const onPointerDown = (event: PointerEvent): void => event.stopPropagation();
  const onClick = (event: MouseEvent): void => {
    event.preventDefault();
    event.stopPropagation();
    const chat = button.closest<HTMLElement>('ai-chat');
    if (!chat) return;
    documentRef.dispatchEvent(new CustomEvent('atlas:chat-tab-toggle-v5359', { detail: { chat } }));
  };
  button.addEventListener('pointerdown', onPointerDown);
  button.addEventListener('click', onClick);
  return () => {
    button.removeEventListener('pointerdown', onPointerDown);
    button.removeEventListener('click', onClick);
  };
}

