export interface AtlasAdminLotsCanvasNodeV1 { x: number; y: number; label: string; comment: string; groupId: string }
export interface AtlasAdminLotsCanvasLotV1 { id: string; label: string; block: string; area: string; node: AtlasAdminLotsCanvasNodeV1 }
export interface AtlasAdminLotsCanvasGroupV1 { id: string; name: string; note: string; x: number; y: number; w: number; h: number; lotCount: number }
export interface AtlasAdminLotsCanvasRelationV1 { id: string; from: string; to: string; label: string }
export interface AtlasAdminLotsCanvasViewModelV1 {
  stageWidth: number; stageHeight: number; nodeWidth: number; nodeHeight: number; zoom: number;
  lots: AtlasAdminLotsCanvasLotV1[]; groups: AtlasAdminLotsCanvasGroupV1[]; relations: AtlasAdminLotsCanvasRelationV1[];
  selected: string | null; relationSource: string | null; savedLabel: string;
}
export interface AtlasAdminLotsCanvasCommandV1 { type: string; [key: string]: unknown }

function atlasAdminLotsCanvasEntityCenterV1(model: AtlasAdminLotsCanvasViewModelV1, id: string): { x: number; y: number } | null {
  if (id.startsWith('lot:')) {
    const lot = model.lots.find(item => item.id === id.slice(4));
    return lot ? { x: lot.node.x + model.nodeWidth / 2, y: lot.node.y + model.nodeHeight / 2 } : null;
  }
  if (id.startsWith('group:')) {
    const group = model.groups.find(item => item.id === id.slice(6));
    return group ? { x: group.x + group.w / 2, y: group.y + group.h / 2 } : null;
  }
  return null;
}

function renderAtlasAdminLotsCanvasRelationsV1(model: AtlasAdminLotsCanvasViewModelV1): string {
  const esc = escapeAtlasStageAdministrationHtmlV1;
  return model.relations.map(relation => {
    const start = atlasAdminLotsCanvasEntityCenterV1(model, relation.from), end = atlasAdminLotsCanvasEntityCenterV1(model, relation.to);
    if (!start || !end) return '';
    const midX = (start.x + end.x) / 2, midY = (start.y + end.y) / 2;
    return `<g data-rel-id="${esc(relation.id)}"><path d="M ${start.x} ${start.y} C ${midX} ${start.y}, ${midX} ${end.y}, ${end.x} ${end.y}" /><rect x="${midX - 54}" y="${midY - 12}" width="108" height="24" rx="12"></rect><text x="${midX}" y="${midY + 4}" text-anchor="middle">${esc(relation.label || 'relaciona')}</text></g>`;
  }).join('');
}

function renderAtlasAdminLotsCanvasInspectorV1(model: AtlasAdminLotsCanvasViewModelV1): string {
  const esc = escapeAtlasStageAdministrationHtmlV1;
  const lot = model.selected?.startsWith('lot:') ? model.lots.find(item => item.id === model.selected!.slice(4)) : null;
  if (lot) return `<div class="inspector-kicker">LOTE SELECIONADO</div><h3>${esc(lot.node.label || lot.label)}</h3><dl><dt>Referência</dt><dd>${esc(lot.id)}</dd><dt>Quadra</dt><dd>${esc(lot.block || '—')}</dd><dt>Área</dt><dd>${esc(lot.area || '—')}</dd></dl><label>Rótulo do lote<input data-lot-label value="${esc(lot.node.label)}" placeholder="${esc(lot.label)}"></label><label>Grupo<select data-lot-group><option value="">Sem grupo</option>${model.groups.map(group => `<option value="${esc(group.id)}" ${lot.node.groupId === group.id ? 'selected' : ''}>${esc(group.name)}</option>`).join('')}</select></label><label>Comentário<textarea data-lot-comment rows="8" placeholder="Observação comercial, restrição, preferência, informação de campo…">${esc(lot.node.comment)}</textarea></label><div class="inspector-actions"><button data-start-relation="lot:${esc(lot.id)}">Relacionar</button><button class="danger" data-delete-relations-for="lot:${esc(lot.id)}">Remover relações</button></div>`;
  const group = model.selected?.startsWith('group:') ? model.groups.find(item => item.id === model.selected!.slice(6)) : null;
  if (group) return `<div class="inspector-kicker">GRUPO SELECIONADO</div><h3>${esc(group.name)}</h3><label>Nome<input data-group-name value="${esc(group.name)}"></label><label>Descrição<textarea data-group-note rows="6" placeholder="Função do agrupamento…">${esc(group.note || '')}</textarea></label><div class="inspector-actions"><button data-start-relation="group:${esc(group.id)}">Relacionar</button><button class="danger" data-delete-group="${esc(group.id)}">Excluir grupo</button></div>`;
  return `<div class="inspector-empty"><small>INSPECTOR</small><strong>Selecione um lote ou grupo</strong><p>Comentários pertencem ao lote. Grupos organizam os lotes e podem se relacionar por linhas rotuladas.</p></div>`;
}

/** Render the local lot-layout canvas. Persistent state and commands stay in program.ts. */
export function renderAtlasAdminLotsCanvasPageV1(root: HTMLElement, model: AtlasAdminLotsCanvasViewModelV1): void {
  const esc = escapeAtlasStageAdministrationHtmlV1;
  root.classList.add('admin-lots-canvas-page');
  root.dataset.relationMode = String(Boolean(model.relationSource));
  const groups = model.groups.map(group => `<section class="lot-group ${model.selected === `group:${group.id}` ? 'selected' : ''}" data-entity="group:${esc(group.id)}" style="left:${group.x}px;top:${group.y}px;width:${group.w}px;height:${group.h}px"><header data-group-drag><span><small>GRUPO</small><strong>${esc(group.name || 'Grupo')}</strong></span><b>${group.lotCount}</b></header><p>${esc(group.note || '')}</p></section>`).join('');
  const lots = model.lots.map(lot => `<button type="button" class="lot-node ${model.selected === `lot:${lot.id}` ? 'selected' : ''}" data-entity="lot:${esc(lot.id)}" style="left:${lot.node.x}px;top:${lot.node.y}px"><small>${esc(lot.block || 'LOTE')}</small><strong>${esc(lot.node.label.trim() || lot.label)}</strong><span>${lot.node.comment ? 'comentado' : (lot.area ? `${esc(lot.area)} m²` : 'sem comentário')}</span></button>`).join('');
  root.innerHTML = `<header class="lots-page-head"><div><small>COMERCIAL · INVENTÁRIO ESPACIAL</small><h1>Lotes</h1><p>Comentários, agrupamentos e relações entre lotes.</p></div><div class="lots-head-stats"><span><b data-lot-count>${model.lots.length}</b><small>lotes</small></span><span><b data-group-count>${model.groups.length}</b><small>grupos</small></span><span><b data-rel-count>${model.relations.length}</b><small>relações</small></span></div></header><div class="lots-toolbar"><button data-new-group>＋ Grupo</button><button data-rel-toolbar>↗ Relacionar</button><button data-zoom-out>−</button><button data-zoom-reset>100%</button><button data-zoom-in>＋</button><span data-relation-hint>${model.relationSource ? 'Selecione o segundo elemento da relação' : 'Clique em Relacionar e escolha dois elementos'}</span><i data-lots-save>${esc(model.savedLabel)}</i><button data-export>Exportar JSON</button><label class="import-button">Importar<input type="file" accept="application/json" data-import></label></div><div class="lots-layout"><div class="lots-canvas-viewport"><div class="lots-stage" data-lots-stage style="width:${model.stageWidth}px;height:${model.stageHeight}px;transform:scale(${model.zoom})"><svg data-lots-relations viewBox="0 0 ${model.stageWidth} ${model.stageHeight}">${renderAtlasAdminLotsCanvasRelationsV1(model)}</svg>${groups}${lots}</div></div><aside class="lots-inspector" data-lots-inspector>${renderAtlasAdminLotsCanvasInspectorV1(model)}</aside></div>`;
}

/** Apply drag coordinates without replacing the canvas or breaking pointer capture. */
export function updateAtlasAdminLotsCanvasDragV1(root: HTMLElement, model: AtlasAdminLotsCanvasViewModelV1): void {
  for (const group of model.groups) {
    const element = root.querySelector<HTMLElement>(`[data-entity="group:${CSS.escape(group.id)}"]`);
    if (element) { element.style.left = `${group.x}px`; element.style.top = `${group.y}px`; }
  }
  for (const lot of model.lots) {
    const element = root.querySelector<HTMLElement>(`[data-entity="lot:${CSS.escape(lot.id)}"]`);
    if (element) { element.style.left = `${lot.node.x}px`; element.style.top = `${lot.node.y}px`; }
  }
  const relations = root.querySelector<SVGElement>('[data-lots-relations]');
  if (relations) relations.innerHTML = renderAtlasAdminLotsCanvasRelationsV1(model);
}

export function bindAtlasAdminLotsCanvasCommandsV1(input: {
  root: HTMLElement; windowRef: Window & typeof globalThis;
  getModel(): AtlasAdminLotsCanvasViewModelV1;
  command(value: AtlasAdminLotsCanvasCommandV1): unknown;
}): () => void {
  const { root, windowRef } = input;
  let drag: { id: string; isGroup: boolean; pointerId: number; startX: number; startY: number; x: number; y: number; zoom: number } | null = null;
  const onPointerDown = (event: PointerEvent): void => {
    const target = event.target instanceof Element ? event.target : null;
    const entity = target?.closest<HTMLElement>('[data-entity]');
    if (!entity) return;
    const id = entity.dataset.entity || '', model = input.getModel();
    if (model.relationSource) {
      if (model.relationSource === id) return;
      const label = windowRef.prompt('Rótulo da relação:', 'relaciona com');
      if (label != null) input.command({ type: 'finish-relation', target: id, label: label.trim() || 'relaciona com' });
      return;
    }
    input.command({ type: 'select', id });
    const isGroup = id.startsWith('group:');
    if (isGroup && !target?.closest('[data-group-drag]')) return;
    if (!isGroup && !target?.closest('.lot-node')) return;
    const current = input.getModel();
    const group = isGroup ? current.groups.find(item => `group:${item.id}` === id) : null;
    const lot = !isGroup ? current.lots.find(item => `lot:${item.id}` === id) : null;
    const position = group ? { x: group.x, y: group.y } : lot ? { x: lot.node.x, y: lot.node.y } : null;
    if (!position) return;
    drag = { id, isGroup, pointerId: event.pointerId, startX: event.clientX, startY: event.clientY, x: position.x, y: position.y, zoom: current.zoom || 1 };
    root.setPointerCapture?.(event.pointerId);
    event.preventDefault();
  };
  const onPointerMove = (event: PointerEvent): void => {
    if (!drag) return;
    const model = input.getModel();
    const width = drag.isGroup ? model.groups.find(item => `group:${item.id}` === drag!.id)?.w || 0 : model.nodeWidth;
    const height = drag.isGroup ? model.groups.find(item => `group:${item.id}` === drag!.id)?.h || 0 : model.nodeHeight;
    const x = Math.max(0, Math.min(model.stageWidth - width, drag.x + (event.clientX - drag.startX) / drag.zoom));
    const y = Math.max(0, Math.min(model.stageHeight - height, drag.y + (event.clientY - drag.startY) / drag.zoom));
    const next = input.command({ type: 'drag-move', id: drag.id, isGroup: drag.isGroup, x, y }) as AtlasAdminLotsCanvasViewModelV1 | undefined;
    if (next) updateAtlasAdminLotsCanvasDragV1(root, next);
  };
  const onPointerUp = (event: PointerEvent): void => {
    if (!drag || event.pointerId !== drag.pointerId) return;
    input.command({ type: 'drag-end' });
    try { root.releasePointerCapture?.(event.pointerId); } catch { /* pointer already released */ }
    drag = null;
  };
  const onClick = (event: MouseEvent): void => {
    const target = event.target instanceof Element ? event.target : null;
    if (target?.closest('[data-new-group]')) {
      const name = windowRef.prompt('Nome do grupo:', 'Novo grupo')?.trim();
      if (name) {
        const viewport = root.querySelector<HTMLElement>('.lots-canvas-viewport'), zoom = input.getModel().zoom || 1;
        input.command({ type: 'create-group', name, x: ((viewport?.scrollLeft || 0) / zoom) + 220, y: ((viewport?.scrollTop || 0) / zoom) + 180 });
      }
      return;
    }
    if (target?.closest('[data-rel-toolbar]')) {
      const selected = input.getModel().selected;
      if (!selected) { windowRef.alert('Selecione primeiro um lote ou grupo.'); return; }
      input.command({ type: 'begin-relation', id: selected }); return;
    }
    const relation = target?.closest<HTMLElement>('[data-start-relation]');
    if (relation) { input.command({ type: 'begin-relation', id: relation.dataset.startRelation || '' }); return; }
    const deleteGroup = target?.closest<HTMLElement>('[data-delete-group]');
    if (deleteGroup) { if (windowRef.confirm('Excluir este grupo?')) input.command({ type: 'delete-group', id: deleteGroup.dataset.deleteGroup || '' }); return; }
    const deleteRelations = target?.closest<HTMLElement>('[data-delete-relations-for]');
    if (deleteRelations) { input.command({ type: 'delete-relations', id: deleteRelations.dataset.deleteRelationsFor || '' }); return; }
    if (target?.closest('[data-zoom-in]')) { input.command({ type: 'zoom-in' }); return; }
    if (target?.closest('[data-zoom-out]')) { input.command({ type: 'zoom-out' }); return; }
    if (target?.closest('[data-zoom-reset]')) { input.command({ type: 'zoom-reset' }); return; }
    if (target?.closest('[data-export]')) {
      const payload = input.command({ type: 'export' });
      if (typeof payload === 'string') {
        const blob = new windowRef.Blob([payload], { type: 'application/json' }), url = windowRef.URL.createObjectURL(blob);
        const link = root.ownerDocument.createElement('a'); link.href = url; link.download = 'belavista-lotes-canvas.json'; link.click();
        windowRef.setTimeout(() => windowRef.URL.revokeObjectURL(url), 1000);
      }
    }
  };
  const onInput = (event: Event): void => {
    const target = event.target instanceof HTMLInputElement || event.target instanceof HTMLTextAreaElement ? event.target : null;
    if (!target) return;
    if (target.matches('[data-lot-label]')) input.command({ type: 'lot-label', value: target.value });
    else if (target.matches('[data-lot-comment]')) input.command({ type: 'lot-comment', value: target.value });
    else if (target.matches('[data-group-name]')) input.command({ type: 'group-name', value: target.value });
    else if (target.matches('[data-group-note]')) input.command({ type: 'group-note', value: target.value });
  };
  const onChange = (event: Event): void => {
    const target = event.target instanceof HTMLSelectElement ? event.target : null;
    if (target?.matches('[data-lot-group]')) input.command({ type: 'lot-group', groupId: target.value });
    const fileInput = event.target instanceof HTMLInputElement && event.target.matches('[data-import]') ? event.target : null;
    const file = fileInput?.files?.[0];
    if (file) void file.text().then(raw => input.command({ type: 'import', raw })).catch(error => windowRef.alert(`Não foi possível importar: ${error.message}`));
  };
  root.addEventListener('pointerdown', onPointerDown);
  windowRef.addEventListener('pointermove', onPointerMove); windowRef.addEventListener('pointerup', onPointerUp);
  root.addEventListener('click', onClick); root.addEventListener('input', onInput); root.addEventListener('change', onChange);
  return () => {
    root.removeEventListener('pointerdown', onPointerDown);
    windowRef.removeEventListener('pointermove', onPointerMove); windowRef.removeEventListener('pointerup', onPointerUp);
    root.removeEventListener('click', onClick); root.removeEventListener('input', onInput); root.removeEventListener('change', onChange);
  };
}

/** Add the optional Lotes workspace entry and preserve the host workspace on close. */
export function installAtlasAdminLotsCanvasNavigationV1(input: {
  documentRef: Document; windowRef: Window & typeof globalThis;
  onOpen(root: HTMLElement): void; onClose(): void;
}): () => void {
  const { documentRef, windowRef } = input;
  let root: HTMLElement | null = null, workspace: Element | null = null;
  let hiddenNodes: Array<[HTMLElement, string]> = [];
  const open = (): void => {
    if (root) return;
    workspace = documentRef.querySelector('.workspace,.maximus-workspace,[data-workspace],main .content,main > section:last-of-type');
    if (!workspace) return;
    hiddenNodes = [...workspace.children].map(node => [node as HTMLElement, (node as HTMLElement).style.display]);
    hiddenNodes.forEach(([node]) => { node.style.display = 'none'; });
    root = documentRef.createElement('section'); root.className = 'admin-lots-canvas-page';
    workspace.append(root); documentRef.body.classList.add('admin-lots-canvas-active');
    documentRef.querySelectorAll('[data-admin-lots-nav]').forEach(node => node.classList.add('active'));
    input.onOpen(root);
  };
  const close = (): void => {
    if (!root) return;
    input.onClose(); root.remove();
    hiddenNodes.forEach(([node, display]) => { if (node.isConnected) node.style.display = display; });
    hiddenNodes = []; root = null; workspace = null;
    documentRef.body.classList.remove('admin-lots-canvas-active');
    documentRef.querySelectorAll('[data-admin-lots-nav]').forEach(node => node.classList.remove('active'));
  };
  const makeButton = (reference: HTMLButtonElement): HTMLButtonElement => {
    const button = reference.cloneNode(true) as HTMLButtonElement;
    button.classList.remove('active');
    [...button.attributes].forEach(attribute => { if (attribute.name.startsWith('data-')) button.removeAttribute(attribute.name); });
    button.dataset.adminLotsNav = 'true'; button.type = 'button';
    const spans = button.querySelectorAll('span');
    if (spans.length) spans[spans.length - 1].textContent = 'Lotes'; else button.textContent = 'Lotes';
    const icon = button.querySelector('i,b'); if (icon) icon.textContent = '▦';
    button.addEventListener('click', event => { event.preventDefault(); event.stopPropagation(); event.stopImmediatePropagation(); open(); }, true);
    return button;
  };
  const installNav = (): boolean => {
    if (documentRef.querySelector('[data-admin-lots-nav]')) return true;
    const candidates = [...documentRef.querySelectorAll<HTMLButtonElement>('aside button, nav button, .sidebar button')];
    const records = candidates.find(button => button.textContent?.trim().toLowerCase().includes('registros'));
    if (!records) return false;
    records.after(makeButton(records)); return true;
  };
  const onDocumentClick = (event: MouseEvent): void => {
    if (!root) return;
    const target = event.target instanceof Element ? event.target : null;
    const nav = target?.closest('aside button,nav button,.sidebar button');
    if (nav && !nav.closest('[data-admin-lots-nav]')) windowRef.setTimeout(close, 0);
  };
  const observer = new windowRef.MutationObserver(() => { installNav(); });
  const boot = (): void => { installNav(); if (documentRef.body) observer.observe(documentRef.body, { childList: true, subtree: true }); };
  documentRef.addEventListener('click', onDocumentClick, true);
  if (documentRef.readyState === 'loading') documentRef.addEventListener('DOMContentLoaded', boot, { once: true }); else boot();
  return () => { observer.disconnect(); documentRef.removeEventListener('click', onDocumentClick, true); close(); };
}

export function renderAtlasStageDetailShellV5361(title: string, body: string, backIcon: string): string {
  return `<section class="stage-detail-shell-v5361"><header class="stage-detail-nav-v5361"><button type="button" data-v5361-stage-back>${backIcon} Agenda e cronograma</button><div><span>PÁGINA DA ETAPA</span><b>${title}</b></div></header><div class="stage-detail-current-v5361">${body}</div></section>`;
}

/** Bind stage navigation and planner-tab gestures, publishing typed semantic commands. */
export function bindAtlasStagesLandingCommandsV5361(root: HTMLElement): () => void {
  const onClick = (event: MouseEvent): void => {
    const target = event.target instanceof Element ? event.target : null;
    if (!target) return;
    let command: AtlasStagesLandingCommandV5361 | null = null;
    const stage = target.closest<HTMLElement>('[data-v5361-open-stage]');
    const back = target.closest<HTMLElement>('[data-v5361-stage-back]');
    const agenda = target.closest<HTMLElement>('[data-v5361-open-agenda-page]');
    const plan = target.closest<HTMLElement>('[data-stage-plan]');
    const legacyPlan = target.closest<HTMLElement>('[data-stage-pane-tab]');
    const utilityPlan = target.closest<HTMLElement>('[data-utility-tab]');
    const relate = target.closest<HTMLElement>('[data-stage-relate]');
    const todo = target.closest<HTMLElement>('[data-plan-todo],.utility-add-todo');
    if (stage && root.contains(stage)) command = { type: 'open-stage', key: String(stage.dataset.v5361OpenStage || '') };
    else if (back && root.contains(back)) command = { type: 'back' };
    else if (agenda && root.contains(agenda)) command = { type: 'open-agenda' };
    else {
      const tab = [plan, legacyPlan, utilityPlan].find((candidate) => candidate && root.contains(candidate));
      if (tab) command = { type: 'planning-pane', name: String(tab.dataset.stagePlan || tab.dataset.stagePaneTab || tab.dataset.utilityTab || ''), source: tab };
      else if (relate && root.contains(relate)) command = { type: 'relate' };
      else if (todo && root.contains(todo)) command = { type: 'todo' };
    }
    if (!command) return;
    event.preventDefault();
    event.stopImmediatePropagation();
    root.dispatchEvent(new CustomEvent<AtlasStagesLandingCommandV5361>('atlas:stages-landing-command-v5361', {
      bubbles: true,
      composed: true,
      detail: command,
    }));
  };
  root.addEventListener('click', onClick, true);
  return () => root.removeEventListener('click', onClick, true);
}

export interface AtlasStagesLandingComponentViewLayerV5361 extends HTMLElement {
  stages(...args: any[]): string;
  bind(...args: any[]): unknown;
  __belavistaStagesLandingV5361Installed?: boolean;
  __atlasStagesLandingCommandsBoundV5361?: boolean;
}

export interface AtlasStagesLandingComponentHostV5361 {
  ViewLayer: { prototype: AtlasStagesLandingComponentViewLayerV5361 & Record<string, any> };
  getRouteState(): { stagesPageV5361?: string; stageSelected?: string };
  getStageName(key: string): string | undefined;
  esc(value: unknown): string;
  ico(name: string): string;
  document?: Document;
  window?: Window & typeof globalThis;
  globalRef?: Window & typeof globalThis;
  consoleRef?: Pick<Console, 'error'>;
}

export interface AtlasStagesLandingComponentControllerV5361 {
  install(): boolean;
  dispose(): void;
}

const atlasStagesLandingComponentControllersV5361 = new WeakMap<object, AtlasStagesLandingComponentControllerV5361>();

/** Own Etapas DOM rendering, route view wrapping, and planner-tab interaction. */
export function installAtlasStagesLandingComponentControllerV5361(
  input: AtlasStagesLandingComponentHostV5361,
): AtlasStagesLandingComponentControllerV5361 {
  const windowRef = input.window || globalThis.window;
  const documentRef = input.document || windowRef?.document || globalThis.document;
  const globalRef = (input.globalRef || windowRef || globalThis) as Window & typeof globalThis & {
    __BELAVISTA_STAGE_DETAIL_BASE_V5361?: (this: HTMLElement, ...args: any[]) => unknown;
  };
  if (!documentRef || !windowRef) throw new Error('A página de etapas precisa de uma janela ativa.');
  const prototype = input.ViewLayer.prototype;
  const existing = atlasStagesLandingComponentControllersV5361.get(prototype);
  if (existing) return existing;
  if (!globalRef.__BELAVISTA_STAGE_DETAIL_BASE_V5361) globalRef.__BELAVISTA_STAGE_DETAIL_BASE_V5361 = prototype.stages;

  const detailTemplate = globalRef.__BELAVISTA_STAGE_DETAIL_BASE_V5361 || prototype.stages;
  const baseStages = prototype.stages;
  const baseBind = prototype.bind;
  let stageRenderer: ((this: AtlasStagesLandingComponentViewLayerV5361, ...args: any[]) => string) | null = null;
  let bindRenderer: ((this: AtlasStagesLandingComponentViewLayerV5361, ...args: any[]) => unknown) | null = null;
  let boundView: AtlasStagesLandingComponentViewLayerV5361 | null = null;
  let unbindView = (): void => undefined;
  let installed = false;
  let stopped = false;

  const activatePlanningPane = (root: HTMLElement, name: string, source: HTMLElement): boolean => {
    const panel = source.closest<HTMLElement>('.stage-planning-panel') ||
      source.closest<HTMLElement>('.stage-planner-panel') ||
      source.closest<HTMLElement>('.utility-content')?.parentElement || root;
    const activate = (tabs: HTMLElement[], panes: HTMLElement[], tabValue: (tab: HTMLElement) => string, paneValue: (pane: HTMLElement) => string): boolean => {
      if (!tabs.length || !panes.length) return false;
      tabs.forEach(tab => tab.classList.toggle('active', tabValue(tab) === name));
      panes.forEach(pane => {
        const visible = paneValue(pane) === name;
        pane.hidden = !visible;
        pane.classList.toggle('active', visible);
      });
      return true;
    };
    if (activate(
      Array.from(panel.querySelectorAll<HTMLElement>('[data-stage-plan]')),
      Array.from(panel.querySelectorAll<HTMLElement>('[data-stage-pane]')),
      tab => String(tab.dataset.stagePlan || ''),
      pane => String(pane.dataset.stagePane || ''),
    )) return true;
    if (activate(
      Array.from(panel.querySelectorAll<HTMLElement>('[data-stage-pane-tab]')),
      Array.from(panel.querySelectorAll<HTMLElement>('[data-stage-pane]')),
      tab => String(tab.dataset.stagePaneTab || ''),
      pane => String(pane.dataset.stagePane || ''),
    )) return true;
    return activate(
      Array.from(panel.querySelectorAll<HTMLElement>('[data-utility-tab]')),
      Array.from(panel.querySelectorAll<HTMLElement>('[data-pane]')),
      tab => String(tab.dataset.utilityTab || ''),
      pane => String(pane.dataset.pane || ''),
    );
  };

  const onPlanningPane = (event: Event): void => {
    const command = (event as CustomEvent<AtlasStagesLandingCommandV5361>).detail;
    if (command?.type === 'planning-pane') activatePlanningPane(event.currentTarget as HTMLElement, command.name, command.source);
  };

  const controller: AtlasStagesLandingComponentControllerV5361 = Object.freeze({
    install(): boolean {
      if (stopped || installed) return installed;
      if (prototype.__belavistaStagesLandingV5361Installed) return false;
      prototype.__belavistaStagesLandingV5361Installed = true;
      stageRenderer = function renderStagesRouteV5361(this: AtlasStagesLandingComponentViewLayerV5361, ...args: any[]): string {
        const state = input.getRouteState();
        if (state.stagesPageV5361 !== 'detail') return renderAtlasStagesLandingV5361(input.ico('calendar-days'));
        let html = '';
        try { html = String(detailTemplate.apply(this, args) || ''); }
        catch (error) {
          (input.consoleRef || globalThis.console)?.error?.('[Aliança Park v5.3.61] stage detail render', error);
          const message = error instanceof Error ? error.message : String(error);
          html = `<section class="stage-detail-error-v5361"><h2>Página da etapa indisponível</h2><p>${input.esc(message)}</p></section>`;
        }
        const title = input.getStageName(String(state.stageSelected || '')) || 'Etapa em foco';
        return renderAtlasStageDetailShellV5361(input.esc(title), html, input.ico('arrow-left'));
      };
      prototype.stages = stageRenderer;
      bindRenderer = function bindStagesRouteV5361(this: AtlasStagesLandingComponentViewLayerV5361, ...args: any[]): unknown {
        const result = baseBind?.apply(this, args);
        if (!this.__atlasStagesLandingCommandsBoundV5361) {
          if (boundView && boundView !== this) unbindView();
          this.__atlasStagesLandingCommandsBoundV5361 = true;
          boundView = this;
          const unbindCommands = bindAtlasStagesLandingCommandsV5361(this);
          this.addEventListener('atlas:stages-landing-command-v5361', onPlanningPane);
          unbindView = () => {
            unbindCommands();
            this.removeEventListener('atlas:stages-landing-command-v5361', onPlanningPane);
            delete this.__atlasStagesLandingCommandsBoundV5361;
          };
        }
        (windowRef as Window & typeof globalThis & { lucide?: { createIcons?: () => void } }).lucide?.createIcons?.();
        return result;
      };
      prototype.bind = bindRenderer;
      installed = true;
      return true;
    },
    dispose(): void {
      stopped = true;
      unbindView();
      if (stageRenderer && prototype.stages === stageRenderer) prototype.stages = baseStages;
      if (bindRenderer && prototype.bind === bindRenderer) prototype.bind = baseBind;
      delete prototype.__belavistaStagesLandingV5361Installed;
      atlasStagesLandingComponentControllersV5361.delete(prototype);
    },
  });
  atlasStagesLandingComponentControllersV5361.set(prototype, controller);
  return controller;
}

export interface AtlasFinalStageCalendarItemViewV5360 {
  id: string;
  status: string;
  name: string;
  owner: string;
  progress: number;
  tone: string;
}

export interface AtlasFinalStageCalendarGroupViewV5360 {
  period: string;
  items: AtlasFinalStageCalendarItemViewV5360[];
}

/** Render the existing activity calendar from its typed program projection. */
export function renderAtlasFinalStageCalendarV5360(input: {
  groups: readonly AtlasFinalStageCalendarGroupViewV5360[];
  esc(value: unknown): string;
}): string {
  const { groups, esc } = input;
  const periods = groups.map(group => `<section class="stage-period-v5360"><header><span>PERÍODO</span><b>${esc(group.period)}</b></header><div>${group.items.map(item => `<button type="button" class="stage-card-v5360 ${esc(item.tone)}" data-v5360-stage-card="${esc(item.id)}"><span>${esc(item.status)}</span><h2>${esc(item.name)}</h2><p>${esc(item.owner)}</p><i><em style="width:${item.progress}%"></em></i><footer><b>${item.progress}%</b><small>Abrir página →</small></footer></button>`).join('')}</div></section>`).join('');
  return `<section class="stage-calendar-only-v5360"><header class="workspace-head-v5360"><div><span>ETAPAS E CRONOGRAMA</span><h1>Calendário de atividades</h1><p>Representação única da execução. Cada card abre a página dedicada da atividade.</p></div><div class="stage-calendar-legend-v5360"><span class="active">Em andamento</span><span class="warn">Pendente / risco</span><span class="done">Concluído</span></div></header><div class="stage-calendar-v5360">${periods || '<div class="dashboard-empty-v5360">Nenhuma atividade disponível.</div>'}</div></section>`;
}

/** Bind activity cards and publish the navigation key without owning app state. */
export function bindAtlasFinalStageCalendarCommandsV5360(root: HTMLElement): () => void {
  const onClick = (event: MouseEvent): void => {
    const target = event.target instanceof Element ? event.target.closest<HTMLElement>('[data-v5360-stage-card]') : null;
    if (!target || !root.contains(target)) return;
    event.preventDefault();
    event.stopImmediatePropagation();
    root.dispatchEvent(new CustomEvent('atlas:final-stage-calendar-command-v5360', {
      bubbles: true,
      composed: true,
      detail: { activityKey: String(target.dataset.v5360StageCard || '') },
    }));
  };
  root.addEventListener('click', onClick, true);
  return () => root.removeEventListener('click', onClick, true);
}

