/** Apply the administrative satellite-scene preset at the element boundary. */
export function applyAtlasAdminPublicMapSurfacePresetV1(input: {
  map: AtlasAdminPublicMapSceneElementV1;
  documentRef: Document;
  view: AtlasAdminPublicMapPresetViewV1;
}): 'configured' | 'static-first-isolated' | 'already-configured' {
  const { map, documentRef, view } = input;
  if (map.dataset.adminPublicMapConfigured) return 'already-configured';
  if (map.dataset.mapInit === view.staticMapInit) {
    map.dataset.adminPublicMapConfigured = 'static-first-isolated';
    map.dataset.adminPublicMapBridge = view.staticBridge;
    return 'static-first-isolated';
  }
  map.dataset.adminPublicMapConfigured = 'true';
  map.dataset.adminMapSource = view.source;
  map.dataset.publicPresentation = 'true';
  map.dataset.publicSelectionEnabled = 'true';
  map.setAttribute('data-public-map', '');
  map.setAttribute('data-public-presentation', 'true');
  map.removeAttribute('data-base-map');
  map.setAttribute('data-public-satellite-base', 'true');
  const leaflet = map.querySelector<HTMLElement>('.map-host');
  if (leaflet) {
    leaflet.style.opacity = '0';
    leaflet.style.pointerEvents = 'none';
  }
  map.sceneManualPan = { x: view.camera.panX, y: view.camera.panY };
  map.sceneManualRotation = view.camera.rotation;
  map.sceneTiltAdjust = view.camera.tilt;
  map.sceneManualZoom = view.camera.zoom;
  map.sceneUserInteracted = true;
  map.style.setProperty('--scene-pan-x', `${view.camera.panX}px`);
  map.style.setProperty('--scene-pan-y', `${view.camera.panY}px`);
  map.setSceneVisual?.(view.camera.sceneZoom, view.camera.rotation, view.camera.zoom);
  map.dataset.adminPublicPreset = view.preset;
  map.dataset.adminPublicCameraPreset = 'true';
  map.dataset.adminMapRotationLock = view.rotationLock;
  map.dataset.adminPublicMapBase = view.base;
  documentRef.documentElement.dataset.adminPublicMapSurface = 'v5352';
  return 'configured';
}

/** Keep diagnostics on the map element so its active 3D state remains inspectable. */
export function setAtlasAdminPublicMap3dStatusV1(
  map: AtlasAdminPublicMapSceneElementV1,
  status: { probe?: string; state?: string; readyMs?: number },
): void {
  map.dataset.admin3dOwnerV1 = 'typescript';
  if (status.probe) map.dataset.admin3dProbe = status.probe;
  if (status.state) map.dataset.admin3dState = status.state;
  if (status.readyMs !== undefined) map.dataset.admin3dReadyMs = String(status.readyMs);
}

/** Apply the map's configured lighting and surface materials to one ready scene. */
export function applyAtlasAdminPublicMapNaturalMaterialsV1(input: {
  map: AtlasAdminPublicMapSceneElementV1 & Record<string, any>;
  environment: import('./program.js').AtlasPublicMapEnvironmentV1;
}): boolean {
  const { map, environment } = input;
  const color = (value: unknown): number => typeof value === 'number' ? value : Number.parseInt(String(value).replace(/^0x/i, ''), 16);
  const fallback = environment.legacyFallback;
  const sourcePalette = fallback.palette;
  const palette = sourcePalette;
  const hash = (value: unknown): number => {
    let result = 2166136261;
    for (const character of String(value || '')) { result ^= character.charCodeAt(0); result = Math.imul(result, 16777619); }
    return result >>> 0;
  };
  const materials = (material: any, apply: (value: any) => any): any => Array.isArray(material) ? material.map(apply) : apply(material);
  const normalize = (material: any, shade: number, options: Record<string, any> = {}): any => {
    if (!material) return material;
    const defaults = fallback.materialDefaults.normalize;
    const clone = material.clone?.() || material;
    clone.color?.setHex?.(shade);
    for (const key of ['map', 'aoMap', 'metalnessMap', 'roughnessMap']) if (key in clone) clone[key] = null;
    if ('vertexColors' in clone) clone.vertexColors = false;
    if ('roughness' in clone) clone.roughness = options.roughness ?? defaults.roughness;
    if ('metalness' in clone) clone.metalness = 0;
    if (clone.emissive) {
      clone.emissive.setHex(color(options.emissive ?? defaults.emissive ?? 0));
      clone.emissiveIntensity = options.emissiveIntensity ?? defaults.emissiveIntensity ?? 0;
    }
    clone.transparent = false; clone.opacity = 1; clone.depthWrite = true; clone.depthTest = true; clone.needsUpdate = true;
    return clone;
  };
  const textured = (material: any, kind: string, shade: number, options: Record<string, any> = {}): any => materials(material, item => {
    const defaults = fallback.materialDefaults.textured;
    const clone = map.makeSiteSurfaceMaterial?.(map.THREE, item, kind) || item?.clone?.() || item;
    if (!clone) return clone;
    clone.color?.setHex?.(shade);
    for (const key of ['map', 'aoMap', 'metalnessMap', 'roughnessMap']) if (key in clone) clone[key] = null;
    if ('vertexColors' in clone) clone.vertexColors = false;
    if ('roughness' in clone) clone.roughness = options.roughness ?? defaults.roughness;
    if ('metalness' in clone) clone.metalness = 0;
    if (clone.emissive) {
      clone.emissive.setHex(color(options.emissive ?? defaults.emissive ?? 0));
      clone.emissiveIntensity = options.emissiveIntensity ?? defaults.emissiveIntensity ?? 0;
    }
    clone.transparent = false; clone.opacity = 1; clone.depthWrite = true; clone.depthTest = true; clone.needsUpdate = true;
    clone.userData = { ...(clone.userData || {}), belavistaPublicSurface: `${kind}-natural-v50` };
    return clone;
  });

  if (map.scene && map.dataset.publicLightingV50 !== 'true') {
    map.dataset.publicLightingV50 = 'true';
    if (map.renderer) map.renderer.toneMappingExposure = fallback.lighting.rendererExposure;
    map.scene.traverse?.((node: any) => {
      if (node.isHemisphereLight) { node.intensity = fallback.lighting.hemisphereLight.intensity; node.color?.setHex?.(color(fallback.lighting.hemisphereLight.color)); node.groundColor?.setHex?.(color(fallback.lighting.hemisphereLight.groundColor)); }
      if (node.isDirectionalLight) { node.intensity = fallback.lighting.directionalLight.intensity; node.color?.setHex?.(color(fallback.lighting.directionalLight.color)); }
    });
    const mapSurface = map.mapSurface?.material;
    if (mapSurface) {
      mapSurface.color?.setHex?.(environment.scene.surface.color);
      mapSurface.opacity = environment.scene.surface.opacity;
      mapSurface.transparent = environment.scene.surface.transparent;
      mapSurface.needsUpdate = true;
    }
  }
  if (!map.THREE || !map.modelReady || !map.masterplanModel) return false;
  const labels = environment.scene.labels;
  const publicSatellite = map.dataset.publicRoadPolicy === 'satellite-only' || map.matches?.('map-scene[data-public-presentation],map-scene[data-public-map]');
  if (publicSatellite) {
    map.disablePublicCobbleTexture?.(); map.disablePublicSyntheticRoads?.();
    map.dataset.publicPalette = labels.satellitePalette;
    map.dataset.publicRoadTexture = labels.disabledRoadTexture;
    map.dataset.publicRoadTextureSource = labels.removedSyntheticRoadTexture;
    map.dataset.publicMaterialsV50 = labels.preservedSatelliteMaterials;
    map.dataset.publicModelAlignment = labels.modelAlignment;
    return true;
  }
  if (map.dataset.publicMaterialsV50 === 'true') return false;
  if (map.dataset.publicRoadPolicy === 'satellite-only') {
    map.disablePublicSyntheticRoads?.();
    map.dataset.publicPalette = labels.satellitePalette;
    map.dataset.publicMaterialsV50 = labels.preservedSatelliteMaterials;
    map.dataset.publicModelAlignment = labels.modelAlignment;
    return true;
  }
  if (map.dataset.publicLotPresentation) {
    map.dataset.publicPalette = labels.satellitePalette;
    map.dataset.publicMaterialsV50 = fallback.labels.preservedMaterials;
    return true;
  }
  map.dataset.publicMaterialsV50 = 'true';
  const lots = map.modelParts?.lots || [];
  lots.forEach((node: any, index: number) => {
    const name = String(node.name || node.userData?.partLabel || '').toLowerCase();
    node.material = textured(node.material, 'earth', palette.grass[(hash(name) + index) % palette.grass.length], fallback.materialDefaults.surfaces.earth);
    node.userData.defaultMaterial = node.material;
  });
  map.masterplanModel.traverse?.((node: any) => {
    if (!node?.isMesh) return;
    const name = String(node.name || '').toLowerCase();
    const role = String(node.userData?.belavistaRole || node.userData?.partKind || '').toLowerCase();
    const operational = Boolean(node.userData?.streetSegment);
    const social = role === 'leisure' || /area.?de.?lazer|court|gym.?pad|gym.?post|gym.?beam|gym.?seat|pavilhao|play|praca|banco.?praca/.test(name);
    if (social && typeof map.makeSocialAreaMaterial === 'function') {
      node.material = materials(node.material, (item: any) => map.makeSocialAreaMaterial(map.THREE, item, name));
      node.userData.defaultMaterial = node.material; node.userData.belavistaSocialSurface = true; return;
    }
    if (/contorno|outline|divisa|limite|borda|linha/.test(name)) { node.material = materials(node.material, (item: any) => normalize(item, palette.line, fallback.materialDefaults.surfaces.outline)); node.userData.defaultMaterial = node.material; return; }
    if ((role === 'streets' || role === 'street' || /asfalto|rua|road|street|paviment/.test(name)) && !operational) { const shade = palette.road[hash(name) % palette.road.length]; node.material = textured(node.material, 'cobble', shade, fallback.materialDefaults.surfaces.road); node.userData.defaultMaterial = node.material; return; }
    if (/meio.?fio|guia|curb/.test(name)) { node.material = materials(node.material, (item: any) => normalize(item, palette.curb, fallback.materialDefaults.surfaces.curb)); node.userData.defaultMaterial = node.material; return; }
    if (/tronco|trunk/.test(name)) { node.material = materials(node.material, (item: any) => normalize(item, palette.trunk, fallback.materialDefaults.surfaces.trunk)); node.userData.defaultMaterial = node.material; return; }
    if (role === 'landscape' || /arvore|tree|copa|folhagem|folha|paisag|grama|veget/.test(name)) { const shade = palette.foliage[hash(name) % palette.foliage.length]; node.material = materials(node.material, (item: any) => normalize(item, shade, fallback.materialDefaults.surfaces.foliage)); node.userData.defaultMaterial = node.material; return; }
    if (role === 'leisure' || /quadra|court|play|academia|gym|lazer|praca/.test(name)) { node.material = materials(node.material, (item: any) => normalize(item, palette.sand, fallback.materialDefaults.surfaces.leisure)); node.userData.defaultMaterial = node.material; return; }
    if (/pavilhao|telhado|quiosque|estrutura/.test(name)) { node.material = materials(node.material, (item: any) => normalize(item, palette.clay, fallback.materialDefaults.surfaces.roof)); node.userData.defaultMaterial = node.material; return; }
    if (/concreto|base|calcada|passeio/.test(name)) { node.material = materials(node.material, (item: any) => normalize(item, palette.concrete, fallback.materialDefaults.surfaces.concrete)); node.userData.defaultMaterial = node.material; }
  });
  for (const node of map.modelParts?.streets || []) {
    if (!node?.userData?.streetSegment) continue;
    const material = node.userData.defaultMaterial || node.material;
    const shade = palette.road[hash(node.name) % palette.road.length];
    node.userData.defaultMaterial = materials(material, (item: any) => {
      const overlay = normalize(item, shade, fallback.materialDefaults.surfaces.streetOverlay);
      overlay.transparent = true; overlay.opacity = fallback.materialDefaults.surfaces.streetOverlay.opacity; overlay.depthWrite = false;
      return overlay;
    });
    if (!node.userData.overlayMaterial) node.material = node.userData.defaultMaterial;
  }
  map.dataset.publicPalette = fallback.labels.naturalPalette;
  map.renderer?.render?.(map.scene, map.camera);
  return true;
}

