      if (runtime.__BELAVISTA_CHAT_TAB_WIDGET_GHOST_V5359 === compatibilityApi) delete runtime.__BELAVISTA_CHAT_TAB_WIDGET_GHOST_V5359;
      delete runtime.__belavistaChatTabWidgetGhostV5359;
